package config

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestDefaultConfig(t *testing.T) {
	cfg := DefaultConfig()
	assert.Len(t, cfg.Views, 1)
	assert.Equal(t, "My PRs", cfg.Views[0].Name)
	assert.Equal(t, "author:@me", cfg.Views[0].Query)
	assert.True(t, cfg.Views[0].Default)
}

func TestLoadFromPath(t *testing.T) {
	tests := []struct {
		name        string
		content     string
		expected    Config
		expectedErr string
	}{
		{
			name: "valid config with multiple views",
			content: `views:
  - name: "My PRs"
    query: "author:@me"
    default: true
  - name: "Team PRs"
    query: "author:teammate1 author:teammate2"
  - name: "Needs Review"
    query: "review-requested:@me"
`,
			expected: Config{
				Views: []View{
					{Name: "My PRs", Query: "author:@me", Default: true},
					{Name: "Team PRs", Query: "author:teammate1 author:teammate2"},
					{Name: "Needs Review", Query: "review-requested:@me"},
				},
			},
		},
		{
			name:     "empty views falls back to default",
			content:  "views: []\n",
			expected: DefaultConfig(),
		},
		{
			name:        "malformed yaml",
			content:     "views: [invalid yaml\n  broken:",
			expectedErr: "parsing config",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := t.TempDir()
			path := filepath.Join(dir, "config.yaml")
			err := os.WriteFile(path, []byte(tt.content), 0644)
			assert.NoError(t, err)

			cfg, err := LoadFromPath(path)

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Equal(t, tt.expected, cfg)
		})
	}
}

func TestLoadFromPath_FileNotExists(t *testing.T) {
	cfg, err := LoadFromPath("/nonexistent/path/config.yaml")
	assert.NoError(t, err)
	assert.Equal(t, DefaultConfig(), cfg)
}

func TestSave(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "subdir", "config.yaml")

	cfg := Config{
		Views: []View{
			{Name: "My PRs", Query: "author:@me", Default: true},
			{Name: "Team", Query: "author:alice author:bob"},
		},
	}

	err := Save(cfg, path)
	assert.NoError(t, err)

	loaded, err := LoadFromPath(path)
	assert.NoError(t, err)
	assert.Equal(t, cfg, loaded)
}

func TestSave_RoundTrip(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yaml")

	original := Config{
		Views: []View{
			{Name: "Default", Query: "author:@me", Default: true},
		},
	}

	err := Save(original, path)
	assert.NoError(t, err)

	// Add a view and save again
	original.Views = append(original.Views, View{Name: "New View", Query: "review-requested:@me"})
	err = Save(original, path)
	assert.NoError(t, err)

	loaded, err := LoadFromPath(path)
	assert.NoError(t, err)
	assert.Len(t, loaded.Views, 2)
	assert.Equal(t, "New View", loaded.Views[1].Name)
}



package deploy

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
)

type mockTokenProvider struct {
	token string
	err   error
}

func (m *mockTokenProvider) GetToken(_ context.Context) (string, error) {
	return m.token, m.err
}

func TestTriggerIntegrate(t *testing.T) {
	tests := []struct {
		name        string
		statusCode  int
		body        string
		expectedErr string
	}{
		{
			name:       "success",
			statusCode: http.StatusOK,
			body:       `{"ok": true}`,
		},
		{
			name:        "server error",
			statusCode:  http.StatusInternalServerError,
			body:        `{"error": "internal"}`,
			expectedErr: "devflow API returned 500",
		},
		{
			name:        "forbidden",
			statusCode:  http.StatusForbidden,
			body:        `{"error": "forbidden"}`,
			expectedErr: "devflow API returned 403",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				assert.Equal(t, http.MethodPost, r.Method)
				assert.Contains(t, r.URL.Path, "/internal/api/v2/devflow/execute/integrate")
				assert.Contains(t, r.URL.RawQuery, "pr=")
				assert.Equal(t, "Bearer test-token", r.Header.Get("Authorization"))

				w.WriteHeader(tt.statusCode)
				w.Write([]byte(tt.body))
			}))
			defer server.Close()

			client := &DevflowClient{
				BaseURL:       server.URL,
				TokenProvider: &mockTokenProvider{token: "test-token"},
				HTTP:          server.Client(),
			}

			err := client.TriggerIntegrate(context.Background(), "https://github.com/DataDog/dd-source/pull/123")

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
		})
	}
}

func TestTriggerIntegrateTokenError(t *testing.T) {
	client := &DevflowClient{
		BaseURL:       "http://localhost",
		TokenProvider: &mockTokenProvider{err: assert.AnError},
		HTTP:          http.DefaultClient,
	}

	err := client.TriggerIntegrate(context.Background(), "https://github.com/DataDog/dd-source/pull/123")
	assert.Error(t, err)
}

func TestTriggerIntegrateAuthorizationHeader(t *testing.T) {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		assert.Equal(t, "Bearer abc123", r.Header.Get("Authorization"))
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()

	client := &DevflowClient{
		BaseURL:       server.URL,
		TokenProvider: &mockTokenProvider{token: "Authorization: Bearer abc123"},
		HTTP:          server.Client(),
	}

	err := client.TriggerIntegrate(context.Background(), "https://github.com/DataDog/dd-source/pull/1")
	assert.NoError(t, err)
}



package deploy

import (
	"context"
	"fmt"
	"net/http"
	"net/url"
	"os/exec"
	"strings"
	"time"

	"io"
)

// TokenProvider abstracts auth token retrieval for testability
type TokenProvider interface {
	GetToken(ctx context.Context) (string, error)
}

// AuthanywhereTokenProvider gets tokens via the authanywhere CLI.
// When Audience is empty, it defaults to "sdm".
type AuthanywhereTokenProvider struct {
	Audience string
}

func (a *AuthanywhereTokenProvider) GetToken(ctx context.Context) (string, error) {
	audience := a.Audience
	if audience == "" {
		audience = "sdm"
	}
	out, err := exec.CommandContext(ctx, "authanywhere", "--audience", audience).Output()
	if err != nil {
		return "", fmt.Errorf("getting auth token: %w", err)
	}
	return strings.TrimSpace(string(out)), nil
}

// HTTPClient abstracts HTTP requests for testability
type HTTPClient interface {
	Do(req *http.Request) (*http.Response, error)
}

// DevflowClient fetches deployment status from the devflow API
type DevflowClient struct {
	BaseURL       string
	TokenProvider TokenProvider
	HTTP          HTTPClient
}

const defaultBaseURL = "https://devflow-api.us1.ddbuild.io"

// NewDevflowClient creates a client with default settings
func NewDevflowClient() *DevflowClient {
	return &DevflowClient{
		BaseURL:       defaultBaseURL,
		TokenProvider: &AuthanywhereTokenProvider{},
		HTTP:          &http.Client{Timeout: 60 * time.Second},
	}
}

// FetchDeployStatus queries whereismycode for a PR and returns deployment info per service
func (c *DevflowClient) FetchDeployStatus(ctx context.Context, prURL string) ([]ServiceDeployment, error) {
	token, err := c.TokenProvider.GetToken(ctx)
	if err != nil {
		return nil, err
	}

	reqURL := fmt.Sprintf("%s/internal/api/v2/devflow/execute/whereismycode?pr=%s",
		c.BaseURL, url.QueryEscape(prURL))

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, reqURL, nil)
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}

	// authanywhere outputs "Authorization: Bearer " format
	if strings.HasPrefix(token, "Authorization:") {
		parts := strings.SplitN(token, ":", 2)
		if len(parts) == 2 {
			req.Header.Set("Authorization", strings.TrimSpace(parts[1]))
		}
	} else {
		req.Header.Set("Authorization", "Bearer "+token)
	}

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("devflow API request: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading devflow response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("devflow API returned %d: %s", resp.StatusCode, string(body))
	}

	return ParseDevflowResponse(body)
}

// TriggerIntegrate calls the devflow integrate API for a PR
func (c *DevflowClient) TriggerIntegrate(ctx context.Context, prURL string) error {
	token, err := c.TokenProvider.GetToken(ctx)
	if err != nil {
		return err
	}

	reqURL := fmt.Sprintf("%s/internal/api/v2/devflow/execute/integrate?pr=%s",
		c.BaseURL, url.QueryEscape(prURL))

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, reqURL, nil)
	if err != nil {
		return fmt.Errorf("creating request: %w", err)
	}

	if strings.HasPrefix(token, "Authorization:") {
		parts := strings.SplitN(token, ":", 2)
		if len(parts) == 2 {
			req.Header.Set("Authorization", strings.TrimSpace(parts[1]))
		}
	} else {
		req.Header.Set("Authorization", "Bearer "+token)
	}

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return fmt.Errorf("devflow API request: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("reading devflow response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("devflow API returned %d: %s", resp.StatusCode, string(body))
	}

	return nil
}



package deploy

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestParseDevflowResponse(t *testing.T) {
	tests := []struct {
		name        string
		input       string
		expected    []ServiceDeployment
		expectedErr string
	}{
		{
			name:        "invalid json",
			input:       `{not json`,
			expectedErr: "parsing devflow response",
		},
		{
			name:        "devflow error response",
			input:       `{"state":{"feedbacks":[{"level":"FEEDBACK_LEVEL_FAILURE","message":"something went wrong","is_final":true}]}}`,
			expectedErr: "devflow error",
		},
		{
			name:        "no final feedback",
			input:       `{"state":{"feedbacks":[{"level":"FEEDBACK_LEVEL_INFO","message":"processing...","is_final":false}]}}`,
			expectedErr: "no final feedback",
		},
		{
			name:  "single service fully deployed",
			input: `{"state":{"feedbacks":[{"message":"**conductor-worker**\n` + "```" + `\n+----------------------+---------+-----------------------+---------------+\n|      DATACENTER      |   ENV   |       NAMESPACE       |   DEPLOYED    |\n+----------------------+---------+-----------------------+---------------+\n| us1.release.mgmt.dog | mgmt    | orchestration         | ✅ (deployed) |\n| us1.ddbuild.io       | prod    | orchestration         | ✅ (deployed) |\n+----------------------+---------+-----------------------+---------------+\n` + "```" + `\n","level":"FEEDBACK_LEVEL_INFO","is_final":true}]}}`,
			expected: []ServiceDeployment{
				{
					Service: "conductor-worker",
					Targets: []DeployTarget{
						{Datacenter: "us1.release.mgmt.dog", Env: "mgmt", Namespace: "orchestration", Status: DeployStatusDeployed},
						{Datacenter: "us1.ddbuild.io", Env: "prod", Namespace: "orchestration", Status: DeployStatusDeployed},
					},
				},
			},
		},
		{
			name:  "service with missing deployment",
			input: `{"state":{"feedbacks":[{"message":"**workflowgen**\n` + "```" + `\n+-------------------------+---------+-----------------------+---------------+\n|       DATACENTER        |   ENV   |       NAMESPACE       |   DEPLOYED    |\n+-------------------------+---------+-----------------------+---------------+\n| us1.ddbuild.io          | prod    | orchestration         | ✅ (deployed) |\n| us1.staging.dog         | staging | orchestration         | ❌ (missing)  |\n+-------------------------+---------+-----------------------+---------------+\n` + "```" + `\n","level":"FEEDBACK_LEVEL_INFO","is_final":true}]}}`,
			expected: []ServiceDeployment{
				{
					Service: "workflowgen",
					Targets: []DeployTarget{
						{Datacenter: "us1.ddbuild.io", Env: "prod", Namespace: "orchestration", Status: DeployStatusDeployed},
						{Datacenter: "us1.staging.dog", Env: "staging", Namespace: "orchestration", Status: DeployStatusNotDeployed},
					},
				},
			},
		},
		{
			name:  "multiple services",
			input: `{"state":{"feedbacks":[{"message":"**svc-a**\n` + "```" + `\n+-----------+------+-----------+---------------+\n| DATACENTER| ENV  | NAMESPACE | DEPLOYED      |\n+-----------+------+-----------+---------------+\n| dc1       | prod | ns1       | ✅ (deployed) |\n+-----------+------+-----------+---------------+\n` + "```" + `\n\n**svc-b**\n` + "```" + `\n+-----------+------+-----------+---------------+\n| DATACENTER| ENV  | NAMESPACE | DEPLOYED      |\n+-----------+------+-----------+---------------+\n| dc2       | staging | ns2   | ❌ (missing)  |\n+-----------+------+-----------+---------------+\n` + "```" + `\n","level":"FEEDBACK_LEVEL_INFO","is_final":true}]}}`,
			expected: []ServiceDeployment{
				{
					Service: "svc-a",
					Targets: []DeployTarget{
						{Datacenter: "dc1", Env: "prod", Namespace: "ns1", Status: DeployStatusDeployed},
					},
				},
				{
					Service: "svc-b",
					Targets: []DeployTarget{
						{Datacenter: "dc2", Env: "staging", Namespace: "ns2", Status: DeployStatusNotDeployed},
					},
				},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := ParseDevflowResponse([]byte(tt.input))

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Equal(t, tt.expected, result)
		})
	}
}

func TestParseDeployedColumn(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected DeployStatus
	}{
		{name: "deployed with emoji", input: "✅ (deployed)", expected: DeployStatusDeployed},
		{name: "missing with emoji", input: "❌ (missing)", expected: DeployStatusNotDeployed},
		{name: "deploying", input: "🔄 (deploying)", expected: DeployStatusDeploying},
		{name: "plain deployed", input: "deployed", expected: DeployStatusDeployed},
		{name: "unknown value", input: "something else", expected: DeployStatusNotDeployed},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, parseDeployedColumn(tt.input))
		})
	}
}



package deploy

import (
	"encoding/json"
	"fmt"
	"strings"
)

// devflowResponse is the top-level JSON response from the devflow API
type devflowResponse struct {
	State struct {
		Feedbacks []devflowFeedback `json:"feedbacks"`
	} `json:"state"`
}

type devflowFeedback struct {
	Title   string `json:"title"`
	Message string `json:"message"`
	Level   string `json:"level"`
	IsFinal bool   `json:"is_final"`
}

// ParseDevflowResponse parses the JSON response from the devflow whereismycode API
// and extracts deployment targets per service from the ASCII tables in the final feedback message.
func ParseDevflowResponse(data []byte) ([]ServiceDeployment, error) {
	var resp devflowResponse
	if err := json.Unmarshal(data, &resp); err != nil {
		return nil, fmt.Errorf("parsing devflow response: %w", err)
	}

	var finalMsg string
	for _, fb := range resp.State.Feedbacks {
		if fb.IsFinal {
			if fb.Level == "FEEDBACK_LEVEL_FAILURE" {
				return nil, fmt.Errorf("devflow error: %s", fb.Message)
			}
			finalMsg = fb.Message
			break
		}
	}

	if finalMsg == "" {
		return nil, fmt.Errorf("no final feedback in devflow response")
	}

	return parseServiceTables(finalMsg)
}

// parseServiceTables extracts service names and their ASCII tables from the message.
// Format:
// **service-name**
// ```
// +------------+-----+...
// | DATACENTER | ENV |...
// +------------+-----+...
// | value      | val |...
// +------------+-----+...
// ```
func parseServiceTables(msg string) ([]ServiceDeployment, error) {
	var deployments []ServiceDeployment

	sections := strings.Split(msg, "**")
	// sections alternate: [before, service1, between, service2, between, ...]
	for i := 1; i+1 < len(sections); i += 2 {
		serviceName := strings.TrimSpace(sections[i])
		if serviceName == "" {
			continue
		}

		// The table content follows in sections[i+1]
		tableSection := sections[i+1]
		targets, err := parseASCIITable(tableSection)
		if err != nil {
			return nil, fmt.Errorf("parsing table for service %s: %w", serviceName, err)
		}

		deployments = append(deployments, ServiceDeployment{
			Service: serviceName,
			Targets: targets,
		})
	}

	return deployments, nil
}

// parseASCIITable parses the ASCII table rows into DeployTarget structs.
func parseASCIITable(section string) ([]DeployTarget, error) {
	lines := strings.Split(section, "\n")

	var dataLines []string
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || trimmed == "```" || strings.HasPrefix(trimmed, "+") {
			continue
		}
		if !strings.Contains(trimmed, "|") {
			continue
		}
		dataLines = append(dataLines, trimmed)
	}

	if len(dataLines) < 2 {
		return nil, nil
	}

	headers := parsePipeRow(dataLines[0])
	headerIndex := make(map[string]int)
	for i, h := range headers {
		headerIndex[strings.ToUpper(strings.TrimSpace(h))] = i
	}

	var targets []DeployTarget
	for _, line := range dataLines[1:] {
		cols := parsePipeRow(line)

		target := DeployTarget{}
		if idx, ok := headerIndex["DATACENTER"]; ok && idx < len(cols) {
			target.Datacenter = strings.TrimSpace(cols[idx])
		}
		if idx, ok := headerIndex["ENV"]; ok && idx < len(cols) {
			target.Env = strings.TrimSpace(cols[idx])
		}
		if idx, ok := headerIndex["NAMESPACE"]; ok && idx < len(cols) {
			target.Namespace = strings.TrimSpace(cols[idx])
		}
		if idx, ok := headerIndex["DEPLOYED"]; ok && idx < len(cols) {
			target.Status = parseDeployedColumn(strings.TrimSpace(cols[idx]))
		}

		targets = append(targets, target)
	}

	return targets, nil
}

// parsePipeRow splits a pipe-delimited row into columns, stripping outer pipes.
func parsePipeRow(line string) []string {
	line = strings.TrimSpace(line)
	line = strings.Trim(line, "|")
	parts := strings.Split(line, "|")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return parts
}

func parseDeployedColumn(val string) DeployStatus {
	lower := strings.ToLower(val)
	switch {
	case strings.Contains(lower, "deployed"):
		return DeployStatusDeployed
	case strings.Contains(lower, "deploying"):
		return DeployStatusDeploying
	default:
		return DeployStatusNotDeployed
	}
}



package deploy

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestDetermineOverallStatus(t *testing.T) {
	tests := []struct {
		name     string
		targets  []DeployTarget
		expected OverallDeployStatus
	}{
		{
			name:     "no targets",
			targets:  nil,
			expected: OverallNotDeployed,
		},
		{
			name: "all deployed",
			targets: []DeployTarget{
				{Status: DeployStatusDeployed},
				{Status: DeployStatusDeployed},
			},
			expected: OverallDeployed,
		},
		{
			name: "some deploying",
			targets: []DeployTarget{
				{Status: DeployStatusDeployed},
				{Status: DeployStatusDeploying},
			},
			expected: OverallDeploying,
		},
		{
			name: "partially deployed",
			targets: []DeployTarget{
				{Status: DeployStatusDeployed},
				{Status: DeployStatusNotDeployed},
			},
			expected: OverallPartiallyDeployed,
		},
		{
			name: "none deployed",
			targets: []DeployTarget{
				{Status: DeployStatusNotDeployed},
				{Status: DeployStatusNotDeployed},
			},
			expected: OverallNotDeployed,
		},
		{
			name: "single target deployed",
			targets: []DeployTarget{
				{Status: DeployStatusDeployed},
			},
			expected: OverallDeployed,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, DetermineOverallStatus(tt.targets))
		})
	}
}



package deploy

// DetermineOverallStatus computes the aggregate deployment status across all targets
func DetermineOverallStatus(targets []DeployTarget) OverallDeployStatus {
	if len(targets) == 0 {
		return OverallNotDeployed
	}

	deployed := 0
	deploying := 0
	for _, t := range targets {
		switch t.Status {
		case DeployStatusDeployed:
			deployed++
		case DeployStatusDeploying:
			deploying++
		}
	}

	if deployed == len(targets) {
		return OverallDeployed
	}
	if deploying > 0 {
		return OverallDeploying
	}
	if deployed > 0 {
		return OverallPartiallyDeployed
	}
	return OverallNotDeployed
}



package deploy

// DeployStatus represents the deployment state of a target
type DeployStatus string

const (
	DeployStatusDeployed    DeployStatus = "deployed"
	DeployStatusDeploying   DeployStatus = "deploying"
	DeployStatusNotDeployed DeployStatus = "not deployed"
)

func (s DeployStatus) String() string { return string(s) }

// OverallDeployStatus represents the aggregate deployment status across all targets
type OverallDeployStatus string

const (
	OverallNotDeployed       OverallDeployStatus = "Not deployed"
	OverallDeploying         OverallDeployStatus = "Deploying"
	OverallPartiallyDeployed OverallDeployStatus = "Partially deployed"
	OverallDeployed          OverallDeployStatus = "Deployed"
	OverallFetchError        OverallDeployStatus = "Error"
)

func (s OverallDeployStatus) String() string { return string(s) }

// DeployTarget represents a single datacenter deployment status
type DeployTarget struct {
	Datacenter string
	Env        string
	Namespace  string
	Status     DeployStatus
}

// ServiceDeployment holds the deployment targets for a single service
type ServiceDeployment struct {
	Service string
	Targets []DeployTarget
}



package tmux

import "context"

// CommandRunner abstracts shell command execution for testability.
// Same shape as github.CommandRunner but defined locally to avoid cross-package coupling.
type CommandRunner interface {
	Run(ctx context.Context, name string, args ...string) ([]byte, error)
}

// PRSession represents a persistent tmux session for a PR.
type PRSession struct {
	SessionName string // sanitized PR title + number
	PRNumber    int
	PRTitle     string // original title for display
	WorkDir     string // chosen worktree directory
	Branch      string // PR's HeadRefName
	PRURL       string // for Claude prompts
}

// Worktree represents a git worktree discovered from `git worktree list --porcelain`.
type Worktree struct {
	Path   string
	Branch string
}



