		lipgloss.NewStyle().Foreground(gray).Render("enter: submit | esc: cancel")

	box := promptInputStyle.Render(content)

	contentWidth := lipgloss.Width(box)
	contentHeight := lipgloss.Height(box)

	padLeft := (m.width - contentWidth) / 2
	padTop := (m.height - contentHeight) / 2
	if padLeft < 0 {
		padLeft = 0
	}
	if padTop < 0 {
		padTop = 0
	}

	return lipgloss.NewStyle().
		PaddingLeft(padLeft).
		PaddingTop(padTop).
		Render(box)
