package tui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

func renderRepoFilterOverlay(m Model) string {
	var b strings.Builder

	title := overlayTitleStyle.Render("Filter by Repo")
	b.WriteString(title)
	b.WriteString("\n\n")

	if m.repoFilterTextMode {
		b.WriteString(lipgloss.NewStyle().Foreground(white).Render("Enter repo name:"))
		b.WriteString("\n\n")
		b.WriteString(m.repoFilterInput.View())
		b.WriteString("\n\n")
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("enter: apply | esc: cancel"))
	} else {
		// [All] + repo items + [Custom...]
		items := make([]string, 0, len(m.repoFilterItems)+2)
		items = append(items, "[All]")
		items = append(items, m.repoFilterItems...)
		items = append(items, "[Custom...]")

		for i, item := range items {
			style := lipgloss.NewStyle().Foreground(white)
			prefix := "  "
			if i == m.repoFilterCursor {
				prefix = "> "
				style = style.Foreground(green).Bold(true)
			}

			// indicate active filter
			suffix := ""
			if i > 0 && i <= len(m.repoFilterItems) && m.repoFilterItems[i-1] == m.repoFilter {
				suffix = " (active)"
			}
			if i == 0 && m.repoFilter == "" {
				suffix = " (active)"
			}

			b.WriteString(fmt.Sprintf("%s%s%s\n", prefix, style.Render(item), lipgloss.NewStyle().Foreground(gray).Render(suffix)))
		}

		b.WriteString("\n")
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | enter: select | esc: close"))
	}

	content := overlayStyle.Render(b.String())
	return centerOverlay(content, m.width, m.height)
}

func centerOverlay(content string, width, height int) string {
	contentWidth := lipgloss.Width(content)
	contentHeight := lipgloss.Height(content)

	padLeft := (width - contentWidth) / 2
	padTop := (height - contentHeight) / 2
	if padLeft < 0 {
		padLeft = 0
	}
	if padTop < 0 {
		padTop = 0
	}

	return lipgloss.NewStyle().
		PaddingLeft(padLeft).
		PaddingTop(padTop).
		Render(content)
}



