        records := m.sessionStore.RecordsForPR(m.rows[i].PR.Number)
        _, hasActiveSession := m.prSessions[m.rows[i].PR.Number]
        autoEnabled := m.autonomyStore.IsEnabled(m.rows[i].PR.RepoNameWithOwner, m.rows[i].PR.Number)
        m.rows[i].AgentStatus = agentColumnText(records, hasActiveSession, autoEnabled, m.agentNeedsAttention)
    }
}
```

