func TestSessionType_MarshalUnmarshal(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "sessions.json")

	state := SessionState{
		Sessions: []SessionEntry{
			{TmuxSession: "pr-session", Type: SessionTypePR},
			{TmuxSession: "local-session", Type: SessionTypeLocal},
		},
	}

	err := SaveSessions(state, path)
	assert.NoError(t, err)

	loaded := LoadSessions(path)
	assert.Equal(t, SessionTypePR, loaded.Sessions[0].Type)
	assert.Equal(t, SessionTypeLocal, loaded.Sessions[1].Type)
}



package config

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
)

// SessionType distinguishes local work sessions from PR-attached sessions.
type SessionType string

const (
	SessionTypePR    SessionType = "pr"
	SessionTypeLocal SessionType = "local"
)

// SessionEntry tracks a single dashboard-managed tmux session.
type SessionEntry struct {
	TmuxSession  string      `json:"tmux_session"`
	Repo         string      `json:"repo"`
	WorktreePath string      `json:"worktree_path"`
	Branch       string      `json:"branch"`
	PRNumber     int         `json:"pr_number"`
	Type         SessionType `json:"type"`
}

// SessionState is the root object persisted to the sessions file.
type SessionState struct {
	Sessions []SessionEntry `json:"sessions"`
}

// SessionsPath returns the path to the sessions state file.
func SessionsPath() (string, error) {
	dir, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("finding config dir: %w", err)
	}
	return filepath.Join(dir, "pr-workstation", "sessions.json"), nil
}

// LoadSessions reads and parses the session state file. Returns empty state
// (not error) if the file is missing or unparseable. The session state file is
// a cache, not configuration — parse errors are silently recovered from, unlike
// config.LoadFromPath which returns errors for invalid YAML.
func LoadSessions(path string) SessionState {
	data, err := os.ReadFile(path)
	if err != nil {
		return SessionState{}
	}

	var state SessionState
	if err := json.Unmarshal(data, &state); err != nil {
		return SessionState{}
	}
	return state
}

// SaveSessions writes the session state to disk, creating the directory if needed.
func SaveSessions(state SessionState, path string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("creating sessions dir: %w", err)
	}

	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling sessions: %w", err)
	}

	if err := os.WriteFile(path, data, 0644); err != nil {
		return fmt.Errorf("writing sessions: %w", err)
	}
	return nil
}



package deploy

import "time"

// ConductorRunState represents the state of a conductor run for a PR.
type ConductorRunState string

const (
	ConductorRunStateBuilding    ConductorRunState = "Building"
	ConductorRunStateDeploying   ConductorRunState = "Deploying"
	ConductorRunStateBuildFailed ConductorRunState = "Build failed"
	// DeployFailed covers both deploy station failures and STATE_ERRORING.
	ConductorRunStateDeployFailed ConductorRunState = "Deploy failed"
	ConductorRunStateDeployed     ConductorRunState = "Deployed"
	ConductorRunStatePending      ConductorRunState = "Pending"
)

// ConductorTargetStatus is the resolved status of a PR in one conductor target.
type ConductorTargetStatus struct {
	Target  string
	RunGUID string
	State   ConductorRunState
	Error   string // non-empty on failure
}

// ConductorServiceStatus is the conductor deployment status for one service.
type ConductorServiceStatus struct {
	ServiceName    string
	TargetStatuses []ConductorTargetStatus
}

// conductorRunResponse mirrors the JSON from /v4/conductor/{svc}/runs.
type conductorRunResponse struct {
	GUID              string     `json:"guid"`
	TriggeredOn       time.Time  `json:"triggeredOn"`
	EndedAt           *time.Time `json:"endedAt"`
	PreviousCommitSHA string     `json:"previousCommitSha"`
	HeadCommitSHA     string     `json:"headCommitSha"`
	Error             string     `json:"error"`
	LatestUpdate      struct {
		State string `json:"state"`
	} `json:"latestUpdate"`
	Stations struct {
		Build struct {
			Status string `json:"status"`
		} `json:"build"`
		Deploy struct {
			Status string `json:"status"`
		} `json:"deploy"`
	} `json:"stations"`
}

type conductorRunsResponse struct {
	Runs []conductorRunResponse `json:"runs"`
}

type conductorTargetResponse struct {
	Target      string `json:"target"`
	ServiceName string `json:"serviceName"`
	Status      string `json:"status"`
}

type conductorTargetsResponse struct {
	Targets []conductorTargetResponse `json:"targets"`
}



package github

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestExtractMergeQueueStatus(t *testing.T) {
	tests := []struct {
		name     string
		labels   []string
		expected MergeQueueStatus
	}{
		{
			name:     "no labels",
			labels:   nil,
			expected: MQNone,
		},
		{
			name:     "no merge queue label",
			labels:   []string{"bug", "changes:myservice"},
			expected: MQNone,
		},
		{
			name:     "queued",
			labels:   []string{"mergequeue-status: queued"},
			expected: MQQueued,
		},
		{
			name:     "in_progress",
			labels:   []string{"mergequeue-status: in_progress"},
			expected: MQInProgress,
		},
		{
			name:     "rejected",
			labels:   []string{"mergequeue-status: rejected"},
			expected: MQRejected,
		},
		{
			name:     "error",
			labels:   []string{"mergequeue-status: error"},
			expected: MQError,
		},
		{
			name:     "retrying",
			labels:   []string{"mergequeue-status: retrying"},
			expected: MQRetrying,
		},
		{
			name:     "unknown value falls back to none",
			labels:   []string{"mergequeue-status: done"},
			expected: MQNone,
		},
		{
			name:     "merge queue label among other labels",
			labels:   []string{"bug", "mergequeue-status: queued", "changes:myservice"},
			expected: MQQueued,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := ExtractMergeQueueStatus(tt.labels)
			assert.Equal(t, tt.expected, result)
		})
	}
}



