package session

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strconv"
)

// AutonomyStore persists per-PR autonomy flags in autonomy.json, separate
// from history.json to avoid mixing user preferences with event records.
type AutonomyStore struct {
	path  string
	flags map[string]bool // "owner/repo/prNumber" → true
}

// NewAutonomyStore creates an AutonomyStore targeting
// /sessions/autonomy.json. If configDir is empty, it defaults to
// os.UserConfigDir()/pr-workstation.
func NewAutonomyStore(configDir string) *AutonomyStore {
	if configDir == "" {
		dir, err := os.UserConfigDir()
		if err != nil {
			dir = os.TempDir()
		}
		configDir = filepath.Join(dir, "pr-workstation")
	}
	return &AutonomyStore{
		path:  filepath.Join(configDir, "sessions", "autonomy.json"),
		flags: make(map[string]bool),
	}
}

// Load reads the autonomy flags from disk. A missing or corrupted file results
// in empty flags with a warning logged — the store degrades gracefully.
func (a *AutonomyStore) Load() error {
	data, err := os.ReadFile(a.path)
	if err != nil {
		if !os.IsNotExist(err) {
			log.Printf("warning: could not read autonomy flags at %s: %v", a.path, err)
		}
		a.flags = make(map[string]bool)
		return nil
	}

	var flags map[string]bool
	if err := json.Unmarshal(data, &flags); err != nil {
		log.Printf("warning: corrupted autonomy flags at %s: %v", a.path, err)
		a.flags = make(map[string]bool)
		return nil
	}

	a.flags = flags
	return nil
}

// Save writes the current autonomy flags to disk, creating directories as needed.
func (a *AutonomyStore) Save() error {
	dir := filepath.Dir(a.path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("creating autonomy store directory: %w", err)
	}

	data, err := json.MarshalIndent(a.flags, "", "  ")
	if err != nil {
		return fmt.Errorf("marshalling autonomy flags: %w", err)
	}

	if err := os.WriteFile(a.path, data, 0o644); err != nil {
		return fmt.Errorf("writing autonomy flags: %w", err)
	}
	return nil
}

// Toggle flips the autonomy flag for the given PR. Enabling adds the key;
// disabling removes it so the file only stores enabled PRs.
func (a *AutonomyStore) Toggle(repo string, prNumber int) {
	key := autonomyKey(repo, prNumber)
	if a.flags[key] {
		delete(a.flags, key)
	} else {
		a.flags[key] = true
	}
	if err := a.Save(); err != nil {
		log.Printf("warning: could not save autonomy flags: %v", err)
	}
}

// IsEnabled reports whether autonomy is enabled for the given PR.
func (a *AutonomyStore) IsEnabled(repo string, prNumber int) bool {
	return a.flags[autonomyKey(repo, prNumber)]
}

// EnabledPRs returns a copy of the flags map.
func (a *AutonomyStore) EnabledPRs() map[string]bool {
	result := make(map[string]bool, len(a.flags))
	for k, v := range a.flags {
		result[k] = v
	}
	return result
}

func autonomyKey(repo string, prNumber int) string {
	return repo + "/" + strconv.Itoa(prNumber)
}



package session

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestStatusFilePath(t *testing.T) {
	got := StatusFilePath("/home/user/.config/pr-workstation", "abc123")
	assert.Equal(t, "/home/user/.config/pr-workstation/sessions/agent-abc123.status", got)
}

func TestReadStatusFile(t *testing.T) {
	t.Run("completed status", func(t *testing.T) {
		dir := t.TempDir()
		path := filepath.Join(dir, "agent-s1.status")
		err := os.WriteFile(path, []byte(`{"outcome":"completed"}`), 0o644)
		assert.NoError(t, err)

		s, err := ReadStatusFile(path)
		assert.NoError(t, err)
		assert.Equal(t, "completed", s.Outcome)
		assert.Empty(t, s.Error)
	})

	t.Run("failed status", func(t *testing.T) {
		dir := t.TempDir()
		path := filepath.Join(dir, "agent-s2.status")
		err := os.WriteFile(path, []byte(`{"outcome":"failed","error":"something went wrong"}`), 0o644)
		assert.NoError(t, err)

		s, err := ReadStatusFile(path)
		assert.NoError(t, err)
		assert.Equal(t, "failed", s.Outcome)
		assert.Equal(t, "something went wrong", s.Error)
	})

	t.Run("missing file returns nil, nil", func(t *testing.T) {
		s, err := ReadStatusFile("/nonexistent/path/agent-x.status")
		assert.NoError(t, err)
		assert.Nil(t, s)
	})

	t.Run("malformed JSON returns nil, err", func(t *testing.T) {
		dir := t.TempDir()
		path := filepath.Join(dir, "agent-bad.status")
		err := os.WriteFile(path, []byte(`not json`), 0o644)
		assert.NoError(t, err)

		s, err := ReadStatusFile(path)
		assert.Error(t, err)
		assert.Nil(t, s)
	})
}



