func TestParseSessionType(t *testing.T) {
	tests := []struct {
		name        string
		input       string
		expected    SessionType
		expectedErr string
	}{
		{
			name:     "manual",
			input:    "manual",
			expected: SessionTypeManual,
		},
		{
			name:     "autonomous",
			input:    "autonomous",
			expected: SessionTypeAutonomous,
		},
		{
			name:        "invalid",
			input:       "unknown",
			expectedErr: "invalid session type: unknown",
		},
		{
			name:        "empty",
			input:       "",
			expectedErr: "invalid session type:",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := ParseSessionType(tt.input)

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Equal(t, tt.expected, result)
		})
	}
}

