package tui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

var githubActionItems = []string{"close", "comment", "mark ready", "request merge", "update branch"}

func renderGithubActionsOverlay(m Model) string {
	var b strings.Builder

	title := overlayTitleStyle.Render("GitHub Actions")
	b.WriteString(title)
	b.WriteString("\n\n")

	if m.githubActionsCommentMode {
		b.WriteString(lipgloss.NewStyle().Foreground(white).Render("Comment body:"))
		b.WriteString("\n\n")
		b.WriteString(m.githubActionsCommentInput.View())
		b.WriteString("\n\n")
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("enter: submit | esc: back"))
	} else {
		for i, item := range githubActionItems {
			style := lipgloss.NewStyle().Foreground(white)
			prefix := "  "
			if i == m.githubActionsCursor {
				prefix = "> "
				style = style.Foreground(green).Bold(true)
			}
			b.WriteString(fmt.Sprintf("%s%s\n", prefix, style.Render(item)))
		}

		b.WriteString("\n")
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | enter: select | esc: close"))
	}

	content := overlayStyle.Render(b.String())
	return centerOverlay(content, m.width, m.height)
}



package tui

import (
	"fmt"
	"testing"

	"github.com/DataDog/pr-workstation/internal/config"
	"github.com/DataDog/pr-workstation/internal/tmux"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/stretchr/testify/assert"
)

func updateImport(t *testing.T, m Model, msg tea.Msg) (*Model, tea.Cmd) {
	t.Helper()
	result, cmd := m.Update(msg)
	updated, ok := result.(*Model)
	if !ok {
		v := result.(Model)
		return &v, cmd
	}
	return updated, cmd
}

func TestIKeyOpensImportOverlay(t *testing.T) {
	m := newTestModel()

	updated, cmd := updateImport(t, m, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'I'}})

	assert.True(t, updated.showImportWork)
	assert.NotNil(t, cmd)
}

func TestImportOverlay_EscCloses(t *testing.T) {
	m := newTestModel()
	m.showImportWork = true
	m.importWorkSessions = []string{"main", "other"}

	updated, _ := updateImport(t, m, tea.KeyMsg{Type: tea.KeyEsc})

	assert.False(t, updated.showImportWork)
}

func TestImportOverlay_Navigation(t *testing.T) {
	m := newTestModel()
	m.showImportWork = true
	m.importWorkSessions = []string{"main", "other", "third"}
	m.importWorkCursor = 0

	updated, _ := updateImport(t, m, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'j'}})
	assert.Equal(t, 1, updated.importWorkCursor)

	updated.importWorkCursor = 2
	updated2, _ := updateImport(t, *updated, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'j'}})
	assert.Equal(t, 2, updated2.importWorkCursor) // stays at end

	updated3, _ := updateImport(t, *updated2, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'k'}})
	assert.Equal(t, 1, updated3.importWorkCursor)
}

func TestImportOverlay_EnterStartsResolving(t *testing.T) {
	m := newTestModel()
	m.showImportWork = true
	m.importWorkSessions = []string{"main", "other"}
	m.importWorkCursor = 0

	updated, cmd := updateImport(t, m, tea.KeyMsg{Type: tea.KeyEnter})

	assert.True(t, updated.importWorkResolving)
	assert.NotNil(t, cmd)
}

func TestTmuxSessionsListedMsg_FiltersManaged(t *testing.T) {
	m := newTestModel()
	m.showImportWork = true
	m.sessionState = config.SessionState{
		Sessions: []config.SessionEntry{
			{TmuxSession: "managed-session", Type: config.SessionTypePR},
		},
	}

	updated, _ := updateImport(t, m, tmuxSessionsListedMsg{
		sessions: []string{"managed-session", "main", "other"},
	})

	assert.Equal(t, []string{"main", "other"}, updated.importWorkSessions)
}

func TestSessionInfoResolvedMsg_AddsLocalEntry(t *testing.T) {
	m := newTestModel()
	m.showImportWork = true
	m.importWorkResolving = true

	updated, _ := updateImport(t, m, sessionInfoResolvedMsg{
		sessionName: "main",
		info: tmux.RepoInfo{
			Repo:         "dd-source",
			Branch:       "main",
			WorktreePath: "/home/user/dd/dd-source",
		},
	})

	assert.False(t, updated.showImportWork)
	assert.Len(t, updated.sessionState.Sessions, 1)
	entry := updated.sessionState.Sessions[0]
	assert.Equal(t, "main", entry.TmuxSession)
	assert.Equal(t, "dd-source", entry.Repo)
	assert.Equal(t, "main", entry.Branch)
	assert.Equal(t, "/home/user/dd/dd-source", entry.WorktreePath)
	assert.Equal(t, config.SessionTypeLocal, entry.Type)
	assert.Contains(t, updated.notification, "main")
}

func TestSessionInfoResolvedMsg_ErrorShowsNotification(t *testing.T) {
	m := newTestModel()
	m.showImportWork = true
	m.importWorkResolving = true

	updated, _ := updateImport(t, m, sessionInfoResolvedMsg{
		sessionName: "main",
		err:         fmt.Errorf("not a git repo"),
	})

	assert.False(t, updated.showImportWork)
	assert.Contains(t, updated.notification, "not a git repo")
	assert.Len(t, updated.sessionState.Sessions, 0)
}



package tui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

func renderImportWorkOverlay(m Model) string {
	var b strings.Builder

	b.WriteString(overlayTitleStyle.Render("Import Work — Select Tmux Session"))
	b.WriteString("\n")

	if m.importWorkResolving {
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("  Resolving session info..."))
	} else if m.importWorkSessions == nil {
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("  Loading sessions..."))
	} else if len(m.importWorkSessions) == 0 {
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("  No unmanaged tmux sessions found"))
	} else {
		for i, sess := range m.importWorkSessions {
			cursor := "  "
			if i == m.importWorkCursor {
				cursor = "> "
			}
			text := lipgloss.NewStyle().Foreground(white).Render(sess)
			b.WriteString(fmt.Sprintf("%s%s\n", cursor, text))
		}
	}

	b.WriteString("\n")
	b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | enter: import | esc: cancel"))

	content := overlayStyle.Render(b.String())

	contentWidth := lipgloss.Width(content)
	contentHeight := lipgloss.Height(content)

	padLeft := (m.width - contentWidth) / 2
	padTop := (m.height - contentHeight) / 2
	if padLeft < 0 {
		padLeft = 0
	}
	if padTop < 0 {
		padTop = 0
	}

	return lipgloss.NewStyle().
		PaddingLeft(padLeft).
		PaddingTop(padTop).
		Render(content)
}



package tui

import (
	"fmt"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

// WorktreeOption represents a single entry in the worktree picker overlay.
type WorktreeOption struct {
	Path        string // worktree directory
	Branch      string // current branch
	InUseBy     string // session name if assigned to another PR, empty if free
	IsCreateNew bool   // true for the "Create new worktree" option
}

func renderWorktreePickerOverlay(m Model) string {
	var b strings.Builder

	title := overlayTitleStyle.Render(fmt.Sprintf("Select worktree for #%d", m.worktreePickerPR))
	b.WriteString(title)
	b.WriteString("\n")
	if m.worktreePickerBranch != "" {
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render(fmt.Sprintf("branch: %s", m.worktreePickerBranch)))
		b.WriteString("\n")
	}
	b.WriteString("\n")

	for i, opt := range m.worktreeOptions {
		style := lipgloss.NewStyle().Foreground(white)
		prefix := "  "
		if i == m.worktreePickerIdx {
			prefix = "> "
			style = style.Foreground(green).Bold(true)
		}

		if opt.IsCreateNew {
			b.WriteString(fmt.Sprintf("%s%s\n", prefix, style.Render("[Create new worktree]")))
			continue
		}

		label := opt.Path
		if opt.Branch != "" {
			label += fmt.Sprintf(" (%s)", opt.Branch)
		}
		if opt.InUseBy != "" {
			label += lipgloss.NewStyle().Foreground(gray).Render(fmt.Sprintf(" [in use: %s]", opt.InUseBy))
		}

		b.WriteString(fmt.Sprintf("%s%s\n", prefix, style.Render(label)))
	}

	b.WriteString("\n")
	b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | enter: select | esc: cancel"))

	content := overlayStyle.Render(b.String())
	return centerOverlay(content, m.width, m.height)
}



# 5. Action-Oriented PR Dashboard

## Status

Accepted

> This ADR was retroactively extracted from existing code. The decision was
> made implicitly during initial development.

Date: 2026-03-02

## Context

GitHub's pull request UI shows the current state of a PR but leaves it to the
developer to figure out what to do next. When managing multiple PRs across
multiple repos, this mental overhead adds up: is this PR blocked on CI? Does
it need my attention? Can I merge it? Is it deployed?

Developers need a single view that answers "what should I do next?" for each
of their PRs, not just "what is the current state?"

## Decision

We will build the dashboard around computed status and suggested action for
every PR. The dashboard does not just display raw PR state — it interprets it
and tells the developer what to do.

The status computation pipeline (`DetermineStatus` in `internal/github/status.go`):
1. If merged → Merged
2. If closed → Open
3. If merge queue active → In merge queue / MQ rejected
4. If mergeable == CONFLICTING → Has conflicts
5. If unresolved review threads > 0 → Changes requested
6. If latest human review is CHANGES_REQUESTED → Changes requested
7. If draft with CI failure → Draft (CI failing)
8. If draft → Draft
9. If CI is failing → CI failing
10. If no human reviews → Waiting for reviews
11. If all reviewers approved → Approved
12. Default → Reviewed (comments)

The ordering is deliberate: merge conflicts (step 4) are checked before
feedback-related states (steps 5-6) because conflicts are a hard blocker
that prevents merging regardless of review status. Feedback-related states
are checked before the draft early-return (steps 7-8) so that draft PRs
with review comments still surface the "address feedback" action.

The action computation (`DetermineAction` in `internal/github/action.go`)
maps status to a concrete next step:
- CI failing → Fix CI
- Changes requested → Address feedback
- Approved → Merge
- Has conflicts → Resolve conflicts
- MQ rejected → Address MQ
- All others → None (no action needed from the developer)

Status and action are displayed as dedicated columns in the PR table. The
"Needs Action" filter shows only PRs where `IsActionable()` returns true,
giving developers a focused view of what requires their attention.

These functions are pure — they take a PR struct and return a status/action
enum with no side effects. This makes them the most testable and most
critical code in the application.

## Consequences

**Positive:**
- Developers can glance at the dashboard and immediately know which PRs need
  work and what kind of work
- The "Needs Action" filter eliminates noise from PRs that are waiting on
  others
- Pure function implementation means the status/action logic is exhaustively
  testable (20+ test cases for `DetermineStatus` alone)
- The computed action feeds directly into the agent-first workspace experience
  (ADR-0004), creating a seamless flow from "what to do" to "doing it"

**Negative:**
- The status determination logic encodes opinions about priority (e.g.,
  unresolved threads take precedence over CI failures) that may not match
  every developer's workflow
- Edge cases in GitHub's review model (dismissed reviews, re-requested
  reviews, bot reviews) require careful handling and ongoing maintenance
- Bot author filtering uses a hardcoded list plus `[bot]` suffix matching,
  which may miss new bot accounts

**Neutral:**
- The status/action enums are string-based types with constants, making the
  set of valid values explicit and easy to extend

## Agent Metadata


- Service: pr-status-dash
- Domain: Core business logic and PR status computation
- Key files: internal/github/status.go, internal/github/action.go, internal/github/types.go, internal/tui/filter.go
- Related ADRs: 0004, 0001
- Implementation plan: n/a (retroactive)



# 9. Tmux Session-Per-PR Workspace with Persistence

## Status

Accepted

> This ADR was retroactively extracted from existing code. The decision was
> made implicitly during development.

Date: 2026-03-02

## Context

Working on a pull request requires being in the right directory with the right
branch checked out. When managing multiple PRs across repos, developers
constantly switch between branches and directories. If they step away from a
PR and come back later, they need to re-establish their working context.

Git worktrees allow multiple branches to be checked out simultaneously in
separate directories. Tmux sessions persist terminal state across
disconnections and allow named, switchable contexts.

## Decision

We will create a dedicated tmux session paired with a git worktree for each
PR the developer works on. Pressing enter on a PR in the dashboard either
creates a new session or switches to an existing one.

The workspace model:
- Each PR gets a tmux session named `-` (max 40
  characters, truncated at word boundary)
- The session's working directory is a git worktree for the PR's branch,
  located at `~/dd//work/`
- If a worktree already exists for the PR's branch, it is reused
- The initial window in the session runs Claude with a context-aware command
  (per ADR-0004)
- Sessions survive dashboard restarts — on startup, the dashboard discovers
  existing tmux sessions and maps them back to PRs by extracting the PR
  number from the session name suffix

A `sessionInUse` map prevents two PRs from being assigned the same worktree,
avoiding branch conflicts.

Users can destroy sessions with the `D` key (moved from `W` per ADR-0014), which kills the tmux session.

## Consequences

**Positive:**
- Developers can pick up where they left off on any PR — the tmux session
  preserves terminal history, running processes, and editor state
- Branch isolation via worktrees means working on one PR doesn't affect
  another
- Session discovery on startup means the dashboard always reflects the
  developer's actual workspace state
- One keypress to enter a fully contextualized workspace from the dashboard

**Negative:**
- Worktrees consume disk space (a full working copy per branch)
- Tmux session naming is limited to 40 characters, which can truncate
  descriptive PR titles
- The session name → PR number mapping relies on the PR number being the
  last segment after a hyphen, which could collide with PR titles ending
  in numbers
- Stale sessions accumulate if PRs are closed without cleaning up the tmux
  session

**Neutral:**
- Users who don't use tmux in their normal workflow need to learn basic tmux
  navigation to benefit from this feature
- Git worktree support requires git 2.30+, which is widely available

## Agent Metadata


- Service: pr-status-dash
- Domain: Workspace management and developer experience
- Key files: internal/tmux/session.go, internal/tmux/types.go, internal/tui/commands.go
- Related ADRs: 0004, 0012
- Implementation plan: n/a (retroactive)



# 10. Separate Conductor Rollouts from Availability Tracking

## Status

Accepted

> This ADR was retroactively extracted from existing code. The decision was
> made implicitly during development.

Date: 2026-03-02

## Context

After a PR is merged at Datadog, its changes go through two distinct
deployment phases that are tracked by different systems:

1. **Conductor rollouts** — the continuous delivery platform that builds and
   deploys service artifacts to specific targets (staging, canary, production
   cells). Conductor tracks the build/deploy lifecycle: building, deploying,
   deployed, build failed, deploy failed. Each service has multiple targets,
   and each target has its own rollout state.

2. **Availability (whereismycode)** — tracks whether the PR's changes are
   actually running in each datacenter/environment combination. This answers
   "is my code live?" rather than "has the deploy completed?"

These are different questions with different data sources:
- Conductor data comes from the orchplatform API (`orchplatform-api.us1.ddbuild.io`)
- Availability data comes from the devflow API (`devflow-api.us1.ddbuild.io`)

## Decision

We will model Conductor rollout status and Availability status as separate,
independent tracking systems with their own clients, types, display columns,
and refresh logic.

Conductor integration (`internal/deploy/conductor_client.go`):
- Queries `/v3/conductor/{service}/targets` for the list of deployment targets
- Queries `/v4/conductor/{service}/runs` per target for recent run history
- Matches runs to the PR by finding the run triggered closest to (but after)
  the PR's merge time, paginating through run history until a pre-merge
  boundary is found
- Maps Conductor state machine states to display states: Building, Deploying,
  Deployed, Build failed, Deploy failed, Pending
- Authenticated via `ddtool`

Availability integration (`internal/deploy/client.go`):
- Queries `/internal/api/v2/devflow/execute/whereismycode` with the PR URL
- Parses ASCII tables embedded in the API's Markdown response to extract
  per-datacenter/environment deployment status
- Maps status to: deployed, deploying, not deployed
- Aggregates across all targets into an overall status
- Authenticated via `authanywhere`

The TUI displays both as separate columns: "Conductor" shows per-target
build/deploy state, "Availability" shows per-datacenter live status.

## Consequences

**Positive:**
- Developers can distinguish between "the deploy completed" (Conductor) and
  "the code is live" (Availability) — these can differ when deploys succeed
  but rollouts are gradual
- Each tracking system can fail independently without affecting the other
- The Conductor detail overlay shows granular per-target state (which cell
  is deploying, which failed), while Availability shows the broader picture
- Different authentication mechanisms (ddtool vs authanywhere) are cleanly
  separated

**Negative:**
- Two API integrations to maintain, each with their own auth, parsing, and
  error handling
- The Devflow API returns ASCII tables embedded in Markdown, requiring a
  brittle text parser that could break if the response format changes
- Conductor run matching by timestamp (closest run triggered after merge) is a
  heuristic that could misattribute runs if no run boundary is found within 100
  fetched runs
- Two columns of deployment data can be confusing for developers unfamiliar
  with the distinction between Conductor and Availability

**Neutral:**
- Both integrations are optional (per ADR-0008) — the dashboard works
  without either

## Agent Metadata


- Service: pr-status-dash
- Domain: Deployment tracking and status aggregation
- Key files: internal/deploy/client.go, internal/deploy/conductor_client.go, internal/deploy/conductor_types.go, internal/deploy/types.go, internal/deploy/status.go
- Related ADRs: 0008, 0011
- Implementation plan: n/a (retroactive)



# 13. New Work Spawning with Persistent Session State

## Status

Accepted

Date: 2026-03-02

## Context

The dashboard currently operates as a reactive tool — it shows PRs that already
exist on GitHub and lets the developer jump into them. But development often
starts *before* a PR exists: a developer has an idea, wants to start fresh work
in a repo, and only opens a PR once the work has taken shape.

Today, the only way to start new work is to leave the dashboard, manually create
a worktree, open a tmux session, and begin coding. The dashboard doesn't know
about this work until a PR is opened and appears in the GitHub search results.
This gap means the dashboard cannot serve as the single command center for all
active development work.

Additionally, the current session discovery mechanism (ADR-0009) relies on
parsing tmux session names to extract PR numbers. This convention-based approach
has known fragility: PR titles ending in numbers can collide with the PR number
suffix, and there is no way to track sessions that don't correspond to a PR.
Introducing "local work" sessions — which have no PR number — makes this naming
convention insufficient as the sole source of truth.

These two problems — the lack of pre-PR work support and the fragility of
convention-based session tracking — are tightly coupled. Solving either one in
isolation would leave the architecture inconsistent: new work spawning requires
persistent tracking (no PR to discover from), and a session state file without
new work spawning would be solving a fragility problem with no immediate
forcing function. This ADR addresses both together.

## Decision Drivers

- The dashboard should be the single entry point for all development work, not
  just existing PRs
- Local work sessions need persistent tracking across dashboard restarts, but
  have no PR to anchor to
- The current tmux session name parsing is fragile and cannot represent sessions
  without PR numbers
- The lifecycle from local work to PR should be seamless, not require manual
  re-creation of the workspace

## Considered Options

### Option 1: Extend tmux naming conventions

Encode local work metadata in the tmux session name (e.g.,
`local--`), and parse these alongside PR sessions on startup.

- Good: No new state file; consistent with existing approach
- Bad: The application truncates session name prefixes to 40 characters (per
  the existing convention); encoding repo + branch often exceeds this, leaving
  names unreadable
- Bad: Doubles down on the fragile name-parsing approach that ADR-0009 already
  identifies as a weakness
- Bad: Cannot store additional metadata (seed prompt, creation time) that would
  be useful for local work

### Option 2: Persistent session state file

Introduce a state file that maps worktree paths to session metadata. Use this
as the source of truth for session discovery instead of tmux name parsing.

- Good: Decouples session identity from tmux naming conventions
- Good: Can store rich metadata (repo, branch, PR number, creation time)
- Good: Local work items and PR sessions use the same tracking mechanism
- Good: The local → PR lifecycle transition is a metadata update, not a
  re-creation
- Bad: Introduces persistent state (contradicts the spirit of ADR-0006)
- Bad: State file can become stale if tmux sessions are killed outside the
  dashboard

### Option 3: Use tmux environment variables

Store metadata as tmux environment variables on each session, queryable via
`tmux show-environment`.

- Good: Metadata lives with the session, no separate state file
- Good: Automatically cleaned up when session is destroyed
- Bad: Cannot discover local work items if the tmux session was killed — the
  metadata disappears with the session
- Bad: Requires tmux-specific knowledge to debug

## Decision

We will implement new work spawning with a persistent session state file
(Option 2).

### New Work Flow

Pressing `N` from the main dashboard view initiates a multi-step overlay flow:

1. **Repository selection**: Scan `~/dd/` for all directories that are git
   repositories (inheriting the directory convention from ADR-0012). Present
   them in a picker overlay with j/k navigation.

2. **Worktree selection**: After selecting a repo, present the standard worktree
   picker (same as the existing PR flow). Options include existing worktrees and
   "Create new." If creating new, the user enters a worktree name via a text
   input. This name becomes the branch name, created from the repo's default
   branch (determined via `git symbolic-ref refs/remotes/origin/HEAD`).

3. **Seed prompt**: Present a free-form text input where the user types an
   initial prompt for Claude. This prompt provides the starting context for the
   agent session.

4. **Session creation**: Create a tmux session named after the worktree/branch,
   with Claude launched using the seed prompt as a CLI argument (e.g.,
   `claude ''`), consistent with the existing PR session pattern
   in `ensureWindowAndSwitchCmd`. The session is tracked in the state file.

### Session State File

Introduce a persistent state file at `~/.config/pr-workstation/sessions.json`
that tracks all dashboard-managed sessions. The implementation ensures the
config directory exists before writing (it may already exist from
`config.yaml`). If the state file is missing or unparseable on startup, the
dashboard starts with an empty session list and falls back to tmux name parsing
for backward compatibility.

```json
{
  "sessions": [
    {
      "tmux_session": "fix-auth-bug-1234",
      "repo": "DataDog/dd-source",
      "worktree_path": "/Users/dev/dd/dd-source-fix-auth-bug",
      "branch": "fix-auth-bug",
      "pr_number": 1234,
      "type": "pr"
    },
    {
      "tmux_session": "add-caching-layer",
      "repo": "DataDog/dd-source",
      "worktree_path": "/Users/dev/dd/dd-source-add-caching-layer",
      "branch": "add-caching-layer",
      "pr_number": 0,
      "type": "local"
    }
  ]
}
```

The state file is written to disk whenever a session is created, updated
(local-to-PR transition), or removed (session destroyed or tmux validation
failure on startup).

The state file becomes the source of truth for session-to-workspace mapping,
replacing the current tmux name parsing.

**On startup**, the dashboard:

1. Reads the state file to get tracked sessions
2. Validates each entry against actual tmux sessions (`tmux has-session`)
3. Removes entries whose tmux sessions no longer exist
4. Merges with tmux sessions discovered via name parsing (backward compatibility
   during migration)

**On each refresh cycle** (every 3 minutes, alongside the GitHub PR fetch), the
dashboard re-validates all state file entries against live tmux state. Entries
whose tmux sessions no longer exist are pruned and the state file is persisted.
This keeps the state file in sync when sessions are killed outside the dashboard
(e.g., via `tmux kill-session` or terminal close).

### Dashboard Display

Local work items appear as rows in the PR table with these characteristics:

- **PR number column**: Displays "local" instead of a number
- **Positioning**: Local work rows appear at the top of the table, above PR rows
- **Repository**: Shows the repo name, same as PR rows
- **Title/branch**: Shows the worktree branch name
- **Available actions**: Enter (switch to session), W (destroy session),
  `o` (open GitHub's "new PR" page in the browser for the branch), and
  `O` (spawn a headless Claude agent to create a draft PR)

Actions that require an open PR (GitHub Actions overlay, deploy, integrate) are
**not available** for local rows. The key handler checks the row type before
allowing these actions.

### Local-to-PR Lifecycle

There are three paths from local work to PR: manual, agent-assisted, and
auto-detected.

#### Manual: `o` key (open in browser)

Pressing `o` on a local work row opens GitHub's "new PR" page in the browser,
pre-filled with the branch. On PR rows, `o` retains its existing behavior
(opens the PR URL in the main view, or opens conductor/CI URLs in the PR detail
overlay). Local rows will not appear in the PR detail overlay, so only the main
view `o` handler needs the row-type branch. This gives the developer full
control over title, description, and reviewers through GitHub's UI.

#### Agent-assisted: `O` key (open with agent)

Pressing `O` (shift-o) on a local work row spawns a headless Claude agent to
create a draft PR automatically.

The dashboard spawns Claude in headless mode (`claude --yes --print`) with a
prompt that instructs it to:

1. Read the diff and commit history on the branch
2. Write a meaningful PR title and description based on the changes
3. Commit any uncommitted work
4. Push the branch to origin
5. Create a draft PR using `gh pr create --draft`

This follows the same pattern as the existing `commit-push-pr` command, which
gathers git status, diff, and branch context before creating the commit and PR
in a single pass. The dashboard passes the repo directory and branch name as
context in the prompt.

While the agent is working, the local row shows a spinner or status indicator.
On completion, the dashboard reads the PR number from the agent's output.

On PR rows, `O` is a no-op (the PR already exists).

#### Auto-detected: external PR creation

On each GitHub refresh cycle, the dashboard checks whether any local work
branch matches a newly-fetched PR's `HeadRefName` in the same repo. If a
match is found, the local entry is automatically transitioned — the same as
if the user had created the PR via `o` or `O`.

This handles the case where the developer opens a PR from the command line,
from GitHub's UI, or from a Claude session outside the dashboard.

#### Transition mechanics (both paths)

On successful PR creation or detection:

1. The state file entry is updated: `type` changes from `"local"` to `"pr"`,
   `pr_number` is set to the new PR number, and `tmux_session` is renamed to
   match the PR naming convention (`-`)
2. On the next GitHub refresh cycle, the PR appears in the normal search
   results and the local entry is removed from the state file — the PR row
   takes over

This ensures a seamless transition: the tmux session, worktree, and branch are
all preserved. Only the tracking mechanism changes from local state to GitHub.

## Consequences

**Positive:**
- The dashboard becomes a true command center for all development work, not just
  existing PRs
- One keypress to go from "I have an idea" to "an agent is working on it in the
  right repo and branch"
- The state file provides more reliable session tracking than tmux name parsing,
  fixing a known weakness in ADR-0009
- The local → PR transition is seamless — no need to manually recreate the
  workspace
- Seed prompts give Claude immediate context, reducing the "cold start" problem
  for new work

**Negative:**
- Introduces persistent local state, which ADR-0006 explicitly avoided. The
  state file must be treated as a cache that can be rebuilt, not as
  authoritative data — if it's deleted, local work rows disappear but tmux
  sessions and worktrees still exist
- The state file can become stale if tmux sessions are killed outside the
  dashboard (mitigated by validation on startup and on each 3-minute refresh
  cycle)
- Scanning `~/dd/` for git repos adds startup latency proportional to the
  number of directories (mitigated by only scanning on `N` press, not on
  startup)
- The multi-step overlay flow (repo → worktree → prompt) is more complex than
  the existing single-step worktree picker
- Repository discovery inherits ADR-0012's `~/dd/` convention — repos cloned
  elsewhere won't appear in the picker

**Neutral:**
- The state file format is intentionally simple JSON. If it needs to evolve, the
  dashboard can migrate it or regenerate it from tmux sessions
- ADR-0006 is not superseded — ephemeral state remains the default for PR data.
  The state file only tracks session mappings, which have no external API
  equivalent to re-fetch from
- Backward compatibility with tmux name parsing is maintained during migration
  but can be removed once all sessions are tracked in the state file

## Agent Metadata


- Service: pr-status-dash
- Domain: Workspace management, session lifecycle, developer experience
- Key files: internal/tui/model.go, internal/tui/commands.go, internal/tui/overlay_worktree.go, internal/tmux/session.go, internal/tmux/types.go, internal/config/config.go
- Related ADRs: 0004, 0006, 0009, 0012
- Implementation plan: docs/adrs/0013-new-work-spawning-with-persistent-session-state.plan.md



package deploy

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

func TestFetchTargets(t *testing.T) {
	tests := []struct {
		name        string
		statusCode  int
		body        string
		expectedLen int
		expectedErr string
	}{
		{
			name:        "success",
			statusCode:  http.StatusOK,
			body:        `{"targets": [{"target": "prod", "serviceName": "my-svc"}, {"target": "staging", "serviceName": "my-svc"}]}`,
			expectedLen: 2,
		},
		{
			name:        "server error",
			statusCode:  http.StatusInternalServerError,
			body:        `{"error": "internal"}`,
			expectedErr: "conductor API returned 500",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				assert.Equal(t, http.MethodGet, r.Method)
				assert.Contains(t, r.URL.Path, "/v3/conductor/my-svc/targets")
				assert.Equal(t, "Bearer test-token", r.Header.Get("Authorization"))
				w.WriteHeader(tt.statusCode)
				w.Write([]byte(tt.body))
			}))
			defer server.Close()

			client := &ConductorClient{
				BaseURL:       server.URL,
				TokenProvider: &mockTokenProvider{token: "test-token"},
				HTTP:          server.Client(),
			}

			targets, err := client.fetchTargets(context.Background(), "my-svc")

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Len(t, targets, tt.expectedLen)
		})
	}
}

func TestFetchRuns(t *testing.T) {
	tests := []struct {
		name        string
		statusCode  int
		body        string
		expectedLen int
		expectedErr string
	}{
		{
			name:        "success",
			statusCode:  http.StatusOK,
			body:        `{"runs": [{"guid": "abc-123", "triggeredOn": "2026-02-27T10:00:00Z", "latestUpdate": {"state": "STATE_DONE"}, "stations": {"build": {"status": "STATION_SUCCESSFUL"}, "deploy": {"status": "STATION_SUCCESSFUL"}}}]}`,
			expectedLen: 1,
		},
		{
			name:        "error response",
			statusCode:  http.StatusUnauthorized,
			body:        `{"message": "unauthorized"}`,
			expectedErr: "conductor API returned 401",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				assert.Contains(t, r.URL.Path, "/v4/conductor/my-svc/runs")
				assert.Contains(t, r.URL.RawQuery, "target=prod")
				assert.Contains(t, r.URL.RawQuery, "limit=5")
				w.WriteHeader(tt.statusCode)
				w.Write([]byte(tt.body))
			}))
			defer server.Close()

			client := &ConductorClient{
				BaseURL:       server.URL,
				TokenProvider: &mockTokenProvider{token: "test-token"},
				HTTP:          server.Client(),
			}

			runs, err := client.fetchRuns(context.Background(), "my-svc", "prod", 5)

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Len(t, runs, tt.expectedLen)
		})
	}
}

func TestMapRunToState(t *testing.T) {
	tests := []struct {
		name          string
		latestState   string
		deployStatus  string
		buildStatus   string
		expectedState ConductorRunState
	}{
		{"building", "STATE_BUILDING", "", "", ConductorRunStateBuilding},
		{"waiting", "STATE_WAITING", "", "", ConductorRunStateBuilding},
		{"transforming", "STATE_TRANSFORMING", "", "", ConductorRunStateBuilding},
		{"deploying", "STATE_DEPLOYING", "", "", ConductorRunStateDeploying},
		{"resuming", "STATE_RESUMING", "", "", ConductorRunStateDeploying},
		{"erroring", "STATE_ERRORING", "", "", ConductorRunStateDeployFailed},
		{"done deploy success", "STATE_DONE", "STATION_SUCCESSFUL", "STATION_SUCCESSFUL", ConductorRunStateDeployed},
		{"done deploy failed", "STATE_DONE", "STATION_FAILED", "STATION_SUCCESSFUL", ConductorRunStateDeployFailed},
		{"done build failed", "STATE_DONE", "", "STATION_FAILED", ConductorRunStateBuildFailed},
		{"unknown state", "STATE_UNKNOWN", "", "", ConductorRunStateDeploying},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			run := conductorRunResponse{}
			run.LatestUpdate.State = tt.latestState
			run.Stations.Deploy.Status = tt.deployStatus
			run.Stations.Build.Status = tt.buildStatus

			state := mapRunToState(run)
			assert.Equal(t, tt.expectedState, state)
		})
	}
}

func TestFindClosestRunAfterMerge(t *testing.T) {
	mergedAt := time.Date(2026, 2, 27, 10, 0, 0, 0, time.UTC)

	makeRun := func(guid string, minutesAfterMerge int) conductorRunResponse {
		return conductorRunResponse{
			GUID:        guid,
			TriggeredOn: mergedAt.Add(time.Duration(minutesAfterMerge) * time.Minute),
		}
	}

	tests := []struct {
		name             string
		runs             []conductorRunResponse
		expectedGUID     string
		expectedBoundary bool
	}{
		{
			name:             "picks closest run after merge when boundary found",
			runs:             []conductorRunResponse{makeRun("newest", 60), makeRun("closest", 5), makeRun("before", -10)},
			expectedGUID:     "closest",
			expectedBoundary: true,
		},
		{
			name:             "single run after merge with boundary",
			runs:             []conductorRunResponse{makeRun("only-after", 10), makeRun("before", -5)},
			expectedGUID:     "only-after",
			expectedBoundary: true,
		},
		{
			name:             "all runs after merge, no boundary",
			runs:             []conductorRunResponse{makeRun("newest", 60), makeRun("older", 30), makeRun("oldest", 5)},
			expectedGUID:     "oldest",
			expectedBoundary: false,
		},
		{
			name:             "all runs before merge",
			runs:             []conductorRunResponse{makeRun("a", -5), makeRun("b", -30)},
			expectedGUID:     "",
			expectedBoundary: true,
		},
		{
			name:             "empty runs",
			runs:             []conductorRunResponse{},
			expectedGUID:     "",
			expectedBoundary: false,
		},
		{
			name:             "run exactly at merge time is not matched",
			runs:             []conductorRunResponse{makeRun("at-merge", 0), makeRun("before", -10)},
			expectedGUID:     "",
			expectedBoundary: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matched, boundaryFound := findClosestRunAfterMerge(tt.runs, mergedAt)

			assert.Equal(t, tt.expectedBoundary, boundaryFound)
			if tt.expectedGUID == "" {
				assert.Nil(t, matched)
			} else {
				assert.Equal(t, tt.expectedGUID, matched.GUID)
			}
		})
	}
}

func TestFetchConductorStatus(t *testing.T) {
	prMergedAt := time.Date(2026, 2, 27, 10, 0, 0, 0, time.UTC)
	runTime := prMergedAt.Add(time.Hour) // run triggered after merge

	t.Run("PR found in post-merge run", func(t *testing.T) {
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			switch {
			case r.URL.Path == "/v3/conductor/my-svc/targets":
				json.NewEncoder(w).Encode(conductorTargetsResponse{
					Targets: []conductorTargetResponse{{Target: "prod"}},
				})
			case r.URL.Path == "/v4/conductor/my-svc/runs":
				run := conductorRunResponse{
					GUID:        "run-guid-1",
					TriggeredOn: runTime,
				}
				run.LatestUpdate.State = "STATE_DONE"
				run.Stations.Deploy.Status = "STATION_SUCCESSFUL"
				json.NewEncoder(w).Encode(conductorRunsResponse{Runs: []conductorRunResponse{run}})
			default:
				http.NotFound(w, r)
			}
		}))
		defer server.Close()

		client := &ConductorClient{
			BaseURL:       server.URL,
			TokenProvider: &mockTokenProvider{token: "test-token"},
			HTTP:          server.Client(),
		}

		statuses, err := client.FetchConductorStatus(context.Background(), 123, prMergedAt, []string{"my-svc"})
		assert.NoError(t, err)
		assert.Len(t, statuses, 1)
		assert.Equal(t, "my-svc", statuses[0].ServiceName)
		assert.Len(t, statuses[0].TargetStatuses, 1)
		assert.Equal(t, ConductorRunStateDeployed, statuses[0].TargetStatuses[0].State)
		assert.Equal(t, "prod", statuses[0].TargetStatuses[0].Target)
		assert.Equal(t, "run-guid-1", statuses[0].TargetStatuses[0].RunGUID)
	})

	t.Run("picks closest run after merge, not newest", func(t *testing.T) {
		closestRun := prMergedAt.Add(5 * time.Minute)
		newestRun := prMergedAt.Add(3 * time.Hour)
		beforeMerge := prMergedAt.Add(-time.Hour)

		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			switch {
			case r.URL.Path == "/v3/conductor/my-svc/targets":
				json.NewEncoder(w).Encode(conductorTargetsResponse{
					Targets: []conductorTargetResponse{{Target: "prod"}},
				})
			case r.URL.Path == "/v4/conductor/my-svc/runs":
				runs := []conductorRunResponse{
					{GUID: "newest-wrong", TriggeredOn: newestRun},
					{GUID: "closest-correct", TriggeredOn: closestRun},
					{GUID: "before-merge", TriggeredOn: beforeMerge},
				}
				for i := range runs {
					runs[i].LatestUpdate.State = "STATE_DONE"
					runs[i].Stations.Deploy.Status = "STATION_SUCCESSFUL"
				}
				json.NewEncoder(w).Encode(conductorRunsResponse{Runs: runs})
			default:
				http.NotFound(w, r)
			}
		}))
		defer server.Close()

		client := &ConductorClient{
			BaseURL:       server.URL,
			TokenProvider: &mockTokenProvider{token: "test-token"},
			HTTP:          server.Client(),
		}

		statuses, err := client.FetchConductorStatus(context.Background(), 123, prMergedAt, []string{"my-svc"})
		assert.NoError(t, err)
		assert.Equal(t, "closest-correct", statuses[0].TargetStatuses[0].RunGUID)
		assert.Equal(t, ConductorRunStateDeployed, statuses[0].TargetStatuses[0].State)
	})

	t.Run("paginates when boundary not found in first batch", func(t *testing.T) {
		callCount := 0
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			switch {
			case r.URL.Path == "/v3/conductor/my-svc/targets":
				json.NewEncoder(w).Encode(conductorTargetsResponse{
					Targets: []conductorTargetResponse{{Target: "prod"}},
				})
			case r.URL.Path == "/v4/conductor/my-svc/runs":
				callCount++
				var runs []conductorRunResponse
				if callCount == 1 {
					// First call: all runs after merge, no boundary
					for i := 0; i < 20; i++ {
						run := conductorRunResponse{
							GUID:        fmt.Sprintf("run-%d", i),
							TriggeredOn: prMergedAt.Add(time.Duration(100-i) * time.Minute),
						}
						run.LatestUpdate.State = "STATE_DONE"
						run.Stations.Deploy.Status = "STATION_SUCCESSFUL"
						runs = append(runs, run)
					}
				} else {
					// Second call with higher limit: includes boundary
					for i := 0; i < 25; i++ {
						run := conductorRunResponse{
							GUID:        fmt.Sprintf("run-%d", i),
							TriggeredOn: prMergedAt.Add(time.Duration(100-i*5) * time.Minute),
						}
						run.LatestUpdate.State = "STATE_DONE"
						run.Stations.Deploy.Status = "STATION_SUCCESSFUL"
						runs = append(runs, run)
					}
					// Add a run before merge to establish boundary
					beforeRun := conductorRunResponse{
						GUID:        "before-merge",
						TriggeredOn: prMergedAt.Add(-time.Hour),
					}
					beforeRun.LatestUpdate.State = "STATE_DONE"
					beforeRun.Stations.Deploy.Status = "STATION_SUCCESSFUL"
					runs = append(runs, beforeRun)
				}
				json.NewEncoder(w).Encode(conductorRunsResponse{Runs: runs})
			default:
				http.NotFound(w, r)
			}
		}))
		defer server.Close()

		client := &ConductorClient{
			BaseURL:       server.URL,
			TokenProvider: &mockTokenProvider{token: "test-token"},
			HTTP:          server.Client(),
		}

		statuses, err := client.FetchConductorStatus(context.Background(), 123, prMergedAt, []string{"my-svc"})
		assert.NoError(t, err)
		assert.Equal(t, 2, callCount, "should have paginated with a second request")
		assert.Equal(t, ConductorRunStateDeployed, statuses[0].TargetStatuses[0].State)
	})

	t.Run("no run found returns Pending", func(t *testing.T) {
		oldRunTime := prMergedAt.Add(-time.Hour)

		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			switch {
			case r.URL.Path == "/v3/conductor/my-svc/targets":
				json.NewEncoder(w).Encode(conductorTargetsResponse{
					Targets: []conductorTargetResponse{{Target: "prod"}},
				})
			case r.URL.Path == "/v4/conductor/my-svc/runs":
				run := conductorRunResponse{
					GUID:        "old-run",
					TriggeredOn: oldRunTime,
				}
				run.LatestUpdate.State = "STATE_DONE"
				run.Stations.Deploy.Status = "STATION_SUCCESSFUL"
				json.NewEncoder(w).Encode(conductorRunsResponse{Runs: []conductorRunResponse{run}})
			default:
				http.NotFound(w, r)
			}
		}))
		defer server.Close()

		client := &ConductorClient{
			BaseURL:       server.URL,
			TokenProvider: &mockTokenProvider{token: "test-token"},
			HTTP:          server.Client(),
		}

		statuses, err := client.FetchConductorStatus(context.Background(), 123, prMergedAt, []string{"my-svc"})
		assert.NoError(t, err)
		assert.Len(t, statuses, 1)
		assert.Equal(t, ConductorRunStatePending, statuses[0].TargetStatuses[0].State)
	})
}



package github

import (
	"encoding/json"
	"fmt"
	"time"
)

type ghPRResponse struct {
	Number      int    `json:"number"`
	Title       string `json:"title"`
	State       string `json:"state"`
	IsDraft     bool   `json:"isDraft"`
	URL         string `json:"url"`
	HeadRefName string `json:"headRefName"`
	HeadRefOID  string `json:"headRefOid"`
	Author      struct {
		Login string `json:"login"`
	} `json:"author"`
	ReviewDecision string `json:"reviewDecision"`
	Reviews        []struct {
		Author struct {
			Login string `json:"login"`
		} `json:"author"`
		State string `json:"state"`
	} `json:"reviews"`
	StatusCheckRollup []struct {
		TypeName   string `json:"__typename"`
		Name       string `json:"name"`
		Context    string `json:"context"`
		Conclusion string `json:"conclusion"`
		State      string `json:"state"`
		Status     string `json:"status"`
		DetailsURL string `json:"detailsUrl"`
		TargetURL  string `json:"targetUrl"`
	} `json:"statusCheckRollup"`
	Labels []struct {
		Name string `json:"name"`
	} `json:"labels"`
	MergedAt  *string `json:"mergedAt"`
	Mergeable string  `json:"mergeable"`
}

// ParsePRListOutput converts raw gh CLI JSON bytes (array) into []PR
func ParsePRListOutput(data []byte) ([]PR, error) {
	var raw []ghPRResponse
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("parsing gh output: %w", err)
	}

	prs := make([]PR, 0, len(raw))
	for _, r := range raw {
		prs = append(prs, convertResponse(r))
	}

	return prs, nil
}

// ParsePRViewOutput converts raw gh pr view JSON (single object) into a PR
func ParsePRViewOutput(data []byte) (PR, error) {
	var raw ghPRResponse
	if err := json.Unmarshal(data, &raw); err != nil {
		return PR{}, fmt.Errorf("parsing pr view output: %w", err)
	}
	return convertResponse(raw), nil
}

func convertResponse(r ghPRResponse) PR {
	pr := PR{
		Number:         r.Number,
		Title:          r.Title,
		State:          PRState(r.State),
		IsDraft:        r.IsDraft,
		URL:            r.URL,
		HeadRefName:    r.HeadRefName,
		HeadCommitOID:  r.HeadRefOID,
		Author:         r.Author.Login,
		ReviewDecision: ReviewDecision(r.ReviewDecision),
		Mergeable:      Mergeable(r.Mergeable),
	}

	for _, rev := range r.Reviews {
		if !IsBotAuthor(rev.Author.Login) {
			pr.Reviews = append(pr.Reviews, Review{
				Author: rev.Author.Login,
				State:  rev.State,
			})
		}
	}

	for _, check := range r.StatusCheckRollup {
		conclusion := resolveCheckConclusion(check.Conclusion, check.State)
		if conclusion == CIConclusionSkipped {
			continue
		}

		name := check.Name
		if name == "" {
			name = check.Context
		}

		detailsURL := check.DetailsURL
		if detailsURL == "" {
			detailsURL = check.TargetURL
		}

		pr.StatusChecks = append(pr.StatusChecks, StatusCheck{
			Name:       name,
			Conclusion: conclusion,
			Status:     check.Status,
			DetailsURL: detailsURL,
		})
	}

	for _, label := range r.Labels {
		pr.Labels = append(pr.Labels, label.Name)
	}
	pr.MergeQueueStatus = ExtractMergeQueueStatus(pr.Labels)

	if r.MergedAt != nil {
		t, err := time.Parse(time.RFC3339, *r.MergedAt)
		if err == nil {
			pr.MergedAt = &t
		}
	}

	return pr
}

// resolveCheckConclusion handles both CheckRun (conclusion field) and
// StatusContext (__typename: StatusContext, state field) entries.
// CheckRun uses conclusion directly; StatusContext maps state to CIConclusion.
func resolveCheckConclusion(conclusion, state string) CIConclusion {
	if conclusion != "" {
		return CIConclusion(conclusion)
	}
	switch state {
	case "SUCCESS":
		return CIConclusionSuccess
	case "FAILURE", "ERROR":
		return CIConclusionFailure
	case "PENDING", "EXPECTED":
		return CIConclusion("PENDING")
	default:
		return CIConclusion(state)
	}
}



package session

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// AgentStatus is the structured outcome written by an autonomous agent to its status file.
type AgentStatus struct {
	Outcome string `json:"outcome"` // "completed" or "failed"
	Error   string `json:"error,omitempty"`
}

// StatusFilePath returns the path where an agent writes its status file.
func StatusFilePath(configDir, recordID string) string {
	return filepath.Join(configDir, "sessions", "agent-"+recordID+".status")
}

// ReadStatusFile reads and parses an agent status file. Returns nil, nil if the file does not
// exist (agent not done yet). Returns nil, err for malformed JSON (caller retries next cycle).
func ReadStatusFile(path string) (*AgentStatus, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var s AgentStatus
	if err := json.Unmarshal(data, &s); err != nil {
		return nil, err
	}
	return &s, nil
}

// DeleteStatusFile removes an agent status file after its contents have been consumed.
func DeleteStatusFile(path string) error {
	return os.Remove(path)
}



package session

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"time"
)

// SessionType distinguishes manual user sessions from autonomous agent sessions.
type SessionType string

const (
	SessionTypeManual     SessionType = "manual"
	SessionTypeAutonomous SessionType = "autonomous"
)

func (s SessionType) String() string {
	return string(s)
}

// ParseSessionType parses a string into a SessionType.
func ParseSessionType(s string) (SessionType, error) {
	switch s {
	case "manual":
		return SessionTypeManual, nil
	case "autonomous":
		return SessionTypeAutonomous, nil
	default:
		return "", fmt.Errorf("invalid session type: %s (must be 'manual' or 'autonomous')", s)
	}
}

// SessionOutcome represents the terminal or current state of a session.
type SessionOutcome string

const (
	SessionOutcomeRunning     SessionOutcome = "running"
	SessionOutcomeCompleted   SessionOutcome = "completed"
	SessionOutcomeFailed      SessionOutcome = "failed"
	SessionOutcomeInterrupted SessionOutcome = "interrupted"
)

func (s SessionOutcome) String() string {
	return string(s)
}

// ParseSessionOutcome parses a string into a SessionOutcome.
func ParseSessionOutcome(s string) (SessionOutcome, error) {
	switch s {
	case "running":
		return SessionOutcomeRunning, nil
	case "completed":
		return SessionOutcomeCompleted, nil
	case "failed":
		return SessionOutcomeFailed, nil
	case "interrupted":
		return SessionOutcomeInterrupted, nil
	default:
		return "", fmt.Errorf("invalid session outcome: %s (must be 'running', 'completed', 'failed', or 'interrupted')", s)
	}
}

// SessionRecord captures a single session's lifecycle for a PR.
type SessionRecord struct {
	ID            string         `json:"id"`
	PRNumber      int            `json:"pr_number"`
	Repo          string         `json:"repo"`
	SessionType   SessionType    `json:"session_type"`
	ActionType    string         `json:"action_type"`
	Prompt        string         `json:"prompt"`
	ClaudeSession string         `json:"claude_session,omitempty"`
	WorkDir       string         `json:"work_dir"`
	WindowName    string         `json:"window_name"`
	HeadCommitOID string         `json:"headCommitOID,omitempty"`
	StartedAt     time.Time      `json:"started_at"`
	EndedAt       *time.Time     `json:"ended_at,omitempty"`
	Outcome       SessionOutcome `json:"outcome"`
	Error         string         `json:"error,omitempty"`
}

// NewSessionID generates a 32-character random hex string for use as a unique session identifier.
func NewSessionID() string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		panic(fmt.Sprintf("crypto/rand.Read failed: %v", err))
	}
	return hex.EncodeToString(b)
}



package tui

import (
	"testing"

	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/stretchr/testify/assert"
)

func TestUniqueRepos(t *testing.T) {
	tests := []struct {
		name     string
		rows     []PRRow
		expected []string
	}{
		{
			name:     "empty rows",
			rows:     nil,
			expected: []string{},
		},
		{
			name: "single repo",
			rows: []PRRow{
				{PR: github.PR{RepoNameWithOwner: "Org/repo-a"}},
				{PR: github.PR{RepoNameWithOwner: "Org/repo-a"}},
			},
			expected: []string{"repo-a"},
		},
		{
			name: "multiple repos sorted",
			rows: []PRRow{
				{PR: github.PR{RepoNameWithOwner: "Org/zebra"}},
				{PR: github.PR{RepoNameWithOwner: "Org/alpha"}},
				{PR: github.PR{RepoNameWithOwner: "Org/zebra"}},
			},
			expected: []string{"alpha", "zebra"},
		},
		{
			name: "empty repo name excluded",
			rows: []PRRow{
				{PR: github.PR{RepoNameWithOwner: ""}},
				{PR: github.PR{RepoNameWithOwner: "Org/real"}},
			},
			expected: []string{"real"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, uniqueRepos(tt.rows))
		})
	}
}

func TestFilterByRepo(t *testing.T) {
	rows := []PRRow{
		{PR: github.PR{Number: 1, RepoNameWithOwner: "Org/repo-a"}},
		{PR: github.PR{Number: 2, RepoNameWithOwner: "Org/repo-b"}},
		{PR: github.PR{Number: 3, RepoNameWithOwner: "Org/repo-a"}},
	}

	tests := []struct {
		name            string
		repo            string
		expectedNumbers []int
	}{
		{
			name:            "empty filter returns all",
			repo:            "",
			expectedNumbers: []int{1, 2, 3},
		},
		{
			name:            "filter repo-a",
			repo:            "repo-a",
			expectedNumbers: []int{1, 3},
		},
		{
			name:            "filter repo-b",
			repo:            "repo-b",
			expectedNumbers: []int{2},
		},
		{
			name:            "no match returns empty",
			repo:            "nonexistent",
			expectedNumbers: nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := filterByRepo(rows, tt.repo)
			var numbers []int
			for _, r := range result {
				numbers = append(numbers, r.PR.Number)
			}
			assert.Equal(t, tt.expectedNumbers, numbers)
		})
	}
}

func TestFilterByStatus(t *testing.T) {
	rows := []PRRow{
		{
			PR:     github.PR{Number: 1, State: github.PRStateOpen, IsDraft: true},
			Status: github.PRStatusDraft,
			Action: github.ActionNone,
		},
		{
			PR:     github.PR{Number: 2, State: github.PRStateOpen, IsDraft: true},
			Status: github.PRStatusDraftCIFailing,
			Action: github.ActionFixCI,
		},
		{
			PR:     github.PR{Number: 3, State: github.PRStateOpen},
			Status: github.PRStatusWaitingForReviews,
			Action: github.ActionNone,
		},
		{
			PR:     github.PR{Number: 4, State: github.PRStateOpen},
			Status: github.PRStatusChangesRequested,
			Action: github.ActionAddressFeedback,
		},
		{
			PR:     github.PR{Number: 5, State: github.PRStateOpen},
			Status: github.PRStatusApproved,
			Action: github.ActionMerge,
		},
		{
			PR:     github.PR{Number: 6, State: github.PRStateMerged},
			Status: github.PRStatusMerged,
			Action: github.ActionNone,
		},
	}

	tests := []struct {
		name            string
		status          string
		expectedNumbers []int
	}{
		{
			name:            "empty filter returns all",
			status:          "",
			expectedNumbers: []int{1, 2, 3, 4, 5, 6},
		},
		{
			name:            "draft includes draft and draft CI failing",
			status:          statusFilterDraft,
			expectedNumbers: []int{1, 2},
		},
		{
			name:            "open excludes drafts and merged",
			status:          statusFilterOpen,
			expectedNumbers: []int{3, 4, 5},
		},
		{
			name:            "needs action matches actionable PRs",
			status:          statusFilterNeedsAction,
			expectedNumbers: []int{2, 4, 5},
		},
		{
			name:            "merged",
			status:          statusFilterMerged,
			expectedNumbers: []int{6},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := filterByStatus(rows, tt.status)
			var numbers []int
			for _, r := range result {
				numbers = append(numbers, r.PR.Number)
			}
			assert.Equal(t, tt.expectedNumbers, numbers)
		})
	}
}

func TestAvailableStatusFilters(t *testing.T) {
	tests := []struct {
		name     string
		rows     []PRRow
		expected []string
	}{
		{
			name:     "empty rows",
			rows:     nil,
			expected: nil,
		},
		{
			name: "only open PRs",
			rows: []PRRow{
				{PR: github.PR{State: github.PRStateOpen}, Status: github.PRStatusWaitingForReviews},
			},
			expected: []string{"Open"},
		},
		{
			name: "all categories present",
			rows: []PRRow{
				{PR: github.PR{State: github.PRStateOpen, IsDraft: true}, Status: github.PRStatusDraft},
				{PR: github.PR{State: github.PRStateOpen}, Status: github.PRStatusWaitingForReviews},
				{PR: github.PR{State: github.PRStateOpen}, Status: github.PRStatusCIFailing, Action: github.ActionFixCI},
				{PR: github.PR{State: github.PRStateMerged}, Status: github.PRStatusMerged},
			},
			expected: []string{"Draft", "Open", "Needs Action", "Merged"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, availableStatusFilters(tt.rows))
		})
	}
}

func TestFilterBySearch(t *testing.T) {
	rows := []PRRow{
		{PR: github.PR{Number: 42, Title: "Add login page", RepoNameWithOwner: "Org/frontend"}},
		{PR: github.PR{Number: 100, Title: "Fix database migration", RepoNameWithOwner: "Org/backend"}},
		{PR: github.PR{Number: 7, Title: "Update README", RepoNameWithOwner: "Org/docs"}, RowType: RowTypeLocal, WorktreePath: "/home/user/worktrees/docs-readme"},
	}

	tests := []struct {
		name            string
		search          string
		expectedNumbers []int
	}{
		{
			name:            "empty search returns all",
			search:          "",
			expectedNumbers: []int{42, 100, 7},
		},
		{
			name:            "match repo name",
			search:          "frontend",
			expectedNumbers: []int{42},
		},
		{
			name:            "match title case insensitive",
			search:          "DATABASE",
			expectedNumbers: []int{100},
		},
		{
			name:            "match PR number",
			search:          "42",
			expectedNumbers: []int{42},
		},
		{
			name:            "match worktree path for local row",
			search:          "docs-readme",
			expectedNumbers: []int{7},
		},
		{
			name:            "no match returns empty",
			search:          "nonexistent",
			expectedNumbers: nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := filterBySearch(rows, tt.search)
			var numbers []int
			for _, r := range result {
				numbers = append(numbers, r.PR.Number)
			}
			assert.Equal(t, tt.expectedNumbers, numbers)
		})
	}
}



