func TestParsePRListOutput(t *testing.T) {
	tests := []struct {
		name        string
		input       string
		expected    []PR
		expectedErr string
	}{
		{
			name:     "empty list",
			input:    `[]`,
			expected: []PR{},
		},
		{
			name:        "invalid json",
			input:       `{not json`,
			expectedErr: "parsing gh output",
		},
		{
			name: "open PR with reviews and CI checks",
			input: `[{
				"number": 123,
				"title": "conductor: add feature",
				"state": "OPEN",
				"isDraft": false,
				"url": "https://github.com/DataDog/dd-source/pull/123",
				"headRefName": "joe/add-feature",
				"author": {"login": "joe"},
				"reviewDecision": "APPROVED",
				"reviews": [
					{"author": {"login": "reviewer1"}, "state": "APPROVED"},
					{"author": {"login": "datadog-official"}, "state": "APPROVED"},
					{"author": {"login": "my-bot[bot]"}, "state": "COMMENTED"}
				],
				"statusCheckRollup": [
					{"name": "ci/build", "conclusion": "SUCCESS", "status": "COMPLETED"},
					{"name": "ci/lint", "conclusion": "SKIPPED", "status": "COMPLETED"},
					{"name": "ci/test", "conclusion": "FAILURE", "status": "COMPLETED", "detailsUrl": "https://ci.example.com/1"}
				],
				"labels": [{"name": "changes:conductor-worker"}, {"name": "go"}],
				"mergedAt": null
			}]`,
			expected: []PR{
				{
					Number:         123,
					Title:          "conductor: add feature",
					State:          PRStateOpen,
					IsDraft:        false,
					URL:            "https://github.com/DataDog/dd-source/pull/123",
					HeadRefName:    "joe/add-feature",
					Author:         "joe",
					ReviewDecision: ReviewDecisionApproved,
					Reviews: []Review{
						{Author: "reviewer1", State: "APPROVED"},
					},
					StatusChecks: []StatusCheck{
						{Name: "ci/build", Conclusion: CIConclusionSuccess, Status: "COMPLETED"},
						{Name: "ci/test", Conclusion: CIConclusionFailure, Status: "COMPLETED", DetailsURL: "https://ci.example.com/1"},
					},
					Labels:   []string{"changes:conductor-worker", "go"},
					MergedAt: nil,
				},
			},
		},
		{
			name: "merged PR with timestamp",
			input: `[{
				"number": 456,
				"title": "fix bug",
				"state": "MERGED",
				"isDraft": false,
				"url": "https://github.com/DataDog/dd-source/pull/456",
				"author": {"login": "joe"},
				"reviewDecision": "APPROVED",
				"reviews": [],
				"statusCheckRollup": [],
				"labels": [{"name": "changes:my-service"}],
				"mergedAt": "2026-02-20T10:30:00Z"
			}]`,
			expected: []PR{
				{
					Number:         456,
					Title:          "fix bug",
					State:          PRStateMerged,
					URL:            "https://github.com/DataDog/dd-source/pull/456",
					Author:         "joe",
					ReviewDecision: ReviewDecisionApproved,
					Labels:         []string{"changes:my-service"},
					MergedAt:       timePtr(time.Date(2026, 2, 20, 10, 30, 0, 0, time.UTC)),
				},
			},
		},
		{
			name: "draft PR",
			input: `[{
				"number": 789,
				"title": "wip: new thing",
				"state": "OPEN",
				"isDraft": true,
				"url": "https://github.com/DataDog/dd-source/pull/789",
				"author": {"login": "joe"},
				"reviewDecision": "",
				"reviews": [],
				"statusCheckRollup": [],
				"labels": [],
				"mergedAt": null
			}]`,
			expected: []PR{
				{
					Number:  789,
					Title:   "wip: new thing",
					State:   PRStateOpen,
					IsDraft: true,
					URL:     "https://github.com/DataDog/dd-source/pull/789",
					Author:  "joe",
				},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := ParsePRListOutput([]byte(tt.input))

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Equal(t, tt.expected, result)
		})
	}
}

func TestParsePRViewOutput(t *testing.T) {
	tests := []struct {
		name        string
		input       string
		expected    PR
		expectedErr string
	}{
		{
			name:        "invalid json",
			input:       `{not json`,
			expectedErr: "parsing pr view output",
		},
		{
			name: "single PR with CheckRun and StatusContext entries",
			input: `{
				"number": 100,
				"title": "multi-repo feature",
				"state": "OPEN",
				"isDraft": false,
				"url": "https://github.com/DataDog/dd-source/pull/100",
				"headRefName": "joe/multi-repo",
				"headRefOid": "abc123def456",
				"author": {"login": "joe"},
				"reviewDecision": "REVIEW_REQUIRED",
				"reviews": [
					{"author": {"login": "alice"}, "state": "COMMENTED"}
				],
				"statusCheckRollup": [
					{"__typename": "CheckRun", "name": "ci/build", "conclusion": "SUCCESS", "status": "COMPLETED"},
					{"__typename": "StatusContext", "context": "deploy/staging", "state": "SUCCESS", "targetUrl": "https://deploy.example.com/1"},
					{"__typename": "StatusContext", "context": "deploy/prod", "state": "FAILURE", "targetUrl": "https://deploy.example.com/2"},
					{"__typename": "StatusContext", "context": "deploy/pending", "state": "PENDING"}
				],
				"labels": [{"name": "go"}],
				"mergedAt": null
			}`,
			expected: PR{
				Number:         100,
				Title:          "multi-repo feature",
				State:          PRStateOpen,
				URL:            "https://github.com/DataDog/dd-source/pull/100",
				HeadRefName:    "joe/multi-repo",
				HeadCommitOID:  "abc123def456",
				Author:         "joe",
				ReviewDecision: ReviewDecisionReviewRequired,
				Reviews: []Review{
					{Author: "alice", State: "COMMENTED"},
				},
				StatusChecks: []StatusCheck{
					{Name: "ci/build", Conclusion: CIConclusionSuccess, Status: "COMPLETED"},
					{Name: "deploy/staging", Conclusion: CIConclusionSuccess, DetailsURL: "https://deploy.example.com/1"},
					{Name: "deploy/prod", Conclusion: CIConclusionFailure, DetailsURL: "https://deploy.example.com/2"},
					{Name: "deploy/pending", Conclusion: CIConclusion("PENDING")},
				},
				Labels: []string{"go"},
			},
		},
		{
			name: "PR with mergeable field",
			input: `{
				"number": 150,
				"title": "conflicting PR",
				"state": "OPEN",
				"isDraft": false,
				"url": "https://github.com/DataDog/dd-source/pull/150",
				"author": {"login": "joe"},
				"reviewDecision": "APPROVED",
				"reviews": [],
				"statusCheckRollup": [],
				"labels": [],
				"mergedAt": null,
				"mergeable": "CONFLICTING"
			}`,
			expected: PR{
				Number:         150,
				Title:          "conflicting PR",
				State:          PRStateOpen,
				URL:            "https://github.com/DataDog/dd-source/pull/150",
				Author:         "joe",
				ReviewDecision: ReviewDecisionApproved,
				Mergeable:      MergeableConflicting,
			},
		},
		{
			name: "StatusContext with conclusion field takes precedence over state",
			input: `{
				"number": 200,
				"title": "test precedence",
				"state": "OPEN",
				"isDraft": false,
				"url": "https://github.com/DataDog/dd-source/pull/200",
				"author": {"login": "joe"},
				"reviewDecision": "",
				"reviews": [],
				"statusCheckRollup": [
					{"__typename": "StatusContext", "context": "ci/check", "conclusion": "FAILURE", "state": "SUCCESS"}
				],
				"labels": [],
				"mergedAt": null
			}`,
			expected: PR{
				Number: 200,
				Title:  "test precedence",
				State:  PRStateOpen,
				URL:    "https://github.com/DataDog/dd-source/pull/200",
				Author: "joe",
				StatusChecks: []StatusCheck{
					{Name: "ci/check", Conclusion: CIConclusionFailure},
				},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := ParsePRViewOutput([]byte(tt.input))

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Equal(t, tt.expected, result)
		})
	}
}

func TestResolveCheckConclusion(t *testing.T) {
	tests := []struct {
		name       string
		conclusion string
		state      string
		expected   CIConclusion
	}{
		{
			name:       "conclusion takes precedence",
			conclusion: "FAILURE",
			state:      "SUCCESS",
			expected:   CIConclusionFailure,
		},
		{
			name:     "state SUCCESS maps to CIConclusionSuccess",
			state:    "SUCCESS",
			expected: CIConclusionSuccess,
		},
		{
			name:     "state FAILURE maps to CIConclusionFailure",
			state:    "FAILURE",
			expected: CIConclusionFailure,
		},
		{
			name:     "state ERROR maps to CIConclusionFailure",
			state:    "ERROR",
			expected: CIConclusionFailure,
		},
		{
			name:     "state PENDING maps to PENDING",
			state:    "PENDING",
			expected: CIConclusion("PENDING"),
		},
		{
			name:       "skipped conclusion",
			conclusion: "SKIPPED",
			expected:   CIConclusionSkipped,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := resolveCheckConclusion(tt.conclusion, tt.state)
			assert.Equal(t, tt.expected, result)
		})
	}
}

func TestIsBotAuthor(t *testing.T) {
	tests := []struct {
