	}{
		{name: "known bot", author: "datadog-official", expected: true},
		{name: "codex bot", author: "chatgpt-codex-connector", expected: true},
		{name: "bot suffix", author: "dependabot[bot]", expected: true},
		{name: "human", author: "joe", expected: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
