package github

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestDetermineStatus(t *testing.T) {
	tests := []struct {
		name     string
		pr       PR
		expected PRStatus
	}{
		{
			name:     "merged PR",
			pr:       PR{State: PRStateMerged},
			expected: PRStatusMerged,
		},
		{
			name:     "draft PR",
			pr:       PR{State: PRStateOpen, IsDraft: true},
			expected: PRStatusDraft,
		},
		{
			name: "draft PR with CI failing",
			pr: PR{
				State:   PRStateOpen,
				IsDraft: true,
				StatusChecks: []StatusCheck{
					{Conclusion: CIConclusionFailure},
				},
			},
			expected: PRStatusDraftCIFailing,
		},
		{
			name: "draft PR with unresolved threads",
			pr: PR{
				State:             PRStateOpen,
				IsDraft:           true,
				UnresolvedThreads: 2,
			},
			expected: PRStatusChangesRequested,
		},
		{
			name: "draft PR with changes requested review",
			pr: PR{
				State:   PRStateOpen,
				IsDraft: true,
				Reviews: []Review{{Author: "alice", State: "CHANGES_REQUESTED"}},
			},
			expected: PRStatusChangesRequested,
		},
		{
			name: "CI failing with approved reviews",
			pr: PR{
				State: PRStateOpen,
				StatusChecks: []StatusCheck{
					{Conclusion: CIConclusionSuccess},
					{Conclusion: CIConclusionFailure},
				},
				Reviews: []Review{
					{Author: "reviewer1", State: "APPROVED"},
				},
			},
			expected: PRStatusCIFailing,
		},
		{
			name: "unresolved threads triggers changes requested",
			pr: PR{
				State:             PRStateOpen,
				UnresolvedThreads: 2,
			},
			expected: PRStatusChangesRequested,
		},
		{
			name: "unresolved threads takes priority over approved reviews",
			pr: PR{
				State:             PRStateOpen,
				UnresolvedThreads: 1,
				Reviews:           []Review{{Author: "alice", State: "APPROVED"}},
			},
			expected: PRStatusChangesRequested,
		},
		{
			name: "zero unresolved threads does not trigger changes requested",
			pr: PR{
				State:             PRStateOpen,
				UnresolvedThreads: 0,
				Reviews:           []Review{{Author: "alice", State: "APPROVED"}},
			},
			expected: PRStatusApproved,
		},
		{
			name:     "no reviews yet",
			pr:       PR{State: PRStateOpen},
			expected: PRStatusWaitingForReviews,
		},
		{
			name: "only bot reviews counts as no reviews",
			pr: PR{
				State: PRStateOpen,
				Reviews: []Review{
					{Author: "datadog-official", State: "APPROVED"},
				},
			},
			expected: PRStatusWaitingForReviews,
		},
		{
			name: "all reviewers approved",
			pr: PR{
				State: PRStateOpen,
				Reviews: []Review{
					{Author: "alice", State: "APPROVED"},
					{Author: "bob", State: "APPROVED"},
				},
			},
			expected: PRStatusApproved,
		},
		{
			name: "changes requested",
			pr: PR{
				State: PRStateOpen,
				Reviews: []Review{
					{Author: "alice", State: "APPROVED"},
					{Author: "bob", State: "CHANGES_REQUESTED"},
				},
			},
			expected: PRStatusChangesRequested,
		},
		{
			name: "reviewer changed mind from changes_requested to approved",
			pr: PR{
				State: PRStateOpen,
				Reviews: []Review{
					{Author: "alice", State: "CHANGES_REQUESTED"},
					{Author: "alice", State: "APPROVED"},
				},
			},
			expected: PRStatusApproved,
		},
		{
			name: "comment-only review counts as waiting on reviewer",
			pr: PR{
				State: PRStateOpen,
				Reviews: []Review{
					{Author: "alice", State: "COMMENTED"},
				},
			},
			expected: PRStatusReviewedWithComments,
		},
		{
			name: "all passing CI with no reviews",
			pr: PR{
				State: PRStateOpen,
				StatusChecks: []StatusCheck{
					{Conclusion: CIConclusionSuccess},
				},
			},
			expected: PRStatusWaitingForReviews,
		},
		{
			name:     "merge queue queued",
			pr:       PR{State: PRStateOpen, MergeQueueStatus: MQQueued},
			expected: PRStatusInMergeQueue,
		},
		{
			name:     "merge queue in progress",
			pr:       PR{State: PRStateOpen, MergeQueueStatus: MQInProgress},
			expected: PRStatusInMergeQueue,
		},
		{
			name:     "merge queue retrying",
			pr:       PR{State: PRStateOpen, MergeQueueStatus: MQRetrying},
			expected: PRStatusInMergeQueue,
		},
		{
			name: "merge queue rejected with CI failing falls through to CI failing",
			pr: PR{
				State:            PRStateOpen,
				MergeQueueStatus: MQRejected,
				StatusChecks:     []StatusCheck{{Conclusion: CIConclusionFailure}},
			},
			expected: PRStatusCIFailing,
		},
		{
			name:     "merge queue error with no reviews falls through to waiting for reviews",
			pr:       PR{State: PRStateOpen, MergeQueueStatus: MQError},
			expected: PRStatusWaitingForReviews,
		},
		{
			name: "merge queue rejected with approved reviews falls through to approved",
			pr: PR{
				State:            PRStateOpen,
				MergeQueueStatus: MQRejected,
				Reviews:          []Review{{Author: "alice", State: "APPROVED"}},
			},
			expected: PRStatusApproved,
		},
		{
			name: "merge queue takes precedence over approved",
			pr: PR{
				State:            PRStateOpen,
				MergeQueueStatus: MQQueued,
				Reviews:          []Review{{Author: "alice", State: "APPROVED"}},
			},
			expected: PRStatusInMergeQueue,
		},
		{
			name: "merge queue takes precedence over unresolved threads",
			pr: PR{
				State:             PRStateOpen,
				MergeQueueStatus:  MQInProgress,
				UnresolvedThreads: 3,
			},
			expected: PRStatusInMergeQueue,
		},
		{
			name:     "PR with merge conflicts",
			pr:       PR{State: PRStateOpen, Mergeable: MergeableConflicting},
			expected: PRStatusHasConflicts,
		},
		{
			name: "conflicts take priority over approved reviews",
			pr: PR{
				State:     PRStateOpen,
				Mergeable: MergeableConflicting,
				Reviews:   []Review{{Author: "alice", State: "APPROVED"}},
			},
			expected: PRStatusHasConflicts,
		},
		{
			name: "conflicts take priority over CI failure",
			pr: PR{
				State:        PRStateOpen,
				Mergeable:    MergeableConflicting,
				StatusChecks: []StatusCheck{{Conclusion: CIConclusionFailure}},
			},
			expected: PRStatusHasConflicts,
		},
		{
			name: "unknown mergeable is not treated as conflicting",
			pr: PR{
				State:     PRStateOpen,
				Mergeable: MergeableUnknown,
				Reviews:   []Review{{Author: "alice", State: "APPROVED"}},
			},
			expected: PRStatusApproved,
		},
		{
			name: "merged PR ignores conflicts",
			pr: PR{
				State:     PRStateMerged,
				Mergeable: MergeableConflicting,
			},
			expected: PRStatusMerged,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := DetermineStatus(tt.pr)
			assert.Equal(t, tt.expected, result)
		})
	}
}



package github

// DetermineStatus computes the display status for a PR.
// For merged PRs, deployment status is handled separately by the deploy package.
func DetermineStatus(pr PR) PRStatus {
	if pr.State == PRStateMerged {
		return PRStatusMerged
	}

	if pr.State == PRStateClosed {
		return PRStatusOpen
	}

	switch pr.MergeQueueStatus {
	case MQQueued, MQInProgress, MQRetrying:
		return PRStatusInMergeQueue
	}

	if pr.Mergeable == MergeableConflicting {
		return PRStatusHasConflicts
	}

	ciFailure := hasCIFailure(pr.StatusChecks)

	// Check for feedback-related states before draft early-return so that
	// draft PRs with review comments still surface the "address feedback" action.
	if pr.UnresolvedThreads > 0 {
		return PRStatusChangesRequested
	}

	humanReviews := filterHumanReviews(pr.Reviews)
	latest := latestReviewPerAuthor(humanReviews)
	hasChangesRequested := false
	allApproved := true
	for _, review := range latest {
		if review.State == "CHANGES_REQUESTED" {
			hasChangesRequested = true
			allApproved = false
		} else if review.State != "APPROVED" {
			allApproved = false
		}
	}

	if hasChangesRequested {
		return PRStatusChangesRequested
	}

	if pr.IsDraft {
		if ciFailure {
			return PRStatusDraftCIFailing
		}
		return PRStatusDraft
	}

	if ciFailure {
		return PRStatusCIFailing
	}

	if len(humanReviews) == 0 {
		return PRStatusWaitingForReviews
	}

	if allApproved {
		return PRStatusApproved
	}

	return PRStatusReviewedWithComments
}

func hasCIFailure(checks []StatusCheck) bool {
	for _, check := range checks {
		if check.Conclusion == CIConclusionFailure {
			return true
		}
	}
	return false
}

func filterHumanReviews(reviews []Review) []Review {
	var result []Review
	for _, r := range reviews {
		if !IsBotAuthor(r.Author) {
			result = append(result, r)
		}
	}
	return result
}

// latestReviewPerAuthor keeps only the last review from each author.
// Reviews are assumed to be ordered chronologically (oldest first) as returned by gh.
func latestReviewPerAuthor(reviews []Review) map[string]Review {
	latest := make(map[string]Review)
	for _, r := range reviews {
		latest[r.Author] = r
	}
	return latest
}



package session

import (
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
)

func newTestStore(t *testing.T) *Store {
	t.Helper()
	dir := t.TempDir()
	return NewStore(dir)
}

func makeRecord(id string, prNum int, outcome SessionOutcome, startedAt time.Time) SessionRecord {
	return SessionRecord{
		ID:          id,
		PRNumber:    prNum,
		Repo:        "owner/repo",
		SessionType: SessionTypeManual,
		ActionType:  "fix-ci",
		Prompt:      "fix the ci",
		StartedAt:   startedAt,
		Outcome:     outcome,
	}
}

func TestLoadMissingFile(t *testing.T) {
	store := NewStore(t.TempDir())
	store.Load()

	records := store.RecordsForPR(123)
	assert.Empty(t, records)
}

func TestLoadCorruptedFile(t *testing.T) {
	dir := t.TempDir()
	historyDir := filepath.Join(dir, "sessions")
	err := os.MkdirAll(historyDir, 0o755)
	assert.NoError(t, err)

	err = os.WriteFile(filepath.Join(historyDir, "history.json"), []byte("not json{{{"), 0o644)
	assert.NoError(t, err)

	store := NewStore(dir)
	store.Load()

	records := store.RecordsForPR(123)
	assert.Empty(t, records)
}

func TestAddRecordAndRecordsForPRRoundTrip(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	now := time.Now()
	r1 := makeRecord("a", 42, SessionOutcomeRunning, now.Add(-2*time.Hour))
	r2 := makeRecord("b", 42, SessionOutcomeCompleted, now.Add(-1*time.Hour))

	assert.NoError(t, store.AddRecord(r1))
	assert.NoError(t, store.AddRecord(r2))

	records := store.RecordsForPR(42)
	assert.Len(t, records, 2)
	assert.Equal(t, "b", records[0].ID)
	assert.Equal(t, "a", records[1].ID)

	// Verify persistence by loading into a new store
	store2 := NewStore(filepath.Dir(filepath.Dir(store.path)))
	store2.Load()
	records2 := store2.RecordsForPR(42)
	assert.Len(t, records2, 2)
}

func TestUpdateRecord(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	now := time.Now()
	r := makeRecord("update-me", 10, SessionOutcomeRunning, now)
	assert.NoError(t, store.AddRecord(r))

	endTime := now.Add(5 * time.Minute)
	err := store.UpdateRecord("update-me", func(rec *SessionRecord) {
		rec.Outcome = SessionOutcomeCompleted
		rec.EndedAt = &endTime
	})
	assert.NoError(t, err)

	records := store.RecordsForPR(10)
	assert.Len(t, records, 1)
	assert.Equal(t, SessionOutcomeCompleted, records[0].Outcome)
	assert.NotNil(t, records[0].EndedAt)
}

func TestDeleteRecord(t *testing.T) {
	tests := []struct {
		name         string
		records      []SessionRecord
		deleteID     string
		expectedErr  string
		expectedLeft []string // IDs remaining for PR 1
	}{
		{
			name: "delete the only record removes PR entry",
			records: []SessionRecord{
				makeRecord("a", 1, SessionOutcomeCompleted, time.Now()),
			},
			deleteID:     "a",
			expectedLeft: nil,
		},
		{
			name: "delete one of two records leaves the other",
			records: []SessionRecord{
				makeRecord("a", 1, SessionOutcomeCompleted, time.Now()),
				makeRecord("b", 1, SessionOutcomeRunning, time.Now()),
			},
			deleteID:     "a",
			expectedLeft: []string{"b"},
		},
		{
			name: "delete nonexistent ID returns error",
			records: []SessionRecord{
				makeRecord("a", 1, SessionOutcomeCompleted, time.Now()),
			},
			deleteID:     "nope",
			expectedErr:  "not found",
			expectedLeft: []string{"a"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			store := newTestStore(t)
			store.Load()
			for _, r := range tt.records {
				assert.NoError(t, store.AddRecord(r))
			}

			err := store.DeleteRecord(tt.deleteID)

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
			} else {
				assert.NoError(t, err)
			}

			remaining := store.RecordsForPR(1)
			var ids []string
			for _, r := range remaining {
				ids = append(ids, r.ID)
			}
			assert.Equal(t, tt.expectedLeft, ids)
		})
	}
}

func TestUpdateRecordNotFound(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	err := store.UpdateRecord("nonexistent", func(rec *SessionRecord) {
		rec.Outcome = SessionOutcomeCompleted
	})
	assert.ErrorContains(t, err, "not found")
}

func TestPruneRemovesOldRecords(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	now := time.Now()
	old := makeRecord("old", 1, SessionOutcomeCompleted, now.Add(-31*24*time.Hour))
	recent := makeRecord("recent", 1, SessionOutcomeCompleted, now.Add(-1*time.Hour))

	assert.NoError(t, store.AddRecord(old))
	assert.NoError(t, store.AddRecord(recent))

	assert.NoError(t, store.Prune())

	records := store.RecordsForPR(1)
	assert.Len(t, records, 1)
	assert.Equal(t, "recent", records[0].ID)
}

func TestPruneCapsAt100PerPR(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	now := time.Now()
	for i := 0; i < 110; i++ {
		r := makeRecord(
			"r-"+string(rune('A'+i/26))+string(rune('a'+i%26)),
			5,
			SessionOutcomeCompleted,
			now.Add(-time.Duration(110-i)*time.Minute),
		)
		assert.NoError(t, store.AddRecord(r))
	}

	records := store.RecordsForPR(5)
	assert.Len(t, records, 110)

	assert.NoError(t, store.Prune())

	records = store.RecordsForPR(5)
	assert.Len(t, records, 100)

	// The 100 most recent should be kept (oldest removed)
	// Most recent first from RecordsForPR, so last element is the oldest kept
	// The oldest 10 were removed, so the oldest kept started 100 minutes ago
	for _, r := range records {
		assert.True(t, r.StartedAt.After(now.Add(-101*time.Minute)),
			"record %s started at %v should be within last 101 minutes", r.ID, r.StartedAt)
	}
}

func TestAllRunning(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	now := time.Now()
	r1 := makeRecord("running1", 1, SessionOutcomeRunning, now)
	r2 := makeRecord("done", 1, SessionOutcomeCompleted, now.Add(-1*time.Hour))
	r3 := makeRecord("running2", 2, SessionOutcomeRunning, now)

	assert.NoError(t, store.AddRecord(r1))
	assert.NoError(t, store.AddRecord(r2))
	assert.NoError(t, store.AddRecord(r3))

	running := store.AllRunning()
	assert.Len(t, running, 2)

	ids := map[string]bool{}
	for _, r := range running {
		ids[r.ID] = true
	}
	assert.True(t, ids["running1"])
	assert.True(t, ids["running2"])
}

func TestSaveCreatesDirectories(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "nested", "deep")
	store := NewStore(dir)
	store.Load()

	r := makeRecord("x", 1, SessionOutcomeRunning, time.Now())
	assert.NoError(t, store.AddRecord(r))

	_, err := os.Stat(filepath.Join(dir, "sessions", "history.json"))
	assert.NoError(t, err)
}

func TestRecordsForPRMostRecentFirst(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	now := time.Now()
	r1 := makeRecord("oldest", 7, SessionOutcomeCompleted, now.Add(-3*time.Hour))
	r2 := makeRecord("middle", 7, SessionOutcomeCompleted, now.Add(-2*time.Hour))
	r3 := makeRecord("newest", 7, SessionOutcomeRunning, now.Add(-1*time.Hour))

	// Add in non-chronological order
	assert.NoError(t, store.AddRecord(r2))
	assert.NoError(t, store.AddRecord(r1))
	assert.NoError(t, store.AddRecord(r3))

	records := store.RecordsForPR(7)
	assert.Len(t, records, 3)
	assert.Equal(t, "newest", records[0].ID)
	assert.Equal(t, "middle", records[1].ID)
	assert.Equal(t, "oldest", records[2].ID)
}

func TestRecordsForPRReturnsNilForUnknownPR(t *testing.T) {
	store := newTestStore(t)
	store.Load()

	records := store.RecordsForPR(999)
	assert.Nil(t, records)
}

func TestHasRunningSession(t *testing.T) {
	now := time.Now()

	makeRunningRecord := func(id string, prNum int, repo, actionType, headOID string, st SessionType) SessionRecord {
		return SessionRecord{
			ID:            id,
			PRNumber:      prNum,
			Repo:          repo,
			SessionType:   st,
			ActionType:    actionType,
			HeadCommitOID: headOID,
			StartedAt:     now,
			Outcome:       SessionOutcomeRunning,
		}
	}

	t.Run("returns true for matching running session", func(t *testing.T) {
		store := newTestStore(t)
		store.Load()
		r := makeRunningRecord("s1", 42, "owner/repo", "fix-ci", "abc123", SessionTypeManual)
		assert.NoError(t, store.AddRecord(r))

		assert.True(t, store.HasRunningSession("owner/repo", 42, "fix-ci", "abc123"))
	})

	t.Run("returns false for different headCommitOID", func(t *testing.T) {
		store := newTestStore(t)
		store.Load()
		r := makeRunningRecord("s2", 42, "owner/repo", "fix-ci", "abc123", SessionTypeManual)
		assert.NoError(t, store.AddRecord(r))

		assert.False(t, store.HasRunningSession("owner/repo", 42, "fix-ci", "differentOID"))
	})

	t.Run("returns false when session is completed", func(t *testing.T) {
		store := newTestStore(t)
		store.Load()
		r := makeRunningRecord("s3", 42, "owner/repo", "fix-ci", "abc123", SessionTypeManual)
		r.Outcome = SessionOutcomeCompleted
		assert.NoError(t, store.AddRecord(r))

		assert.False(t, store.HasRunningSession("owner/repo", 42, "fix-ci", "abc123"))
	})

	t.Run("matches autonomous sessions too", func(t *testing.T) {
		store := newTestStore(t)
		store.Load()
		r := makeRunningRecord("s4", 42, "owner/repo", "address-feedback", "abc123", SessionTypeAutonomous)
		assert.NoError(t, store.AddRecord(r))

		assert.True(t, store.HasRunningSession("owner/repo", 42, "address-feedback", "abc123"))
	})
}



package session

import (
	"encoding/json"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"time"
)

const (
	maxRecordsPerPR = 100
	maxRecordAge    = 30 * 24 * time.Hour
)

// jsonFile is the on-disk representation of the session history.
// Keys are PR numbers as strings (JSON requires string map keys).
type jsonFile struct {
	Sessions map[string][]SessionRecord `json:"sessions"`
}

// Store manages persistent session history backed by a JSON file.
type Store struct {
	path     string
	sessions map[int][]SessionRecord
}

// NewStore creates a Store targeting /sessions/history.json.
// If configDir is empty, it defaults to os.UserConfigDir()/pr-workstation.
func NewStore(configDir string) *Store {
	if configDir == "" {
		dir, err := os.UserConfigDir()
		if err != nil {
			dir = os.TempDir()
		}
		configDir = filepath.Join(dir, "pr-workstation")
	}
	return &Store{
		path:     filepath.Join(configDir, "sessions", "history.json"),
		sessions: make(map[int][]SessionRecord),
	}
}

// Load reads the JSON history file into memory. If the file is missing or
// corrupted, the store starts with empty history and logs a warning.
func (s *Store) Load() {
	data, err := os.ReadFile(s.path)
	if err != nil {
		if !os.IsNotExist(err) {
			log.Printf("warning: could not read session history at %s: %v", s.path, err)
		}
		s.sessions = make(map[int][]SessionRecord)
		return
	}

	var f jsonFile
	if err := json.Unmarshal(data, &f); err != nil {
		log.Printf("warning: corrupted session history at %s: %v", s.path, err)
		s.sessions = make(map[int][]SessionRecord)
		return
	}

	s.sessions = make(map[int][]SessionRecord, len(f.Sessions))
	for k, v := range f.Sessions {
		prNum, err := strconv.Atoi(k)
		if err != nil {
			log.Printf("warning: skipping non-numeric PR key %q in session history", k)
			continue
		}
		s.sessions[prNum] = v
	}
}

// Save writes the in-memory session map to the JSON file, creating
// directories as needed.
func (s *Store) Save() error {
	dir := filepath.Dir(s.path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("creating session history directory: %w", err)
	}

	f := jsonFile{
		Sessions: make(map[string][]SessionRecord, len(s.sessions)),
	}
	for k, v := range s.sessions {
		f.Sessions[strconv.Itoa(k)] = v
	}

	data, err := json.MarshalIndent(f, "", "  ")
	if err != nil {
		return fmt.Errorf("marshalling session history: %w", err)
	}

	if err := os.WriteFile(s.path, data, 0o644); err != nil {
		return fmt.Errorf("writing session history: %w", err)
	}
	return nil
}

// AddRecord appends a record to the in-memory map and persists.
func (s *Store) AddRecord(record SessionRecord) error {
	s.sessions[record.PRNumber] = append(s.sessions[record.PRNumber], record)
	return s.Save()
}

// DeleteRecord removes the record with the given ID and persists.
func (s *Store) DeleteRecord(id string) error {
	for prNum, records := range s.sessions {
		for i, r := range records {
			if r.ID == id {
				s.sessions[prNum] = append(records[:i], records[i+1:]...)
				if len(s.sessions[prNum]) == 0 {
					delete(s.sessions, prNum)
				}
				return s.Save()
			}
		}
	}
	return fmt.Errorf("session record %q not found", id)
}

// UpdateRecord finds a record by ID across all PRs, applies the mutator
// function, and persists.
func (s *Store) UpdateRecord(id string, mutator func(*SessionRecord)) error {
	for prNum, records := range s.sessions {
		for i := range records {
			if records[i].ID == id {
				mutator(&records[i])
				s.sessions[prNum] = records
				return s.Save()
			}
		}
	}
	return fmt.Errorf("session record %q not found", id)
}

// RecordsForPR returns records for a PR, most recent first (by StartedAt).
func (s *Store) RecordsForPR(prNumber int) []SessionRecord {
	records := s.sessions[prNumber]
	if len(records) == 0 {
		return nil
	}

	result := make([]SessionRecord, len(records))
	copy(result, records)
	sort.Slice(result, func(i, j int) bool {
		return result[i].StartedAt.After(result[j].StartedAt)
	})
	return result
}

// AllRunning returns all records with Outcome=running across all PRs.
func (s *Store) AllRunning() []SessionRecord {
	var running []SessionRecord
	for _, records := range s.sessions {
		for _, r := range records {
			if r.Outcome == SessionOutcomeRunning {
				running = append(running, r)
			}
		}
	}
	return running
}

// ConfigDir returns the root config directory (parent of the "sessions" subdirectory).
func (s *Store) ConfigDir() string {
	return filepath.Dir(filepath.Dir(s.path))
}

// HasRunningSession reports whether any running session matches the four-tuple idempotency key.
// Both manual and autonomous sessions are considered.
func (s *Store) HasRunningSession(repo string, prNumber int, actionType string, headCommitOID string) bool {
	for _, records := range s.sessions {
		for _, r := range records {
			if r.Outcome == SessionOutcomeRunning &&
				r.Repo == repo &&
				r.PRNumber == prNumber &&
				r.ActionType == actionType &&
				r.HeadCommitOID == headCommitOID {
				return true
			}
		}
	}
	return false
}

// Prune removes records older than 30 days and caps each PR at 100 records
// (oldest removed first). It persists after pruning if any records were removed.
func (s *Store) Prune() error {
	cutoff := time.Now().Add(-maxRecordAge)
	changed := false

	for prNum, records := range s.sessions {
		// Remove records older than 30 days
		var kept []SessionRecord
		for _, r := range records {
			if r.StartedAt.After(cutoff) {
				kept = append(kept, r)
			} else {
				changed = true
			}
		}

		// Cap at 100 per PR, removing oldest first
		if len(kept) > maxRecordsPerPR {
			sort.Slice(kept, func(i, j int) bool {
				return kept[i].StartedAt.Before(kept[j].StartedAt)
			})
			kept = kept[len(kept)-maxRecordsPerPR:]
			changed = true
		}

		if len(kept) == 0 {
			delete(s.sessions, prNum)
			changed = true
		} else {
			s.sessions[prNum] = kept
		}
	}

	if changed {
		return s.Save()
	}
	return nil
}



package tui

import (
	"fmt"
	"sort"
	"strings"

	"github.com/DataDog/pr-workstation/internal/github"
)

// uniqueRepos returns sorted unique repo names from the given row sets
func uniqueRepos(rowSets ...[]PRRow) []string {
	seen := make(map[string]bool)
	for _, rows := range rowSets {
		for _, r := range rows {
			name := extractRepoName(r.PR.RepoNameWithOwner)
			if name != "" {
				seen[name] = true
			}
		}
	}

	repos := make([]string, 0, len(seen))
	for name := range seen {
		repos = append(repos, name)
	}
	sort.Strings(repos)
	return repos
}

// filterByRepo returns rows matching the given repo name
func filterByRepo(rows []PRRow, repo string) []PRRow {
	if repo == "" {
		return rows
	}
	var result []PRRow
	for _, r := range rows {
		if extractRepoName(r.PR.RepoNameWithOwner) == repo {
			result = append(result, r)
		}
	}
	return result
}

const (
	statusFilterDraft       = "Draft"
	statusFilterOpen        = "Open"
	statusFilterNeedsAction = "Needs Action"
	statusFilterMerged      = "Merged"
)

// filterByStatus returns rows matching the given status category
func filterByStatus(rows []PRRow, status string) []PRRow {
	if status == "" {
		return rows
	}
	var result []PRRow
	for _, r := range rows {
		if matchesStatusCategory(r, status) {
			result = append(result, r)
		}
	}
	return result
}

func matchesStatusCategory(r PRRow, category string) bool {
	switch category {
	case statusFilterDraft:
		return r.Status == github.PRStatusDraft || r.Status == github.PRStatusDraftCIFailing
	case statusFilterOpen:
		return r.PR.State == github.PRStateOpen && r.Status != github.PRStatusDraft && r.Status != github.PRStatusDraftCIFailing
	case statusFilterNeedsAction:
		return r.Action.IsActionable()
	case statusFilterMerged:
		return r.PR.State == github.PRStateMerged
	default:
		return false
	}
}

// filterBySearch returns rows where the search term is a case-insensitive
// substring of the repo name, PR title, PR number, or worktree path.
func filterBySearch(rows []PRRow, search string) []PRRow {
	if search == "" {
		return rows
	}
	term := strings.ToLower(search)
	var result []PRRow
	for _, r := range rows {
		repo := strings.ToLower(extractRepoName(r.PR.RepoNameWithOwner))
		title := strings.ToLower(r.PR.Title)
		number := fmt.Sprintf("%d", r.PR.Number)
		worktree := strings.ToLower(r.WorktreePath)
		if strings.Contains(repo, term) ||
			strings.Contains(title, term) ||
			strings.Contains(number, term) ||
			strings.Contains(worktree, term) {
			result = append(result, r)
		}
	}
	return result
}

// availableStatusFilters returns status categories present in the given rows
func availableStatusFilters(rows []PRRow) []string {
	categories := []string{statusFilterDraft, statusFilterOpen, statusFilterNeedsAction, statusFilterMerged}
	var result []string
	for _, cat := range categories {
		for _, r := range rows {
			if matchesStatusCategory(r, cat) {
				result = append(result, cat)
				break
			}
		}
	}
	return result
}



# Changelog

## 2026-03-03

### Needs-Attention Indicator

Running Claude sessions that are blocked waiting for human input (e.g. a permission prompt) are now flagged with a 🙋 indicator in the Agent column and session history. This makes it easy to spot which sessions need you to jump in without having to check each one manually. The same 🙋 emoji is used for both autonomous and manual sessions for a consistent "needs human" signal.

### Autonomous PR Agents

Toggle autonomous mode with **W** to let the dashboard automatically spawn Claude agents for PRs that need CI fixes or review feedback addressed. Agents run with priority ordering (CI fixes first) and a configurable concurrency limit. Sessions that hit a permission prompt are flagged as needs-attention so you can intervene. All sessions launch in `acceptEdits` permission mode by default, allowing file reads and edits without prompting while still requiring approval for shell commands.

### Session History

View past Claude sessions for any PR by pressing **H**. The history overlay shows session outcomes (success, failure, killed) and lets you jump into a running session with **Enter** or delete old entries with **D**.

### New Work Flow

Start new work directly from the dashboard. Press **N** to open a guided overlay that walks through repo selection, worktree/branch setup, and an optional seed prompt before launching a Claude session. When a local session's branch matches a newly opened PR, the dashboard automatically transitions it to a PR row — no manual re-linking needed.

### Session Import

Press **I** to import existing tmux sessions that aren't already tracked by the dashboard. The importer auto-detects the repo, branch, and worktree path from the session's working directory.

### Free-Text Search

Press **/** to search across repo names, PR titles, PR numbers, and worktree paths. The filter composes with existing repo and status filters and narrows results live as you type. The same **/** filter is available inside the new work overlay's repo selection step.

### Agent Status Column

The PR table now includes an **Agent** column showing the live status of Claude sessions — running, completed, failed, or needs-attention. For PRs with autonomous agents enabled, the column shows a compound summary (e.g. `1🙋 2❌ 1🔄`).

### Help Overlay

Press **?** to open a two-column help overlay showing all keybindings organized by category. Bindings that don't apply to the current row are shown in a disabled state so you always know what's available. The bottom help line now uses a compact format with colored separators.

### Local Session Persistence

Local work sessions now persist across tmux restarts. Previously, restarting tmux would cause local entries to disappear. They're now only removed explicitly via **D** or when they transition to a PR.

### Conductor Investigate Action

PRs with failed Conductor deployments now show an **Investigate** action. Pressing **c** launches a Claude session pre-loaded with failure details (service, target, state, Mosaic URL, error message) across all failed targets.

### Bug Fixes

- New work flow now runs git commands (`fetch`, `checkout -b`, `claude`) directly in the tmux session shell, giving immediate visible output instead of hanging on Go-side async operations.
- Session history overlay: pressing **Enter** with no past records now switches to the PR's active tmux session instead of doing nothing.
- Session history overlay: **D** now destroys the entire tmux session (not just the window), cleaning up properly.
- Autonomous agents now checkout the PR branch before starting, so they work on the correct code.
- Fixed autonomous agent spawning, session overlay navigation, and stop+delete lifecycle.
- Fixed agent status not updating when filters were reapplied.
- Fixed post-merge CI run matching to pick the run triggered closest to the merge time instead of the newest run, preventing misattribution in rapid-merge scenarios.
- Worktrees are now filtered out of the repo selection list to avoid duplicates.

## 2026-03-02

### Internal Distribution

Rewritten README with features, prerequisites, and usage instructions. Added a hosted demo video. Renamed project to pr-workstation with a Datadog module path.

### Architecture Decision Records

Retroactively documented existing architectural decisions as ADRs. Added three new ADRs covering new work spawning with persistent session state (ADR-0013), session history and agent column (ADR-0014), and autonomous PR agents (ADR-0015), along with implementation plans.

### Session State Foundation

Added persistent session state with file-backed storage, repo discovery, default branch detection, worktree creation, and tmux session renaming — the groundwork for the new work flow and session history features that landed on 2026-03-03.

## 2026-02-27

### PR Detail Overlay

Replaced the deploy overlay with a navigable PR detail overlay showing failing CI checks and unresolved review comments with full markdown rendering. Press **c** on a review comment to launch a Claude session that addresses it directly.

### Conductor and Availability Columns

Split the single Deploy column into separate **Conductor** and **Availability** columns for clearer visibility into deployment pipeline stages.

### Tmux Workspace Integration

Press **Enter** to switch to a PR's tmux workspace with automatic worktree selection. Press **o** to open the PR in the browser. Claude sessions now route through managed tmux sessions tied to each PR's worktree.

## 2026-02-26

### Saved Views

Create and switch between saved views with custom GitHub search queries. Press **v** to pick a view or create a new one. Views persist to a YAML config file.

### Repo and Status Filters

Filter the PR table by repository or status using picker overlays. Filters compose together and persist within the session.

### GitHub Actions Overlay

Press **g** to open a GitHub actions overlay with commands like deploy, integrate, and mark-ready — replacing the previous single mark-ready keybinding.

### Deploy Overlay Improvements

Rewrote the deploy overlay with collapsible service summaries showing rollout progress at a glance.

## 2026-02-25

### Initial Release

First working version of the PR status dashboard: a terminal UI showing your open and recently merged PRs across multiple repositories with live-updating status and deploy tracking.

### Action Column

Each PR row now shows a recommended **Action** — what you should do next (fix CI, address feedback, merge, etc.). Rows with actionable items are highlighted.

### Claude Integration

Press **c** to launch a Claude agent in a tmux window scoped to a PR's worktree. Press **C** to launch with a custom prompt.

### Context-Aware Help Bar

The bottom help bar dynamically updates to show only the keybindings relevant to the currently selected row's state.



package deploy

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os/exec"
	"strings"
	"sync"
	"time"
)

const conductorBaseURL = "https://orchplatform-api.us1.ddbuild.io"

// ConductorTokenProvider gets tokens via ddtool.
type ConductorTokenProvider struct{}

func (c *ConductorTokenProvider) GetToken(ctx context.Context) (string, error) {
	out, err := exec.CommandContext(ctx, "ddtool", "auth", "token",
		"--datacenter", "us1.ddbuild.io", "orchestration", "--http-header").Output()
	if err != nil {
		return "", fmt.Errorf("getting conductor auth token: %w", err)
	}
	return strings.TrimSpace(string(out)), nil
}

// ConductorClient fetches deployment status from the Conductor API.
type ConductorClient struct {
	BaseURL       string
	TokenProvider TokenProvider
	HTTP          HTTPClient
}

// NewConductorClient creates a client with default settings.
func NewConductorClient() *ConductorClient {
	return &ConductorClient{
		BaseURL:       conductorBaseURL,
		TokenProvider: &ConductorTokenProvider{},
		HTTP:          &http.Client{Timeout: 60 * time.Second},
	}
}

func (c *ConductorClient) doRequest(ctx context.Context, url string) ([]byte, error) {
	token, err := c.TokenProvider.GetToken(ctx)
	if err != nil {
		return nil, err
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}

	if strings.HasPrefix(token, "Authorization:") {
		parts := strings.SplitN(token, ":", 2)
		if len(parts) == 2 {
			req.Header.Set("Authorization", strings.TrimSpace(parts[1]))
		}
	} else {
		req.Header.Set("Authorization", "Bearer "+token)
	}

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return nil, fmt.Errorf("conductor API request: %w", err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, fmt.Errorf("reading conductor response: %w", err)
	}

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("conductor API returned %d: %s", resp.StatusCode, string(body))
	}

	return body, nil
}

func (c *ConductorClient) fetchTargets(ctx context.Context, svc string) ([]conductorTargetResponse, error) {
	url := fmt.Sprintf("%s/v3/conductor/%s/targets", c.BaseURL, svc)
	body, err := c.doRequest(ctx, url)
	if err != nil {
		return nil, err
	}

	var resp conductorTargetsResponse
	if err := json.Unmarshal(body, &resp); err != nil {
		return nil, fmt.Errorf("parsing targets response: %w", err)
	}

	return resp.Targets, nil
}

func (c *ConductorClient) fetchRuns(ctx context.Context, svc, target string, limit int) ([]conductorRunResponse, error) {
	url := fmt.Sprintf("%s/v4/conductor/%s/runs?target=%s&limit=%d&datasource=RAILYARD",
		c.BaseURL, svc, target, limit)
	body, err := c.doRequest(ctx, url)
	if err != nil {
		return nil, err
	}

	var resp conductorRunsResponse
	if err := json.Unmarshal(body, &resp); err != nil {
		return nil, fmt.Errorf("parsing runs response: %w", err)
	}

	return resp.Runs, nil
}

const (
	initialRunFetchLimit = 20
	maxRunFetchLimit     = 100
)

// findClosestRunAfterMerge finds the conductor run triggered closest to (but after) prMergedAt.
// Runs must be ordered newest-first. Returns nil if no run was triggered after prMergedAt.
// boundaryFound is true when a run before prMergedAt was seen, meaning the closest match is definitive.
func findClosestRunAfterMerge(runs []conductorRunResponse, prMergedAt time.Time) (matched *conductorRunResponse, boundaryFound bool) {
	for i := range runs {
		if runs[i].TriggeredOn.After(prMergedAt) {
			matched = &runs[i]
		} else {
			return matched, true
		}
	}
	return matched, false
}

// mapRunToState converts a conductor run's API state fields to a ConductorRunState.
func mapRunToState(run conductorRunResponse) ConductorRunState {
	switch run.LatestUpdate.State {
	case "STATE_BUILDING", "STATE_WAITING", "STATE_TRANSFORMING":
		return ConductorRunStateBuilding
	case "STATE_DEPLOYING", "STATE_RESUMING":
		return ConductorRunStateDeploying
	case "STATE_ERRORING":
		return ConductorRunStateDeployFailed
	case "STATE_DONE":
		if run.Stations.Deploy.Status == "STATION_SUCCESSFUL" {
			return ConductorRunStateDeployed
		}
		if run.Stations.Deploy.Status == "STATION_FAILED" {
			return ConductorRunStateDeployFailed
		}
		if run.Stations.Build.Status == "STATION_FAILED" {
			return ConductorRunStateBuildFailed
		}
		return ConductorRunStateDeployed
	default:
		// Treat unknown active states as deploying
		return ConductorRunStateDeploying
	}
}

// FetchConductorStatus resolves the conductor deployment status for a merged PR.
// prMergedAt must be non-zero.
func (c *ConductorClient) FetchConductorStatus(
	ctx context.Context,
	prNumber int,
	prMergedAt time.Time,
	services []string,
) ([]ConductorServiceStatus, error) {
	var result []ConductorServiceStatus
	var errs []error

	for _, svc := range services {
		targets, err := c.fetchTargets(ctx, svc)
		if err != nil {
			errs = append(errs, fmt.Errorf("fetching targets for %s: %w", svc, err))
			continue
		}

		targetStatuses := make([]ConductorTargetStatus, len(targets))
		var wg sync.WaitGroup

		for i, t := range targets {
			wg.Add(1)
			go func(idx int, target conductorTargetResponse) {
				defer wg.Done()

				var matchedRun *conductorRunResponse
				limit := initialRunFetchLimit
				for {
					runs, err := c.fetchRuns(ctx, svc, target.Target, limit)
					if err != nil || len(runs) == 0 {
						break
					}

					matched, boundaryFound := findClosestRunAfterMerge(runs, prMergedAt)
					if matched != nil {
						matchedRun = matched
					}

					if boundaryFound || limit >= maxRunFetchLimit || len(runs) < limit {
						break
					}
					limit = maxRunFetchLimit
				}

				if matchedRun == nil {
					targetStatuses[idx] = ConductorTargetStatus{Target: target.Target, State: ConductorRunStatePending}
					return
				}

				targetStatuses[idx] = ConductorTargetStatus{
					Target:  target.Target,
					RunGUID: matchedRun.GUID,
					State:   mapRunToState(*matchedRun),
					Error:   matchedRun.Error,
				}
			}(i, t)
		}

		wg.Wait()

		result = append(result, ConductorServiceStatus{
			ServiceName:    svc,
			TargetStatuses: targetStatuses,
		})
	}

	if len(errs) > 0 {
		return result, errors.Join(errs...)
	}
	return result, nil
}



package github

import (
	"context"
	"fmt"
	"testing"

	"github.com/stretchr/testify/assert"
)

type mockRunner struct {
	output []byte
	err    error
}

func (m *mockRunner) Run(_ context.Context, _ string, _ ...string) ([]byte, error) {
	return m.output, m.err
}

func TestFetchReviewThreadComments(t *testing.T) {
	tests := []struct {
		name        string
		output      string
		runnerErr   error
		expected    []ReviewThreadComment
		expectedErr string
	}{
		{
			name: "filters to only unresolved threads",
			output: `{
				"data": {
					"repository": {
						"pullRequest": {
							"reviewThreads": {
								"nodes": [
									{
										"isResolved": false,
										"path": "main.go",
										"comments": {"nodes": [{"body": "fix this", "url": "https://github.com/org/repo/pull/1#discussion_r100", "author": {"login": "alice"}}]}
									},
									{
										"isResolved": true,
										"path": "util.go",
										"comments": {"nodes": [{"body": "done", "url": "https://github.com/org/repo/pull/1#discussion_r101", "author": {"login": "bob"}}]}
									},
									{
										"isResolved": false,
										"path": "",
										"comments": {"nodes": [{"body": "general comment", "url": "https://github.com/org/repo/pull/1#discussion_r102", "author": {"login": "bob"}}]}
									}
								]
							}
						}
					}
				}
			}`,
			expected: []ReviewThreadComment{
				{Author: "alice", Body: "fix this", Path: "main.go", URL: "https://github.com/org/repo/pull/1#discussion_r100"},
				{Author: "bob", Body: "general comment", Path: "", URL: "https://github.com/org/repo/pull/1#discussion_r102"},
			},
		},
		{
			name: "no unresolved threads returns nil",
			output: `{
				"data": {
					"repository": {
						"pullRequest": {
							"reviewThreads": {
								"nodes": [
									{
										"isResolved": true,
										"path": "main.go",
										"comments": {"nodes": [{"body": "done", "author": {"login": "alice"}}]}
									}
								]
							}
						}
					}
				}
			}`,
			expected: nil,
		},
		{
			name:        "runner error",
			runnerErr:   fmt.Errorf("network failure"),
			expectedErr: "fetching review thread comments",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			client := &GHClient{Runner: &mockRunner{output: []byte(tt.output), err: tt.runnerErr}}

			comments, err := client.FetchReviewThreadComments(context.Background(), "owner", "repo", 1)

			if tt.expectedErr != "" {
				assert.ErrorContains(t, err, tt.expectedErr)
				return
			}

			assert.NoError(t, err)
			assert.Equal(t, tt.expected, comments)
		})
	}
}



package main

import (
	"fmt"
	"os"
	"time"

	"github.com/DataDog/pr-workstation/internal/config"
	"github.com/DataDog/pr-workstation/internal/deploy"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/session"
	"github.com/DataDog/pr-workstation/internal/tmux"
	"github.com/DataDog/pr-workstation/internal/tui"
	tea "github.com/charmbracelet/bubbletea"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		fmt.Fprintf(os.Stderr, "config error: %v\n", err)
		os.Exit(1)
	}

	configPath, _ := config.ConfigPath()
	sessionsPath, _ := config.SessionsPath()

	var views []tui.View
	for _, v := range cfg.Views {
		views = append(views, tui.View{
			Name:    v.Name,
			Query:   v.Query,
			Default: v.Default,
		})
	}

	runner := &github.ExecRunner{}
	ghClient := &github.GHClient{
		Runner: runner,
	}
	deployClient := deploy.NewDevflowClient()
	conductorClient := deploy.NewConductorClient()

	homeDir, _ := os.UserHomeDir()
	sessionMgr := &tmux.SessionManager{
		Runner:  runner,
		HomeDir: homeDir,
	}

	sessionStore := session.NewStore("")
	autonomyStore := session.NewAutonomyStore("")

	model := tui.NewModel(tui.Config{
		RefreshInterval: 3 * time.Minute,
		Views:           views,
		ConfigPath:      configPath,
		SessionsPath:    sessionsPath,
	}, ghClient, deployClient, conductorClient, sessionMgr, sessionStore, autonomyStore)

	p := tea.NewProgram(model, tea.WithAltScreen())
	if _, err := p.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}



package github

import (
	"context"
	"encoding/json"
	"fmt"
	"os/exec"
	"strings"
	"sync"
)

// CommandRunner abstracts shell command execution for testability
type CommandRunner interface {
	Run(ctx context.Context, name string, args ...string) ([]byte, error)
}

// ExecRunner is the real implementation using os/exec
type ExecRunner struct{}

func (e *ExecRunner) Run(ctx context.Context, name string, args ...string) ([]byte, error) {
	return exec.CommandContext(ctx, name, args...).Output()
}

// GHClient fetches PR data using the gh CLI
type GHClient struct {
	Runner CommandRunner
}

type searchResult struct {
	URL        string `json:"url"`
	Repository struct {
		Name          string `json:"name"`
		NameWithOwner string `json:"nameWithOwner"`
	} `json:"repository"`
	Number  int                     `json:"number"`
	IsDraft bool                    `json:"isDraft"`
	Labels  []struct{ Name string } `json:"labels"`
	State   string                  `json:"state"`
}

var prViewFields = "number,title,state,isDraft,url,headRefName,headRefOid,author,reviewDecision,reviews,statusCheckRollup,labels,mergedAt,mergeable"

// FetchOpenPRs returns the user's open PRs across all repos
func (c *GHClient) FetchOpenPRs(ctx context.Context) ([]PR, error) {
	return c.searchPRsAPI(ctx, "author:@me is:open")
}

// FetchMergedPRs returns the user's recently merged PRs across all repos
func (c *GHClient) FetchMergedPRs(ctx context.Context) ([]PR, error) {
	return c.searchPRsAPI(ctx, "author:@me is:merged")
}

// FetchPRsForView fetches open and merged PRs using the given query string.
// Uses the GitHub Search API directly so that queries with multiple author:
// fields are ORed (matching GitHub web search behavior).
func (c *GHClient) FetchPRsForView(ctx context.Context, query string) ([]PR, error) {
	openPRs, err := c.searchPRsAPI(ctx, query+" is:open")
	if err != nil {
		return nil, err
	}

	mergedPRs, err := c.searchPRsAPI(ctx, query+" is:merged")
	if err != nil {
		return nil, err
	}

	return append(openPRs, mergedPRs...), nil
}

// fetchUnresolvedThreadCount queries the GraphQL API for the count of unresolved review threads
func (c *GHClient) fetchUnresolvedThreadCount(ctx context.Context, repoOwner, repoName string, prNumber int) (int, error) {
	query := fmt.Sprintf(`{ repository(owner:%q, name:%q) { pullRequest(number:%d) { reviewThreads(first:100) { nodes { isResolved } } } } }`, repoOwner, repoName, prNumber)

	out, err := c.Runner.Run(ctx, "gh", "api", "graphql", "-f", "query="+query)
	if err != nil {
		return 0, fmt.Errorf("fetching review threads: %w", err)
	}

	var resp struct {
		Data struct {
			Repository struct {
				PullRequest struct {
					ReviewThreads struct {
						Nodes []struct {
							IsResolved bool `json:"isResolved"`
						} `json:"nodes"`
					} `json:"reviewThreads"`
				} `json:"pullRequest"`
			} `json:"repository"`
		} `json:"data"`
	}
	if err := json.Unmarshal(out, &resp); err != nil {
		return 0, fmt.Errorf("parsing review threads: %w", err)
	}

	unresolved := 0
	for _, thread := range resp.Data.Repository.PullRequest.ReviewThreads.Nodes {
		if !thread.IsResolved {
			unresolved++
		}
	}
	return unresolved, nil
}

// FetchReviewThreadComments queries the GraphQL API for unresolved review thread comments.
// Returns the first comment from each unresolved thread.
func (c *GHClient) FetchReviewThreadComments(ctx context.Context, repoOwner, repoName string, prNumber int) ([]ReviewThreadComment, error) {
	query := fmt.Sprintf(`{ repository(owner:%q, name:%q) { pullRequest(number:%d) { reviewThreads(first:100) { nodes { isResolved path comments(first:1) { nodes { body url author { login } } } } } } } }`, repoOwner, repoName, prNumber)

	out, err := c.Runner.Run(ctx, "gh", "api", "graphql", "-f", "query="+query)
	if err != nil {
		return nil, fmt.Errorf("fetching review thread comments: %w", err)
	}

	var resp struct {
		Data struct {
			Repository struct {
				PullRequest struct {
					ReviewThreads struct {
						Nodes []struct {
							IsResolved bool   `json:"isResolved"`
							Path       string `json:"path"`
							Comments   struct {
								Nodes []struct {
									Body   string `json:"body"`
									URL    string `json:"url"`
									Author struct {
										Login string `json:"login"`
									} `json:"author"`
								} `json:"nodes"`
							} `json:"comments"`
						} `json:"nodes"`
					} `json:"reviewThreads"`
				} `json:"pullRequest"`
			} `json:"repository"`
		} `json:"data"`
	}
	if err := json.Unmarshal(out, &resp); err != nil {
		return nil, fmt.Errorf("parsing review thread comments: %w", err)
	}

	var comments []ReviewThreadComment
	for _, thread := range resp.Data.Repository.PullRequest.ReviewThreads.Nodes {
		if thread.IsResolved {
			continue
		}
		if len(thread.Comments.Nodes) == 0 {
			continue
		}
		c := thread.Comments.Nodes[0]
		comments = append(comments, ReviewThreadComment{
			Author: c.Author.Login,
			Body:   c.Body,
			Path:   thread.Path,
			URL:    c.URL,
		})
	}
	return comments, nil
}

// apiSearchResult mirrors the relevant fields from the GitHub Search API response.
type apiSearchResult struct {
	Items []struct {
		HTMLURL       string `json:"html_url"`
		Number        int    `json:"number"`
		State         string `json:"state"`
		Draft         bool   `json:"draft"`
		RepositoryURL string `json:"repository_url"`
		Labels        []struct {
			Name string `json:"name"`
		} `json:"labels"`
	} `json:"items"`
}

// repoNameFromAPIURL extracts "Owner/Repo" from "https://api.github.com/repos/Owner/Repo".
func repoNameFromAPIURL(apiURL string) string {
	const prefix = "https://api.github.com/repos/"
	if strings.HasPrefix(apiURL, prefix) {
		return strings.TrimPrefix(apiURL, prefix)
	}
	return ""
}

func (c *GHClient) searchPRsAPI(ctx context.Context, query string) ([]PR, error) {
	fullQuery := query + " is:pr"
	out, err := c.Runner.Run(ctx, "gh", "api", "search/issues",
		"-X", "GET",
		"-f", "q="+fullQuery,
		"-f", "per_page=20",
		"-f", "sort=updated",
		"-f", "order=desc",
	)
	if err != nil {
		return nil, fmt.Errorf("searching PRs: %w", err)
	}

	var resp apiSearchResult
	if err := json.Unmarshal(out, &resp); err != nil {
		return nil, fmt.Errorf("parsing search results: %w", err)
	}

	if len(resp.Items) == 0 {
		return nil, nil
	}

	// Convert to searchResult for downstream compatibility
	results := make([]searchResult, len(resp.Items))
	for i, item := range resp.Items {
		nameWithOwner := repoNameFromAPIURL(item.RepositoryURL)
		results[i] = searchResult{
			URL:     item.HTMLURL,
			Number:  item.Number,
			IsDraft: item.Draft,
			State:   item.State,
		}
		results[i].Repository.NameWithOwner = nameWithOwner
		if parts := strings.SplitN(nameWithOwner, "/", 2); len(parts) == 2 {
			results[i].Repository.Name = parts[1]
		}
		for _, l := range item.Labels {
			results[i].Labels = append(results[i].Labels, struct{ Name string }{Name: l.Name})
		}
	}

	type indexedPR struct {
		idx int
		pr  PR
		err error
	}

	ch := make(chan indexedPR, len(results))
	var wg sync.WaitGroup

	for i, sr := range results {
		wg.Add(1)
		go func(idx int, sr searchResult) {
			defer wg.Done()

			out, err := c.Runner.Run(ctx, "gh", "pr", "view", sr.URL,
				"--json", prViewFields,
			)
			if err != nil {
				ch <- indexedPR{idx: idx, err: fmt.Errorf("fetching PR %s: %w", sr.URL, err)}
				return
			}

			pr, err := ParsePRViewOutput(out)
			if err != nil {
				ch <- indexedPR{idx: idx, err: fmt.Errorf("parsing PR %s: %w", sr.URL, err)}
				return
			}
			pr.RepoNameWithOwner = sr.Repository.NameWithOwner

			// Fetch unresolved review threads for open PRs
			if strings.EqualFold(sr.State, "open") {
				parts := strings.SplitN(sr.Repository.NameWithOwner, "/", 2)
				if len(parts) == 2 {
					count, err := c.fetchUnresolvedThreadCount(ctx, parts[0], parts[1], sr.Number)
					if err == nil {
						pr.UnresolvedThreads = count
					}
				}
			}

			ch <- indexedPR{idx: idx, pr: pr}
		}(i, sr)
	}

	go func() {
		wg.Wait()
		close(ch)
	}()

	prs := make([]PR, len(results))
	for result := range ch {
		if result.err != nil {
			return nil, result.err
		}
		prs[result.idx] = result.pr
	}

	return prs, nil
}



package github

import (
	"strings"
	"time"
)

// PRState represents the GitHub state of a pull request
type PRState string

const (
	PRStateOpen   PRState = "OPEN"
	PRStateMerged PRState = "MERGED"
	PRStateClosed PRState = "CLOSED"
)

func (s PRState) String() string { return string(s) }

// PRStatus represents the computed display status of a pull request
type PRStatus string

const (
	PRStatusDraft                PRStatus = "Draft"
	PRStatusDraftCIFailing       PRStatus = "Draft (CI failing)"
	PRStatusOpen                 PRStatus = "Open"
	PRStatusWaitingForReviews    PRStatus = "Waiting for reviews"
	PRStatusChangesRequested     PRStatus = "Changes requested"
	PRStatusReviewedWithComments PRStatus = "Reviewed (comments)"
	PRStatusApproved             PRStatus = "Approved"
	PRStatusCIFailing            PRStatus = "CI failing"
	PRStatusMerged               PRStatus = "Merged"
	PRStatusInMergeQueue         PRStatus = "In merge queue"
	PRStatusHasConflicts         PRStatus = "Has conflicts"
)

func (s PRStatus) String() string { return string(s) }

// ReviewDecision from GitHub's GraphQL API
type ReviewDecision string

const (
	ReviewDecisionApproved         ReviewDecision = "APPROVED"
	ReviewDecisionChangesRequested ReviewDecision = "CHANGES_REQUESTED"
	ReviewDecisionReviewRequired   ReviewDecision = "REVIEW_REQUIRED"
)

// CIConclusion from statusCheckRollup
type CIConclusion string

const (
	CIConclusionSuccess CIConclusion = "SUCCESS"
	CIConclusionFailure CIConclusion = "FAILURE"
	CIConclusionSkipped CIConclusion = "SKIPPED"
)

// Mergeable represents the GitHub mergeability state of a pull request
type Mergeable string

const (
	MergeableMergeable   Mergeable = "MERGEABLE"
	MergeableConflicting Mergeable = "CONFLICTING"
	MergeableUnknown     Mergeable = "UNKNOWN"
)

// MergeQueueStatus represents the state of a PR in the Datadog merge queue,
// derived from `mergequeue-status: ` labels applied by devflow.
type MergeQueueStatus string

const (
	MQNone       MergeQueueStatus = ""
	MQQueued     MergeQueueStatus = "queued"
	MQInProgress MergeQueueStatus = "in_progress"
	MQRetrying   MergeQueueStatus = "retrying"
	MQError      MergeQueueStatus = "error"
	MQRejected   MergeQueueStatus = "rejected"
)

// PR holds all data needed to compute and display PR status
type PR struct {
	Number            int
	Title             string
	State             PRState
	IsDraft           bool
	URL               string
	HeadRefName       string
	HeadCommitOID     string
	RepoNameWithOwner string
	ReviewDecision    ReviewDecision
	Reviews           []Review
	StatusChecks      []StatusCheck
	Labels            []string
	MergedAt          *time.Time
	Author            string
	UnresolvedThreads int
	MergeQueueStatus  MergeQueueStatus
	Mergeable         Mergeable
}

// Review represents a single human review
type Review struct {
	Author string
	State  string
}

// StatusCheck represents a CI check
type StatusCheck struct {
	Name       string
	Conclusion CIConclusion
	Status     string
	DetailsURL string
}

// ReviewThreadComment holds the first comment of an unresolved review thread.
type ReviewThreadComment struct {
	Author string
	Body   string
	Path   string // file path; empty for PR-level comments
	URL    string
}

var botAuthors = map[string]bool{
	"chatgpt-codex-connector": true,
	"datadog-official":        true,
}

// IsBotAuthor returns true if the author should be filtered out as a bot
func IsBotAuthor(author string) bool {
	if botAuthors[author] {
		return true
	}
	return strings.HasSuffix(author, "[bot]")
}

const mergeQueueLabelPrefix = "mergequeue-status: "

var validMergeQueueStatuses = map[string]MergeQueueStatus{
	"queued":      MQQueued,
	"in_progress": MQInProgress,
	"retrying":    MQRetrying,
	"error":       MQError,
	"rejected":    MQRejected,
}

// ExtractMergeQueueStatus returns the merge queue status from PR labels.
func ExtractMergeQueueStatus(labels []string) MergeQueueStatus {
	for _, label := range labels {
		if strings.HasPrefix(label, mergeQueueLabelPrefix) {
			value := strings.TrimPrefix(label, mergeQueueLabelPrefix)
			if status, ok := validMergeQueueStatuses[value]; ok {
				return status
			}
		}
	}
	return MQNone
}

// ExtractServiceNames finds labels matching "changes:" and returns the service names
func ExtractServiceNames(labels []string) []string {
	var services []string
	for _, label := range labels {
		if strings.HasPrefix(label, "changes:") {
			services = append(services, strings.TrimPrefix(label, "changes:"))
		}
	}
	return services
}



package tui

import (
	"testing"

	"github.com/DataDog/pr-workstation/internal/config"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/tmux"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/stretchr/testify/assert"
)

func newTestModel() Model {
	return Model{
		prSessions:   make(map[int]tmux.PRSession),
		sessionInUse: make(map[string]string),
		sessionMgr:   &tmux.SessionManager{HomeDir: "/home"},
		width:        120,
		height:       40,
	}
}

// updateNewWork sends a key through Update when showNewWork is true.
// Returns *Model because updateNewWorkOverlay uses a pointer receiver.
func updateNewWork(t *testing.T, m Model, msg tea.Msg) (*Model, tea.Cmd) {
	t.Helper()
	result, cmd := m.Update(msg)
	updated, ok := result.(*Model)
	if !ok {
		// Some paths (non-overlay messages) return Model value
		v := result.(Model)
		return &v, cmd
	}
	return updated, cmd
}

func TestNKeyOpensNewWorkOverlay(t *testing.T) {
	m := newTestModel()
	m.rows = []PRRow{
		{PR: github.PR{Number: 1, State: github.PRStateOpen}, RowType: RowTypePR},
	}
	m.table = m.rebuildTable()

	result, cmd := m.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'N'}})
	updated := result.(Model)

	assert.True(t, updated.showNewWork)
	assert.Equal(t, newWorkSelectRepo, updated.newWorkStep)
	assert.NotNil(t, cmd)
}

func TestNewWorkRepoPicker_Navigation(t *testing.T) {
	m := newTestModel()
	m.showNewWork = true
	m.newWorkStep = newWorkSelectRepo
	m.newWorkRepos = []string{"dd-source", "datadog-agent", "logs-backend"}
	m.newWorkRepoCursor = 0

	// j moves down
	updated, _ := updateNewWork(t, m, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'j'}})
	assert.Equal(t, 1, updated.newWorkRepoCursor)

	// k moves up
	m.newWorkRepoCursor = 1
	updated, _ = updateNewWork(t, m, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'k'}})
	assert.Equal(t, 0, updated.newWorkRepoCursor)

	// k at 0 stays at 0
	m.newWorkRepoCursor = 0
	updated, _ = updateNewWork(t, m, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'k'}})
	assert.Equal(t, 0, updated.newWorkRepoCursor)

	// j at end stays at end
	m.newWorkRepoCursor = 2
	updated, _ = updateNewWork(t, m, tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'j'}})
	assert.Equal(t, 2, updated.newWorkRepoCursor)
}

