		},
		{
			name:     "special chars removed",
			input:    "feat!@#$%branch",
			expected: "feat-branch",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, sanitizeBranchForSession(tt.input))
		})
	}
}

