package tui

import (
	"fmt"
	"path/filepath"
	"strings"

	"github.com/charmbracelet/lipgloss"
)

type newWorkStep int

const (
	newWorkSelectRepo     newWorkStep = iota
	newWorkSelectWorktree             // selecting from discovered worktrees
	newWorkNewBranch                  // entering a new branch name
	newWorkSeedPrompt                 // entering the seed prompt
)

func renderNewWorkOverlay(m Model) string {
	var b strings.Builder

	switch m.newWorkStep {
	case newWorkSelectRepo:
		b.WriteString(overlayTitleStyle.Render("New Work — Select Repository"))
		b.WriteString("\n")

		if m.newWorkRepoFilterMode {
			b.WriteString("Filter: ")
			b.WriteString(m.newWorkRepoFilterInput.View())
			b.WriteString("\n")
		}

		repos := m.filteredNewWorkRepos()
		if len(m.newWorkRepos) == 0 {
			b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("  Scanning for repos..."))
		} else if len(repos) == 0 {
			b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("  No matching repos"))
		} else {
			for i, repo := range repos {
				cursor := "  "
				if i == m.newWorkRepoCursor {
					cursor = "> "
				}
				text := lipgloss.NewStyle().Foreground(white).Render(repo)
				b.WriteString(fmt.Sprintf("%s%s\n", cursor, text))
			}
		}
		b.WriteString("\n")
		if m.newWorkRepoFilterMode {
			b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("enter: select | esc: clear filter"))
		} else {
			b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("/: filter | j/k: navigate | enter: select | esc: cancel"))
		}

	case newWorkSelectWorktree:
		title := fmt.Sprintf("New Work — Select Worktree for %s", m.newWorkSelectedRepo)
		b.WriteString(overlayTitleStyle.Render(title))
		b.WriteString("\n")

		for i, opt := range m.newWorkWorktreeOptions {
			cursor := "  "
			if i == m.newWorkWorktreeCursor {
				cursor = "> "
			}
			if opt.IsCreateNew {
				text := lipgloss.NewStyle().Foreground(green).Render("[Create new]")
				b.WriteString(fmt.Sprintf("%s%s\n", cursor, text))
			} else {
				name := filepath.Base(opt.Path)
				text := lipgloss.NewStyle().Foreground(white).Render(name)
				branch := lipgloss.NewStyle().Foreground(gray).Render(fmt.Sprintf(" (%s)", opt.Branch))
				inUse := ""
				if opt.InUseBy != "" {
					inUse = lipgloss.NewStyle().Foreground(gray).Render(fmt.Sprintf(" (in use by %s)", opt.InUseBy))
				}
				b.WriteString(fmt.Sprintf("%s%s%s%s\n", cursor, text, branch, inUse))
			}
		}
		b.WriteString("\n")
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | enter: select | esc: back"))

	case newWorkNewBranch:
		title := fmt.Sprintf("New Work — New Branch in %s", m.newWorkSelectedRepo)
		b.WriteString(overlayTitleStyle.Render(title))
		b.WriteString("\n")
		b.WriteString("Branch name: ")
		b.WriteString(m.newWorkBranchInput.View())
		b.WriteString("\n\n")
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("enter: create | esc: back"))

	case newWorkSeedPrompt:
		b.WriteString(overlayTitleStyle.Render("New Work — Seed Prompt"))
		b.WriteString("\n")
		b.WriteString("What should Claude work on?\n")
		b.WriteString(m.newWorkSeedInput.View())
		b.WriteString("\n\n")
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("enter: launch | esc: back"))
	}

	content := overlayStyle.Render(b.String())

	contentWidth := lipgloss.Width(content)
	contentHeight := lipgloss.Height(content)

	padLeft := (m.width - contentWidth) / 2
	padTop := (m.height - contentHeight) / 2
	if padLeft < 0 {
		padLeft = 0
	}
	if padTop < 0 {
		padTop = 0
	}

	return lipgloss.NewStyle().
		PaddingLeft(padLeft).
		PaddingTop(padTop).
		Render(content)
}



package tui

import (
	"testing"

	"github.com/DataDog/pr-workstation/internal/deploy"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/charmbracelet/lipgloss"
	"github.com/stretchr/testify/assert"
)

func TestServiceSummary(t *testing.T) {
	tests := []struct {
		name     string
		svc      deploy.ServiceDeployment
		expected string
	}{
		{
			name:     "no targets",
			svc:      deploy.ServiceDeployment{Service: "svc"},
			expected: "no targets",
		},
		{
			name: "all deployed",
			svc: deploy.ServiceDeployment{
				Service: "svc",
				Targets: []deploy.DeployTarget{
					{Status: deploy.DeployStatusDeployed},
					{Status: deploy.DeployStatusDeployed},
					{Status: deploy.DeployStatusDeployed},
				},
			},
			expected: "3/3 deployed",
		},
		{
			name: "none deployed",
			svc: deploy.ServiceDeployment{
				Service: "svc",
				Targets: []deploy.DeployTarget{
					{Status: deploy.DeployStatusNotDeployed},
					{Status: deploy.DeployStatusNotDeployed},
				},
			},
			expected: "0/2 deployed",
		},
		{
			name: "partially deployed",
			svc: deploy.ServiceDeployment{
				Service: "svc",
				Targets: []deploy.DeployTarget{
					{Status: deploy.DeployStatusDeployed},
					{Status: deploy.DeployStatusNotDeployed},
					{Status: deploy.DeployStatusDeployed},
				},
			},
			expected: "2/3 deployed",
		},
		{
			name: "some deploying",
			svc: deploy.ServiceDeployment{
				Service: "svc",
				Targets: []deploy.DeployTarget{
					{Status: deploy.DeployStatusDeployed},
					{Status: deploy.DeployStatusDeploying},
					{Status: deploy.DeployStatusNotDeployed},
				},
			},
			expected: "1/3 deploying",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, serviceSummary(tt.svc))
		})
	}
}

