func TestHasConductorFailure(t *testing.T) {
	tests := []struct {
		name     string
		statuses []deploy.ConductorServiceStatus
		expected bool
	}{
		{
			name:     "nil statuses",
			statuses: nil,
			expected: false,
		},
		{
			name:     "empty statuses",
			statuses: []deploy.ConductorServiceStatus{},
			expected: false,
		},
		{
			name: "all deployed",
			statuses: []deploy.ConductorServiceStatus{
				{ServiceName: "svc", TargetStatuses: []deploy.ConductorTargetStatus{
					{Target: "staging", State: deploy.ConductorRunStateDeployed},
				}},
			},
			expected: false,
		},
		{
			name: "build failed",
			statuses: []deploy.ConductorServiceStatus{
				{ServiceName: "svc", TargetStatuses: []deploy.ConductorTargetStatus{
					{Target: "staging", State: deploy.ConductorRunStateBuildFailed},
				}},
			},
			expected: true,
		},
		{
			name: "deploy failed among others",
			statuses: []deploy.ConductorServiceStatus{
				{ServiceName: "svc", TargetStatuses: []deploy.ConductorTargetStatus{
					{Target: "staging", State: deploy.ConductorRunStateDeployed},
					{Target: "prod", State: deploy.ConductorRunStateDeployFailed},
				}},
			},
			expected: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, hasConductorFailure(tt.statuses))
		})
	}
}

func TestConductorInvestigatePromptFromRow(t *testing.T) {
	row := &PRRow{
		ConductorStatuses: []deploy.ConductorServiceStatus{
			{
				ServiceName: "api-server",
				TargetStatuses: []deploy.ConductorTargetStatus{
					{Target: "staging", State: deploy.ConductorRunStateDeployed},
					{Target: "prod", State: deploy.ConductorRunStateDeployFailed, RunGUID: "guid-1", Error: "timeout"},
				},
			},
			{
				ServiceName: "worker",
				TargetStatuses: []deploy.ConductorTargetStatus{
					{Target: "staging", State: deploy.ConductorRunStateBuildFailed, Error: "compile error"},
				},
			},
		},
	}

	prompt := conductorInvestigatePromptFromRow(row)
	assert.Contains(t, prompt, "Conductor deployments have failed")
	// Includes failed targets
	assert.Contains(t, prompt, "api-server")
	assert.Contains(t, prompt, "prod")
	assert.Contains(t, prompt, "Deploy failed")
	assert.Contains(t, prompt, "timeout")
	assert.Contains(t, prompt, "guid-1")
	assert.Contains(t, prompt, "worker")
	assert.Contains(t, prompt, "Build failed")
	assert.Contains(t, prompt, "compile error")
	// Excludes successful targets
	assert.NotContains(t, prompt, "staging\nState: Deployed")
}

