			name: "none deployed is red",
			svc: deploy.ServiceDeployment{
				Targets: []deploy.DeployTarget{
					{Status: deploy.DeployStatusNotDeployed},
				},
			},
			expected: red,
		},
		{
			name: "some deploying is yellow",
			svc: deploy.ServiceDeployment{
				Targets: []deploy.DeployTarget{
					{Status: deploy.DeployStatusDeployed},
					{Status: deploy.DeployStatusDeploying},
				},
			},
			expected: yellow,
		},
		{
			name: "partial deploy is white",
			svc: deploy.ServiceDeployment{
				Targets: []deploy.DeployTarget{
					{Status: deploy.DeployStatusDeployed},
					{Status: deploy.DeployStatusNotDeployed},
				},
			},
			expected: white,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, serviceSummaryColor(tt.svc))
		})
	}
}

func TestBuildPRDetailItems_OpenPRWithMixedChecks(t *testing.T) {
	row := PRRow{
		PR: github.PR{
			State: github.PRStateOpen,
			StatusChecks: []github.StatusCheck{
				{Name: "ci/test", Conclusion: github.CIConclusionFailure, DetailsURL: "https://ci/test"},
				{Name: "ci/lint", Conclusion: github.CIConclusionSuccess},
				{Name: "ci/build", Conclusion: github.CIConclusionFailure, DetailsURL: "https://ci/build"},
				{Name: "ci/skip", Conclusion: github.CIConclusionSkipped},
			},
		},
	}

	items := buildPRDetailItems(row)
	assert.Len(t, items, 2)
	assert.Equal(t, prDetailCICheck, items[0].Kind)
	assert.Equal(t, "ci/test", items[0].CheckName)
	assert.Equal(t, "https://ci/test", items[0].CheckURL)
	assert.Equal(t, "ci/build", items[1].CheckName)
}

func TestBuildPRDetailItems_OpenPRNoFailingChecks(t *testing.T) {
