func TestBuildPRDetailItems_MergedPRIgnoresChecks(t *testing.T) {
	row := PRRow{
		PR: github.PR{
			State: github.PRStateMerged,
			StatusChecks: []github.StatusCheck{
				{Name: "ci/test", Conclusion: github.CIConclusionFailure},
			},
		},
		ConductorStatuses: []deploy.ConductorServiceStatus{
			makeSvc(deploy.ConductorRunStateDeployed),
		},
	}

	items := buildPRDetailItems(row)
	// Should contain conductor items, not CI checks
	for _, item := range items {
		assert.NotEqual(t, prDetailCICheck, item.Kind)
	}
	assert.Len(t, items, 1)
	assert.Equal(t, prDetailConductorTarget, items[0].Kind)
}



package tmux

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
)

type mockRunner struct {
	calls []runCall
	// responses maps "name arg1 arg2..." to (output, error)
	responses map[string]mockResponse
}

type runCall struct {
	name string
	args []string
}

type mockResponse struct {
	output []byte
	err    error
}

func newMockRunner() *mockRunner {
	return &mockRunner{responses: make(map[string]mockResponse)}
}

func (m *mockRunner) Run(_ context.Context, name string, args ...string) ([]byte, error) {
	m.calls = append(m.calls, runCall{name: name, args: args})
	key := name + " " + strings.Join(args, " ")
	if resp, ok := m.responses[key]; ok {
		return resp.output, resp.err
	}
	return nil, nil
}

func (m *mockRunner) lastCall() runCall {
	if len(m.calls) == 0 {
		return runCall{}
	}
	return m.calls[len(m.calls)-1]
}

func TestSanitizeSessionName(t *testing.T) {
	tests := []struct {
		name     string
		title    string
		number   int
		expected string
	}{
		{
			name:     "simple title",
			title:    "Fix nil pointer",
			number:   123,
			expected: "fix-nil-pointer-123",
		},
		{
			name:     "dots and colons replaced",
			title:    "conductor: fix v2.3 issue",
			number:   456,
			expected: "conductor-fix-v2-3-issue-456",
		},
		{
			name:     "slashes replaced",
			title:    "fix path/to/file",
			number:   789,
			expected: "fix-path-to-file-789",
		},
		{
			name:     "special characters collapsed",
			title:    "feat: add @user & #tag support!",
			number:   100,
			expected: "feat-add-user-tag-support-100",
		},
		{
			name:     "truncation at word boundary",
			title:    "this is a very long pull request title that exceeds the maximum length allowed",
			number:   200,
			expected: "this-is-a-very-long-pull-request-title-200",
		},
		{
			name:     "truncation without good word boundary",
			title:    "abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrst",
			number:   300,
			expected: "abcdefghijklmnopqrstuvwxyzabcdefghijklmn-300",
		},
		{
			name:     "leading and trailing special chars",
			title:    "---fix something---",
			number:   400,
			expected: "fix-something-400",
		},
		{
			name:     "backslashes replaced",
			title:    "fix\\path\\issue",
			number:   500,
			expected: "fix-path-issue-500",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, SanitizeSessionName(tt.title, tt.number))
		})
	}
}

