func TestListRepos(t *testing.T) {
	dir := t.TempDir()

	// Create a git repo (has .git dir)
	os.MkdirAll(filepath.Join(dir, "my-repo", ".git"), 0755)

	// Create a non-repo directory (no .git)
	os.MkdirAll(filepath.Join(dir, "not-a-repo"), 0755)

	// Create another git repo with .git as a file (worktree-style)
	os.MkdirAll(filepath.Join(dir, "worktree-repo"), 0755)
	os.WriteFile(filepath.Join(dir, "worktree-repo", ".git"), []byte("gitdir: /some/path"), 0644)

	// Create a regular file (should be ignored)
	os.WriteFile(filepath.Join(dir, "a-file.txt"), []byte("hello"), 0644)

	sm := &SessionManager{Runner: newMockRunner()}
	repos, err := sm.ListRepos(context.Background(), dir)

	assert.NoError(t, err)
	assert.Equal(t, []string{"my-repo"}, repos)
	// worktree-repo has .git as a file, not a directory — should be excluded
}

