package tmux

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// SessionManager wraps tmux, git, and workspace discovery commands behind a testable interface.
type SessionManager struct {
	Runner  CommandRunner
	HomeDir string
}

var nonAlphanumHyphen = regexp.MustCompile(`[^a-z0-9-]`)
var multiHyphen = regexp.MustCompile(`-{2,}`)

// SanitizeSessionName builds a human-readable tmux session name from a PR title and number.
func SanitizeSessionName(title string, number int) string {
	s := strings.ToLower(title)
	s = strings.NewReplacer(".", "-", ":", "-", "/", "-", "\\", "-").Replace(s)
	s = nonAlphanumHyphen.ReplaceAllString(s, "-")
	s = multiHyphen.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")

	const maxLen = 40
	if len(s) > maxLen {
		// try to truncate at a word boundary
		cut := s[:maxLen]
		if idx := strings.LastIndex(cut, "-"); idx > maxLen/2 {
			cut = cut[:idx]
		}
		s = strings.TrimRight(cut, "-")
	}

	return fmt.Sprintf("%s-%d", s, number)
}

// ListRepos returns directory names within baseDir that are git repositories.
func (sm *SessionManager) ListRepos(ctx context.Context, baseDir string) ([]string, error) {
	entries, err := os.ReadDir(baseDir)
	if err != nil {
		return nil, fmt.Errorf("reading directory %s: %w", baseDir, err)
	}

	var repos []string
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		gitPath := filepath.Join(baseDir, entry.Name(), ".git")
		info, err := os.Stat(gitPath)
		if err != nil {
			continue
		}
		// Worktrees have .git as a file, not a directory
		if !info.IsDir() {
			continue
		}
		repos = append(repos, entry.Name())
	}
	return repos, nil
}

// DefaultBranch returns the default branch name for a repo by reading the
// symbolic ref of origin/HEAD (e.g., "main" or "master").
func (sm *SessionManager) DefaultBranch(ctx context.Context, repoDir string) (string, error) {
	out, err := sm.Runner.Run(ctx, "git", "-C", repoDir, "symbolic-ref", "refs/remotes/origin/HEAD")
	if err != nil {
		return "", fmt.Errorf("determining default branch for %s: %w", repoDir, err)
	}
	ref := strings.TrimSpace(string(out))
	return strings.TrimPrefix(ref, "refs/remotes/origin/"), nil
}

// CheckoutPullCreateBranch checks out the default branch in an existing worktree,
// pulls latest, then creates and checks out a new branch from it.
func (sm *SessionManager) CheckoutPullCreateBranch(ctx context.Context, workDir, defaultBranch, newBranch string) error {
	if _, err := sm.Runner.Run(ctx, "git", "-C", workDir, "checkout", defaultBranch); err != nil {
		return fmt.Errorf("checking out %s: %w", defaultBranch, err)
	}
	if _, err := sm.Runner.Run(ctx, "git", "-C", workDir, "pull"); err != nil {
		return fmt.Errorf("pulling %s: %w", defaultBranch, err)
	}
	if _, err := sm.Runner.Run(ctx, "git", "-C", workDir, "checkout", "-b", newBranch); err != nil {
		return fmt.Errorf("creating branch %s: %w", newBranch, err)
	}
	return nil
}

// CreateWorktreeNewBranch fetches the latest remote state, then creates a new
// git worktree at path with a new branch starting from origin/.
func (sm *SessionManager) CreateWorktreeNewBranch(ctx context.Context, repoDir, path, newBranch, startPoint string) error {
	if _, err := sm.Runner.Run(ctx, "git", "-C", repoDir, "fetch", "origin", startPoint); err != nil {
		return fmt.Errorf("fetching origin/%s: %w", startPoint, err)
	}
	_, err := sm.Runner.Run(ctx, "git", "-C", repoDir, "worktree", "add", "-b", newBranch, path, "origin/"+startPoint)
	if err != nil {
		return fmt.Errorf("creating worktree with new branch: %w", err)
	}
	return nil
}

// RenameSession renames a tmux session. Safe even if the user is attached to it.
func (sm *SessionManager) RenameSession(ctx context.Context, oldName, newName string) error {
	_, err := sm.Runner.Run(ctx, "tmux", "rename-session", "-t", oldName, newName)
	if err != nil {
		return fmt.Errorf("renaming session %q to %q: %w", oldName, newName, err)
	}
	return nil
}

// ListWorktrees returns all git worktrees for a repo directory.
func (sm *SessionManager) ListWorktrees(ctx context.Context, repoDir string) ([]Worktree, error) {
	out, err := sm.Runner.Run(ctx, "git", "-C", repoDir, "worktree", "list", "--porcelain")
	if err != nil {
		return nil, fmt.Errorf("listing worktrees: %w", err)
	}
	return parseWorktrees(string(out)), nil
}

func parseWorktrees(output string) []Worktree {
	var worktrees []Worktree
	var current Worktree

	for _, line := range strings.Split(output, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			if current.Path != "" {
				worktrees = append(worktrees, current)
				current = Worktree{}
			}
			continue
		}
		if strings.HasPrefix(line, "worktree ") {
			current.Path = strings.TrimPrefix(line, "worktree ")
		}
		if strings.HasPrefix(line, "branch ") {
			// branch refs/heads/my-branch -> my-branch
			branch := strings.TrimPrefix(line, "branch ")
			branch = strings.TrimPrefix(branch, "refs/heads/")
			current.Branch = branch
		}
	}
	// flush last entry
	if current.Path != "" {
		worktrees = append(worktrees, current)
	}
	return worktrees
}

// CreateWorktree creates a new git worktree at path for the given branch.
func (sm *SessionManager) CreateWorktree(ctx context.Context, repoDir, path, branch string) error {
	_, err := sm.Runner.Run(ctx, "git", "-C", repoDir, "worktree", "add", path, branch)
	if err != nil {
		return fmt.Errorf("creating worktree: %w", err)
	}
	return nil
}

// ListTmuxSessions returns the names of all active tmux sessions.
func (sm *SessionManager) ListTmuxSessions(ctx context.Context) ([]string, error) {
	out, err := sm.Runner.Run(ctx, "tmux", "list-sessions", "-F", "#{session_name}")
	if err != nil {
		return nil, fmt.Errorf("listing tmux sessions: %w", err)
	}
	var sessions []string
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if line != "" {
			sessions = append(sessions, line)
		}
	}
	return sessions, nil
}

// SessionPanePath returns the current working directory of the active pane in a session.
func (sm *SessionManager) SessionPanePath(ctx context.Context, sessionName string) (string, error) {
	out, err := sm.Runner.Run(ctx, "tmux", "display-message", "-p", "-t", sessionName, "#{pane_current_path}")
	if err != nil {
		return "", fmt.Errorf("getting pane path for session %q: %w", sessionName, err)
	}
	return strings.TrimSpace(string(out)), nil
}

// RepoInfo holds the resolved git metadata for a path.
type RepoInfo struct {
	Repo         string // repo directory name (e.g. "dd-source")
	Branch       string
	WorktreePath string // absolute path to the worktree root
}

// RepoInfoFromPath resolves git repo name, branch, and worktree root from any directory within a repo.
func (sm *SessionManager) RepoInfoFromPath(ctx context.Context, path string) (RepoInfo, error) {
	// Worktree root (the directory that contains .git or is the checked-out dir)
	out, err := sm.Runner.Run(ctx, "git", "-C", path, "rev-parse", "--show-toplevel")
	if err != nil {
		return RepoInfo{}, fmt.Errorf("not a git repo: %w", err)
	}
	worktreePath := strings.TrimSpace(string(out))

	out, err = sm.Runner.Run(ctx, "git", "-C", path, "rev-parse", "--abbrev-ref", "HEAD")
	if err != nil {
		return RepoInfo{}, fmt.Errorf("getting branch: %w", err)
	}
	branch := strings.TrimSpace(string(out))

	// git common dir points to the main repo's .git; for the main worktree it returns ".git"
	out, err = sm.Runner.Run(ctx, "git", "-C", path, "rev-parse", "--git-common-dir")
	if err != nil {
		return RepoInfo{}, fmt.Errorf("getting git common dir: %w", err)
	}
	commonDir := strings.TrimSpace(string(out))

	var repoDir string
	if commonDir == ".git" {
		repoDir = worktreePath
	} else {
		// commonDir is an absolute path like /home/user/dd/dd-source/.git
		repoDir = filepath.Dir(commonDir)
	}

	return RepoInfo{
		Repo:         filepath.Base(repoDir),
		Branch:       branch,
		WorktreePath: worktreePath,
	}, nil
}

// SessionExists checks whether a tmux session with the given name exists.
func (sm *SessionManager) SessionExists(ctx context.Context, name string) bool {
	_, err := sm.Runner.Run(ctx, "tmux", "has-session", "-t", name)
	return err == nil
}

// CreateSessionWithWindow creates a detached tmux session whose initial window
// runs the given command. This avoids the empty default window that would
// result from creating a session then adding a named window separately.
func (sm *SessionManager) CreateSessionWithWindow(ctx context.Context, session PRSession, windowName, cmd string) error {
	args := []string{"new-session", "-d", "-s", session.SessionName, "-n", windowName, "-c", session.WorkDir}
	if cmd != "" {
		args = append(args, cmd)
	}
	_, err := sm.Runner.Run(ctx, "tmux", args...)
	if err != nil {
		return fmt.Errorf("creating session %q: %w", session.SessionName, err)
	}
	return nil
}

// SwitchToSession switches the tmux client to the given session.
func (sm *SessionManager) SwitchToSession(ctx context.Context, name string) error {
	_, err := sm.Runner.Run(ctx, "tmux", "switch-client", "-t", name)
	if err != nil {
		return fmt.Errorf("switching to session %q: %w", name, err)
	}
	return nil
}

// DestroySession kills a tmux session.
func (sm *SessionManager) DestroySession(ctx context.Context, name string) error {
	_, err := sm.Runner.Run(ctx, "tmux", "kill-session", "-t", name)
	if err != nil {
		return fmt.Errorf("killing session %q: %w", name, err)
	}
	return nil
}

// WindowExists checks whether a named window exists in a session.
func (sm *SessionManager) WindowExists(ctx context.Context, session, window string) bool {
	out, err := sm.Runner.Run(ctx, "tmux", "list-windows", "-t", session, "-F", "#{window_name}")
	if err != nil {
		return false
	}
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if line == window {
			return true
		}
	}
	return false
}

// CreateNamedWindow creates a named window in a session, optionally running a command.
func (sm *SessionManager) CreateNamedWindow(ctx context.Context, session, window, workDir, cmd string) error {
	args := []string{"new-window", "-t", session, "-n", window, "-c", workDir}
	if cmd != "" {
		args = append(args, cmd)
	}
	_, err := sm.Runner.Run(ctx, "tmux", args...)
	if err != nil {
		return fmt.Errorf("creating window %q in session %q: %w", window, session, err)
	}
	return nil
}

// SwitchToWindow selects a named window in a session.
func (sm *SessionManager) SwitchToWindow(ctx context.Context, session, window string) error {
	target := fmt.Sprintf("%s:%s", session, window)
	_, err := sm.Runner.Run(ctx, "tmux", "select-window", "-t", target)
	if err != nil {
		return fmt.Errorf("selecting window %q: %w", target, err)
	}
	return nil
}

// RepoDir returns the expected local clone path for a repo name.
func (sm *SessionManager) RepoDir(repoName string) string {
	return fmt.Sprintf("%s/dd/%s", sm.HomeDir, repoName)
}

// ListPRSessions discovers existing PR sessions from tmux by parsing session names.
// Session names end with - where number is the PR number.
func (sm *SessionManager) ListPRSessions(ctx context.Context) (map[int]PRSession, error) {
	out, err := sm.Runner.Run(ctx, "tmux", "list-sessions", "-F", "#{session_name}\t#{session_path}")
	if err != nil {
		// tmux returns error when no server is running
		return nil, nil
	}

	sessions := make(map[int]PRSession)
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, "\t", 2)
		name := parts[0]
		workDir := ""
		if len(parts) == 2 {
			workDir = parts[1]
		}

		prNumber := extractPRNumber(name)
		if prNumber <= 0 {
			continue
		}

		sessions[prNumber] = PRSession{
			SessionName: name,
			PRNumber:    prNumber,
			WorkDir:     workDir,
		}
	}
	return sessions, nil
}

// ListWindows returns the names of all windows in a tmux session.
func (sm *SessionManager) ListWindows(ctx context.Context, sessionName string) ([]string, error) {
	out, err := sm.Runner.Run(ctx, "tmux", "list-windows", "-t", sessionName, "-F", "#{window_name}")
	if err != nil {
		return nil, fmt.Errorf("listing windows for session %q: %w", sessionName, err)
	}
	var windows []string
	for _, line := range strings.Split(strings.TrimSpace(string(out)), "\n") {
		if line != "" {
			windows = append(windows, line)
		}
	}
	return windows, nil
}

// CapturePane returns the last N lines of output from a tmux pane, used to
// detect whether an agent is blocked on a permission prompt.
func (sm *SessionManager) CapturePane(ctx context.Context, sessionName, windowName string, lines int) (string, error) {
	target := fmt.Sprintf("%s:%s", sessionName, windowName)
	out, err := sm.Runner.Run(ctx, "tmux", "capture-pane", "-p", "-t", target, "-S", fmt.Sprintf("-%d", lines))
	if err != nil {
		return "", fmt.Errorf("capturing pane %q: %w", target, err)
	}
	return string(out), nil
}

// extractPRNumber extracts the PR number from the suffix of a session name.
// E.g. "fix-nil-pointer-369456" -> 369456
func extractPRNumber(name string) int {
	idx := strings.LastIndex(name, "-")
	if idx < 0 || idx == len(name)-1 {
		return 0
	}
	n, err := strconv.Atoi(name[idx+1:])
	if err != nil {
		return 0
	}
	return n
}



package tui

import (
	"testing"
	"time"

	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/session"
	"github.com/DataDog/pr-workstation/internal/tmux"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/stretchr/testify/assert"
)

func TestRenderSessionHistoryOverlay_Empty(t *testing.T) {
	m := Model{
		sessionHistoryPR:      42,
		sessionHistoryTitle:   "#42",
		sessionHistoryRecords: nil,
		showSessionHistory:    true,
		width:                 120,
		height:                40,
	}

	output := renderSessionHistoryOverlay(m)
	assert.Contains(t, output, "Sessions for #42")
	assert.Contains(t, output, "No sessions")
}

func TestRenderSessionHistoryOverlay_LocalRow(t *testing.T) {
	m := Model{
		sessionHistoryPR:      0,
		sessionHistoryTitle:   "my-feature-branch",
		sessionHistoryTmux:    "my-feature",
		sessionHistoryRecords: nil,
		showSessionHistory:    true,
		width:                 120,
		height:                40,
	}

	output := renderSessionHistoryOverlay(m)
	assert.Contains(t, output, "Sessions for my-feature-branch")
	assert.Contains(t, output, "tmux: my-feature")
	assert.NotContains(t, output, "No active sessions")
}

func TestRenderSessionHistoryOverlay_WithRecords(t *testing.T) {
	m := Model{
		sessionHistoryPR:    99,
		sessionHistoryTitle: "#99",
		sessionHistoryRecords: []session.SessionRecord{
			{
				PRNumber:    99,
				ActionType:  "fix CI",
				SessionType: session.SessionTypeManual,
				Outcome:     session.SessionOutcomeCompleted,
				StartedAt:   time.Now().Add(-5 * time.Minute),
			},
			{
				PRNumber:    99,
				ActionType:  "address feedback",
				SessionType: session.SessionTypeAutonomous,
				Outcome:     session.SessionOutcomeRunning,
				StartedAt:   time.Now().Add(-30 * time.Minute),
			},
		},
		sessionHistoryCursor: 0,
		showSessionHistory:   true,
		width:                120,
		height:               40,
	}

	output := renderSessionHistoryOverlay(m)
	assert.Contains(t, output, "Sessions for #99")
	assert.Contains(t, output, "fix CI")
	assert.Contains(t, output, "address feedback")
	assert.Contains(t, output, "j/k: navigate")
}

func TestSessionHistoryCursorBounds(t *testing.T) {
	records := []session.SessionRecord{
		{PRNumber: 1, ActionType: "a", StartedAt: time.Now()},
		{PRNumber: 1, ActionType: "b", StartedAt: time.Now()},
		{PRNumber: 1, ActionType: "c", StartedAt: time.Now()},
	}

	t.Run("cursor does not go below zero", func(t *testing.T) {
		m := &Model{
			sessionHistoryRecords: records,
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'k'}})
		assert.Equal(t, 0, m.sessionHistoryCursor)
	})

	t.Run("cursor does not exceed last index", func(t *testing.T) {
		m := &Model{
			sessionHistoryRecords: records,
			sessionHistoryCursor:  2,
			showSessionHistory:    true,
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'j'}})
		assert.Equal(t, 2, m.sessionHistoryCursor)
	})

	t.Run("cursor moves down", func(t *testing.T) {
		m := &Model{
			sessionHistoryRecords: records,
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'j'}})
		assert.Equal(t, 1, m.sessionHistoryCursor)
	})

	t.Run("cursor moves up", func(t *testing.T) {
		m := &Model{
			sessionHistoryRecords: records,
			sessionHistoryCursor:  2,
			showSessionHistory:    true,
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'k'}})
		assert.Equal(t, 1, m.sessionHistoryCursor)
	})

	t.Run("esc closes overlay", func(t *testing.T) {
		m := &Model{
			sessionHistoryRecords: records,
			sessionHistoryCursor:  1,
			showSessionHistory:    true,
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyEsc})
		assert.False(t, m.showSessionHistory)
	})
}

func TestRelativeTime(t *testing.T) {
	tests := []struct {
		name     string
		elapsed  time.Duration
		expected string
	}{
		{name: "just now", elapsed: 30 * time.Second, expected: "just now"},
		{name: "minutes", elapsed: 5 * time.Minute, expected: "5m ago"},
		{name: "hours", elapsed: 3 * time.Hour, expected: "3h ago"},
		{name: "days", elapsed: 48 * time.Hour, expected: "2d ago"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, relativeTime(time.Now().Add(-tt.elapsed)))
		})
	}
}

