func TestRenderSessionHistoryOverlay_AutonomousStates(t *testing.T) {
	t.Run("autonomous running shows rolling", func(t *testing.T) {
		m := Model{
			sessionHistoryPR: 1,
			sessionHistoryRecords: []session.SessionRecord{
				{ID: "r1", PRNumber: 1, SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning, StartedAt: time.Now()},
			},
			agentNeedsAttention: map[string]bool{},
			width:               120,
			height:              40,
		}
		output := renderSessionHistoryOverlay(m)
		assert.Contains(t, output, "🔄")
	})

	t.Run("autonomous running needs attention shows warning", func(t *testing.T) {
		m := Model{
			sessionHistoryPR: 1,
			sessionHistoryRecords: []session.SessionRecord{
				{ID: "r1", PRNumber: 1, SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning, StartedAt: time.Now()},
			},
			agentNeedsAttention: map[string]bool{"r1": true},
			width:               120,
			height:              40,
		}
		output := renderSessionHistoryOverlay(m)
		assert.Contains(t, output, "🙋")
	})

	t.Run("autonomous failed shows error message", func(t *testing.T) {
		m := Model{
			sessionHistoryPR: 1,
			sessionHistoryRecords: []session.SessionRecord{
				{ID: "r1", PRNumber: 1, SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeFailed, Error: "process exited unexpectedly", StartedAt: time.Now()},
			},
			agentNeedsAttention: map[string]bool{},
			width:               120,
			height:              40,
		}
		output := renderSessionHistoryOverlay(m)
		assert.Contains(t, output, "❌")
		assert.Contains(t, output, "process exited unexpectedly")
	})

	t.Run("autonomous completed shows checkmark", func(t *testing.T) {
		now := time.Now()
		m := Model{
			sessionHistoryPR: 1,
			sessionHistoryRecords: []session.SessionRecord{
				{ID: "r1", PRNumber: 1, SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeCompleted, StartedAt: now, EndedAt: &now},
			},
			agentNeedsAttention: map[string]bool{},
			width:               120,
			height:              40,
		}
		output := renderSessionHistoryOverlay(m)
		assert.Contains(t, output, "✅")
	})
}

func TestSessionHistoryDeleteKey(t *testing.T) {
	t.Run("d deletes selected record and adjusts cursor", func(t *testing.T) {
		store := session.NewStore(t.TempDir())
		store.Load()
		r1 := session.SessionRecord{ID: "r1", PRNumber: 1, SessionType: session.SessionTypeManual, Outcome: session.SessionOutcomeCompleted, StartedAt: time.Now()}
		r2 := session.SessionRecord{ID: "r2", PRNumber: 1, SessionType: session.SessionTypeManual, Outcome: session.SessionOutcomeFailed, StartedAt: time.Now()}
		_ = store.AddRecord(r1)
		_ = store.AddRecord(r2)

		m := &Model{
			sessionHistoryPR:      1,
			sessionHistoryRecords: []session.SessionRecord{r1, r2},
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
			sessionStore:          store,
			prSessions:            make(map[int]tmux.PRSession),
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'D'}})

		assert.Len(t, m.sessionHistoryRecords, 1)
		assert.Equal(t, "r2", m.sessionHistoryRecords[0].ID)
		assert.Equal(t, 0, m.sessionHistoryCursor)
		// Verify persisted to store
		assert.Len(t, store.RecordsForPR(1), 1)
	})

	t.Run("d on last record clamps cursor", func(t *testing.T) {
		store := session.NewStore(t.TempDir())
		store.Load()
		r1 := session.SessionRecord{ID: "r1", PRNumber: 1, SessionType: session.SessionTypeManual, Outcome: session.SessionOutcomeCompleted, StartedAt: time.Now()}
		_ = store.AddRecord(r1)

		m := &Model{
			sessionHistoryPR:      1,
			sessionHistoryRecords: []session.SessionRecord{r1},
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
			sessionStore:          store,
			prSessions:            make(map[int]tmux.PRSession),
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'D'}})

		assert.Empty(t, m.sessionHistoryRecords)
		assert.Equal(t, 0, m.sessionHistoryCursor)
	})

	t.Run("d on empty list is a no-op", func(t *testing.T) {
		m := &Model{
			sessionHistoryPR:      1,
			sessionHistoryRecords: nil,
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
		}
		m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'D'}})
		assert.Empty(t, m.sessionHistoryRecords)
	})
}

func TestSessionHistoryDeleteTmuxSession(t *testing.T) {
	t.Run("d with no records destroys tmux session", func(t *testing.T) {
		m := &Model{
			sessionHistoryPR:      42,
			sessionHistoryRecords: nil,
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
			prSessions: map[int]tmux.PRSession{
				42: {SessionName: "my-session", PRNumber: 42},
			},
			sessionMgr: &tmux.SessionManager{Runner: &mockRunner{}},
		}
		_, cmd := m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'D'}})
		assert.NotNil(t, cmd)
		assert.False(t, m.showSessionHistory)
	})

	t.Run("d with no records and no tmux session is no-op", func(t *testing.T) {
		m := &Model{
			sessionHistoryPR:      42,
			sessionHistoryRecords: nil,
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
			prSessions:            make(map[int]tmux.PRSession),
			sessionMgr:            &tmux.SessionManager{Runner: &mockRunner{}},
		}
		_, cmd := m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'D'}})
		assert.Nil(t, cmd)
	})
}

func TestSessionHistoryDeleteRunningSession(t *testing.T) {
	t.Run("d on running record returns stop command", func(t *testing.T) {
		store := session.NewStore(t.TempDir())
