func TestSessionHistoryEnterKey_AutonomousRunning(t *testing.T) {
	t.Run("enter with only running records switches to session", func(t *testing.T) {
		m := &Model{
			sessionHistoryPR: 42,
			sessionHistoryRecords: []session.SessionRecord{
				{ID: "r1", PRNumber: 42, SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning, StartedAt: time.Now()},
			},
			sessionHistoryCursor: 0,
			showSessionHistory:   true,
			prSessions: map[int]tmux.PRSession{
				42: {SessionName: "my-session", PRNumber: 42},
			},
			sessionMgr: &tmux.SessionManager{Runner: &mockRunner{}},
			rows:       []PRRow{{PR: github.PR{Number: 42}, RowType: RowTypePR}},
		}
		_, cmd := m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyEnter})
		assert.False(t, m.showSessionHistory)
		assert.NotNil(t, cmd)
	})

	t.Run("enter with no sessions and no PR row is no-op", func(t *testing.T) {
		m := &Model{
			sessionHistoryPR:      99,
			sessionHistoryRecords: nil,
			sessionHistoryCursor:  0,
			showSessionHistory:    true,
			prSessions:            make(map[int]tmux.PRSession),
			sessionMgr:            &tmux.SessionManager{Runner: &mockRunner{}},
			rows:                  []PRRow{{PR: github.PR{Number: 42}, RowType: RowTypePR}},
		}
		_, cmd := m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyEnter})
		assert.False(t, m.showSessionHistory)
		assert.Nil(t, cmd)
	})

	t.Run("enter on completed autonomous follows up", func(t *testing.T) {
		m := &Model{
			sessionHistoryPR: 42,
			sessionHistoryRecords: []session.SessionRecord{
				{ID: "r1", PRNumber: 42, SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeCompleted, StartedAt: time.Now()},
			},
			sessionHistoryCursor: 0,
			showSessionHistory:   true,
			prSessions:           make(map[int]tmux.PRSession),
			sessionMgr:           &tmux.SessionManager{Runner: &mockRunner{}},
			rows:                 []PRRow{{PR: github.PR{Number: 42}, RowType: RowTypePR}},
		}
		_, _ = m.updateSessionHistoryOverlay(tea.KeyMsg{Type: tea.KeyEnter})
		assert.False(t, m.showSessionHistory)
	})
}



package tui

import (
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/charmbracelet/lipgloss"
)

// Retro green phosphor CRT palette
var (
	green  = lipgloss.Color("#00ff41")
	yellow = lipgloss.Color("#ffb000")
	red    = lipgloss.Color("#ff3333")
	gray   = lipgloss.Color("#4a5a4a")
	white  = lipgloss.Color("#b0c4b0")
	cyan   = lipgloss.Color("#00ccaa")

	actionColor = lipgloss.Color("#ff9500")
	selectedBg  = lipgloss.Color("#1a3a1a")

	rowEvenBg = lipgloss.Color("#0a0f0a")
	rowOddBg  = lipgloss.Color("#0f1a0f")

	titleStyle = lipgloss.NewStyle().
			Bold(true).
			Foreground(lipgloss.Color("#00ff41")).
			MarginBottom(1)

	helpColor = lipgloss.Color("#6b8a6b")

	statusBarStyle = lipgloss.NewStyle().
			Foreground(gray).
			MarginTop(1)

	helpStyle = lipgloss.NewStyle().
			Foreground(helpColor)

	errorStyle = lipgloss.NewStyle().
			Foreground(red)

	loadingStyle = lipgloss.NewStyle().
			Foreground(cyan)

	searchBarStyle = lipgloss.NewStyle().
			Border(lipgloss.RoundedBorder()).
			BorderForeground(helpColor).
			Padding(0, 1)

	searchBarActiveStyle = lipgloss.NewStyle().
				Border(lipgloss.RoundedBorder()).
				BorderForeground(cyan).
				Padding(0, 1)

	helpCategoryStyle = lipgloss.NewStyle().
				Bold(true).
				Foreground(cyan)

	spinnerFrames = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}
)

func prStatusColor(status github.PRStatus) lipgloss.Color {
	switch status {
	case github.PRStatusApproved:
		return green
	case github.PRStatusDraft, github.PRStatusOpen, github.PRStatusWaitingForReviews, github.PRStatusReviewedWithComments:
		return yellow
	case github.PRStatusCIFailing, github.PRStatusDraftCIFailing, github.PRStatusChangesRequested, github.PRStatusHasConflicts:
		return red
	case github.PRStatusMerged, github.PRStatusInMergeQueue:
		return cyan
	default:
		return gray
	}
}

func statusEmoji(status github.PRStatus) string {
	switch status {
	case github.PRStatusDraft:
		return "📝"
	case github.PRStatusDraftCIFailing:
		return "📝"
	case github.PRStatusOpen:
		return "🔵"
	case github.PRStatusWaitingForReviews:
		return "⏳"
	case github.PRStatusChangesRequested:
		return "🔴"
	case github.PRStatusReviewedWithComments:
		return "💬"
	case github.PRStatusApproved:
		return "✅"
	case github.PRStatusCIFailing:
		return "❌"
	case github.PRStatusMerged:
		return "🟣"
	case github.PRStatusInMergeQueue:
		return "🚂"
	case github.PRStatusHasConflicts:
		return "⚠️"
	default:
		return ""
	}
}

func actionEmoji(action github.Action) string {
	switch action {
	case github.ActionFixCI:
		return "🔧"
	case github.ActionAddressFeedback:
		return "💬"
	case github.ActionMerge:
		return "🚀"
	case github.ActionInvestigate:
		return "🔍"
	case github.ActionResolveConflicts:
		return "⚠️"
	default:
		return ""
	}
}



package tui

import (
	"testing"
	"time"

	"github.com/DataDog/pr-workstation/internal/deploy"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/session"
	"github.com/stretchr/testify/assert"
)

func makeSvc(targetState deploy.ConductorRunState) deploy.ConductorServiceStatus {
	return deploy.ConductorServiceStatus{
		ServiceName: "svc",
		TargetStatuses: []deploy.ConductorTargetStatus{
			{Target: "prod", State: targetState},
		},
	}
}

func makeSvcNamed(name string, targetState deploy.ConductorRunState) deploy.ConductorServiceStatus {
	return deploy.ConductorServiceStatus{
		ServiceName: name,
		TargetStatuses: []deploy.ConductorTargetStatus{
			{Target: "prod", State: targetState},
		},
	}
}

func TestConductorFullyDeployed(t *testing.T) {
	tests := []struct {
		name     string
		statuses []deploy.ConductorServiceStatus
		expected bool
	}{
		{
			name:     "nil (never fetched)",
			statuses: nil,
			expected: false,
		},
		{
			name:     "empty slice (error sentinel)",
			statuses: []deploy.ConductorServiceStatus{},
			expected: false,
		},
		{
			name:     "all deployed",
			statuses: []deploy.ConductorServiceStatus{makeSvc(deploy.ConductorRunStateDeployed)},
			expected: true,
		},
		{
			name:     "one target not deployed",
			statuses: []deploy.ConductorServiceStatus{makeSvc(deploy.ConductorRunStateDeploying)},
			expected: false,
		},
		{
			name: "multiple services all deployed",
			statuses: []deploy.ConductorServiceStatus{
				makeSvc(deploy.ConductorRunStateDeployed),
				makeSvc(deploy.ConductorRunStateDeployed),
			},
			expected: true,
		},
		{
			name: "multiple services one pending",
			statuses: []deploy.ConductorServiceStatus{
				makeSvc(deploy.ConductorRunStateDeployed),
				makeSvc(deploy.ConductorRunStatePending),
			},
			expected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, conductorFullyDeployed(tt.statuses))
		})
	}
}

func TestWorstConductorState(t *testing.T) {
	tests := []struct {
		name     string
		states   []deploy.ConductorRunState
		expected deploy.ConductorRunState
	}{
		{
			name:     "single deployed",
			states:   []deploy.ConductorRunState{deploy.ConductorRunStateDeployed},
			expected: deploy.ConductorRunStateDeployed,
		},
		{
			name:     "deploy failed is worst",
			states:   []deploy.ConductorRunState{deploy.ConductorRunStateDeployed, deploy.ConductorRunStateDeployFailed},
			expected: deploy.ConductorRunStateDeployFailed,
		},
		{
			name:     "build failed outranks deploying",
			states:   []deploy.ConductorRunState{deploy.ConductorRunStateDeploying, deploy.ConductorRunStateBuildFailed},
			expected: deploy.ConductorRunStateBuildFailed,
		},
		{
			name:     "deploying outranks building",
			states:   []deploy.ConductorRunState{deploy.ConductorRunStateBuilding, deploy.ConductorRunStateDeploying},
			expected: deploy.ConductorRunStateDeploying,
		},
		{
			name:     "pending outranks deployed",
			states:   []deploy.ConductorRunState{deploy.ConductorRunStateDeployed, deploy.ConductorRunStatePending},
			expected: deploy.ConductorRunStatePending,
		},
		{
			name:     "deploy failed beats all",
			states:   []deploy.ConductorRunState{deploy.ConductorRunStateBuildFailed, deploy.ConductorRunStateDeployFailed, deploy.ConductorRunStateBuilding},
			expected: deploy.ConductorRunStateDeployFailed,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var statuses []deploy.ConductorServiceStatus
			for _, state := range tt.states {
				statuses = append(statuses, makeSvc(state))
			}
			assert.Equal(t, tt.expected, worstConductorState(statuses))
		})
	}
}

func TestConductorColumnText(t *testing.T) {
	mergedAt := time.Date(2026, 2, 27, 10, 0, 0, 0, time.UTC)
	spinner := "⠋"

	tests := []struct {
		name     string
		row      PRRow
		expected string
	}{
		{
			name:     "open PR shows dash",
			row:      PRRow{PR: github.PR{State: github.PRStateOpen}},
			expected: "-",
		},
		{
			name: "merged without changes label shows dash",
			row: PRRow{
				PR: github.PR{State: github.PRStateMerged, Labels: []string{"go"}},
			},
			expected: "-",
		},
		{
			name: "merged with changes label and nil conductor statuses shows spinner",
			row: PRRow{
				PR: github.PR{
					State:    github.PRStateMerged,
					Labels:   []string{"changes:my-svc"},
					MergedAt: &mergedAt,
				},
				ConductorStatuses: nil,
			},
			expected: spinner,
		},
		{
			name: "merged with changes label and empty conductor statuses shows fetch error",
			row: PRRow{
				PR: github.PR{
					State:    github.PRStateMerged,
					Labels:   []string{"changes:my-svc"},
					MergedAt: &mergedAt,
				},
				ConductorStatuses: []deploy.ConductorServiceStatus{},
			},
			expected: "fetch error",
		},
		{
			name: "all targets deployed",
			row: PRRow{
				PR: github.PR{
					State:    github.PRStateMerged,
					Labels:   []string{"changes:my-svc"},
					MergedAt: &mergedAt,
				},
				ConductorStatuses: []deploy.ConductorServiceStatus{makeSvc(deploy.ConductorRunStateDeployed)},
			},
			expected: "✅ 1/1",
		},
		{
			name: "single failed target shows category counts",
			row: PRRow{
				PR: github.PR{
					State:    github.PRStateMerged,
					Labels:   []string{"changes:my-svc"},
					MergedAt: &mergedAt,
				},
				ConductorStatuses: []deploy.ConductorServiceStatus{makeSvc(deploy.ConductorRunStateDeployFailed)},
			},
			expected: "✅0 ❌1",
		},
		{
			name: "in progress shows progress fraction",
			row: PRRow{
				PR: github.PR{
					State:    github.PRStateMerged,
					Labels:   []string{"changes:my-svc"},
					MergedAt: &mergedAt,
				},
				ConductorStatuses: []deploy.ConductorServiceStatus{{
					ServiceName: "my-svc",
					TargetStatuses: []deploy.ConductorTargetStatus{
						{Target: "staging", State: deploy.ConductorRunStateBuilding},
						{Target: "prod", State: deploy.ConductorRunStateDeploying},
					},
				}},
			},
			expected: "🔄 0/2",
		},
		{
			name: "mix of deployed failed and in-progress shows category counts",
			row: PRRow{
				PR: github.PR{
					State:    github.PRStateMerged,
					Labels:   []string{"changes:my-svc"},
					MergedAt: &mergedAt,
				},
				ConductorStatuses: []deploy.ConductorServiceStatus{{
					ServiceName: "my-svc",
					TargetStatuses: []deploy.ConductorTargetStatus{
						{Target: "staging", State: deploy.ConductorRunStateDeployed},
						{Target: "prod", State: deploy.ConductorRunStateDeployFailed},
						{Target: "mgmt", State: deploy.ConductorRunStateDeploying},
					},
				}},
			},
			expected: "✅1 ❌1 🔄1",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, conductorColumnText(tt.row, spinner))
		})
	}
}

func TestAgentColumnText(t *testing.T) {
	now := time.Now()
	fiveMinAgo := now.Add(-5 * time.Minute)
	fifteenMinAgo := now.Add(-15 * time.Minute)

	tests := []struct {
		name                  string
		records               []session.SessionRecord
		hasActiveSession      bool
		autonomyEnabled       bool
		needsAttention        map[string]bool
		sessionNeedsAttention bool
		expected              string
	}{
		{
			name:     "no records no session",
			expected: "",
		},
		{
			name:             "manual active session",
			hasActiveSession: true,
			expected:         "💻",
		},
		{
			name: "autonomous running (non-autonomy mode)",
			records: []session.SessionRecord{
				{SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning},
			},
			expected: "🤖",
		},
		{
			name: "autonomous running takes priority over active session",
			records: []session.SessionRecord{
				{SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning},
			},
			hasActiveSession: true,
			expected:         "🤖",
		},
		{
			name: "failed most recent",
			records: []session.SessionRecord{
				{Outcome: session.SessionOutcomeFailed},
			},
			expected: "❌",
		},
		{
			name: "completed within 10 minutes",
			records: []session.SessionRecord{
				{Outcome: session.SessionOutcomeCompleted, EndedAt: &fiveMinAgo},
			},
			expected: "✅",
		},
		{
			name: "completed more than 10 minutes ago",
			records: []session.SessionRecord{
				{Outcome: session.SessionOutcomeCompleted, EndedAt: &fifteenMinAgo},
			},
			expected: "",
		},
		{
			name: "active session takes priority over failed",
			records: []session.SessionRecord{
				{Outcome: session.SessionOutcomeFailed},
			},
			hasActiveSession: true,
			expected:         "💻",
		},
		{
			name:                  "session needs attention shows human emoji",
			hasActiveSession:      true,
			sessionNeedsAttention: true,
			expected:              "💻🙋",
		},
		{
			name: "failed takes priority over recently completed",
			records: []session.SessionRecord{
				{Outcome: session.SessionOutcomeFailed, StartedAt: now},
				{Outcome: session.SessionOutcomeCompleted, EndedAt: &fiveMinAgo, StartedAt: now.Add(-1 * time.Hour)},
			},
			expected: "❌",
		},
		// Autonomy-enabled paths
		{
			name:            "autonomy enabled, no agents",
			autonomyEnabled: true,
			expected:        "🤖",
		},
		{
			name:            "autonomy enabled, one running agent",
			autonomyEnabled: true,
			records: []session.SessionRecord{
				{ID: "r1", SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning},
			},
			expected: "🤖: 1🔄",
		},
		{
			name:            "autonomy enabled, needs attention",
			autonomyEnabled: true,
			needsAttention:  map[string]bool{"r1": true},
			records: []session.SessionRecord{
				{ID: "r1", SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning},
			},
			expected: "🤖: 1🙋",
		},
		{
			name:            "autonomy enabled, compound state",
			autonomyEnabled: true,
			needsAttention:  map[string]bool{"r1": true, "r2": true},
			records: []session.SessionRecord{
				{ID: "r1", SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning},
				{ID: "r2", SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning},
				{ID: "r3", SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeFailed, EndedAt: &fiveMinAgo},
				{ID: "r4", SessionType: session.SessionTypeAutonomous, Outcome: session.SessionOutcomeRunning},
			},
			expected: "🤖: 2🙋 1❌ 1🔄",
		},
		{
			name:            "autonomy enabled, ignores non-autonomous records",
			autonomyEnabled: true,
			records: []session.SessionRecord{
				{ID: "r1", SessionType: session.SessionTypeManual, Outcome: session.SessionOutcomeRunning},
			},
			expected: "🤖",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, agentColumnText(tt.records, tt.hasActiveSession, tt.autonomyEnabled, tt.needsAttention, tt.sessionNeedsAttention))
		})
	}
}

func TestMaxAgentWidth(t *testing.T) {
	t.Run("empty rows returns minimum", func(t *testing.T) {
		assert.Equal(t, 7, maxAgentWidth(nil))
	})

	t.Run("short statuses return minimum", func(t *testing.T) {
		rows := []PRRow{
			{AgentStatus: "💻"},
			{AgentStatus: "❌"},
		}
		assert.Equal(t, 7, maxAgentWidth(rows))
	})

	t.Run("long compound status expands width", func(t *testing.T) {
		rows := []PRRow{
			{AgentStatus: "🤖: 2🙋 1❌ 1🔄"},
		}
		w := maxAgentWidth(rows)
		assert.GreaterOrEqual(t, w, 7)
		assert.LessOrEqual(t, w, 22)
	})

	t.Run("capped at 22", func(t *testing.T) {
		rows := []PRRow{
			{AgentStatus: "🤖: 99🙋 99❌ 99🔄 99✅"},
		}
		assert.Equal(t, 22, maxAgentWidth(rows))
	})
}

func TestBuildTableColumnCount(t *testing.T) {
	rows := []PRRow{
