			PR:      github.PR{Number: 1, State: github.PRStateOpen, RepoNameWithOwner: "owner/repo"},
			Status:  github.PRStatusWaitingForReviews,
			Action:  github.ActionNone,
			RowType: RowTypePR,
		},
	}

	tbl := buildTable(rows, 160, "⠋", 7)
