func TestBuildTableLocalRowRendering(t *testing.T) {
	rows := []PRRow{
		{
			PR: github.PR{
				RepoNameWithOwner: "DataDog/dd-source",
				Title:             "add-caching",
				HeadRefName:       "add-caching",
			},
			RowType:      RowTypeLocal,
			TmuxSession:  "add-caching",
			WorktreePath: "/Users/dev/dd/dd-source-add-caching",
		},
		{
			PR: github.PR{
				Number:            123,
				RepoNameWithOwner: "DataDog/dd-source",
				Title:             "Fix auth bug",
				State:             github.PRStateOpen,
			},
			Status:  github.PRStatusWaitingForReviews,
			Action:  github.ActionNone,
			RowType: RowTypePR,
		},
	}

	tbl := buildTable(rows, 120, "⠋", 7)
	renderedRows := tbl.GetVisibleRows()
	assert.Len(t, renderedRows, 2)

	// Local row should have "local" in PR column
