	// PR row should have "#123" in PR column
	prPRData := renderedRows[1].Data[colPR]
	assert.Contains(t, prPRData, "#123")
}

func TestAvailabilityColumnText(t *testing.T) {
	spinner := "⠋"
	deployed := deploy.OverallDeployed
	notDeployed := deploy.OverallNotDeployed

	tests := []struct {
		name     string
		row      PRRow
		expected string
	}{
		{
			name:     "open PR shows dash",
			row:      PRRow{PR: github.PR{State: github.PRStateOpen}},
			expected: "-",
		},
		{
			name: "merged nil deploy status shows spinner",
			row: PRRow{
				PR:           github.PR{State: github.PRStateMerged},
				DeployStatus: nil,
			},
			expected: spinner,
		},
		{
			name: "merged with no deployments shows dash",
			row: PRRow{
				PR:           github.PR{State: github.PRStateMerged},
				DeployStatus: &deployed,
				Deployments:  []deploy.ServiceDeployment{},
			},
			expected: "-",
		},
		{
			name: "merged with targets shows fraction",
			row: PRRow{
				PR:           github.PR{State: github.PRStateMerged},
				DeployStatus: &notDeployed,
				Deployments: []deploy.ServiceDeployment{
					{
						Service: "my-svc",
						Targets: []deploy.DeployTarget{
							{Datacenter: "us1", Status: deploy.DeployStatusDeployed},
							{Datacenter: "eu1", Status: deploy.DeployStatusNotDeployed},
							{Datacenter: "ap1", Status: deploy.DeployStatusDeployed},
						},
					},
				},
			},
			expected: "2/3",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, availabilityColumnText(tt.row, spinner))
		})
	}
}



# pr-workstation

A terminal dashboard that puts all your GitHub PRs in one place — status, reviews, CI, deployments — so you always know what to do next.

**Why use this?**

- **One place for all your PRs**: See status, reviews, CI, and deployments across all repos at a glance — no more bouncing between GitHub tabs
- **Know what to do next**: Every PR shows a suggested action (fix CI, address feedback, merge) so you always know your next move
- **Track deployments end-to-end**: See Conductor builds and Availability rollout status for merged PRs without leaving the terminal
- **AI-assisted PR workflows**: Launch Claude directly into a PR workspace with context-aware commands — fix CI failures, address review comments, or investigate deploy failures with a single keypress
- **Workspace management**: Each PR gets a dedicated tmux session with the right worktree, so context-switching between PRs is instant


**This entire project has been 100% vibecoded with zero human review of code. We push to main-actual to bypass branch protection rules. Ship baby ship. Please contribute!**

See the following demo (audio on):

https://github.com/user-attachments/assets/422ed3a3-e655-457c-a40f-1dd844a2343a

![Go](https://img.shields.io/badge/Go-1.25-blue)

## Install

Clone and install:

```bash
git clone -b main-actual git@github.com:DataDog/pr-workstation.git
cd pr-workstation
go install .
```

> **Note**: The default branch (`main`) is locked down by org-level rulesets. All development happens on `main-actual`. Push directly to `main-actual` — no PRs needed.

This builds the binary and places it in `$GOPATH/bin`, which is typically already on your `$PATH`. If it isn't, you can build manually and move the binary yourself:

```bash
go build -o pr-workstation ./
mv pr-workstation ~/bin/  # or /usr/local/bin, etc.
```

## Prerequisites

| Tool | Purpose | Required? |
|------|---------|-----------|
| [Go](https://golang.org/) 1.25+ | Build the binary | Yes |
| [`gh`](https://cli.github.com/) | GitHub CLI — fetches PR data and manages PRs | Yes |
| [`git`](https://git-scm.com/) | Worktree management for PR workspaces | Yes |
| [`tmux`](https://github.com/tmux/tmux) | Workspace sessions for PRs and Claude | Yes |
| [`claude`](https://docs.anthropic.com/en/docs/claude-code) | Claude Code — AI-powered PR actions | Optional |
| [`authanywhere`](https://datadoghq.atlassian.net/wiki/x/CwKE3g) | Internal auth for Conductor/devflow APIs | Optional |
| [`ddtool`](https://datadoghq.atlassian.net/wiki/spaces/ENG/pages/2396684402/ddtool#Installation) | Conductor API authentication | Optional |

`gh` must be authenticated (`gh auth login`) before first use.

Without `authanywhere` and `ddtool`, deployment tracking (Conductor and Availability columns) is unavailable — everything else works. Without `claude`, workspace sessions still open but AI-assisted actions won't work.

## Repo directory convention

Workspace management assumes repos are cloned to `~/dd/` (e.g. `~/dd/dd-source`). Without this layout, workspace features will show "Repo directory not found" errors.

## Usage

```bash
pr-workstation
```

On first run, a default config is created at `~/.config/pr-workstation/config.yaml` with a single "My PRs" view.

## Features

### PR status tracking

Automatically determines the status of each PR:

| Status | Meaning |
|--------|---------|
| Draft | PR is in draft mode |
| Draft (CI failing) | Draft with failing CI |
| Waiting for reviews | Awaiting human review |
| Changes requested | Reviewer requested changes or unresolved review threads (including on draft PRs) |
| Reviewed (comments) | Has reviews but not all approved |
| Approved | All reviewers approved |
| CI failing | CI checks are failing |
| Merged | PR is merged |

### Suggested actions

Shows what you should do next for each PR:

| Action | When |
|--------|------|
| Fix CI | CI checks are failing |
| Address feedback | Changes requested or unresolved comments (including drafts) |
| Merge | PR is approved |

### PR detail overlay

Press `space` on any PR to see details:

- **Open PRs**: Shows failing CI checks and unresolved review comments (with markdown rendering)
- **Merged PRs**: Shows Conductor per-target deployment state and Availability rollout status across datacenters

Navigation within the overlay:

| Key | Action |
|-----|--------|
| `j` / `k` | Navigate items |
| `o` | Open item URL (CI check details or Conductor Mosaic) |
| `enter` | Expand/collapse (Availability service targets or review comment body) |
| `c` | Launch Claude (fix CI, address feedback, or investigate conductor failure) |
| `space` / `esc` | Close overlay |

### Deployment tracking

For merged PRs, tracks deployment via two systems:

**Conductor** — Shows per-target deployment state (building, deploying, deployed, failed) with progress counts. When in progress, shows abbreviated target status for the primary service.

**Availability (devflow)** — Shows deployed/total target counts across datacenters.

### Workspace management

Pressing `enter` on any PR opens a tmux session as a workspace:

1. If a session already exists, switches to it
2. If a worktree matches the PR's branch, auto-selects it
3. Otherwise, shows a worktree picker (filtered to exclude temp directories) with the PR branch displayed for reference
4. Launches Claude in the new session with a context-aware command depending on the PR's action

Press `D` to destroy the tmux session for the selected PR. Press `N` to create a new work session (not tied to a specific PR).

### Claude integration

| Key | Context | Behavior |
|-----|---------|----------|
| `enter` | Main view, any PR | Open workspace and launch Claude with action-aware command (`/dd:ci:fix`, `/dd:pr:address-feedback`, or `/dd:pr:followup`) |
| `c` | Main view, open PR | Same as `enter` — launch Claude with action-aware command |
| `C` | Main view, open PR | Launch Claude with a custom prompt |
| `c` | PR detail overlay, failing CI check | Launch Claude to fix CI (`/dd:ci:fix`) |
| `c` | PR detail overlay, review comment | Launch Claude to address feedback (`/dd:pr:address-feedback`) |
| `c` | PR detail overlay, failed conductor target | Launch Claude to investigate deployment failure (with service, target, run GUID, Mosaic URL, and error details) |

Claude launches in a named tmux window within the PR's session. All sessions use `--permission-mode acceptEdits`, meaning file reads and edits are auto-approved while shell commands still require approval.

**Note on Claude Code skills**: The `/dd:pr:followup`, `/dd:ci:fix`, and `/dd:pr:address-feedback` commands are custom Claude Code slash commands. Without them configured in Claude Code, the commands will be sent but not recognized — Claude will still open but won't have the specialized context.

### Autonomous agents

Press `W` on an open or merged PR to toggle autonomous mode. When enabled, the dashboard automatically spawns Claude agents to work on actionable PRs without manual intervention.

**How it works:**

1. On each refresh cycle, the dashboard evaluates all autonomy-enabled PRs
2. PRs with a `Fix CI` or `Address feedback` action are candidates for spawning
3. An idempotency key `(repo, prNumber, actionType, headCommitOID)` prevents duplicate work — if a session (manual or autonomous) already covers the same action on the same commit, no new agent is spawned
4. Up to 3 concurrent autonomous agents run at a time (configurable). `Fix CI` is prioritized over `Address feedback`
5. Each agent runs in a named tmux window (e.g., `auto-fix-ci`) within the PR's session

**Agent lifecycle:**

- Agents write a status file on completion (`completed` or `failed` with error details)
- If a tmux window disappears without a status file, the dashboard checks whether the head commit changed to infer success or failure
- The Agent column shows a compound display: `🤖: 2🔄 1⚠️` (2 running, 1 needs attention)

Autonomy flags persist in `~/.config/pr-workstation/sessions/autonomy.json`.

### Attention and acknowledgment

The dashboard monitors all active Claude sessions (manual and autonomous) by periodically capturing tmux pane output. When a session's output stops changing for 30 seconds, it's flagged as needing attention — the agent may be waiting for permission approval, stuck, or finished.

**Indicators:**

- `⚠️` in the Agent column for autonomous sessions needing attention
- `💻🙋` for manual sessions with stale output
- `⚠️` icon in the session history overlay for running sessions that are stale

**Acknowledging attention:** Press `a` to acknowledge attention on the selected row. This records the current pane content so the alert is suppressed until the output changes again. If the agent produces new output and then stalls again, attention re-triggers.

### Session history

Press `H` on any PR to open the session history overlay, showing all past and current sessions for that PR.

Each entry displays:
- Session type: `🤖` (autonomous) or `💻` (manual)
- State: `🔄` (running), `✅` (completed), `❌` (failed), `⚠️` (needs attention)
- Action type and relative timestamp

**Navigation:**

| Key | Action |
|-----|--------|
| `j` / `k` | Navigate sessions |
| `enter` | Follow up (launches Claude to review the previous session's transcript) or switch to a running session |
| `o` | Open the Claude transcript |
| `d` | Delete session record (or destroy a running session) |
| `esc` | Close |

Session records are stored in `~/.config/pr-workstation/sessions/history.json` with automatic cleanup (max 100 per PR, 30-day retention).

### GitHub actions

Press `g` on an open PR to access GitHub actions:

- **Close** — Close the PR
- **Comment** — Add a comment to the PR
- **Mark ready** — Convert a draft PR to ready for review
- **Request merge** — Add a `/merge` comment to the PR

### Other actions

- **`i`** — Trigger devflow integrate for the PR
- **`d`** — Open the deploy run overlay
- **`o`** — Open the PR in browser

### Filtering

- **`f`** — Filter by repository (pick from a list or type a custom name)
- **`s`** — Filter by status category

### Saved views

- **`v`** — Switch between saved views or create new ones

Views use GitHub search query syntax. Examples:
- `author:@me` — your PRs
- `review-requested:@me` — PRs requesting your review
- `repo:DataDog/dd-source author:@me` — your PRs in a specific repo

Views are persisted to the config file.

## Keybindings

### Main view

| Key | Action |
|-----|--------|
| `j` / `k` / arrows | Navigate rows |
| `enter` | Open workspace and launch Claude (any PR) |
| `c` | Launch Claude with context-aware action (open PRs) |
| `C` | Launch Claude with custom prompt |
| `W` | Toggle autonomous agents |
| `a` | Acknowledge attention |
| `H` | Session history |
| `N` | New work session |
| `I` | Import session |
| `D` | Kill workspace session |
| `o` | Open PR in browser |
| `space` | PR detail overlay |
| `/` | Search |
| `g` | GitHub actions (close, comment, mark ready, merge) |
| `i` | Trigger integrate |
| `d` | Deploy run |
| `f` | Filter by repo |
| `s` | Filter by status |
| `v` | Switch saved view |
| `r` | Refresh |
| `?` | Help |
| `q` | Quit |

### PR detail overlay

| Key | Action |
|-----|--------|
| `j` / `k` | Navigate items (CI checks, review comments, conductor targets, availability services) |
| `o` | Open URL (CI check details or Conductor Mosaic) |
| `enter` | Expand/collapse (availability service targets or review comment body) |
| `c` | Launch Claude for selected item (fix CI, address feedback, or investigate conductor failure) |
| `space` / `esc` | Close |

### Session history overlay

| Key | Action |
|-----|--------|
| `j` / `k` | Navigate sessions |
| `enter` | Follow up or switch to running session |
| `o` | Open transcript |
| `d` | Delete / destroy session |
| `esc` | Close |

### Worktree picker

| Key | Action |
|-----|--------|
| `j` / `k` | Navigate options |
| `enter` | Select worktree |
| `esc` | Cancel |

## Table columns

| Column | Description |
|--------|-------------|
| Repo | Repository name |
| PR | PR number (with `>` selection indicator) |
| Title | PR title |
| Status | Computed PR status |
| Action | Suggested next action |
| Agent | Autonomous agent status and attention indicators |
| Conductor | Conductor deployment state for merged PRs |
| Avail | Availability deployment progress (deployed/total) |

## Configuration

Config lives at `~/.config/pr-workstation/config.yaml`:

```yaml
views:
  - name: "My PRs"
    query: "author:@me"
    default: true
  - name: "Review requests"
    query: "review-requested:@me"
  - name: "Team PRs"
    query: "org:DataDog team:my-team"
```

| Field | Description |
|-------|-------------|
| `views[].name` | Display name in the view picker |
| `views[].query` | GitHub search query (any `gh search prs` syntax) |
| `views[].default` | Set `true` for the view active on startup |

## How it works

1. Searches for PRs using `gh search prs` with the active view's query
2. Fetches detailed PR data concurrently via `gh pr view` (reviews, CI status, labels)
3. Queries unresolved review thread counts via GitHub GraphQL API
4. For merged PRs with `changes:` labels, fetches Conductor deployment status
5. For merged PRs, fetches Availability deployment status from the devflow API
6. Auto-refreshes every 3 minutes; fully-deployed PRs skip deploy refetch



package tui

import (
	"context"
	"fmt"
	"strings"
	"testing"
	"time"

	"github.com/DataDog/pr-workstation/internal/config"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/session"
	"github.com/DataDog/pr-workstation/internal/tmux"
	"github.com/stretchr/testify/assert"
)

type mockRunner struct {
	output []byte
	err    error
}

func (m *mockRunner) Run(_ context.Context, _ string, _ ...string) ([]byte, error) {
	return m.output, m.err
}

// Verify mockRunner implements CommandRunner
var _ github.CommandRunner = (*mockRunner)(nil)

// mockAutonomyStore satisfies the autonomySessionStore interface for testing.
type mockAutonomyStore struct {
	running map[string]bool // "repo/prNum/actionType/oid" → true
}

func (m *mockAutonomyStore) HasRunningSession(repo string, prNumber int, actionType string, headCommitOID string) bool {
	key := fmt.Sprintf("%s/%d/%s/%s", repo, prNumber, actionType, headCommitOID)
	return m.running[key]
}

func TestPollRunningSessionsCmd(t *testing.T) {
	now := time.Now()

	t.Run("window still exists returns no completions", func(t *testing.T) {
		running := []session.SessionRecord{
			{ID: "s1", PRNumber: 42, WindowName: "ci-fix", StartedAt: now, Outcome: session.SessionOutcomeRunning},
		}
		mgr := &tmux.SessionManager{Runner: &mockRunner{output: []byte("ci-fix\nclaude\n")}}
		sessions := map[int]tmux.PRSession{
			42: {SessionName: "sess", PRNumber: 42},
		}

		cmd := pollRunningSessionsCmd(running, mgr, sessions, "", nil, nil)
		msg := cmd().(sessionsPollResultMsg)
		assert.Empty(t, msg.completedIDs)
		assert.Empty(t, msg.unexpectedTerminations)
	})

	t.Run("window gone, first observation → no termination (grace period starts)", func(t *testing.T) {
		running := []session.SessionRecord{
			{ID: "s1", PRNumber: 42, WindowName: "ci-fix", StartedAt: now, Outcome: session.SessionOutcomeRunning},
		}
		mgr := &tmux.SessionManager{Runner: &mockRunner{output: []byte("claude\n")}}
		sessions := map[int]tmux.PRSession{
			42: {SessionName: "sess", PRNumber: 42},
		}

		cmd := pollRunningSessionsCmd(running, mgr, sessions, "", nil, nil)
		msg := cmd().(sessionsPollResultMsg)
		assert.Empty(t, msg.completedIDs)
		assert.Empty(t, msg.unexpectedTerminations)
		assert.Contains(t, msg.updatedMissing, "s1")
	})

	t.Run("window gone, in grace period → no termination", func(t *testing.T) {
		running := []session.SessionRecord{
			{ID: "s1", PRNumber: 42, WindowName: "ci-fix", StartedAt: now, Outcome: session.SessionOutcomeRunning},
		}
		mgr := &tmux.SessionManager{Runner: &mockRunner{output: []byte("claude\n")}}
		sessions := map[int]tmux.PRSession{
			42: {SessionName: "sess", PRNumber: 42},
		}
		// Already observed 30 seconds ago — still within the 1-minute grace period
		previouslyMissing := map[string]time.Time{"s1": now.Add(-30 * time.Second)}

		cmd := pollRunningSessionsCmd(running, mgr, sessions, "", previouslyMissing, nil)
		msg := cmd().(sessionsPollResultMsg)
		assert.Empty(t, msg.unexpectedTerminations)
		assert.Contains(t, msg.updatedMissing, "s1") // timestamp carried forward
	})

	t.Run("window gone, grace period elapsed → unexpectedTermination", func(t *testing.T) {
		running := []session.SessionRecord{
			{ID: "s1", PRNumber: 42, WindowName: "ci-fix", StartedAt: now, Outcome: session.SessionOutcomeRunning},
		}
		mgr := &tmux.SessionManager{Runner: &mockRunner{output: []byte("claude\n")}}
		sessions := map[int]tmux.PRSession{
			42: {SessionName: "sess", PRNumber: 42},
		}
		// First observed 2 minutes ago — grace period has elapsed
		previouslyMissing := map[string]time.Time{"s1": now.Add(-2 * time.Minute)}

		cmd := pollRunningSessionsCmd(running, mgr, sessions, "", previouslyMissing, nil)
		msg := cmd().(sessionsPollResultMsg)
		assert.Equal(t, []string{"s1"}, msg.unexpectedTerminations)
		assert.NotContains(t, msg.updatedMissing, "s1")
	})

	t.Run("no session for PR, first observation → no termination", func(t *testing.T) {
		running := []session.SessionRecord{
			{ID: "s1", PRNumber: 42, WindowName: "ci-fix", StartedAt: now, Outcome: session.SessionOutcomeRunning},
		}
		mgr := &tmux.SessionManager{Runner: &mockRunner{}}
		sessions := map[int]tmux.PRSession{}

		cmd := pollRunningSessionsCmd(running, mgr, sessions, "", nil, nil)
		msg := cmd().(sessionsPollResultMsg)
		assert.Empty(t, msg.unexpectedTerminations)
		assert.Contains(t, msg.updatedMissing, "s1")
	})

	t.Run("empty running list returns empty result", func(t *testing.T) {
		mgr := &tmux.SessionManager{Runner: &mockRunner{}}
		cmd := pollRunningSessionsCmd(nil, mgr, nil, "", nil, nil)
		msg := cmd().(sessionsPollResultMsg)
		assert.Empty(t, msg.completedIDs)
		assert.Empty(t, msg.unexpectedTerminations)
	})

	t.Run("config session captures pane content", func(t *testing.T) {
		runner := &responseMockRunner{responses: map[string]mockRunnerResponse{
			"tmux has-session -t my-local":                    {output: []byte("")},
			"tmux list-windows -t my-local -F #{window_name}": {output: []byte("claude\n")},
			"tmux capture-pane -p -t my-local:claude -S -50":  {output: []byte("Would you like to proceed?\n❯ 1. Yes\n")},
		}}
		mgr := &tmux.SessionManager{Runner: runner}
		entries := []config.SessionEntry{
			{TmuxSession: "my-local", Type: config.SessionTypeLocal},
		}

		cmd := pollRunningSessionsCmd(nil, mgr, nil, "", nil, entries)
		msg := cmd().(sessionsPollResultMsg)
		assert.Equal(t, "Would you like to proceed?\n❯ 1. Yes\n", msg.paneCaptures["my-local:claude"])
	})

	t.Run("autonomous session captures pane content by record ID", func(t *testing.T) {
		paneContent := "Building project...\nRunning tests...\n"
		runner := &responseMockRunner{responses: map[string]mockRunnerResponse{
			"tmux list-windows -t sess -F #{window_name}": {output: []byte("ci-fix\nclaude\n")},
			"tmux capture-pane -p -t sess:ci-fix -S -50":  {output: []byte(paneContent)},
		}}
		mgr := &tmux.SessionManager{Runner: runner}
		running := []session.SessionRecord{
			{ID: "s1", PRNumber: 42, WindowName: "ci-fix", SessionType: session.SessionTypeAutonomous, StartedAt: now, Outcome: session.SessionOutcomeRunning},
		}
		sessions := map[int]tmux.PRSession{
			42: {SessionName: "sess", PRNumber: 42},
		}

		cmd := pollRunningSessionsCmd(running, mgr, sessions, "", nil, nil)
		msg := cmd().(sessionsPollResultMsg)
		assert.Equal(t, paneContent, msg.paneCaptures["s1"])
	})
}

// responseMockRunner maps "command arg1 arg2..." to (output, error) for multi-step tmux interactions.
type responseMockRunner struct {
	responses map[string]mockRunnerResponse
}

type mockRunnerResponse struct {
	output []byte
	err    error
}

func (m *responseMockRunner) Run(_ context.Context, name string, args ...string) ([]byte, error) {
	key := name + " " + strings.Join(args, " ")
	if resp, ok := m.responses[key]; ok {
		return resp.output, resp.err
	}
	return nil, fmt.Errorf("unexpected command: %s", key)
}

func TestPaneStalenessThreshold(t *testing.T) {
	t.Run("constant value", func(t *testing.T) {
		assert.Equal(t, 6, paneStaleThreshold)
	})
}

func TestStalenessTracking(t *testing.T) {
	t.Run("unchanged content increments count", func(t *testing.T) {
		m := Model{
			paneSnapshots:      map[string]string{"s1": "some output"},
			paneUnchangedCount: map[string]int{"s1": 2},
		}
		captures := map[string]string{"s1": "some output"}

		newSnapshots, newCounts := applyStaleness(m.paneSnapshots, m.paneUnchangedCount, captures)
		assert.Equal(t, 3, newCounts["s1"])
		assert.Equal(t, "some output", newSnapshots["s1"])
	})

	t.Run("changed content resets count", func(t *testing.T) {
		m := Model{
			paneSnapshots:      map[string]string{"s1": "old output"},
			paneUnchangedCount: map[string]int{"s1": 5},
		}
		captures := map[string]string{"s1": "new output"}

		_, newCounts := applyStaleness(m.paneSnapshots, m.paneUnchangedCount, captures)
		assert.Equal(t, 0, newCounts["s1"])
	})

	t.Run("new pane starts at zero", func(t *testing.T) {
		m := Model{
			paneSnapshots:      map[string]string{},
			paneUnchangedCount: map[string]int{},
		}
		captures := map[string]string{"s1": "first capture"}

		_, newCounts := applyStaleness(m.paneSnapshots, m.paneUnchangedCount, captures)
		assert.Equal(t, 0, newCounts["s1"])
	})

	t.Run("disappeared pane removed from tracking", func(t *testing.T) {
		m := Model{
			paneSnapshots:      map[string]string{"s1": "output", "s2": "other"},
			paneUnchangedCount: map[string]int{"s1": 3, "s2": 1},
		}
		// s2 no longer reported
		captures := map[string]string{"s1": "output"}

		newSnapshots, newCounts := applyStaleness(m.paneSnapshots, m.paneUnchangedCount, captures)
		assert.Contains(t, newSnapshots, "s1")
		assert.NotContains(t, newSnapshots, "s2")
		assert.NotContains(t, newCounts, "s2")
	})

	t.Run("autonomous session stale → needs attention", func(t *testing.T) {
		counts := map[string]int{"s1": paneStaleThreshold}
		snapshots := map[string]string{"s1": "stuck content"}
		attention := stalenessToAttention(counts, snapshots, nil)
		assert.True(t, attention["s1"])
	})

	t.Run("autonomous session not yet stale → no attention", func(t *testing.T) {
		counts := map[string]int{"s1": paneStaleThreshold - 1}
		snapshots := map[string]string{"s1": "some content"}
		attention := stalenessToAttention(counts, snapshots, nil)
		assert.False(t, attention["s1"])
	})

	t.Run("acked content suppresses attention", func(t *testing.T) {
		counts := map[string]int{"s1": paneStaleThreshold}
		snapshots := map[string]string{"s1": "stuck content"}
		acked := map[string]string{"s1": "stuck content"}
		attention := stalenessToAttention(counts, snapshots, acked)
		assert.Empty(t, attention)
	})

	t.Run("acked content with changed screen re-triggers attention", func(t *testing.T) {
		counts := map[string]int{"s1": paneStaleThreshold}
		snapshots := map[string]string{"s1": "new stuck content"}
		acked := map[string]string{"s1": "old stuck content"}
		attention := stalenessToAttention(counts, snapshots, acked)
		assert.True(t, attention["s1"])
	})

	t.Run("config session stale → session needs attention", func(t *testing.T) {
		counts := map[string]int{"my-local:claude": paneStaleThreshold}
		snapshots := map[string]string{"my-local:claude": "stuck"}
		sessionAttention := stalenessToSessionAttention(counts, snapshots, nil)
		assert.True(t, sessionAttention["my-local"])
	})

	t.Run("config session not stale → no session attention", func(t *testing.T) {
		counts := map[string]int{"my-local:claude": paneStaleThreshold - 1}
		snapshots := map[string]string{"my-local:claude": "content"}
		sessionAttention := stalenessToSessionAttention(counts, snapshots, nil)
		assert.Empty(t, sessionAttention)
	})

	t.Run("acked config session suppresses attention", func(t *testing.T) {
		counts := map[string]int{"my-local:claude": paneStaleThreshold}
		snapshots := map[string]string{"my-local:claude": "stuck"}
		acked := map[string]string{"my-local:claude": "stuck"}
		sessionAttention := stalenessToSessionAttention(counts, snapshots, acked)
		assert.Empty(t, sessionAttention)
	})
}

func TestMarkReadyCmd(t *testing.T) {
	tests := []struct {
		name        string
		runner      *mockRunner
		prNumber    int
		expectedErr string
	}{
		{
			name:     "success",
			runner:   &mockRunner{output: []byte(""), err: nil},
			prNumber: 42,
		},
		{
			name:        "error",
			runner:      &mockRunner{err: fmt.Errorf("not authorized")},
			prNumber:    42,
			expectedErr: "not authorized",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cmd := markReadyCmd(tt.runner, "https://github.com/org/repo/pull/42", tt.prNumber)
			msg := cmd().(markReadyMsg)

			assert.Equal(t, tt.prNumber, msg.prNumber)
			if tt.expectedErr != "" {
				assert.ErrorContains(t, msg.err, tt.expectedErr)
				return
			}
			assert.NoError(t, msg.err)
		})
	}
}

func TestUpdateBranchCmd(t *testing.T) {
	tests := []struct {
		name        string
		runner      *mockRunner
		prNumber    int
		expectedErr string
	}{
		{
			name:     "success",
			runner:   &mockRunner{output: []byte(""), err: nil},
			prNumber: 42,
		},
		{
			name:        "error",
			runner:      &mockRunner{err: fmt.Errorf("merge conflict")},
			prNumber:    42,
			expectedErr: "merge conflict",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			cmd := updateBranchCmd(tt.runner, "org/repo", tt.prNumber)
			msg := cmd().(githubActionMsg)

			assert.Equal(t, tt.prNumber, msg.prNumber)
			assert.Equal(t, "update branch", msg.action)
			if tt.expectedErr != "" {
				assert.ErrorContains(t, msg.err, tt.expectedErr)
				return
			}
			assert.NoError(t, msg.err)
		})
