}

func makeCandidate(repo string, prNumber int, actionType string, oid string) evaluateAutonomousSpawnsCandidate {
	return evaluateAutonomousSpawnsCandidate{
		sess:          tmux.PRSession{SessionName: "sess", PRNumber: prNumber},
		pr:            github.PR{Number: prNumber, RepoNameWithOwner: repo},
		actionType:    actionType,
		claudeCmd:     "some prompt",
		windowName:    "auto-" + actionType,
		headCommitOID: oid,
		recordID:      "test-record-id",
	}
}

func TestEvaluateAutonomousSpawnsCmd(t *testing.T) {
	mgr := &tmux.SessionManager{Runner: &mockRunner{}}

	t.Run("no candidates returns nil", func(t *testing.T) {
		cmd := evaluateAutonomousSpawnsCmd(mgr, &mockAutonomyStore{}, nil, 0, 3)
		msg := cmd()
		assert.Nil(t, msg)
	})

	t.Run("idempotency: skips already-running session", func(t *testing.T) {
		store := &mockAutonomyStore{
			running: map[string]bool{"owner/repo/42/fix-ci/abc123": true},
		}
		candidates := []evaluateAutonomousSpawnsCandidate{
			makeCandidate("owner/repo", 42, "fix-ci", "abc123"),
		}
		cmd := evaluateAutonomousSpawnsCmd(mgr, store, candidates, 0, 3)
		msg := cmd()
		assert.Nil(t, msg)
	})

	t.Run("concurrency limit: skips when limit reached", func(t *testing.T) {
		store := &mockAutonomyStore{}
		candidates := []evaluateAutonomousSpawnsCandidate{
			makeCandidate("owner/repo", 42, "fix-ci", "abc123"),
		}
		// runningCount already at limit
		cmd := evaluateAutonomousSpawnsCmd(mgr, store, candidates, 3, 3)
		msg := cmd()
		assert.Nil(t, msg)
	})

	t.Run("spawns when slot available and not running", func(t *testing.T) {
		store := &mockAutonomyStore{}
		candidates := []evaluateAutonomousSpawnsCandidate{
			makeCandidate("owner/repo", 42, "fix-ci", "abc123"),
		}
		cmd := evaluateAutonomousSpawnsCmd(mgr, store, candidates, 0, 3)
		msg := cmd()
		// autonomousSpawnMsg returned (even if spawn errors due to no tmux)
		_, ok := msg.(autonomousSpawnMsg)
		assert.True(t, ok)
	})
}

func TestBuildAutonomousPrompt(t *testing.T) {
	pr := github.PR{Number: 42, URL: "https://github.com/org/repo/pull/42"}
	statusPath := "/home/user/.config/pr-workstation/sessions/agent-abc123.status"

	t.Run("fix-ci includes lifecycle preamble and status file path", func(t *testing.T) {
		prompt := buildAutonomousPrompt(pr, "fix-ci", statusPath)
		assert.Contains(t, prompt, "autonomous agent")
		assert.Contains(t, prompt, statusPath)
		assert.Contains(t, prompt, "/dd:ci:fix")
		assert.Contains(t, prompt, "https://github.com/org/repo/pull/42")
		assert.Contains(t, prompt, `{"outcome": "completed"}`)
	})

	t.Run("address-feedback uses correct slash command", func(t *testing.T) {
		prompt := buildAutonomousPrompt(pr, "address-feedback", statusPath)
		assert.Contains(t, prompt, "/dd:pr:address-feedback")
		assert.Contains(t, prompt, statusPath)
	})

	t.Run("default action falls back to followup", func(t *testing.T) {
		prompt := buildAutonomousPrompt(pr, "custom", statusPath)
		assert.Contains(t, prompt, "/dd:pr:followup")
	})

	t.Run("resolve-conflicts includes rebase instruction", func(t *testing.T) {
		prompt := buildAutonomousPrompt(pr, "resolve-conflicts", statusPath)
		assert.Contains(t, prompt, "merge conflicts")
		assert.Contains(t, prompt, "Rebase onto the base branch")
		assert.Contains(t, prompt, statusPath)
	})
}



package tui

import (
	"fmt"
	"strings"

	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/charmbracelet/lipgloss"
)

type helpEntry struct {
	key      string
	desc     string
	disabled bool
}

type helpCategory struct {
	name    string
	entries []helpEntry
}

var (
	disabledColor = lipgloss.Color("#2a3a2a")

	helpOverlayStyle = lipgloss.NewStyle().
				Border(lipgloss.RoundedBorder()).
				BorderForeground(green).
				Padding(1, 2)
)

func renderHelpOverlay(m Model) string {
	row := m.findSelectedPRRow()
	hasSession := false
	if row != nil {
		if row.RowType == RowTypeLocal {
			hasSession = true
		} else {
			_, hasSession = m.prSessions[row.PR.Number]
		}
	}

	isLocal := row != nil && row.RowType == RowTypeLocal
	isOpen := row != nil && row.RowType != RowTypeLocal && row.PR.State == github.PRStateOpen
	isMerged := row != nil && row.RowType != RowTypeLocal && row.PR.State == github.PRStateMerged

	actionLabel := "claude"
	if row != nil {
		actionLabel = contextActionLabel(row.Action)
	}

	// Left column categories
	left := []helpCategory{
		{
			name: "Table",
			entries: []helpEntry{
				{"q", "quit", false},
				{"r", "refresh", false},
				{"/", "search", false},
				{"f", "filter repo", false},
				{"s", "filter status", false},
				{"v", "saved view", false},
			},
		},
		{
			name: "Explore",
			entries: []helpEntry{
				{"o", "open in browser", isLocal},
				{"space", "PR detail", isLocal},
				{"H", "sessions", false},
			},
		},
		{
			name: "Sessions",
			entries: []helpEntry{
				{"N", "new work", false},
				{"I", "import session", false},
				{"D", "kill workspace", !hasSession},
			},
		},
	}

	// Right column categories
	right := []helpCategory{
		{
			name: "Agents",
			entries: []helpEntry{
				{"enter", "session", !isOpen && !isMerged && !isLocal},
				{"c", actionLabel, !isOpen && !(isMerged && row != nil && row.Action == github.ActionInvestigate)},
				{"C", "custom prompt", !isOpen},
				{"W", "toggle autonomy", !isOpen && !isMerged},
				{"a", "ack attention", false},
			},
		},
		{
			name: "Actions",
			entries: []helpEntry{
				{"g", "github actions", !isOpen},
				{"i", "integrate", !isOpen},
				{"d", "deploy", !isOpen},
			},
		},
		{
			name: "Local",
			entries: []helpEntry{
				{"enter", "switch to session", !isLocal},
				{"o", "new PR", !isLocal},
				{"O", "create PR", !isLocal},
			},
		},
	}

	leftCol := renderHelpColumn(left)
	rightCol := renderHelpColumn(right)

	columns := lipgloss.JoinHorizontal(lipgloss.Top, leftCol, "    ", rightCol)

	var b strings.Builder
	b.WriteString(overlayTitleStyle.Render("Keybindings"))
	b.WriteString("\n\n")
	b.WriteString(columns)
	b.WriteString("\n")
	footerStyle := lipgloss.NewStyle().Foreground(gray)
	b.WriteString(footerStyle.Render("highlighted actions apply to current row"))
	b.WriteString("\n")
	b.WriteString(footerStyle.Render("esc or ? to close"))

	content := helpOverlayStyle.Render(b.String())
	return centerOverlay(content, m.width, m.height)
}

func renderHelpColumn(categories []helpCategory) string {
	keyActive := lipgloss.NewStyle().Foreground(white).Bold(true)
	descActive := lipgloss.NewStyle().Foreground(gray)
	keyDisabled := lipgloss.NewStyle().Foreground(disabledColor)
	descDisabled := lipgloss.NewStyle().Foreground(disabledColor)

	// find max key width across all categories in this column
	maxKeyLen := 0
	for _, cat := range categories {
		for _, e := range cat.entries {
			if len(e.key) > maxKeyLen {
				maxKeyLen = len(e.key)
			}
		}
	}

	var b strings.Builder
	for _, cat := range categories {
		b.WriteString(helpCategoryStyle.Render(cat.name))
		b.WriteString("\n")
		for _, e := range cat.entries {
			paddedKey := fmt.Sprintf("%-*s", maxKeyLen, e.key)
			ks, ds := keyActive, descActive
			if e.disabled {
				ks, ds = keyDisabled, descDisabled
			}
			b.WriteString(fmt.Sprintf("  %s  %s\n", ks.Render(paddedKey), ds.Render(e.desc)))
		}
		b.WriteString("\n")
	}
	return b.String()
}

func contextActionLabel(action github.Action) string {
	switch action {
	case github.ActionFixCI:
		return "fix CI"
	case github.ActionAddressFeedback:
		return "address feedback"
	case github.ActionInvestigate:
		return "investigate"
	case github.ActionResolveConflicts:
		return "resolve conflicts"
	default:
		return "claude"
	}
}



package tui

import (
	"fmt"
	"strings"
	"time"

	"github.com/DataDog/pr-workstation/internal/session"
	"github.com/DataDog/pr-workstation/internal/tmux"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

func (m *Model) updateSessionHistoryOverlay(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	records := m.sessionHistoryRecords

	switch msg.String() {
	case "esc":
		m.showSessionHistory = false
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	case "j", "down":
		if m.sessionHistoryCursor < len(records)-1 {
			m.sessionHistoryCursor++
		}
		return m, nil
	case "k", "up":
		if m.sessionHistoryCursor > 0 {
			m.sessionHistoryCursor--
		}
		return m, nil
	case "enter":
		if len(records) == 0 {
			m.showSessionHistory = false
			return m, m.switchToSessionHistoryPR()
		}
		record := records[m.sessionHistoryCursor]
		m.showSessionHistory = false
		if record.Outcome == session.SessionOutcomeRunning {
			return m, m.switchToSessionHistoryPR()
		}
		return m, m.followUpFromSession(record)
	case "D":
		if len(records) == 0 {
			return m, m.destroySessionHistoryTmux()
		}
		record := records[m.sessionHistoryCursor]
		if record.Outcome == session.SessionOutcomeRunning {
			return m, m.stopAndDeleteRunningSession(record)
		}
		_ = m.sessionStore.DeleteRecord(record.ID)
		m.sessionHistoryRecords = removeRecordByID(m.sessionHistoryRecords, record.ID)
		if m.sessionHistoryCursor > 0 && m.sessionHistoryCursor >= len(m.sessionHistoryRecords) {
			m.sessionHistoryCursor--
		}
		m.updateAgentStatuses()
		m.table = m.rebuildTable()
		return m, nil
	}
	return m, nil
}

// stopAndDeleteRunningSession kills the tmux session and removes the record.
// Uses the same destroySessionCmd as the "D" key on the main table.
func (m *Model) stopAndDeleteRunningSession(record session.SessionRecord) tea.Cmd {
	_ = m.sessionStore.DeleteRecord(record.ID)
	m.sessionHistoryRecords = removeRecordByID(m.sessionHistoryRecords, record.ID)
	if m.sessionHistoryCursor > 0 && m.sessionHistoryCursor >= len(m.sessionHistoryRecords) {
		m.sessionHistoryCursor--
	}
	m.updateAgentStatuses()
	m.table = m.rebuildTable()

	sess, ok := m.prSessions[m.sessionHistoryPR]
	if !ok {
		return nil
	}
	return destroySessionCmd(m.sessionMgr, sess.SessionName)
}

// destroySessionHistoryTmux kills the tmux session shown at the top of the overlay.
func (m *Model) destroySessionHistoryTmux() tea.Cmd {
	sess, ok := m.prSessions[m.sessionHistoryPR]
	if !ok {
		return nil
	}
	m.showSessionHistory = false
	return destroySessionCmd(m.sessionMgr, sess.SessionName)
}

// switchToSessionHistoryPR switches to the tmux session for the PR currently
// shown in the session history overlay. Used when Enter is pressed with no
// past records to follow up on.
func (m *Model) switchToSessionHistoryPR() tea.Cmd {
	if sess, ok := m.prSessions[m.sessionHistoryPR]; ok {
		return createAndSwitchCmd(m.sessionMgr, sess)
	}
	r := m.findPRRowByNumber(m.sessionHistoryPR)
	if r == nil {
		return nil
	}
	return m.initiateWorktreeDiscovery(r, func(workDir string) tea.Cmd {
		sess := tmux.PRSession{
			SessionName: tmux.SanitizeSessionName(r.PR.Title, r.PR.Number),
			PRNumber:    r.PR.Number,
			PRTitle:     r.PR.Title,
			WorkDir:     workDir,
			Branch:      r.PR.HeadRefName,
			PRURL:       r.PR.URL,
		}
		return createAndSwitchCmd(m.sessionMgr, sess)
	})
}

func (m *Model) followUpFromSession(record session.SessionRecord) tea.Cmd {
	r := m.findPRRowByNumber(m.sessionHistoryPR)
	if r == nil {
		return nil
	}

	// When ClaudeSession is populated, --resume should be a CLI flag, not prompt text.
	// This path is currently unused and will need reworking when session resume is added.
	var prompt string
	if record.ClaudeSession != "" {
		prompt = fmt.Sprintf("--resume %s", record.ClaudeSession)
	} else {
		prompt = fmt.Sprintf("I want to follow up on a previous session for PR #%d. "+
			"The previous session ran action '%s' with prompt: %s. "+
			"Please review what was done and continue from where it left off.",
			record.PRNumber, record.ActionType, record.Prompt)
	}

	return m.launchClaudeForPR(r, prompt)
}

func (m *Model) findPRRowByNumber(prNumber int) *PRRow {
	for i := range m.rows {
		if m.rows[i].PR.Number == prNumber {
			return &m.rows[i]
		}
	}
	return nil
}

func renderSessionHistoryOverlay(m Model) string {
	var b strings.Builder

	b.WriteString(overlayTitleStyle.Render(fmt.Sprintf("Sessions for %s", m.sessionHistoryTitle)))
	b.WriteString("\n")
	b.WriteString(lipgloss.NewStyle().Foreground(gray).Render(strings.Repeat("─", 45)))
	b.WriteString("\n")

	// Active tmux session (not a session record — always shown at top, not navigable)
	tmuxName := m.sessionHistoryTmux
	if tmuxName == "" {
		if sess, ok := m.prSessions[m.sessionHistoryPR]; ok {
			tmuxName = sess.SessionName
		}
	}
	if tmuxName != "" {
		activeStyle := lipgloss.NewStyle().Foreground(cyan)
		b.WriteString(activeStyle.Render(fmt.Sprintf("  ▶ tmux: %s", tmuxName)))
		b.WriteString("\n")
	}

	// All session records in a single navigable list
	if len(m.sessionHistoryRecords) == 0 {
		if tmuxName == "" {
			b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("  No sessions"))
			b.WriteString("\n")
		}
	} else {
		for i, record := range m.sessionHistoryRecords {
			prefix := "  "
			style := lipgloss.NewStyle().Foreground(white)
			if i == m.sessionHistoryCursor {
				prefix = "> "
				style = style.Foreground(green).Bold(true)
			}

			typeIcon := sessionTypeIcon(record.SessionType)
			relTime := relativeTime(record.StartedAt)

			if record.Outcome == session.SessionOutcomeRunning {
				icon := "🔄"
				if m.agentNeedsAttention[record.ID] {
					icon = "🙋"
				}
				line := fmt.Sprintf("%s%s %s %-18s %8s",
					prefix,
					typeIcon,
					icon,
					truncate(record.ActionType, 18),
					relTime,
				)
				if i != m.sessionHistoryCursor {
					style = style.Foreground(cyan)
				}
				b.WriteString(style.Render(line))
				b.WriteString("\n")
			} else {
				outcomeIcon := sessionOutcomeIcon(record.Outcome)
				line := fmt.Sprintf("%s%s %-18s %8s  %s %s",
					prefix,
					typeIcon,
					truncate(record.ActionType, 18),
					relTime,
					outcomeIcon,
					record.Outcome.String(),
				)
				b.WriteString(style.Render(line))
				b.WriteString("\n")

				if record.Outcome == session.SessionOutcomeFailed && record.Error != "" {
					errStyle := lipgloss.NewStyle().Foreground(red)
					b.WriteString(errStyle.Render("    " + truncate(record.Error, 40)))
					b.WriteString("\n")
				}
			}
		}
	}

	b.WriteString("\n")
	b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | enter: follow up | D: delete | esc: close"))

	content := overlayStyle.Render(b.String())
	return centerOverlay(content, m.width, m.height)
}

func sessionTypeIcon(t session.SessionType) string {
	switch t {
	case session.SessionTypeAutonomous:
		return "🤖"
	default:
		return "💻"
	}
}

func sessionOutcomeIcon(o session.SessionOutcome) string {
	switch o {
	case session.SessionOutcomeRunning:
		return "🔄"
	case session.SessionOutcomeCompleted:
		return "✅"
	case session.SessionOutcomeFailed:
		return "❌"
	case session.SessionOutcomeInterrupted:
		return "⚠️"
	default:
		return ""
	}
}

func filterPastRecords(records []session.SessionRecord) []session.SessionRecord {
	var past []session.SessionRecord
	for _, r := range records {
		if r.Outcome != session.SessionOutcomeRunning {
			past = append(past, r)
		}
	}
	return past
}

func removeRecordByID(records []session.SessionRecord, id string) []session.SessionRecord {
	var result []session.SessionRecord
	for _, r := range records {
		if r.ID != id {
			result = append(result, r)
		}
	}
	return result
}

func relativeTime(t time.Time) string {
	d := time.Since(t)
	switch {
	case d < time.Minute:
		return "just now"
	case d < time.Hour:
		mins := int(d.Minutes())
		return fmt.Sprintf("%dm ago", mins)
	case d < 24*time.Hour:
		hours := int(d.Hours())
		return fmt.Sprintf("%dh ago", hours)
	default:
		days := int(d.Hours() / 24)
		return fmt.Sprintf("%dd ago", days)
	}
}



package tui

import (
	"fmt"
	"strings"
	"time"

	"github.com/DataDog/pr-workstation/internal/deploy"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/session"
	"github.com/charmbracelet/lipgloss"
	"github.com/evertras/bubble-table/table"
)

// conductorRunStateEmoji returns an emoji for a conductor run state.
func conductorRunStateEmoji(state deploy.ConductorRunState) string {
	switch state {
	case deploy.ConductorRunStateDeployed:
		return "✅"
	case deploy.ConductorRunStateDeploying, deploy.ConductorRunStateBuilding:
		return "🔄"
	case deploy.ConductorRunStateDeployFailed, deploy.ConductorRunStateBuildFailed:
		return "⚠️"
	case deploy.ConductorRunStatePending:
		return "⏳"
	default:
		return ""
	}
}

func worstConductorState(statuses []deploy.ConductorServiceStatus) deploy.ConductorRunState {
	priority := map[deploy.ConductorRunState]int{
		deploy.ConductorRunStateDeployFailed: 5,
		deploy.ConductorRunStateBuildFailed:  4,
		deploy.ConductorRunStateDeploying:    3,
		deploy.ConductorRunStateBuilding:     2,
		deploy.ConductorRunStatePending:      1,
		deploy.ConductorRunStateDeployed:     0,
	}
	worst := deploy.ConductorRunStateDeployed
	for _, svc := range statuses {
		for _, t := range svc.TargetStatuses {
			if priority[t.State] > priority[worst] {
				worst = t.State
			}
		}
	}
	return worst
}

func conductorAggregateColor(statuses []deploy.ConductorServiceStatus) lipgloss.Color {
	if len(statuses) == 0 {
		return red
	}
	switch worstConductorState(statuses) {
	case deploy.ConductorRunStateDeployed:
		return green
	case deploy.ConductorRunStateDeploying, deploy.ConductorRunStateBuilding, deploy.ConductorRunStatePending:
		return yellow
	case deploy.ConductorRunStateDeployFailed, deploy.ConductorRunStateBuildFailed:
		return red
	default:
		return gray
	}
}

func conductorColumnText(r PRRow, spinnerFrame string) string {
	if r.PR.State != github.PRStateMerged {
		return "-"
	}
	services := github.ExtractServiceNames(r.PR.Labels)
	if len(services) == 0 {
		return "-"
	}
	if r.ConductorStatuses == nil {
		return spinnerFrame
	}
	if len(r.ConductorStatuses) == 0 {
		return "fetch error"
	}

	deployed, failed, inProgress := 0, 0, 0
	for _, svc := range r.ConductorStatuses {
		for _, t := range svc.TargetStatuses {
			switch t.State {
			case deploy.ConductorRunStateDeployed:
				deployed++
			case deploy.ConductorRunStateDeployFailed, deploy.ConductorRunStateBuildFailed:
				failed++
			default:
				inProgress++
			}
		}
	}
	total := deployed + failed + inProgress

	if failed == 0 && inProgress == 0 {
		return fmt.Sprintf("✅ %d/%d", deployed, total)
	}

	if failed > 0 {
		parts := []string{fmt.Sprintf("✅%d", deployed), fmt.Sprintf("❌%d", failed)}
		if inProgress > 0 {
			parts = append(parts, fmt.Sprintf("🔄%d", inProgress))
		}
		return strings.Join(parts, " ")
	}

	return fmt.Sprintf("🔄 %d/%d", deployed, total)
}

func conductorColumnColor(r PRRow) lipgloss.Color {
	if r.PR.State != github.PRStateMerged {
		return gray
	}
	services := github.ExtractServiceNames(r.PR.Labels)
	if len(services) == 0 {
		return gray
	}
	if r.ConductorStatuses == nil {
		return cyan
	}
	return conductorAggregateColor(r.ConductorStatuses)
}

func availabilityColumnText(r PRRow, spinnerFrame string) string {
	if r.PR.State != github.PRStateMerged {
		return "-"
	}
	if r.DeployStatus == nil {
		return spinnerFrame
	}

	total := 0
	deployed := 0
	for _, svc := range r.Deployments {
		for _, t := range svc.Targets {
			total++
			if t.Status == deploy.DeployStatusDeployed {
				deployed++
			}
		}
	}

	if total == 0 {
		return "-"
	}
	return fmt.Sprintf("%d/%d", deployed, total)
}

func availabilityColumnColor(r PRRow) lipgloss.Color {
	if r.PR.State != github.PRStateMerged {
		return gray
	}
	if r.DeployStatus == nil {
		return cyan
	}
	if len(r.Deployments) == 0 {
		return gray
	}

	total := 0
	deployed := 0
	for _, svc := range r.Deployments {
		for _, t := range svc.Targets {
			total++
			if t.Status == deploy.DeployStatusDeployed {
				deployed++
			}
		}
	}

	if deployed == total {
		return green
	}
	if deployed == 0 {
		return red
	}
	return yellow
}

const (
	colPR        = "pr"
	colRepo      = "repo"
	colTitle     = "title"
	colStatus    = "status"
	colAction    = "action"
	colAgent     = "agent"
	colConductor = "conductor"
	colAvail     = "avail"
)

func maxAgentWidth(rows []PRRow) int {
	w := 7
	for _, r := range rows {
		display := lipgloss.Width(r.AgentStatus) + 2
		if display > w {
			w = display
		}
	}
	if w > 22 {
		w = 22
	}
	return w
}

func buildTable(rows []PRRow, width int, spinnerFrame string, agentWidth int, highlightedRow ...int) table.Model {
	prWidth := 8
	repoWidth := 20
	statusWidth := 22
	actionWidth := 20
	conductorWidth := 22
	availWidth := 14
	titleWidth := width - prWidth - repoWidth - statusWidth - actionWidth - agentWidth - conductorWidth - availWidth - 18
	if titleWidth < 20 {
		titleWidth = 20
	}

	idx := 0
	if len(highlightedRow) > 0 {
		idx = highlightedRow[0]
	}

	columns := []table.Column{
		table.NewColumn(colRepo, "Repo", repoWidth),
		table.NewColumn(colPR, "PR", prWidth),
		table.NewColumn(colTitle, "Title", titleWidth),
		table.NewColumn(colStatus, "Status", statusWidth),
		table.NewColumn(colAction, "Action", actionWidth),
		table.NewColumn(colAgent, "Agent", agentWidth),
		table.NewColumn(colConductor, "Conductor", conductorWidth),
		table.NewColumn(colAvail, "Availability", availWidth),
	}

	tableRows := make([]table.Row, 0, len(rows))
	for i, r := range rows {
		isSelected := i == idx

		bg := rowEvenBg
		if i%2 == 1 {
			bg = rowOddBg
		}
		if isSelected {
			bg = selectedBg
		}

		rowStyle := lipgloss.NewStyle().Background(bg)
		styledCell := func(text string, fg lipgloss.Color) string {
			return lipgloss.NewStyle().Foreground(fg).Background(bg).Render(text)
		}

		var prText, statusText, actionText, conductorText, availText string
		var statusFg, actionFg, conductorFg, availFg lipgloss.Color

		if r.RowType == RowTypeLocal {
			prText = " local"
			statusText = "-"
			statusFg = gray
			actionText = "-"
			actionFg = gray
			conductorText = "-"
			conductorFg = gray
			availText = "-"
			availFg = gray
		} else {
			prText = fmt.Sprintf(" #%d", r.PR.Number)

			statusText = statusEmoji(r.Status) + " " + r.Status.String()
			statusFg = prStatusColor(r.Status)

			actionText = "-"
			actionFg = gray
			if r.Action.IsActionable() {
				actionText = actionEmoji(r.Action) + " " + r.Action.String()
				actionFg = actionColor
			}

			conductorText = conductorColumnText(r, spinnerFrame)
			conductorFg = conductorColumnColor(r)

			availText = availabilityColumnText(r, spinnerFrame)
			availFg = availabilityColumnColor(r)
		}

		repoName := truncate(extractRepoName(r.PR.RepoNameWithOwner), repoWidth-3)
		repoText := " " + repoName
		if isSelected {
			repoText = ">" + repoName
		}

		tableRows = append(tableRows, table.NewRow(table.RowData{
			colPR:        styledCell(prText, white),
			colRepo:      styledCell(repoText, white),
			colTitle:     styledCell(truncate(r.PR.Title, titleWidth-2), white),
			colStatus:    styledCell(statusText, statusFg),
			colAction:    styledCell(actionText, actionFg),
			colAgent:     styledCell(r.AgentStatus, white),
			colConductor: styledCell(conductorText, conductorFg),
			colAvail:     styledCell(availText, availFg),
		}).WithStyle(rowStyle))
	}

	t := table.New(columns).
		WithRows(tableRows).
		WithBaseStyle(lipgloss.NewStyle().Foreground(white)).
		Focused(true).
		WithPageSize(30).
		WithHighlightedRow(idx)

	return t
}

func truncate(s string, max int) string {
	if len(s) <= max {
		return s
	}
	if max <= 3 {
		return s[:max]
	}
	return s[:max-3] + "..."
}

// RowType distinguishes PR rows from local work rows in the table.
type RowType string

const (
	RowTypePR    RowType = "pr"
	RowTypeLocal RowType = "local"
)

// PRRow combines PR data with computed statuses for display
type PRRow struct {
	PR                github.PR
	Status            github.PRStatus
	Action            github.Action
	DeployStatus      *deploy.OverallDeployStatus
	Deployments       []deploy.ServiceDeployment
	ConductorStatuses []deploy.ConductorServiceStatus // nil = still loading for PRs with changes: labels
	ConductorErr      error                           // preserved from last fetch attempt
	AgentStatus       string                          // emoji computed by agentColumnText()
	RowType           RowType
	WorktreePath      string // only populated for local rows
	TmuxSession       string // only populated for local rows
}

// agentColumnText computes the Agent column emoji from session records and active session state.
// When autonomyEnabled, shows a compound summary (🤖: 2🙋 1❌ 1🔄).
// Otherwise: autonomous running > manual active > failed > recently completed > blank.
// sessionNeedsAttention indicates whether the tmux session itself has a prompt waiting.
func agentColumnText(records []session.SessionRecord, hasActiveSession bool, autonomyEnabled bool, needsAttention map[string]bool, sessionNeedsAttention bool) string {
	if autonomyEnabled {
		attn, running, failed, completed := 0, 0, 0, 0
		for _, r := range records {
			if r.SessionType != session.SessionTypeAutonomous {
				continue
			}
			switch r.Outcome {
			case session.SessionOutcomeRunning:
				if needsAttention[r.ID] {
					attn++
				} else {
					running++
				}
			case session.SessionOutcomeFailed:
				if r.EndedAt != nil && time.Since(*r.EndedAt) < 10*time.Minute {
					failed++
				}
			case session.SessionOutcomeCompleted:
				if r.EndedAt != nil && time.Since(*r.EndedAt) < 10*time.Minute {
					completed++
				}
			}
		}
		if attn == 0 && running == 0 && failed == 0 && completed == 0 {
			return "🤖"
		}
		var parts []string
		if attn > 0 {
			parts = append(parts, fmt.Sprintf("%d🙋", attn))
		}
		if failed > 0 {
			parts = append(parts, fmt.Sprintf("%d❌", failed))
		}
		if running > 0 {
			parts = append(parts, fmt.Sprintf("%d🔄", running))
		}
		if completed > 0 {
			parts = append(parts, fmt.Sprintf("%d✅", completed))
		}
		return "🤖: " + strings.Join(parts, " ")
	}

	if len(records) > 0 {
		most := records[0] // records are most-recent-first
		if most.SessionType == session.SessionTypeAutonomous && most.Outcome == session.SessionOutcomeRunning {
			return "🤖"
		}
	}

	if hasActiveSession && sessionNeedsAttention {
		return "💻🙋"
	}

	if hasActiveSession {
		return "💻"
	}

	if len(records) > 0 {
		most := records[0]
		if most.Outcome == session.SessionOutcomeFailed {
			return "❌"
		}
		if most.Outcome == session.SessionOutcomeCompleted && most.EndedAt != nil && time.Since(*most.EndedAt) < 10*time.Minute {
			return "✅"
		}
	}

	return ""
}

// conductorFullyDeployed reports whether all conductor targets are in the Deployed state.
// nil means never fetched; [] means error on last fetch — both return false to trigger a fetch/retry.
func conductorFullyDeployed(statuses []deploy.ConductorServiceStatus) bool {
	if len(statuses) == 0 {
		return false
	}
	for _, svc := range statuses {
		for _, t := range svc.TargetStatuses {
			if t.State != deploy.ConductorRunStateDeployed {
				return false
			}
		}
	}
	return true
}



