func TestExtractRepoName(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "owner/repo format",
			input:    "DataDog/datadog-agent",
			expected: "datadog-agent",
		},
		{
			name:     "repo only",
			input:    "datadog-agent",
			expected: "datadog-agent",
		},
		{
			name:     "empty string",
			input:    "",
			expected: "",
		},
		{
			name:     "multiple slashes takes first split",
			input:    "org/repo/extra",
			expected: "repo/extra",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, tt.expected, extractRepoName(tt.input))
		})
	}
}

