func TestReviewThreadsMsgAppendsCommentItems(t *testing.T) {
	m := Model{
		prSessions:   make(map[int]tmux.PRSession),
		sessionInUse: make(map[string]string),
		sessionMgr:   &tmux.SessionManager{},
		showPRDetail: true,
		prDetailIdx:  0,
		prDetailItems: []prDetailItem{
			{Kind: prDetailCICheck, CheckName: "ci/test"},
		},
		prDetailReviewCommentsLoading: true,
	}
	m.rows = []PRRow{
		{PR: github.PR{Number: 42, State: github.PRStateOpen}},
	}
	m.table = m.rebuildTable()

	msg := reviewThreadsMsg{
		prNumber: 42,
		comments: []github.ReviewThreadComment{
			{Author: "alice", Body: "fix this", Path: "main.go"},
			{Author: "bob", Body: "looks wrong"},
		},
	}

	result, _ := m.Update(msg)
	updated := result.(Model)
	assert.False(t, updated.prDetailReviewCommentsLoading)
	assert.Len(t, updated.prDetailItems, 3) // 1 CI check + 2 comments
	assert.Equal(t, prDetailReviewComment, updated.prDetailItems[1].Kind)
	assert.Equal(t, "alice", updated.prDetailItems[1].CommentAuthor)
	assert.Equal(t, "main.go", updated.prDetailItems[1].CommentPath)
	assert.Equal(t, "bob", updated.prDetailItems[2].CommentAuthor)
}

