func TestPRDetailExpandComment(t *testing.T) {
	m := Model{
		prSessions:   make(map[int]tmux.PRSession),
		sessionInUse: make(map[string]string),
		sessionMgr:   &tmux.SessionManager{},
		showPRDetail: true,
		prDetailIdx:  0,
		prDetailItems: []prDetailItem{
			{Kind: prDetailCICheck, CheckName: "ci/test"},
			{Kind: prDetailReviewComment, CommentAuthor: "alice", CommentBody: "fix this"},
		},
		prDetailCursor:          1,
		prDetailExpandedComment: -1,
	}
	m.rows = []PRRow{
		{PR: github.PR{Number: 42, State: github.PRStateOpen}},
	}
	m.table = m.rebuildTable()

	// Press enter to expand comment at cursor
	result, _ := m.Update(tea.KeyMsg{Type: tea.KeyEnter})
	updated := result.(Model)
	assert.Equal(t, 1, updated.prDetailExpandedComment)

	// Press enter again to collapse
	result, _ = updated.Update(tea.KeyMsg{Type: tea.KeyEnter})
	updated = result.(Model)
	assert.Equal(t, -1, updated.prDetailExpandedComment)
}

