func TestClaudeWindowName(t *testing.T) {
	tests := []struct {
		name           string
		action         github.Action
		customPrompt   string
		expectedWindow string
	}{
		{"fix CI", github.ActionFixCI, "", "ci-fix"},
		{"address feedback", github.ActionAddressFeedback, "", "feedback"},
		{"investigate", github.ActionInvestigate, "", "investigate"},
		{"merge falls through to default", github.ActionMerge, "", "claude"},
		{"default", github.ActionNone, "", "claude"},
		{"custom prompt", github.ActionFixCI, "do something", "claude"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			windowName, _ := claudeWindowAndCmd(&PRRow{
				PR:     github.PR{URL: "https://github.com/org/repo/pull/1"},
				Action: tt.action,
			}, tt.customPrompt)
			assert.Equal(t, tt.expectedWindow, windowName)
		})
	}
}

func TestTransitionMatchedLocalEntries_MatchingBranchAndRepo(t *testing.T) {
	m := Model{
		prSessions:           make(map[int]tmux.PRSession),
		sessionInUse:         make(map[string]string),
		prCreationInProgress: make(map[string]bool),
		sessionMgr:           &tmux.SessionManager{},
		sessionState: config.SessionState{
			Sessions: []config.SessionEntry{
				{
					TmuxSession:  "my-feature",
					Repo:         "dd-source",
					WorktreePath: "/repo/wt-feature",
					Branch:       "my-feature",
					Type:         config.SessionTypeLocal,
				},
			},
		},
	}

	prs := []github.PR{
		{
			Number:            42,
			Title:             "Add caching",
