					WorktreePath: "/repo/wt-feature",
					Branch:       "my-feature",
					Type:         config.SessionTypeLocal,
				},
			},
		},
	}

	pr := github.PR{
		Number:      99,
		Title:       "Fix the thing",
		URL:         "https://github.com/DataDog/dd-source/pull/99",
		HeadRefName: "my-feature",
	}

	cmds := m.transitionEntryToPR(0, pr)
	assert.NotEmpty(t, cmds) // rename + save

	entry := m.sessionState.Sessions[0]
