func TestParsePRFromAgentOutput(t *testing.T) {
	tests := []struct {
		name    string
		output  string
		wantNum int
		wantURL string
	}{
		{
			name:    "standard github URL",
			output:  "Created PR\nhttps://github.com/DataDog/dd-source/pull/123",
			wantNum: 123,
			wantURL: "https://github.com/DataDog/dd-source/pull/123",
		},
		{
			name:    "URL with trailing newline",
			output:  "https://github.com/DataDog/dd-source/pull/456\n",
			wantNum: 456,
			wantURL: "https://github.com/DataDog/dd-source/pull/456",
		},
		{
			name:    "no URL",
			output:  "Some output without a URL",
			wantNum: 0,
			wantURL: "",
		},
		{
			name:    "URL in middle of output",
			output:  "line1\nhttps://github.com/org/repo/pull/789\nline3",
			wantNum: 789,
			wantURL: "https://github.com/org/repo/pull/789",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			num, url := parsePRFromAgentOutput(tt.output)
			assert.Equal(t, tt.wantNum, num)
			assert.Equal(t, tt.wantURL, url)
		})
	}
}

func TestPRAgentCompletedMsg_SuccessTransitions(t *testing.T) {
	m := Model{
		prSessions:           make(map[int]tmux.PRSession),
		sessionInUse:         make(map[string]string),
		prCreationInProgress: map[string]bool{"/repo/wt-feature": true},
		sessionMgr:           &tmux.SessionManager{},
		sessionState: config.SessionState{
			Sessions: []config.SessionEntry{
				{
					TmuxSession:  "my-feature",
					Repo:         "dd-source",
					WorktreePath: "/repo/wt-feature",
					Branch:       "my-feature",
					Type:         config.SessionTypeLocal,
				},
			},
		},
	}

	msg := prAgentCompletedMsg{
		worktreePath: "/repo/wt-feature",
		output:       "Done\nhttps://github.com/DataDog/dd-source/pull/42\n",
	}

	result, cmd := m.Update(msg)
	updated := result.(Model)

	assert.NotNil(t, cmd)
	assert.False(t, updated.prCreationInProgress["/repo/wt-feature"])
	assert.Equal(t, config.SessionTypePR, updated.sessionState.Sessions[0].Type)
	assert.Equal(t, 42, updated.sessionState.Sessions[0].PRNumber)
	assert.Contains(t, updated.notification, "Created PR #42")
}

func TestPRAgentCompletedMsg_ErrorShowsNotification(t *testing.T) {
	m := Model{
		prSessions:           make(map[int]tmux.PRSession),
		sessionInUse:         make(map[string]string),
		prCreationInProgress: map[string]bool{"/repo/wt-feature": true},
		sessionMgr:           &tmux.SessionManager{},
	}

	msg := prAgentCompletedMsg{
		worktreePath: "/repo/wt-feature",
		err:          fmt.Errorf("agent crashed"),
	}

	result, _ := m.Update(msg)
	updated := result.(Model)

	assert.False(t, updated.prCreationInProgress["/repo/wt-feature"])
	assert.Contains(t, updated.notification, "PR creation failed")
}



package tui

import (
	"fmt"
	"net/url"
	"strings"

	"github.com/DataDog/pr-workstation/internal/deploy"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/charmbracelet/glamour"
	"github.com/charmbracelet/lipgloss"
)

var (
	overlayStyle = lipgloss.NewStyle().
			Border(lipgloss.RoundedBorder()).
			BorderForeground(green).
			Padding(1, 2).
			Background(lipgloss.Color("#0a0f0a"))

	overlayTitleStyle = lipgloss.NewStyle().
				Bold(true).
				Foreground(green).
				MarginBottom(1)

	serviceNameStyle = lipgloss.NewStyle().
				Bold(true).
				Foreground(cyan)
)

const maxExpandedTargets = 15

// prDetailItemKind distinguishes conductor targets from availability services in the overlay.
type prDetailItemKind int

const (
	prDetailConductorTarget prDetailItemKind = iota
	prDetailAvailService
	prDetailCICheck
	prDetailReviewComment
)

// prDetailItem is a single navigable row in the PR detail overlay.
type prDetailItem struct {
	Kind        prDetailItemKind
	ServiceName string

	// Conductor target fields
	Target  string
	RunGUID string
	State   deploy.ConductorRunState
	Error   string

	// Availability service fields
	DeployedCount int
	TotalCount    int
	SvcIndex      int // index into row.Deployments for expand/collapse

	// CI check fields
	CheckName string
	CheckURL  string

	// Review comment fields
	CommentAuthor string
	CommentBody   string
	CommentPath   string
	CommentURL    string
}

func buildPRDetailItems(row PRRow) []prDetailItem {
	var items []prDetailItem

	// For open PRs, show failing CI checks (review comment items are appended
	// asynchronously by the reviewThreadsMsg handler)
	if row.PR.State == github.PRStateOpen {
		for _, check := range row.PR.StatusChecks {
			if check.Conclusion != github.CIConclusionFailure {
				continue
			}
			items = append(items, prDetailItem{
				Kind:      prDetailCICheck,
				CheckName: check.Name,
				CheckURL:  check.DetailsURL,
			})
		}
		return items
	}

	for _, svc := range row.ConductorStatuses {
		for _, t := range svc.TargetStatuses {
			items = append(items, prDetailItem{
				Kind:        prDetailConductorTarget,
				ServiceName: svc.ServiceName,
				Target:      t.Target,
				RunGUID:     t.RunGUID,
				State:       t.State,
				Error:       t.Error,
			})
		}
	}

	for i, svc := range row.Deployments {
		deployed := 0
		for _, t := range svc.Targets {
			if t.Status == deploy.DeployStatusDeployed {
				deployed++
			}
		}
		items = append(items, prDetailItem{
			Kind:          prDetailAvailService,
			ServiceName:   svc.Service,
			DeployedCount: deployed,
			TotalCount:    len(svc.Targets),
			SvcIndex:      i,
		})
	}

	return items
}

func mosaicSelectedTab(state deploy.ConductorRunState) string {
	switch state {
	case deploy.ConductorRunStateBuilding, deploy.ConductorRunStateBuildFailed:
		return "build"
	default:
		return "deploy"
	}
}

func conductorMosaicURL(serviceName, target, runGUID string, state deploy.ConductorRunState) string {
	base := fmt.Sprintf(
		"https://mosaic.us1.ddbuild.io/services/details?name=%s&selectedTarget=%s&selectedTab=%s&page=1",
		url.QueryEscape(serviceName), url.QueryEscape(target), mosaicSelectedTab(state))
	if runGUID != "" {
		base += "&conductorRunGuid=" + url.QueryEscape(runGUID)
	}
	return base
}

func isFailedConductorState(state deploy.ConductorRunState) bool {
	return state == deploy.ConductorRunStateBuildFailed || state == deploy.ConductorRunStateDeployFailed
}

func hasConductorFailure(statuses []deploy.ConductorServiceStatus) bool {
	for _, svc := range statuses {
		for _, t := range svc.TargetStatuses {
			if isFailedConductorState(t.State) {
				return true
			}
		}
	}
	return false
}

// conductorInvestigatePromptFromRow builds an investigate prompt covering all failed conductor targets.
func conductorInvestigatePromptFromRow(r *PRRow) string {
	parts := []string{"Conductor deployments have failed. Investigate the failures."}
	for _, svc := range r.ConductorStatuses {
		for _, t := range svc.TargetStatuses {
			if !isFailedConductorState(t.State) {
				continue
			}
			parts = append(parts, fmt.Sprintf("\nService: %s", svc.ServiceName))
			parts = append(parts, fmt.Sprintf("Target: %s", t.Target))
			parts = append(parts, fmt.Sprintf("State: %s", t.State))
			if t.RunGUID != "" {
				parts = append(parts, fmt.Sprintf("Run GUID: %s", t.RunGUID))
				parts = append(parts, fmt.Sprintf("Mosaic URL: %s", conductorMosaicURL(svc.ServiceName, t.Target, t.RunGUID, t.State)))
			}
			if t.Error != "" {
				parts = append(parts, fmt.Sprintf("Error: %s", t.Error))
			}
		}
	}
	return strings.Join(parts, "\n")
}

func conductorInvestigatePrompt(item prDetailItem) string {
	parts := []string{
		fmt.Sprintf("A conductor deployment has failed. Investigate the failure."),
		fmt.Sprintf("Service: %s", item.ServiceName),
		fmt.Sprintf("Target: %s", item.Target),
		fmt.Sprintf("State: %s", item.State),
	}
	if item.RunGUID != "" {
		parts = append(parts, fmt.Sprintf("Run GUID: %s", item.RunGUID))
		parts = append(parts, fmt.Sprintf("Mosaic URL: %s", conductorMosaicURL(item.ServiceName, item.Target, item.RunGUID, item.State)))
	}
	if item.Error != "" {
		parts = append(parts, fmt.Sprintf("Error: %s", item.Error))
	}
	return strings.Join(parts, "\n")
}

const maxCommentBodyLen = 120

func renderPRDetailOverlay(m Model) string {
	row := m.rows[m.prDetailIdx]

	var b strings.Builder

	b.WriteString(overlayTitleStyle.Render(fmt.Sprintf("PR #%d", row.PR.Number)))
	b.WriteString("\n")
	b.WriteString(lipgloss.NewStyle().Foreground(white).Render(truncate(row.PR.Title, 60)))
	b.WriteString("\n\n")

	if row.PR.State == github.PRStateOpen {
		renderOpenPRDetail(&b, m, row)
	} else {
		renderMergedPRDetail(&b, m, row)
	}

	content := overlayStyle.Render(b.String())

	contentWidth := lipgloss.Width(content)
	contentHeight := lipgloss.Height(content)

	padLeft := (m.width - contentWidth) / 2
	padTop := (m.height - contentHeight) / 2
	if padLeft < 0 {
		padLeft = 0
	}
	if padTop < 0 {
		padTop = 0
	}

	return lipgloss.NewStyle().
		PaddingLeft(padLeft).
		PaddingTop(padTop).
		Render(content)
}

func renderOpenPRDetail(b *strings.Builder, m Model, row PRRow) {
	hasCIChecks := false
	hasComments := false
	for _, item := range m.prDetailItems {
		switch item.Kind {
		case prDetailCICheck:
			hasCIChecks = true
		case prDetailReviewComment:
			hasComments = true
		}
	}

	// Failing CI checks section
	if hasCIChecks {
		b.WriteString(lipgloss.NewStyle().Foreground(cyan).Bold(true).Render("Failing CI Checks:"))
		b.WriteString("\n")

		for i, item := range m.prDetailItems {
			if item.Kind != prDetailCICheck {
				continue
			}
			cursor := "  "
			if i == m.prDetailCursor {
				cursor = "> "
			}

			checkText := lipgloss.NewStyle().Foreground(red).Render("x " + item.CheckName)

			hint := ""
			if i == m.prDetailCursor {
				hint = lipgloss.NewStyle().Foreground(gray).Render("  (o: open | c: fix)")
			}

			b.WriteString(fmt.Sprintf("%s%s%s\n", cursor, checkText, hint))
		}
		b.WriteString("\n")
	}

	// Review comments section
	if row.PR.UnresolvedThreads > 0 {
		header := fmt.Sprintf("Review Comments (%d unresolved):", row.PR.UnresolvedThreads)
		b.WriteString(lipgloss.NewStyle().Foreground(cyan).Bold(true).Render(header))
		b.WriteString("\n")

		if m.prDetailReviewCommentsLoading {
			b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("  Loading..."))
			b.WriteString("\n")
		} else if m.prDetailReviewCommentsErr != nil {
			b.WriteString(lipgloss.NewStyle().Foreground(red).Render("  failed to load comments"))
			b.WriteString("\n")
		} else if hasComments {
			for i, item := range m.prDetailItems {
				if item.Kind != prDetailReviewComment {
					continue
				}
				cursor := "  "
				if i == m.prDetailCursor {
					cursor = "> "
				}

				authorLine := item.CommentAuthor
				if item.CommentPath != "" {
					authorLine += " (" + item.CommentPath + ")"
				}
				authorText := lipgloss.NewStyle().Foreground(white).Bold(true).Render(authorLine)

				hint := ""
				if i == m.prDetailCursor {
					hint = lipgloss.NewStyle().Foreground(gray).Render("  (enter: expand | c: address)")
				}

				if i == m.prDetailExpandedComment {
					b.WriteString(fmt.Sprintf("%s%s:%s\n", cursor, authorText, hint))
					b.WriteString(renderMarkdown(item.CommentBody, 60))
					b.WriteString("\n")
				} else {
					bodyPreview := lipgloss.NewStyle().Foreground(gray).Render(truncate(item.CommentBody, maxCommentBodyLen))
					b.WriteString(fmt.Sprintf("%s%s: %s%s\n", cursor, authorText, bodyPreview, hint))
				}
			}
		}
		b.WriteString("\n")
	}

	if !hasCIChecks && !hasComments && row.PR.UnresolvedThreads == 0 {
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("No failing checks or review comments"))
		b.WriteString("\n\n")
	}

	b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | enter: expand | o: open | c: fix CI | space/esc: close"))
}

func renderMarkdown(body string, width int) string {
	r, err := glamour.NewTermRenderer(
		glamour.WithAutoStyle(),
		glamour.WithWordWrap(width),
	)
	if err != nil {
		return body
	}
	rendered, err := r.Render(body)
	if err != nil {
		return body
	}
	return strings.TrimRight(rendered, "\n")
}

func renderMergedPRDetail(b *strings.Builder, m Model, row PRRow) {
	// Conductor section
	if len(row.ConductorStatuses) > 0 {
		b.WriteString(lipgloss.NewStyle().Foreground(cyan).Bold(true).Render("Conductor:"))
		b.WriteString("\n")

		itemIdx := 0
		for _, svc := range row.ConductorStatuses {
			b.WriteString(fmt.Sprintf("  %s\n", serviceNameStyle.Render(svc.ServiceName)))
			for _, t := range svc.TargetStatuses {
				cursor := "    "
				if itemIdx == m.prDetailCursor {
					cursor = "  > "
				}

				stateColor := conductorStateColor(t.State)
				stateText := lipgloss.NewStyle().Foreground(stateColor).
					Render(conductorRunStateEmoji(t.State) + " " + string(t.State))

				hint := ""
				if itemIdx == m.prDetailCursor {
					if isFailedConductorState(t.State) {
						hint = lipgloss.NewStyle().Foreground(gray).Render(" (o: mosaic | c: investigate)")
					} else {
						hint = lipgloss.NewStyle().Foreground(gray).Render(" (o: mosaic)")
					}
				}

				b.WriteString(fmt.Sprintf("%s%-12s %s%s\n", cursor, t.Target+":", stateText, hint))
				if t.Error != "" {
					b.WriteString(fmt.Sprintf("              %s\n",
						lipgloss.NewStyle().Foreground(red).Render(truncate(t.Error, 50))))
				}
				itemIdx++
			}
		}
		b.WriteString("\n")
	}

	// Availability section
	if len(row.Deployments) > 0 {
		b.WriteString(lipgloss.NewStyle().Foreground(cyan).Bold(true).Render("Availability:"))
		b.WriteString("\n")

		conductorItemCount := 0
		for _, svc := range row.ConductorStatuses {
			conductorItemCount += len(svc.TargetStatuses)
		}

		for i, svc := range row.Deployments {
			itemIdx := conductorItemCount + i
			cursor := "  "
			if itemIdx == m.prDetailCursor {
				cursor = "> "
			}

			summary := serviceSummary(svc)
			summaryColor := serviceSummaryColor(svc)

			nameText := serviceNameStyle.Render(svc.Service)
			summaryText := lipgloss.NewStyle().Foreground(summaryColor).Render(summary)

			b.WriteString(fmt.Sprintf("%s%s  %s\n", cursor, nameText, summaryText))

			if i == m.prDetailExpandedSvc {
				shown := svc.Targets
				truncated := 0
				if len(shown) > maxExpandedTargets {
					truncated = len(shown) - maxExpandedTargets
					shown = shown[:maxExpandedTargets]
				}

				for _, target := range shown {
					statusColor := deployTargetStatusColor(target.Status)
					statusText := lipgloss.NewStyle().Foreground(statusColor).Render(string(target.Status))
					label := fmt.Sprintf("      %s", target.Datacenter)
					if target.Env != "" {
						label += fmt.Sprintf(" (%s)", target.Env)
					}
					b.WriteString(fmt.Sprintf("%-34s %s\n", label, statusText))
				}

				if truncated > 0 {
					b.WriteString(lipgloss.NewStyle().Foreground(gray).Render(
						fmt.Sprintf("      ... and %d more\n", truncated)))
				}
			}
		}
		b.WriteString("\n")
	}

	if len(row.ConductorStatuses) == 0 && row.ConductorErr != nil {
		b.WriteString(lipgloss.NewStyle().Foreground(cyan).Bold(true).Render("Conductor:"))
		b.WriteString("\n")
		b.WriteString(fmt.Sprintf("  %s\n\n",
			lipgloss.NewStyle().Foreground(red).Render(row.ConductorErr.Error())))
	}

	if len(row.ConductorStatuses) == 0 && row.ConductorErr == nil && len(row.Deployments) == 0 {
		b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("No deployment data available"))
		b.WriteString("\n\n")
	}

	b.WriteString(lipgloss.NewStyle().Foreground(gray).Render("j/k: navigate | o: mosaic | c: investigate | enter: expand | space/esc: close"))
}

func serviceSummary(svc deploy.ServiceDeployment) string {
	total := len(svc.Targets)
	if total == 0 {
		return "no targets"
	}

	deployed := 0
	deploying := 0
	for _, t := range svc.Targets {
		switch t.Status {
		case deploy.DeployStatusDeployed:
			deployed++
		case deploy.DeployStatusDeploying:
			deploying++
		}
	}

	if deploying > 0 {
		return fmt.Sprintf("%d/%d deploying", deployed, total)
	}
	return fmt.Sprintf("%d/%d deployed", deployed, total)
}

func serviceSummaryColor(svc deploy.ServiceDeployment) lipgloss.Color {
	total := len(svc.Targets)
	if total == 0 {
		return gray
	}

	deployed := 0
	deploying := 0
	for _, t := range svc.Targets {
		switch t.Status {
		case deploy.DeployStatusDeployed:
			deployed++
		case deploy.DeployStatusDeploying:
			deploying++
		}
	}

	if deploying > 0 {
		return yellow
	}
	if deployed == total {
		return green
	}
	if deployed == 0 {
		return red
	}
	return white
}

func conductorStateColor(state deploy.ConductorRunState) lipgloss.Color {
	switch state {
	case deploy.ConductorRunStateDeployed:
		return green
	case deploy.ConductorRunStateDeploying, deploy.ConductorRunStateBuilding, deploy.ConductorRunStatePending:
		return yellow
	case deploy.ConductorRunStateDeployFailed, deploy.ConductorRunStateBuildFailed:
		return red
	default:
		return gray
	}
}

func deployTargetStatusColor(status deploy.DeployStatus) lipgloss.Color {
	switch status {
	case deploy.DeployStatusDeployed:
		return green
	case deploy.DeployStatusDeploying:
		return yellow
	case deploy.DeployStatusNotDeployed:
		return red
	default:
		return gray
	}
}



package tui

import (
	"testing"

	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/tmux"
	"github.com/stretchr/testify/assert"
)

func TestBuildHelpText(t *testing.T) {
	tests := []struct {
		name        string
		row         *PRRow
		hasSession  bool
		contains    []string
		notContains []string
	}{
		{
			name:     "nil row shows compact nav with help and enter",
			row:      nil,
			contains: []string{"q: quit", "r: refresh", "/: search", "enter: session", "?: help", "|"},
		},
		{
			name: "open PR with CI failing shows fix CI action",
			row: &PRRow{
				PR:     github.PR{State: github.PRStateOpen},
				Action: github.ActionFixCI,
			},
			contains: []string{"q: quit", "/: search", "enter: session", "c: fix CI", "?: help"},
		},
		{
			name: "open PR with changes requested shows address feedback",
			row: &PRRow{
				PR:     github.PR{State: github.PRStateOpen},
				Action: github.ActionAddressFeedback,
			},
			contains: []string{"c: address feedback", "?: help"},
		},
		{
			name: "open PR approved shows claude",
			row: &PRRow{
				PR:     github.PR{State: github.PRStateOpen},
				Action: github.ActionMerge,
			},
			contains: []string{"c: claude", "?: help"},
		},
		{
			name: "open PR no action shows claude",
			row: &PRRow{
				PR:     github.PR{State: github.PRStateOpen},
				Action: github.ActionNone,
			},
			contains: []string{"c: claude"},
		},
		{
			name: "merged PR shows enter but no context action",
			row: &PRRow{
				PR: github.PR{State: github.PRStateMerged},
			},
			contains:    []string{"q: quit", "enter: session", "?: help"},
			notContains: []string{"c: claude", "c: fix CI"},
		},
		{
			name: "merged PR with investigate action shows investigate",
			row: &PRRow{
				PR:     github.PR{State: github.PRStateMerged},
				Action: github.ActionInvestigate,
			},
			contains: []string{"c: investigate", "?: help"},
		},
		{
			name: "local row shows enter but no context action",
			row: &PRRow{
				RowType: RowTypeLocal,
			},
			contains:    []string{"q: quit", "enter: session", "?: help"},
			notContains: []string{"c: claude"},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := buildHelpText(tt.row, tt.hasSession)
			for _, s := range tt.contains {
				assert.Contains(t, result, s)
			}
			for _, s := range tt.notContains {
				assert.NotContains(t, result, s)
			}
		})
	}
}

func TestRenderHelpOverlay(t *testing.T) {
	t.Run("always shows all categories", func(t *testing.T) {
		m := Model{width: 120, height: 40, prSessions: make(map[int]tmux.PRSession)}
		result := renderHelpOverlay(m)
		assert.Contains(t, result, "Keybindings")
		assert.Contains(t, result, "Table")
		assert.Contains(t, result, "Explore")
		assert.Contains(t, result, "Agents")
		assert.Contains(t, result, "Actions")
		assert.Contains(t, result, "Sessions")
		assert.Contains(t, result, "Local")
	})

	t.Run("open PR shows agent labels as active", func(t *testing.T) {
		m := Model{
			width:      120,
			height:     40,
			prSessions: make(map[int]tmux.PRSession),
			rows: []PRRow{
				{
					PR:     github.PR{State: github.PRStateOpen},
					Action: github.ActionFixCI,
				},
			},
		}
		m.table = m.rebuildTable()
		result := renderHelpOverlay(m)
		assert.Contains(t, result, "fix CI")
		assert.Contains(t, result, "github actions")
		assert.Contains(t, result, "deploy")
	})

	t.Run("local row shows local actions", func(t *testing.T) {
		m := Model{
			width:      120,
			height:     40,
			prSessions: make(map[int]tmux.PRSession),
			rows: []PRRow{
				{
					RowType: RowTypeLocal,
				},
			},
		}
		m.table = m.rebuildTable()
		result := renderHelpOverlay(m)
		assert.Contains(t, result, "switch to session")
		assert.Contains(t, result, "create PR")
		// all categories still present
		assert.Contains(t, result, "Agents")
		assert.Contains(t, result, "Actions")
	})
}



