func fetchConductorStatusCmd(client *deploy.ConductorClient, pr github.PR) tea.Cmd {
	return func() tea.Msg {
		if pr.MergedAt == nil {
			return conductorStatusMsg{prNumber: pr.Number, statuses: []deploy.ConductorServiceStatus{}}
		}
		ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
		defer cancel()
		services := github.ExtractServiceNames(pr.Labels)
		statuses, err := client.FetchConductorStatus(ctx, pr.Number, *pr.MergedAt, services)
		return conductorStatusMsg{prNumber: pr.Number, statuses: statuses, err: err}
	}
}

