	isNewWindow   bool
	windowName    string
	claudeCmd     string
	actionType    string
	repo          string
	sessionType   session.SessionType
	headCommitOID string
}

type sessionDestroyedMsg struct {
	sessionName string
}

type sessionsLoadedMsg struct {
	state config.SessionState
}

type sessionsValidatedMsg struct {
	state config.SessionState
}

type sessionsSavedMsg struct{}

type worktreeCreatedMsg struct {
	workDir string
}

func discoverSessionsCmd(mgr *tmux.SessionManager) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()

		sessions, err := mgr.ListPRSessions(ctx)
		if err != nil {
			return sessionsDiscoveredMsg{}
		}
		return sessionsDiscoveredMsg{sessions: sessions}
	}
}

func discoverWorktreesCmd(mgr *tmux.SessionManager, repoDir string, prNumber int) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()

		worktrees, err := mgr.ListWorktrees(ctx, repoDir)
		if err != nil {
			return sessionErrorMsg{prNumber: prNumber, err: err}
		}
		return worktreesDiscoveredMsg{prNumber: prNumber, worktrees: worktrees}
	}
}

func createWorktreeCmd(mgr *tmux.SessionManager, repoDir, path, branch string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()

		err := mgr.CreateWorktree(ctx, repoDir, path, branch)
		if err != nil {
			return sessionErrorMsg{err: err}
		}
		return worktreeCreatedMsg{workDir: path}
	}
}

func destroySessionCmd(mgr *tmux.SessionManager, name string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()

		if err := mgr.DestroySession(ctx, name); err != nil {
			return sessionErrorMsg{sessionName: name, err: err}
		}
		return sessionDestroyedMsg{sessionName: name}
	}
}

func ensureWindowAndSwitchCmd(mgr *tmux.SessionManager, sess tmux.PRSession, windowName, claudeCmd, actionType, repo, headCommitOID string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()

		escaped := strings.ReplaceAll(claudeCmd, "'", "'\\''")
		shellCmd := fmt.Sprintf("claude --permission-mode acceptEdits '%s'", escaped)

		isNew := false
		if !mgr.SessionExists(ctx, sess.SessionName) {
			if err := mgr.CreateSessionWithWindow(ctx, sess, windowName, shellCmd); err != nil {
				return sessionErrorMsg{sessionName: sess.SessionName, prNumber: sess.PRNumber, err: err}
			}
			isNew = true
		} else if mgr.WindowExists(ctx, sess.SessionName, windowName) {
			if err := mgr.SwitchToWindow(ctx, sess.SessionName, windowName); err != nil {
				return sessionErrorMsg{sessionName: sess.SessionName, prNumber: sess.PRNumber, err: err}
			}
		} else {
			if err := mgr.CreateNamedWindow(ctx, sess.SessionName, windowName, sess.WorkDir, shellCmd); err != nil {
				return sessionErrorMsg{sessionName: sess.SessionName, prNumber: sess.PRNumber, err: err}
			}
			isNew = true
		}

		if err := mgr.SwitchToSession(ctx, sess.SessionName); err != nil {
			return sessionErrorMsg{sessionName: sess.SessionName, prNumber: sess.PRNumber, err: err}
		}
		return sessionCreatedMsg{
			session:       sess,
			isNewWindow:   isNew,
			windowName:    windowName,
			claudeCmd:     claudeCmd,
			actionType:    actionType,
			repo:          repo,
			sessionType:   session.SessionTypeManual,
			headCommitOID: headCommitOID,
		}
	}
}

// newWorkSessionCmd creates a tmux session in an existing worktree that fetches,
// checks out a new branch, and runs claude. Git output is visible in the pane.
func newWorkSessionCmd(mgr *tmux.SessionManager, sess tmux.PRSession, seedPrompt, repo string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()

		escaped := strings.ReplaceAll(seedPrompt, "'", "'\\''")
		shellCmd := fmt.Sprintf(
			"git fetch origin main && git checkout -b %s origin/main && claude --permission-mode acceptEdits '%s'",
			sess.Branch, escaped,
		)

		if err := mgr.CreateSessionWithWindow(ctx, sess, "claude", shellCmd); err != nil {
			return sessionErrorMsg{sessionName: sess.SessionName, err: err}
		}
		if err := mgr.SwitchToSession(ctx, sess.SessionName); err != nil {
			return sessionErrorMsg{sessionName: sess.SessionName, err: err}
		}
		return sessionCreatedMsg{
			session:     sess,
			isNewWindow: true,
			windowName:  "claude",
			claudeCmd:   seedPrompt,
			actionType:  "custom",
			repo:        repo,
			sessionType: session.SessionTypeManual,
		}
	}
}

// newWorkWorktreeSessionCmd creates a tmux session that fetches, creates a new
// worktree with a branch, cds into it, and runs claude. Git output is visible in the pane.
func newWorkWorktreeSessionCmd(mgr *tmux.SessionManager, sess tmux.PRSession, seedPrompt, repo, worktreePath, branchName string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		defer cancel()

		escaped := strings.ReplaceAll(seedPrompt, "'", "'\\''")
		shellCmd := fmt.Sprintf(
			"git fetch origin main && git worktree add -b %s %s origin/main && cd %s && claude --permission-mode acceptEdits '%s'",
			branchName, worktreePath, worktreePath, escaped,
		)

		if err := mgr.CreateSessionWithWindow(ctx, sess, "claude", shellCmd); err != nil {
			return sessionErrorMsg{sessionName: sess.SessionName, err: err}
		}
		if err := mgr.SwitchToSession(ctx, sess.SessionName); err != nil {
			return sessionErrorMsg{sessionName: sess.SessionName, err: err}
		}
		sess.WorkDir = worktreePath
		return sessionCreatedMsg{
			session:     sess,
			isNewWindow: true,
			windowName:  "claude",
			claudeCmd:   seedPrompt,
			actionType:  "custom",
			repo:        repo,
			sessionType: session.SessionTypeManual,
		}
	}
}

// createAndSwitchCmd creates a plain shell tmux session (no claude) and switches to it.
// Used when enter is pressed on a PR with no existing session.
func createAndSwitchCmd(mgr *tmux.SessionManager, sess tmux.PRSession) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		if !mgr.SessionExists(ctx, sess.SessionName) {
			if err := mgr.CreateSessionWithWindow(ctx, sess, "main", ""); err != nil {
				return sessionErrorMsg{sessionName: sess.SessionName, prNumber: sess.PRNumber, err: err}
			}
		}
		if err := mgr.SwitchToSession(ctx, sess.SessionName); err != nil {
			return sessionErrorMsg{sessionName: sess.SessionName, prNumber: sess.PRNumber, err: err}
		}
		// Return sessionCreatedMsg with isNewWindow=false so the session is registered
		// in prSessions but no session history record is written (no claude was spawned).
		return sessionCreatedMsg{session: sess}
	}
}

func loadSessionsCmd(mgr *tmux.SessionManager, sessionsPath string) tea.Cmd {
	return func() tea.Msg {
		if sessionsPath == "" {
			return sessionsLoadedMsg{}
		}
		state := config.LoadSessions(sessionsPath)

		// Validate each entry against live tmux sessions
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()

		var valid []config.SessionEntry
		for _, entry := range state.Sessions {
			// Local entries persist across tmux restarts
			if entry.Type == config.SessionTypeLocal || mgr.SessionExists(ctx, entry.TmuxSession) {
				valid = append(valid, entry)
			}
		}

		pruned := len(state.Sessions) != len(valid)
		state.Sessions = valid

		if pruned {
			_ = config.SaveSessions(state, sessionsPath)
		}

		return sessionsLoadedMsg{state: state}
	}
}

func validateSessionsCmd(mgr *tmux.SessionManager, state config.SessionState, sessionsPath string) tea.Cmd {
	return func() tea.Msg {
		if sessionsPath == "" {
			return sessionsValidatedMsg{state: state}
		}

		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()

		var valid []config.SessionEntry
		for _, entry := range state.Sessions {
			if entry.Type == config.SessionTypeLocal || mgr.SessionExists(ctx, entry.TmuxSession) {
				valid = append(valid, entry)
			}
		}

		pruned := len(state.Sessions) != len(valid)
		result := config.SessionState{Sessions: valid}

		if pruned {
			_ = config.SaveSessions(result, sessionsPath)
		}

		return sessionsValidatedMsg{state: result}
	}
}

func saveSessionsCmd(state config.SessionState, sessionsPath string) tea.Cmd {
	return func() tea.Msg {
		if sessionsPath != "" {
			_ = config.SaveSessions(state, sessionsPath)
		}
		return sessionsSavedMsg{}
	}
}

type sessionRenamedMsg struct {
	oldName string
	newName string
	err     error
}

func renameSessionCmd(mgr *tmux.SessionManager, oldName, newName string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()

		err := mgr.RenameSession(ctx, oldName, newName)
		return sessionRenamedMsg{oldName: oldName, newName: newName, err: err}
	}
}

type prAgentCompletedMsg struct {
	worktreePath string
	output       string
	err          error
}

func spawnPRAgentCmd(worktreePath string) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
		defer cancel()

		prompt := "Look at the git diff and commit history on this branch. " +
			"Commit any uncommitted work, push the branch, then create a draft PR " +
			"with gh pr create --draft. Output the PR URL as the last line."

		cmd := exec.CommandContext(ctx, "claude", "--yes", "--print", prompt)
		cmd.Dir = worktreePath
		out, err := cmd.Output()
		return prAgentCompletedMsg{worktreePath: worktreePath, output: string(out), err: err}
	}
}

type sessionPollTickMsg struct{}

type pruneTickMsg struct{}

// sessionsPollResultMsg carries the outcome of one poll cycle.
type sessionsPollResultMsg struct {
	// completedIDs are sessions whose status file reported "completed".
	completedIDs []string
	// failedRecords maps record ID → error string for sessions that wrote "failed" to their status file.
	failedRecords map[string]string
	// unexpectedTerminations are sessions whose tmux window disappeared without a status file
	// and whose grace period has elapsed.
	unexpectedTerminations []string
	// paneCaptures maps a pane key to its captured content for staleness tracking.
	// Keys are record IDs for autonomous sessions, "session:window" for config-tracked.
	paneCaptures map[string]string
	// statusFilesToDelete are file paths to clean up after processing.
	statusFilesToDelete []string
	// updatedMissing carries forward the first-observed-missing timestamps for the next poll.
	updatedMissing map[string]time.Time
}

const windowGracePeriod = 1 * time.Minute

// paneStaleThreshold is the number of consecutive unchanged poll ticks before
// a pane is considered stale (waiting for input). At 5s intervals this is 30s.
const paneStaleThreshold = 6

// applyStaleness compares current pane captures against previous snapshots and returns
// updated snapshots and unchanged counts. Panes not present in captures are dropped.
func applyStaleness(prevSnapshots map[string]string, prevCounts map[string]int, captures map[string]string) (map[string]string, map[string]int) {
	newSnapshots := make(map[string]string, len(captures))
	newCounts := make(map[string]int, len(captures))
	for key, content := range captures {
		newSnapshots[key] = content
		if prev, ok := prevSnapshots[key]; ok && prev == content {
			newCounts[key] = prevCounts[key] + 1
		}
	}
	return newSnapshots, newCounts
}

// stalenessToAttention returns a map of autonomous session record IDs that are stale.
// Autonomous session keys have no ":" separator (record IDs).
// Panes whose current snapshot matches their acked content are skipped.
func stalenessToAttention(counts map[string]int, snapshots, acked map[string]string) map[string]bool {
	result := make(map[string]bool)
	for key, count := range counts {
		if !strings.Contains(key, ":") && count >= paneStaleThreshold {
			if ackedContent, ok := acked[key]; ok && snapshots[key] == ackedContent {
				continue
			}
			result[key] = true
		}
	}
	return result
}

// stalenessToSessionAttention returns a map of tmux session names that have at least
// one stale window. Config-tracked session keys use "session:window" format.
// Panes whose current snapshot matches their acked content are skipped.
func stalenessToSessionAttention(counts map[string]int, snapshots, acked map[string]string) map[string]bool {
	result := make(map[string]bool)
	for key, count := range counts {
		if idx := strings.Index(key, ":"); idx > 0 && count >= paneStaleThreshold {
			if ackedContent, ok := acked[key]; ok && snapshots[key] == ackedContent {
				continue
			}
			result[key[:idx]] = true
		}
	}
	return result
}

func sessionPollTickCmd(interval time.Duration) tea.Cmd {
	return tea.Tick(interval, func(t time.Time) tea.Msg {
		return sessionPollTickMsg{}
	})
}

func pruneTickCmd(interval time.Duration) tea.Cmd {
	return tea.Tick(interval, func(t time.Time) tea.Msg {
		return pruneTickMsg{}
	})
}

// pollRunningSessionsCmd checks each running session record against its status file, tmux window
// state, and pane content. It also scrapes panes in config-tracked sessions (local and PR) for
// prompts waiting on user input.
//
// configDir is the root config directory (for locating status files). previouslyMissing maps
// record ID to the first time its tmux window was observed missing; the grace period prevents
// brief tmux glitches from being misinterpreted as session failures.
func pollRunningSessionsCmd(running []session.SessionRecord, mgr *tmux.SessionManager, sessions map[int]tmux.PRSession, configDir string, previouslyMissing map[string]time.Time, configSessions []config.SessionEntry) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()

		result := sessionsPollResultMsg{
			failedRecords:  make(map[string]string),
			updatedMissing: make(map[string]time.Time),
			paneCaptures:   make(map[string]string),
		}

		for _, record := range running {
			// 1. Check status file (written by the autonomous agent on exit).
			if configDir != "" {
				statusPath := session.StatusFilePath(configDir, record.ID)
				status, _ := session.ReadStatusFile(statusPath)
				if status != nil {
					result.statusFilesToDelete = append(result.statusFilesToDelete, statusPath)
					if status.Outcome == "completed" {
						result.completedIDs = append(result.completedIDs, record.ID)
					} else {
						result.failedRecords[record.ID] = status.Error
					}
					continue
				}
			}

			// 2. Check tmux window existence.
			sess, ok := sessions[record.PRNumber]
			windowGone := !ok || !mgr.WindowExists(ctx, sess.SessionName, record.WindowName)

			if !windowGone {
				// 3. For autonomous sessions with a live window, capture pane for staleness tracking.
				if record.SessionType == session.SessionTypeAutonomous && ok {
					pane, err := mgr.CapturePane(ctx, sess.SessionName, record.WindowName, 50)
					if err == nil {
						result.paneCaptures[record.ID] = pane
					}
				}
				continue
			}

			// Window is gone. Apply grace period.
			firstMissing, seen := previouslyMissing[record.ID]
			if !seen {
				// First observation — start the grace period timer and defer judgment.
				result.updatedMissing[record.ID] = time.Now()
				continue
			}
			if time.Since(firstMissing) < windowGracePeriod {
				// Still within grace period — carry the timestamp forward.
				result.updatedMissing[record.ID] = firstMissing
				continue
			}
			// Grace period elapsed — treat as unexpected termination.
			result.unexpectedTerminations = append(result.unexpectedTerminations, record.ID)
		}

		// Capture pane content for config-tracked sessions for staleness tracking.
		seen := make(map[string]bool)
		for _, entry := range configSessions {
			if entry.TmuxSession == "" || seen[entry.TmuxSession] {
				continue
			}
			seen[entry.TmuxSession] = true
			if !mgr.SessionExists(ctx, entry.TmuxSession) {
				continue
			}
			windows, err := mgr.ListWindows(ctx, entry.TmuxSession)
			if err != nil {
				continue
			}
			for _, w := range windows {
				pane, err := mgr.CapturePane(ctx, entry.TmuxSession, w, 50)
				if err == nil {
					key := entry.TmuxSession + ":" + w
					result.paneCaptures[key] = pane
				}
			}
		}

		return result
	}
}

// autonomousSpawnMsg is returned when an autonomous agent window has been created (no switch).
type autonomousSpawnMsg struct {
	session       tmux.PRSession
	windowName    string
	claudeCmd     string
	actionType    string
	repo          string
	headCommitOID string
	recordID      string // pre-generated so the status file path matches the session record
	err           error
}

// evaluateAutonomousSpawnsCandidate carries spawn parameters for one PR.
type evaluateAutonomousSpawnsCandidate struct {
	sess          tmux.PRSession
	pr            github.PR
	actionType    string
	claudeCmd     string
	windowName    string
	headCommitOID string
	recordID      string // pre-generated ID for the session record and status file path
}

type autonomySessionStore interface {
	HasRunningSession(repo string, prNumber int, actionType string, headCommitOID string) bool
}

// evaluateAutonomousSpawnsCmd checks each autonomy-enabled PR against the idempotency key and
// current concurrency limit, spawning agents for PRs that need one.
//
// runningCount is the current number of running autonomous sessions. maxConcurrent is the
// concurrency cap (0 defaults to 3).
func evaluateAutonomousSpawnsCmd(mgr *tmux.SessionManager, store autonomySessionStore, candidates []evaluateAutonomousSpawnsCandidate, runningCount, maxConcurrent int) tea.Cmd {
	if maxConcurrent <= 0 {
		maxConcurrent = 3
	}
	return func() tea.Msg {
		slots := maxConcurrent - runningCount
		for _, c := range candidates {
			if slots <= 0 {
				break
			}
			if store.HasRunningSession(c.pr.RepoNameWithOwner, c.pr.Number, c.actionType, c.headCommitOID) {
				continue
			}
			slots--
			return spawnAutonomousAgentCmd(mgr, c)()
		}
		return nil
	}
}

// spawnAutonomousAgentCmd creates a new tmux window for an autonomous agent without switching.
// The agent runs interactively using the user's configured tool permissions (no --yes flag).
func spawnAutonomousAgentCmd(mgr *tmux.SessionManager, c evaluateAutonomousSpawnsCandidate) tea.Cmd {
	return func() tea.Msg {
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()

		escaped := strings.ReplaceAll(c.claudeCmd, "'", "'\\''")
		shellCmd := fmt.Sprintf("git checkout %s && claude --permission-mode acceptEdits '%s'", c.sess.Branch, escaped)

		var err error
		if !mgr.SessionExists(ctx, c.sess.SessionName) {
			err = mgr.CreateSessionWithWindow(ctx, c.sess, c.windowName, shellCmd)
		} else {
			err = mgr.CreateNamedWindow(ctx, c.sess.SessionName, c.windowName, c.sess.WorkDir, shellCmd)
		}
		return autonomousSpawnMsg{
			session:       c.sess,
			windowName:    c.windowName,
			claudeCmd:     c.claudeCmd,
			actionType:    c.actionType,
			repo:          c.pr.RepoNameWithOwner,
			headCommitOID: c.headCommitOID,
			recordID:      c.recordID,
			err:           err,
		}
	}
}

// buildAutonomousPrompt returns the Claude command for an autonomous session. It wraps the
// action slash command with a lifecycle preamble so the agent writes a status file on exit.
func buildAutonomousPrompt(pr github.PR, actionType string, statusFilePath string) string {
	var actionCmd string
	switch actionType {
	case "fix-ci":
		actionCmd = fmt.Sprintf("/dd:ci:fix %s", pr.URL)
	case "address-feedback":
		actionCmd = fmt.Sprintf("/dd:pr:address-feedback %s", pr.URL)
	case "resolve-conflicts":
		actionCmd = fmt.Sprintf("PR %s has merge conflicts with the base branch. Rebase onto the base branch, resolve all conflicts, then commit and push.", pr.URL)
	default:
		actionCmd = fmt.Sprintf("/dd:pr:followup %s", pr.URL)
	}

	preamble := fmt.Sprintf(`You are an autonomous agent working on PR #%d.

After completing your task:
1. Commit and push your changes
2. Write your outcome to %s as JSON: {"outcome": "completed"}
3. Exit the session

If you encounter an unrecoverable error:
1. Write your outcome to %s as JSON: {"outcome": "failed", "error": ""}
2. Exit the session

Do not ask for confirmation. Work autonomously using your configured permissions.

`, pr.Number, statusFilePath, statusFilePath)

	return preamble + actionCmd
}



package tui

import (
	"fmt"
	"os"
	"os/exec"
	"regexp"
	"runtime"
	"sort"
	"strings"
	"time"

	"github.com/DataDog/pr-workstation/internal/config"
	"github.com/DataDog/pr-workstation/internal/deploy"
	"github.com/DataDog/pr-workstation/internal/github"
	"github.com/DataDog/pr-workstation/internal/session"
	"github.com/DataDog/pr-workstation/internal/tmux"
	"github.com/charmbracelet/bubbles/textinput"
	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
	"github.com/evertras/bubble-table/table"
)

var (
	reNonAlphanumHyphen = regexp.MustCompile(`[^a-z0-9-]`)
	reMultiHyphen       = regexp.MustCompile(`-{2,}`)
)

// View represents a saved PR query view
type View struct {
	Name    string
	Query   string
	Default bool
}

type viewCreateStep int

const (
	viewCreateNone  viewCreateStep = iota
	viewCreateName                 // entering view name
	viewCreateQuery                // entering query string
)

// Config holds TUI configuration
type Config struct {
	RefreshInterval     time.Duration
	Views               []View
	ConfigPath          string
	SessionsPath        string
	MaxConcurrentAgents int // 0 means use default (3)
}

// Model is the Bubbletea model for the PR dashboard
type Model struct {
	config                        Config
	table                         table.Model
	allRows                       []PRRow // unfiltered complete set from GitHub
	rows                          []PRRow // filtered set for display
	loading                       bool
	err                           error
	deployErr                     error
	lastRefresh                   time.Time
	width                         int
	height                        int
	spinnerIdx                    int
	spinnerActive                 bool // true when a spinner tick chain is running
	showPRDetail                  bool
	prDetailIdx                   int            // index into m.rows for the overlay PR
	prDetailCursor                int            // highlighted item in PR detail overlay
	prDetailExpandedSvc           int            // expanded devflow service in availability section (-1 = none)
	prDetailItems                 []prDetailItem // flat list for cursor navigation
	prDetailExpandedComment       int            // expanded review comment in overlay (-1 = none)
	prDetailReviewCommentsLoading bool
	prDetailReviewCommentsErr     error
	showCustomPrompt              bool
	customPromptInput             textinput.Model
	notification                  string // transient status message (e.g. "Marking #123 ready...")
	ghClient                      *github.GHClient
	deployClient                  *deploy.DevflowClient
	conductorClient               *deploy.ConductorClient

	// github actions overlay
	showGithubActions         bool
	githubActionsCursor       int
	githubActionsCommentMode  bool
	githubActionsCommentInput textinput.Model

	// deploy run overlay
	showDeployRun     bool
	deployRunCursor   int
	deployRunServices []string
	deployRunTextMode bool
	deployRunInput    textinput.Model

	// client-side filters
	repoFilter    string
	statusFilter  string
	searchFilter  string
	searchEditing bool
	searchInput   textinput.Model

	// repo filter overlay
	showRepoFilter     bool
	repoFilterCursor   int
	repoFilterItems    []string
	repoFilterTextMode bool
	repoFilterInput    textinput.Model

	// status filter overlay
	showStatusFilter   bool
	statusFilterCursor int
	statusFilterItems  []string

	// saved views
	views            []View
	activeViewIdx    int
	showViewPicker   bool
	viewPickerCursor int

	// new view creation
	viewCreateMode viewCreateStep
	viewNameInput  textinput.Model
	viewQueryInput textinput.Model
	configPath     string

	// session history overlay
	showSessionHistory    bool
	sessionHistoryCursor  int
	sessionHistoryRecords []session.SessionRecord
	sessionHistoryPR      int
	sessionHistoryTitle   string // overlay title (e.g. "#42" or branch name)
	sessionHistoryTmux    string // tmux session name for local rows

	// PR sessions
	sessionMgr    *tmux.SessionManager
	sessionStore  *session.Store
	autonomyStore *session.AutonomyStore
	prSessions    map[int]tmux.PRSession // PR number -> session
	sessionInUse  map[string]string      // worktree path -> session name
	sessionState  config.SessionState    // persistent session tracking
	localRows     []PRRow                // local work items from session state

	// autonomous agent state
	agentNeedsAttention   map[string]bool      // record ID → needs attention
	sessionNeedsAttention map[string]bool      // tmux session name → needs attention
	windowFirstMissing    map[string]time.Time // record ID → first observed missing

	// screen staleness tracking
	paneSnapshots      map[string]string // pane key → last captured content
	paneUnchangedCount map[string]int    // pane key → consecutive unchanged ticks
	paneAckedContent   map[string]string // pane key → content at time of ack

	// PR creation agent
	prCreationInProgress map[string]bool // worktree path -> agent running

	// new work overlay
	showNewWork                bool
	newWorkPendingRepo         string // set before session creation so sessionCreatedMsg can use it
	newWorkStep                newWorkStep
	newWorkRepos               []string
	newWorkRepoCursor          int
	newWorkSelectedRepo        string
	newWorkSelectedWorktree    string
	newWorkWorktreeOptions     []WorktreeOption
	newWorkWorktreeCursor      int
	newWorkSeedInput           textinput.Model
	newWorkBranchInput         textinput.Model
	newWorkUseExistingWorktree bool
	newWorkRepoFilterMode      bool
	newWorkRepoFilterInput     textinput.Model

	// import work overlay
	showImportWork      bool
	importWorkSessions  []string
	importWorkCursor    int
	importWorkResolving bool

	// help overlay
	showHelp bool

	// worktree picker overlay
	showWorktreePicker   bool
	worktreeOptions      []WorktreeOption
	worktreePickerIdx    int
	worktreePickerPR     int                          // PR number being picked for
	worktreePickerBranch string                       // PR branch name for display
	pendingSessionAction func(workDir string) tea.Cmd // callback after worktree selection
	pendingSessionPR     *PRRow                       // the PR row for the pending action

}

type spinnerTickMsg struct{}

type viewSavedMsg struct {
	view View
	err  error
}

// NewModel creates a new TUI model
func NewModel(cfg Config, ghClient *github.GHClient, deployClient *deploy.DevflowClient, conductorClient *deploy.ConductorClient, sessionMgr *tmux.SessionManager, sessionStore *session.Store, autonomyStore *session.AutonomyStore) Model {
	views := cfg.Views
	if len(views) == 0 {
		views = []View{{Name: "My PRs", Query: "author:@me", Default: true}}
	}

	activeIdx := 0
	for i, v := range views {
		if v.Default {
			activeIdx = i
			break
		}
	}

	sessionStore.Load()
	_ = sessionStore.Prune()
	_ = autonomyStore.Load()

	return Model{
		config:                cfg,
		loading:               true,
		ghClient:              ghClient,
		deployClient:          deployClient,
		conductorClient:       conductorClient,
		sessionMgr:            sessionMgr,
		sessionStore:          sessionStore,
		autonomyStore:         autonomyStore,
		prSessions:            make(map[int]tmux.PRSession),
		sessionInUse:          make(map[string]string),
		prCreationInProgress:  make(map[string]bool),
		agentNeedsAttention:   make(map[string]bool),
		sessionNeedsAttention: make(map[string]bool),
		windowFirstMissing:    make(map[string]time.Time),
		paneSnapshots:         make(map[string]string),
		paneUnchangedCount:    make(map[string]int),
		paneAckedContent:      make(map[string]string),
		width:                 120,
		height:                40,
		views:                 views,
		activeViewIdx:         activeIdx,
		configPath:            cfg.ConfigPath,
	}
}

func (m Model) activeQuery() string {
	if m.activeViewIdx >= 0 && m.activeViewIdx < len(m.views) {
		return m.views[m.activeViewIdx].Query
	}
	return "author:@me"
}

func (m Model) Init() tea.Cmd {
	return tea.Batch(
		fetchPRsCmd(m.ghClient, m.activeQuery()),
		tickCmd(m.config.RefreshInterval),
		loadSessionsCmd(m.sessionMgr, m.config.SessionsPath),
		sessionPollTickCmd(5*time.Second),
		pruneTickCmd(10*time.Minute),
	)
}

func spinnerTickCmd() tea.Cmd {
	return tea.Tick(80*time.Millisecond, func(t time.Time) tea.Msg {
		return spinnerTickMsg{}
	})
}

func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.KeyMsg:
		if m.showCustomPrompt {
			switch msg.Type {
			case tea.KeyEsc:
				m.showCustomPrompt = false
				return m, nil
			case tea.KeyEnter:
				prompt := m.customPromptInput.Value()
				m.showCustomPrompt = false
				if prompt == "" {
					return m, nil
				}
				r := m.findSelectedPRRow()
				if r == nil {
					return m, nil
				}
				return m, m.launchClaudeForPR(r, prompt)
			}
			var cmd tea.Cmd
			m.customPromptInput, cmd = m.customPromptInput.Update(msg)
			return m, cmd
		}

		if m.showRepoFilter {
			if m.repoFilterTextMode {
				switch msg.Type {
				case tea.KeyEsc:
					m.showRepoFilter = false
					return m, nil
				case tea.KeyEnter:
					repo := m.repoFilterInput.Value()
					m.selectRepoFilter(repo)
					return m, nil
				}
				var cmd tea.Cmd
				m.repoFilterInput, cmd = m.repoFilterInput.Update(msg)
				return m, cmd
			}

			// item count: [All] + repos + [Custom...]
			itemCount := 1 + len(m.repoFilterItems) + 1
			switch msg.String() {
			case "esc":
				m.showRepoFilter = false
				return m, nil
			case "q", "ctrl+c":
				return m, tea.Quit
			case "j", "down":
				if m.repoFilterCursor < itemCount-1 {
					m.repoFilterCursor++
				}
				return m, nil
			case "k", "up":
				if m.repoFilterCursor > 0 {
					m.repoFilterCursor--
				}
				return m, nil
			case "enter":
				if m.repoFilterCursor == 0 {
					m.selectRepoFilter("")
				} else if m.repoFilterCursor <= len(m.repoFilterItems) {
					m.selectRepoFilter(m.repoFilterItems[m.repoFilterCursor-1])
				} else {
					// [Custom...] selected - switch to text mode
					ti := textinput.New()
					ti.Placeholder = "type repo name..."
					ti.Focus()
					ti.CharLimit = 100
					ti.Width = 40
					m.repoFilterInput = ti
					m.repoFilterTextMode = true
					return m, textinput.Blink
				}
				return m, nil
			}
			return m, nil
		}

		if m.showViewPicker {
			if m.viewCreateMode == viewCreateName {
				switch msg.Type {
				case tea.KeyEsc:
					m.viewCreateMode = viewCreateNone
					return m, nil
				case tea.KeyEnter:
					name := m.viewNameInput.Value()
					if name == "" {
						return m, nil
					}
					ti := textinput.New()
					ti.Placeholder = "e.g. author:@me, review-requested:@me"
					ti.Focus()
					ti.CharLimit = 200
					ti.Width = 50
					m.viewQueryInput = ti
					m.viewCreateMode = viewCreateQuery
					return m, textinput.Blink
				}
				var cmd tea.Cmd
				m.viewNameInput, cmd = m.viewNameInput.Update(msg)
				return m, cmd
			}

			if m.viewCreateMode == viewCreateQuery {
				switch msg.Type {
				case tea.KeyEsc:
					m.viewCreateMode = viewCreateName
					return m, nil
				case tea.KeyEnter:
					query := m.viewQueryInput.Value()
					if query == "" {
						return m, nil
					}
					return m, m.createNewView(m.viewNameInput.Value(), query)
				}
				var cmd tea.Cmd
				m.viewQueryInput, cmd = m.viewQueryInput.Update(msg)
				return m, cmd
			}

			// picker list: views + [New View...]
			itemCount := len(m.views) + 1
			switch msg.String() {
			case "esc":
				m.showViewPicker = false
				return m, nil
			case "q", "ctrl+c":
				return m, tea.Quit
			case "j", "down":
				if m.viewPickerCursor < itemCount-1 {
					m.viewPickerCursor++
				}
				return m, nil
			case "k", "up":
				if m.viewPickerCursor > 0 {
					m.viewPickerCursor--
				}
				return m, nil
			case "enter":
				if m.viewPickerCursor < len(m.views) {
					m.activeViewIdx = m.viewPickerCursor
					m.showViewPicker = false
					m.repoFilter = ""
					m.statusFilter = ""
					m.loading = true
					m.rows = nil
					m.allRows = nil
					return m, fetchPRsCmd(m.ghClient, m.activeQuery())
				}
				// [New View...] selected
				ti := textinput.New()
				ti.Placeholder = "view name..."
				ti.Focus()
				ti.CharLimit = 50
				ti.Width = 40
				m.viewNameInput = ti
				m.viewCreateMode = viewCreateName
				return m, textinput.Blink
			}
			return m, nil
		}

		if m.showStatusFilter {
			itemCount := 1 + len(m.statusFilterItems) // [All] + categories
			switch msg.String() {
			case "esc":
				m.showStatusFilter = false
				return m, nil
			case "q", "ctrl+c":
				return m, tea.Quit
			case "j", "down":
				if m.statusFilterCursor < itemCount-1 {
					m.statusFilterCursor++
				}
				return m, nil
			case "k", "up":
				if m.statusFilterCursor > 0 {
					m.statusFilterCursor--
				}
				return m, nil
			case "enter":
				if m.statusFilterCursor == 0 {
					m.selectStatusFilter("")
				} else {
					m.selectStatusFilter(m.statusFilterItems[m.statusFilterCursor-1])
				}
				return m, nil
			}
			return m, nil
		}

		if m.showSessionHistory {
			return m.updateSessionHistoryOverlay(msg)
		}

		if m.showPRDetail {
			numItems := len(m.prDetailItems)

			switch msg.String() {
			case " ", "esc":
				m.showPRDetail = false
				return m, nil
			case "q", "ctrl+c":
				return m, tea.Quit
			case "j", "down":
				if m.prDetailCursor < numItems-1 {
					m.prDetailCursor++
				}
				return m, nil
			case "k", "up":
				if m.prDetailCursor > 0 {
					m.prDetailCursor--
				}
				return m, nil
			case "o":
				if m.prDetailCursor < numItems {
					item := m.prDetailItems[m.prDetailCursor]
					switch item.Kind {
					case prDetailConductorTarget:
						mosaicURL := conductorMosaicURL(item.ServiceName, item.Target, item.RunGUID, item.State)
						return m, func() tea.Msg {
							openBrowser(mosaicURL)
							return nil
						}
					case prDetailCICheck:
						checkURL := item.CheckURL
						return m, func() tea.Msg {
							openBrowser(checkURL)
							return nil
						}
					}
				}
				return m, nil
			case "enter":
				if m.prDetailCursor < numItems {
					item := m.prDetailItems[m.prDetailCursor]
					switch item.Kind {
					case prDetailAvailService:
						if m.prDetailExpandedSvc == item.SvcIndex {
							m.prDetailExpandedSvc = -1
						} else {
							m.prDetailExpandedSvc = item.SvcIndex
						}
					case prDetailReviewComment:
						if m.prDetailExpandedComment == m.prDetailCursor {
							m.prDetailExpandedComment = -1
						} else {
							m.prDetailExpandedComment = m.prDetailCursor
						}
					}
				}
				return m, nil
			case "c":
				if m.prDetailCursor < numItems {
					item := m.prDetailItems[m.prDetailCursor]
					switch item.Kind {
					case prDetailConductorTarget:
						if isFailedConductorState(item.State) {
							r := &m.rows[m.prDetailIdx]
							m.showPRDetail = false
							prompt := conductorInvestigatePrompt(item)
							return m, m.launchClaudeForPR(r, prompt)
						}
					case prDetailCICheck:
						r := &m.rows[m.prDetailIdx]
						m.showPRDetail = false
						return m, m.launchClaudeForPR(r, fmt.Sprintf("/dd:ci:fix %s", r.PR.URL))
					case prDetailReviewComment:
						r := &m.rows[m.prDetailIdx]
						m.showPRDetail = false
						return m, m.launchClaudeForPR(r, fmt.Sprintf("/dd:pr:address-feedback %s", item.CommentURL))
					}
				}
				return m, nil
			}
			return m, nil
		}

		if m.showHelp {
			if msg.String() == "?" || msg.Type == tea.KeyEsc {
				m.showHelp = false
			}
			return m, nil
		}

		if m.showImportWork {
			return m.updateImportWorkOverlay(msg)
		}

		if m.showNewWork {
			return m.updateNewWorkOverlay(msg)
		}

		if m.showWorktreePicker {
			return m.updateWorktreePickerOverlay(msg)
		}

		if m.showDeployRun {
			return m.updateDeployRunOverlay(msg)
		}

		if m.showGithubActions {
			return m.updateGithubActionsOverlay(msg)
		}

		if m.searchEditing {
			switch msg.Type {
			case tea.KeyEsc:
				m.searchInput.SetValue("")
				m.searchFilter = ""
				m.searchEditing = false
				m.applyFilters()
				m.table = m.rebuildTable()
				return m, nil
			case tea.KeyEnter:
				m.searchEditing = false
				return m, nil
			}
			var cmd tea.Cmd
			m.searchInput, cmd = m.searchInput.Update(msg)
			m.searchFilter = m.searchInput.Value()
			m.applyFilters()
			m.table = m.rebuildTable()
			return m, cmd
		}

		switch msg.String() {
		case "esc":
			if m.searchFilter != "" {
				m.searchFilter = ""
				m.searchInput.SetValue("")
				m.applyFilters()
				m.table = m.rebuildTable()
				return m, nil
			}
		case "q", "ctrl+c":
			return m, tea.Quit
		case "r":
			m.loading = true
			return m, fetchPRsCmd(m.ghClient, m.activeQuery())
		case "enter":
			return m, m.switchToSession()
		case "o":
			return m, m.openSelectedPR()
		case "c":
			if r := m.findSelectedPRRow(); r != nil && r.RowType == RowTypeLocal {
				return m, nil
			}
			return m, m.switchToPRSession()
		case "C":
			if r := m.findSelectedPRRow(); r != nil && r.RowType == RowTypeLocal {
				return m, nil
			}
			return m, m.showCustomPromptOverlay()
		case "g":
			if r := m.findSelectedPRRow(); r != nil && r.RowType == RowTypeLocal {
				return m, nil
			}
			return m, m.openGithubActionsOverlay()
		case "d":
			if r := m.findSelectedPRRow(); r != nil && r.RowType == RowTypeLocal {
				return m, nil
			}
			return m, m.openDeployRunOverlay()
		case "i":
			if r := m.findSelectedPRRow(); r != nil && r.RowType == RowTypeLocal {
				return m, nil
			}
			cmd := m.triggerIntegrate()
			return m, cmd
		case "D":
			return m, m.destroyPRSession()
		case "H":
			r := m.findSelectedPRRow()
			if r == nil {
				return m, nil
			}
			m.sessionHistoryCursor = 0
			m.sessionHistoryTmux = ""
			if r.RowType == RowTypeLocal {
				m.sessionHistoryPR = 0
				m.sessionHistoryTitle = r.PR.HeadRefName
				m.sessionHistoryTmux = r.TmuxSession
				m.sessionHistoryRecords = nil
			} else {
				if m.sessionStore == nil {
					return m, nil
				}
				m.sessionHistoryPR = r.PR.Number
				m.sessionHistoryTitle = fmt.Sprintf("#%d", r.PR.Number)
				m.sessionHistoryRecords = m.sessionStore.RecordsForPR(r.PR.Number)
			}
			m.showSessionHistory = true
			return m, nil
		case "W":
			r := m.findSelectedPRRow()
			if r == nil || r.RowType != RowTypePR {
				return m, nil
			}
			m.autonomyStore.Toggle(r.PR.RepoNameWithOwner, r.PR.Number)
			m.updateAgentStatuses()
			m.table = m.rebuildTable()
			enabled := m.autonomyStore.IsEnabled(r.PR.RepoNameWithOwner, r.PR.Number)
			if !enabled {
				m.notification = fmt.Sprintf("Autonomy disabled for #%d", r.PR.Number)
				return m, clearNotificationCmd(3 * time.Second)
			}
			return m, m.spawnAutonomyForSelectedPR(r)
		case "a":
			m.ackAttention()
			return m, nil
		case "O":
			return m, m.spawnPRCreationAgent()
		case " ":
			if r := m.findSelectedPRRow(); r != nil && r.RowType == RowTypeLocal {
				return m, nil
			}
			return m, m.showPRDetailOverlay()
		case "/":
			return m, m.openSearch()
		case "f":
			return m, m.openRepoFilterOverlay()
		case "s":
			return m, m.openStatusFilterOverlay()
		case "v":
			return m, m.openViewPicker()
		case "N":
			return m, m.openNewWorkOverlay()
		case "I":
			return m, m.openImportWorkOverlay()
		case "?":
			m.showHelp = true
			return m, nil
		}

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		if len(m.rows) > 0 {
			m.updateAgentStatuses()
			m.table = m.rebuildTable()
		}
		return m, nil

	case spinnerTickMsg:
		if !m.hasLoadingRows() {
			m.spinnerActive = false
			return m, nil
		}
		m.spinnerIdx = (m.spinnerIdx + 1) % len(spinnerFrames)
		m.table = m.rebuildTable()
		return m, spinnerTickCmd()

	case tickMsg:
		m.loading = true
		return m, tea.Batch(
			fetchPRsCmd(m.ghClient, m.activeQuery()),
			tickCmd(m.config.RefreshInterval),
			validateSessionsCmd(m.sessionMgr, m.sessionState, m.config.SessionsPath),
		)

	case sessionPollTickMsg:
		running := m.sessionStore.AllRunning()
		sessionsCopy := make(map[int]tmux.PRSession, len(m.prSessions))
		for k, v := range m.prSessions {
			sessionsCopy[k] = v
		}
		missingCopy := make(map[string]time.Time, len(m.windowFirstMissing))
		for k, v := range m.windowFirstMissing {
			missingCopy[k] = v
		}
		configDir := ""
		if m.sessionStore != nil {
			configDir = m.sessionStore.ConfigDir()
		}
		configSessions := make([]config.SessionEntry, len(m.sessionState.Sessions))
		copy(configSessions, m.sessionState.Sessions)
		return m, tea.Batch(
			pollRunningSessionsCmd(running, m.sessionMgr, sessionsCopy, configDir, missingCopy, configSessions),
			sessionPollTickCmd(5*time.Second),
		)

	case pruneTickMsg:
		_ = m.sessionStore.Prune()
		return m, pruneTickCmd(10 * time.Minute)

	case sessionsPollResultMsg:
		// Clean up consumed status files.
		for _, path := range msg.statusFilesToDelete {
			_ = session.DeleteStatusFile(path)
		}

		// Update window-first-missing map for the next poll.
		m.windowFirstMissing = msg.updatedMissing

		now := time.Now()

		for _, id := range msg.completedIDs {
			_ = m.sessionStore.UpdateRecord(id, func(r *session.SessionRecord) {
				r.EndedAt = &now
				r.Outcome = session.SessionOutcomeCompleted
			})
		}
		for id, errStr := range msg.failedRecords {
			_ = m.sessionStore.UpdateRecord(id, func(r *session.SessionRecord) {
				r.EndedAt = &now
				r.Outcome = session.SessionOutcomeFailed
				r.Error = errStr
			})
		}
		for _, id := range msg.unexpectedTerminations {
			_ = m.sessionStore.UpdateRecord(id, func(r *session.SessionRecord) {
				r.EndedAt = &now
				r.Outcome = session.SessionOutcomeFailed
				r.Error = "unexpected termination"
			})
		}

		// Update screen staleness tracking and derive needs-attention from it.
		m.paneSnapshots, m.paneUnchangedCount = applyStaleness(
			m.paneSnapshots, m.paneUnchangedCount, msg.paneCaptures,
		)

		newAttention := stalenessToAttention(m.paneUnchangedCount, m.paneSnapshots, m.paneAckedContent)
		m.agentNeedsAttention = newAttention

		newSessionAttention := stalenessToSessionAttention(m.paneUnchangedCount, m.paneSnapshots, m.paneAckedContent)
		sessionAttentionChanged := len(m.sessionNeedsAttention) != len(newSessionAttention)
		if !sessionAttentionChanged {
			for k := range newSessionAttention {
				if !m.sessionNeedsAttention[k] {
					sessionAttentionChanged = true
					break
				}
			}
		}
		m.sessionNeedsAttention = newSessionAttention

		changed := len(msg.completedIDs) > 0 || len(msg.failedRecords) > 0 ||
			len(msg.unexpectedTerminations) > 0 || len(newAttention) > 0 ||
			sessionAttentionChanged
		if changed {
			m.updateAgentStatuses()
			m.table = m.rebuildTable()
		}
		return m, nil

	case prsLoadedMsg:
		m.loading = false
		if msg.err != nil {
			m.err = msg.err
			return m, nil
		}
		m.err = nil
		m.lastRefresh = time.Now()

		// Preserve existing deploy and conductor data across refreshes
		type cachedDeploy struct {
			status            *deploy.OverallDeployStatus
			deployments       []deploy.ServiceDeployment
			conductorStatuses []deploy.ConductorServiceStatus
			conductorErr      error
		}
		existing := make(map[int]cachedDeploy)
		for _, row := range m.allRows {
			c := cachedDeploy{}
			if row.DeployStatus != nil {
				c.status = row.DeployStatus
				c.deployments = row.Deployments
			}
			if len(row.ConductorStatuses) > 0 {
				c.conductorStatuses = row.ConductorStatuses
			}
			c.conductorErr = row.ConductorErr
			if c.status != nil || c.conductorStatuses != nil {
				existing[row.PR.Number] = c
			}
		}

		m.allRows = buildRows(msg.prs)
		for i := range m.allRows {
			if cached, ok := existing[m.allRows[i].PR.Number]; ok {
				m.allRows[i].DeployStatus = cached.status
				m.allRows[i].Deployments = cached.deployments
				m.allRows[i].ConductorStatuses = cached.conductorStatuses
				m.allRows[i].ConductorErr = cached.conductorErr
				if hasConductorFailure(m.allRows[i].ConductorStatuses) {
					m.allRows[i].Action = github.ActionInvestigate
				}
			}
		}
		// Auto-detect local entries that now have a matching PR
		cmds := m.transitionMatchedLocalEntries(msg.prs)

		m.applyFilters()
		m.table = m.rebuildTable()

		// Fetch devflow deploy status for merged PRs that aren't fully deployed
		for _, row := range m.allRows {
			if row.PR.State != github.PRStateMerged {
				continue
			}
			if row.DeployStatus != nil && *row.DeployStatus == deploy.OverallDeployed {
				continue
			}
			cmds = append(cmds, fetchDeployStatusCmd(m.deployClient, row.PR.URL, row.PR.Number))
		}

		// Fetch conductor status for merged PRs with changes: labels that aren't fully deployed
		for _, row := range m.allRows {
			if row.PR.State != github.PRStateMerged || row.PR.MergedAt == nil {
				continue
			}
			if len(github.ExtractServiceNames(row.PR.Labels)) == 0 {
				continue
			}
			if conductorFullyDeployed(row.ConductorStatuses) {
				continue
			}
			cmds = append(cmds, fetchConductorStatusCmd(m.conductorClient, row.PR))
		}

		// Trigger autonomous agent evaluation after each PR fetch.
		if spawnCmd := m.buildAutonomousSpawnCmd(); spawnCmd != nil {
			cmds = append(cmds, spawnCmd)
		}

		if len(cmds) > 0 {
			if !m.spinnerActive {
				m.spinnerActive = true
				cmds = append(cmds, spinnerTickCmd())
			}
			return m, tea.Batch(cmds...)
		}
		return m, nil

	case markReadyMsg:
		if msg.err != nil {
			m.notification = fmt.Sprintf("Failed to mark #%d ready: %v", msg.prNumber, msg.err)
			return m, clearNotificationCmd(5 * time.Second)
		}
		m.notification = fmt.Sprintf("Marked #%d ready for review", msg.prNumber)
		m.loading = true
		return m, tea.Batch(
			fetchPRsCmd(m.ghClient, m.activeQuery()),
			clearNotificationCmd(3*time.Second),
		)

	case clearNotificationMsg:
		m.notification = ""
		return m, nil

	case deployStatusMsg:

		if msg.err != nil {
			m.deployErr = msg.err
			// Only set error status if there's no existing status to preserve
			for i := range m.allRows {
				if m.allRows[i].PR.Number == msg.prNumber {
					if m.allRows[i].DeployStatus == nil {
						errStatus := deploy.OverallFetchError
						m.allRows[i].DeployStatus = &errStatus
					}
					break
				}
			}
			m.applyFilters()
			m.table = m.rebuildTable()
			return m, nil
		}
		m.updateDeployStatus(msg)
		m.applyFilters()
		m.table = m.rebuildTable()
		return m, nil

	case conductorStatusMsg:

		for i := range m.allRows {
			if m.allRows[i].PR.Number == msg.prNumber {
				m.allRows[i].ConductorErr = msg.err
				if len(msg.statuses) > 0 {
					m.allRows[i].ConductorStatuses = msg.statuses
				} else if msg.err != nil {
					// Empty (non-nil) slice marks as fetched so spinner stops;
					// next refresh will retry since conductorFullyDeployed([]) == false.
					m.allRows[i].ConductorStatuses = []deploy.ConductorServiceStatus{}
				} else {
					m.allRows[i].ConductorStatuses = msg.statuses
				}
				if hasConductorFailure(m.allRows[i].ConductorStatuses) {
					m.allRows[i].Action = github.ActionInvestigate
				}
				break
			}
		}
		m.applyFilters()
		m.table = m.rebuildTable()
		return m, nil

	case reviewThreadsMsg:
		// Ignore stale responses if the overlay was closed or switched to a different PR
		if !m.showPRDetail || m.prDetailIdx >= len(m.rows) || m.rows[m.prDetailIdx].PR.Number != msg.prNumber {
			return m, nil
		}
		m.prDetailReviewCommentsLoading = false
		if msg.err != nil {
			m.prDetailReviewCommentsErr = msg.err
		} else {
			for _, c := range msg.comments {
				m.prDetailItems = append(m.prDetailItems, prDetailItem{
					Kind:          prDetailReviewComment,
					CommentAuthor: c.Author,
					CommentBody:   c.Body,
					CommentPath:   c.Path,
					CommentURL:    c.URL,
				})
			}
		}
		return m, nil

	case integrateMsg:
		if msg.err != nil {
			m.notification = fmt.Sprintf("Failed to integrate #%d: %v", msg.prNumber, msg.err)
			return m, clearNotificationCmd(5 * time.Second)
		}
		m.notification = fmt.Sprintf("Integrated #%d", msg.prNumber)
		return m, clearNotificationCmd(3 * time.Second)

	case githubActionMsg:
		if msg.err != nil {
			m.notification = fmt.Sprintf("#%d: %v", msg.prNumber, msg.err)
			return m, clearNotificationCmd(5 * time.Second)
		}
		switch msg.action {
		case "close":
			m.notification = fmt.Sprintf("Closed #%d", msg.prNumber)
		case "comment":
			m.notification = fmt.Sprintf("Commented on #%d", msg.prNumber)
		case "request merge":
			m.notification = fmt.Sprintf("Requested merge for #%d", msg.prNumber)
		case "update branch":
			m.notification = fmt.Sprintf("Updated branch for #%d", msg.prNumber)
		}
		return m, clearNotificationCmd(3 * time.Second)

	case viewSavedMsg:
		if msg.err != nil {
			m.err = fmt.Errorf("saving view: %w", msg.err)
			return m, nil
		}
		m.views = append(m.views, msg.view)
		m.activeViewIdx = len(m.views) - 1
		m.showViewPicker = false
		m.viewCreateMode = viewCreateNone
		m.repoFilter = ""
		m.statusFilter = ""
		m.loading = true
		return m, fetchPRsCmd(m.ghClient, m.activeQuery())

	case sessionsLoadedMsg:
		m.sessionState = msg.state
		for _, entry := range msg.state.Sessions {
			if entry.Type == config.SessionTypePR && entry.PRNumber > 0 {
				m.prSessions[entry.PRNumber] = tmux.PRSession{
					SessionName: entry.TmuxSession,
					PRNumber:    entry.PRNumber,
					WorkDir:     entry.WorktreePath,
					Branch:      entry.Branch,
				}
				if entry.WorktreePath != "" {
					m.sessionInUse[entry.WorktreePath] = entry.TmuxSession
				}
			}
		}
		m.rebuildLocalRows()
		m.applyFilters()
		m.table = m.rebuildTable()
		// Trigger an immediate session poll so staleness tracking starts on startup.
		// Also evaluate autonomous spawns — PRs may have loaded before sessions,
		// so the prsLoadedMsg handler would have found no candidates.
		cmds := []tea.Cmd{
			discoverSessionsCmd(m.sessionMgr),
			func() tea.Msg { return sessionPollTickMsg{} },
		}
		if spawnCmd := m.buildAutonomousSpawnCmd(); spawnCmd != nil {
			cmds = append(cmds, spawnCmd)
		}
		return m, tea.Batch(cmds...)

	case sessionsValidatedMsg:
		m.sessionState = msg.state
		// Rebuild prSessions and sessionInUse from validated state
		m.prSessions = make(map[int]tmux.PRSession)
		m.sessionInUse = make(map[string]string)
		for _, entry := range msg.state.Sessions {
			if entry.Type == config.SessionTypePR && entry.PRNumber > 0 {
				m.prSessions[entry.PRNumber] = tmux.PRSession{
					SessionName: entry.TmuxSession,
					PRNumber:    entry.PRNumber,
					WorkDir:     entry.WorktreePath,
					Branch:      entry.Branch,
				}
			}
			if entry.WorktreePath != "" {
				m.sessionInUse[entry.WorktreePath] = entry.TmuxSession
			}
		}
		m.rebuildLocalRows()
		m.applyFilters()
		m.table = m.rebuildTable()
		return m, nil

	case sessionsSavedMsg:
		return m, nil

	case sessionsDiscoveredMsg:
		if msg.sessions != nil {
			// Track which tmux sessions are already in the state file
			knownSessions := make(map[string]bool)
			for _, entry := range m.sessionState.Sessions {
				knownSessions[entry.TmuxSession] = true
			}

			for num, sess := range msg.sessions {
				m.prSessions[num] = sess
				if sess.WorkDir != "" {
					m.sessionInUse[sess.WorkDir] = sess.SessionName
				}

				// Backward compatibility: add tmux-discovered sessions not yet in state file
				if !knownSessions[sess.SessionName] {
					m.sessionState.Sessions = append(m.sessionState.Sessions, config.SessionEntry{
						TmuxSession:  sess.SessionName,
						Repo:         "",
						WorktreePath: sess.WorkDir,
						Branch:       sess.Branch,
						PRNumber:     num,
						Type:         config.SessionTypePR,
					})
				}
			}

			m.updateAgentStatuses()
			m.table = m.rebuildTable()
			if m.config.SessionsPath != "" {
				return m, saveSessionsCmd(m.sessionState, m.config.SessionsPath)
			}
		}
		return m, nil

	case tmuxSessionsListedMsg:
		if !m.showImportWork {
			return m, nil
		}
		if msg.err != nil {
			m.showImportWork = false
			m.notification = fmt.Sprintf("Failed to list tmux sessions: %v", msg.err)
			return m, clearNotificationCmd(5 * time.Second)
		}
		// Filter out sessions already managed by the dashboard
		managed := make(map[string]bool)
		for _, entry := range m.sessionState.Sessions {
			managed[entry.TmuxSession] = true
		}
		var unmanaged []string
		for _, s := range msg.sessions {
			if !managed[s] {
				unmanaged = append(unmanaged, s)
			}
		}
		m.importWorkSessions = unmanaged
		m.importWorkCursor = 0
		return m, nil

	case sessionInfoResolvedMsg:
		if !m.showImportWork {
			return m, nil
		}
		m.importWorkResolving = false
		if msg.err != nil {
			m.notification = fmt.Sprintf("Failed to resolve session info: %v", msg.err)
			m.showImportWork = false
			return m, clearNotificationCmd(5 * time.Second)
		}
		// Add the local entry
		m.sessionState.Sessions = append(m.sessionState.Sessions, config.SessionEntry{
			TmuxSession:  msg.sessionName,
			Repo:         msg.info.Repo,
			WorktreePath: msg.info.WorktreePath,
			Branch:       msg.info.Branch,
			Type:         config.SessionTypeLocal,
		})
		m.sessionInUse[msg.info.WorktreePath] = msg.sessionName
		m.showImportWork = false
		m.notification = fmt.Sprintf("Imported %s (%s)", msg.sessionName, msg.info.Branch)
		m.rebuildLocalRows()
		m.applyFilters()
		m.table = m.rebuildTable()
		var cmds []tea.Cmd
		cmds = append(cmds, clearNotificationCmd(5*time.Second))
		if m.config.SessionsPath != "" {
			cmds = append(cmds, saveSessionsCmd(m.sessionState, m.config.SessionsPath))
		}
		return m, tea.Batch(cmds...)

	case reposDiscoveredMsg:
		if msg.err != nil {
			m.showNewWork = false
			m.notification = fmt.Sprintf("Failed to scan repos: %v", msg.err)
			return m, clearNotificationCmd(5 * time.Second)
		}
		m.newWorkRepos = msg.repos
		return m, nil

	case worktreesDiscoveredMsg:
		if m.showNewWork {
			return m, m.handleNewWorkWorktrees(msg)
		}
		return m, m.showWorktreePickerForPR(msg)

	case worktreeCreatedMsg:
		if m.pendingSessionAction != nil {
			action := m.pendingSessionAction
			m.showWorktreePicker = false
			m.pendingSessionAction = nil
			return m, action(msg.workDir)
		}
		return m, nil

	case sessionCreatedMsg:
		m.prSessions[msg.session.PRNumber] = msg.session
		if msg.session.WorkDir != "" {
			m.sessionInUse[msg.session.WorkDir] = msg.session.SessionName
		}
		// Record session history when a new window is created
		if msg.isNewWindow && msg.session.PRNumber > 0 {
			sessionType := msg.sessionType
			if sessionType == "" {
				sessionType = session.SessionTypeManual
			}
			record := session.SessionRecord{
				ID:            session.NewSessionID(),
				PRNumber:      msg.session.PRNumber,
				Repo:          msg.repo,
				SessionType:   sessionType,
				ActionType:    msg.actionType,
				Prompt:        msg.claudeCmd,
				WorkDir:       msg.session.WorkDir,
				WindowName:    msg.windowName,
				HeadCommitOID: msg.headCommitOID,
				StartedAt:     time.Now(),
				Outcome:       session.SessionOutcomeRunning,
			}
			_ = m.sessionStore.AddRecord(record)
		}
		// Update state file entry (update if exists, add if new)
		found := false
		for i, entry := range m.sessionState.Sessions {
			if entry.TmuxSession == msg.session.SessionName {
				m.sessionState.Sessions[i].WorktreePath = msg.session.WorkDir
				m.sessionState.Sessions[i].Branch = msg.session.Branch
				m.sessionState.Sessions[i].PRNumber = msg.session.PRNumber
				found = true
				break
			}
		}
		if !found {
			sessionType := config.SessionTypePR
			if msg.session.PRNumber == 0 {
				sessionType = config.SessionTypeLocal
			}
			m.sessionState.Sessions = append(m.sessionState.Sessions, config.SessionEntry{
				TmuxSession:  msg.session.SessionName,
				Repo:         m.newWorkPendingRepo,
				WorktreePath: msg.session.WorkDir,
				Branch:       msg.session.Branch,
				PRNumber:     msg.session.PRNumber,
				Type:         sessionType,
			})
		}
		m.newWorkPendingRepo = ""
		m.rebuildLocalRows()
		m.updateAgentStatuses()
		m.applyFilters()
		m.table = m.rebuildTable()
		if m.config.SessionsPath != "" {
			return m, saveSessionsCmd(m.sessionState, m.config.SessionsPath)
		}
		return m, nil

	case sessionDestroyedMsg:
		// Remove from state file
		var notifText string
		for i, entry := range m.sessionState.Sessions {
			if entry.TmuxSession == msg.sessionName {
				if entry.Type == config.SessionTypePR && entry.PRNumber > 0 {
					notifText = fmt.Sprintf("Killed session for #%d", entry.PRNumber)
					delete(m.prSessions, entry.PRNumber)
					// Mark any running records as interrupted (user-initiated kill, not a crash)
					for _, record := range m.sessionStore.RecordsForPR(entry.PRNumber) {
						if record.Outcome == session.SessionOutcomeRunning {
							_ = m.sessionStore.UpdateRecord(record.ID, func(r *session.SessionRecord) {
								t := time.Now()
								r.EndedAt = &t
								r.Outcome = session.SessionOutcomeInterrupted
							})
						}
					}
				} else {
					notifText = fmt.Sprintf("Killed session %s", msg.sessionName)
				}
				delete(m.sessionInUse, entry.WorktreePath)
				m.sessionState.Sessions = append(m.sessionState.Sessions[:i], m.sessionState.Sessions[i+1:]...)
				break
			}
		}
		if notifText == "" {
			notifText = fmt.Sprintf("Killed session %s", msg.sessionName)
		}
		m.notification = notifText
		m.updateAgentStatuses()
		m.rebuildLocalRows()
		m.applyFilters()
		m.table = m.rebuildTable()
		if m.showSessionHistory {
			m.sessionHistoryRecords = m.sessionStore.RecordsForPR(m.sessionHistoryPR)
			if m.sessionHistoryCursor > 0 && m.sessionHistoryCursor >= len(m.sessionHistoryRecords) {
				m.sessionHistoryCursor--
			}
		}
		var cmds []tea.Cmd
		cmds = append(cmds, clearNotificationCmd(3*time.Second))
		if m.config.SessionsPath != "" {
			cmds = append(cmds, saveSessionsCmd(m.sessionState, m.config.SessionsPath))
		}
		return m, tea.Batch(cmds...)

	case sessionErrorMsg:
		if msg.prNumber > 0 {
			m.notification = fmt.Sprintf("Session error for #%d: %v", msg.prNumber, msg.err)
		} else if msg.sessionName != "" {
			m.notification = fmt.Sprintf("Session error for %s: %v", msg.sessionName, msg.err)
		} else {
			m.notification = fmt.Sprintf("Session error: %v", msg.err)
		}
		return m, clearNotificationCmd(5 * time.Second)

	case sessionRenamedMsg:
		if msg.err != nil {
			m.notification = fmt.Sprintf("Failed to rename session %s: %v", msg.oldName, msg.err)
			return m, clearNotificationCmd(5 * time.Second)
		}
		return m, nil

	case prAgentCompletedMsg:
		delete(m.prCreationInProgress, msg.worktreePath)
		if msg.err != nil {
			m.notification = fmt.Sprintf("PR creation failed: %v", msg.err)
			m.rebuildLocalRows()
			m.applyFilters()
			m.table = m.rebuildTable()
			return m, clearNotificationCmd(5 * time.Second)
		}
		prNumber, prURL := parsePRFromAgentOutput(msg.output)
		if prNumber == 0 {
			m.notification = "PR creation agent finished but no PR URL found in output"
			m.rebuildLocalRows()
			m.applyFilters()
			m.table = m.rebuildTable()
			return m, clearNotificationCmd(5 * time.Second)
		}
		m.notification = fmt.Sprintf("Created PR #%d", prNumber)
		cmds := m.transitionLocalEntryByWorktree(msg.worktreePath, prNumber, prURL)
		m.rebuildLocalRows()
		m.applyFilters()
		m.table = m.rebuildTable()
		cmds = append(cmds, clearNotificationCmd(5*time.Second))
		return m, tea.Batch(cmds...)

	case autonomousSpawnMsg:
		if msg.err != nil {
			m.notification = fmt.Sprintf("Autonomous spawn failed for %s: %v", msg.repo, msg.err)
			return m, clearNotificationCmd(5 * time.Second)
		}
		// Record the new autonomous session using the pre-generated ID so the status file
		// path embedded in the agent prompt matches this record's ID.
		if msg.session.PRNumber > 0 {
			id := msg.recordID
			if id == "" {
				id = session.NewSessionID()
			}
			record := session.SessionRecord{
				ID:            id,
				PRNumber:      msg.session.PRNumber,
				Repo:          msg.repo,
				SessionType:   session.SessionTypeAutonomous,
				ActionType:    msg.actionType,
				Prompt:        msg.claudeCmd,
				WorkDir:       msg.session.WorkDir,
				WindowName:    msg.windowName,
				HeadCommitOID: msg.headCommitOID,
				StartedAt:     time.Now(),
				Outcome:       session.SessionOutcomeRunning,
			}
			_ = m.sessionStore.AddRecord(record)
		}
		// Register session so subsequent spawn cycles and user interactions find it.
		if _, exists := m.prSessions[msg.session.PRNumber]; !exists {
			m.prSessions[msg.session.PRNumber] = msg.session
			if msg.session.WorkDir != "" {
				m.sessionInUse[msg.session.WorkDir] = msg.session.SessionName
			}
		}
		m.updateAgentStatuses()
		m.table = m.rebuildTable()
		m.notification = fmt.Sprintf("Spawned %s agent for #%d", msg.actionType, msg.session.PRNumber)
		return m, clearNotificationCmd(5 * time.Second)
	}

	prevIdx := m.table.GetHighlightedRowIndex()
	var cmd tea.Cmd
	m.table, cmd = m.table.Update(msg)
	// Rebuild table when navigation changes the highlighted row so
	// baked-in row styles (cursor prefix, selected background) update.
	if m.table.GetHighlightedRowIndex() != prevIdx {
		m.table = m.rebuildTable()
	}
	return m, cmd
}

func (m Model) View() string {
	headerText := "PR Status Dashboard"
	if len(m.views) > 1 {
		headerText += " - " + m.views[m.activeViewIdx].Name
	}
	header := titleStyle.Render(headerText)

	var status string
	if m.err != nil {
		status = errorStyle.Render(fmt.Sprintf("Error: %v", m.err))
	} else if m.loading && m.lastRefresh.IsZero() {
		status = loadingStyle.Render("Loading PRs...")
	} else {
		status = fmt.Sprintf("Last refresh: %s", m.lastRefresh.Format("15:04:05"))
		if m.repoFilter != "" {
			status += fmt.Sprintf(" | repo: %s", m.repoFilter)
		}
		if m.statusFilter != "" {
			status += fmt.Sprintf(" | status: %s", m.statusFilter)
		}
		if m.searchFilter != "" && !m.searchEditing {
			status += fmt.Sprintf(" | search: %s", m.searchFilter)
		}
		if m.loading {
			status += " | Refreshing..."
		}
	}
	if m.deployErr != nil {
		status += "\n" + errorStyle.Render(fmt.Sprintf("Deploy lookup: %v", m.deployErr))
	}
	if m.notification != "" {
		status += "\n" + loadingStyle.Render(m.notification)
	}

	var searchBar string
	if m.searchEditing {
		searchBar = searchBarActiveStyle.Render("/ "+m.searchInput.View()) + "\n"
	} else if m.searchFilter != "" {
		searchBar = searchBarStyle.Render("/ "+m.searchFilter) + "\n"
	}

	view := header + "\n" +
		searchBar +
		m.table.View() + "\n" +
		statusBarStyle.Render(status) + "\n" +
		m.buildHelpLine()

	if m.showHelp {
		return renderHelpOverlay(m)
	}

	if m.showImportWork {
		return renderImportWorkOverlay(m)
	}

	if m.showNewWork {
		return renderNewWorkOverlay(m)
	}

	if m.showCustomPrompt {
		return renderCustomPromptOverlay(m)
	}

	if m.showRepoFilter {
		return renderRepoFilterOverlay(m)
	}

	if m.showStatusFilter {
		return renderStatusFilterOverlay(m)
	}

	if m.showViewPicker {
		return renderViewPickerOverlay(m)
	}

	if m.showGithubActions {
		return renderGithubActionsOverlay(m)
	}

	if m.showWorktreePicker {
		return renderWorktreePickerOverlay(m)
	}

	if m.showDeployRun {
		return renderDeployRunOverlay(m)
	}

	if m.showSessionHistory {
		return renderSessionHistoryOverlay(m)
	}

	if m.showPRDetail && m.prDetailIdx < len(m.rows) {
		return renderPRDetailOverlay(m)
	}

	return view
}

// hasLoadingRows returns true if any row is still waiting for deploy or conductor data.
func (m Model) hasLoadingRows() bool {
	for _, row := range m.allRows {
		if row.PR.State != github.PRStateMerged {
			continue
		}
		if row.DeployStatus == nil {
			return true
		}
		if row.ConductorStatuses == nil && len(github.ExtractServiceNames(row.PR.Labels)) > 0 {
			return true
		}
	}
	return false
}

func (m Model) spinnerFrame() string {
	return spinnerFrames[m.spinnerIdx%len(spinnerFrames)]
}

func (m Model) rebuildTable() table.Model {
	return buildTable(m.rows, m.width, m.spinnerFrame(), maxAgentWidth(m.rows), m.table.GetHighlightedRowIndex())
}

// ackAttention acknowledges the current stale state of all panes associated with
// the highlighted row. The acked content is stored so that the same static screen
// won't re-trigger attention — but if the pane changes and gets stuck again on
// new content, attention will fire again.
func (m *Model) ackAttention() {
	r := m.findSelectedPRRow()
	if r == nil {
		return
	}

	acked := false

	// Ack autonomous session panes (keyed by record ID).
	if m.sessionStore != nil {
		prNum := r.PR.Number
		if r.RowType == RowTypeLocal {
			prNum = 0
		}
		for _, rec := range m.sessionStore.RecordsForPR(prNum) {
			if content, ok := m.paneSnapshots[rec.ID]; ok {
				m.paneAckedContent[rec.ID] = content
				acked = true
			}
		}
	}

	// Ack config-tracked session panes (keyed by "session:window").
	sessionName := ""
	if r.RowType == RowTypeLocal {
		sessionName = r.TmuxSession
	} else if sess, ok := m.prSessions[r.PR.Number]; ok {
		sessionName = sess.SessionName
	}
	if sessionName != "" {
		prefix := sessionName + ":"
		for key, content := range m.paneSnapshots {
			if strings.HasPrefix(key, prefix) {
				m.paneAckedContent[key] = content
				acked = true
			}
		}
	}

	if acked {
		// Recompute attention state and rebuild the table.
		m.agentNeedsAttention = stalenessToAttention(m.paneUnchangedCount, m.paneSnapshots, m.paneAckedContent)
		m.sessionNeedsAttention = stalenessToSessionAttention(m.paneUnchangedCount, m.paneSnapshots, m.paneAckedContent)
		m.updateAgentStatuses()
		m.table = m.rebuildTable()
		m.notification = "Acknowledged"
	}
}

func (m *Model) updateAgentStatuses() {
	if m.sessionStore == nil {
		return
	}
	for i := range m.rows {
		if m.rows[i].RowType == RowTypeLocal {
			sessionAttn := m.sessionNeedsAttention[m.rows[i].TmuxSession]
			m.rows[i].AgentStatus = agentColumnText(nil, m.rows[i].TmuxSession != "", false, nil, sessionAttn)
			continue
		}
		records := m.sessionStore.RecordsForPR(m.rows[i].PR.Number)
		sess, hasActiveSession := m.prSessions[m.rows[i].PR.Number]
		sessionAttn := hasActiveSession && m.sessionNeedsAttention[sess.SessionName]
		autonomyEnabled := m.autonomyStore != nil && m.autonomyStore.IsEnabled(m.rows[i].PR.RepoNameWithOwner, m.rows[i].PR.Number)
		m.rows[i].AgentStatus = agentColumnText(records, hasActiveSession, autonomyEnabled, m.agentNeedsAttention, sessionAttn)
	}
}

// buildAutonomousSpawnCmd constructs the spawn command for any autonomy-enabled PRs that lack
// a running session, subject to the concurrency limit. Returns nil if there is nothing to spawn.
func (m *Model) buildAutonomousSpawnCmd() tea.Cmd {
	if m.autonomyStore == nil || m.sessionStore == nil || m.sessionMgr == nil {
		return nil
	}

	// Count running autonomous sessions toward the concurrency limit.
	// Needs-attention sessions (blocked on permission) are excluded: they consume minimal
	// resources and should not prevent new agents from starting.
	runningCount := 0
	for _, r := range m.sessionStore.AllRunning() {
		if r.SessionType == session.SessionTypeAutonomous && !m.agentNeedsAttention[r.ID] {
			runningCount++
		}
	}

	configDir := m.sessionStore.ConfigDir()

	// Build candidates: open PRs with autonomy enabled, an actionable item, and a known session.
	var candidates []evaluateAutonomousSpawnsCandidate
	for _, row := range m.rows {
		if row.RowType != RowTypePR || row.PR.State != github.PRStateOpen {
			continue
		}
		// Merge is excluded: it's a one-click action, not an agent task.
		if row.Action == github.ActionNone || row.Action == github.ActionMerge {
			continue
		}
		if !m.autonomyStore.IsEnabled(row.PR.RepoNameWithOwner, row.PR.Number) {
			continue
		}
		sess, ok := m.prSessions[row.PR.Number]
		if !ok {
			continue
		}
		actionType := actionTypeForSession(&row, false)
		recordID := session.NewSessionID()
		statusFilePath := session.StatusFilePath(configDir, recordID)
		claudeCmd := buildAutonomousPrompt(row.PR, actionType, statusFilePath)
		windowName := "auto-" + actionType
		candidates = append(candidates, evaluateAutonomousSpawnsCandidate{
			sess:          sess,
			pr:            row.PR,
			actionType:    actionType,
			claudeCmd:     claudeCmd,
			windowName:    windowName,
			headCommitOID: row.PR.HeadCommitOID,
			recordID:      recordID,
		})
	}
	if len(candidates) == 0 {
		return nil
	}
	// Fix CI is higher priority than Address feedback since CI failures block the PR.
	sort.SliceStable(candidates, func(i, j int) bool {
		return candidates[i].actionType == "fix-ci" && candidates[j].actionType != "fix-ci"
	})
	return evaluateAutonomousSpawnsCmd(m.sessionMgr, m.sessionStore, candidates, runningCount, m.config.MaxConcurrentAgents)
}

// spawnAutonomyForSelectedPR handles the "W" key when autonomy is being enabled.
// It checks whether the PR has actionable items, then either spawns immediately
// (if a session exists) or goes through worktree discovery (same flow as "enter").
func (m *Model) spawnAutonomyForSelectedPR(r *PRRow) tea.Cmd {
	if r.PR.State != github.PRStateOpen {
		m.notification = fmt.Sprintf("Autonomy enabled for #%d — PR is not open", r.PR.Number)
		return clearNotificationCmd(3 * time.Second)
	}
	if r.Action == github.ActionNone || r.Action == github.ActionMerge {
		m.notification = fmt.Sprintf("Autonomy enabled for #%d — no actionable items", r.PR.Number)
		return clearNotificationCmd(3 * time.Second)
	}

	// If session exists, spawn immediately
	if _, ok := m.prSessions[r.PR.Number]; ok {
		m.notification = fmt.Sprintf("Autonomy enabled for #%d — spawning agent", r.PR.Number)
		spawnCmd := m.buildAutonomousSpawnCmd()
		if spawnCmd == nil {
			m.notification = fmt.Sprintf("Autonomy enabled for #%d — agent already running", r.PR.Number)
			return clearNotificationCmd(3 * time.Second)
		}
		return tea.Batch(clearNotificationCmd(5*time.Second), spawnCmd)
	}

	// No session — go through worktree discovery (same UX as pressing enter)
	m.notification = fmt.Sprintf("Autonomy enabled for #%d", r.PR.Number)
	return m.initiateWorktreeDiscovery(r, func(workDir string) tea.Cmd {
		return m.buildAutonomousSpawnForNewSession(r, workDir)
	})
}

// buildAutonomousSpawnForNewSession constructs a session and spawns an autonomous agent
// for a PR that doesn't have an existing tmux session. Called from the worktree discovery
// callback when "W" enables autonomy on a session-less PR.
func (m *Model) buildAutonomousSpawnForNewSession(r *PRRow, workDir string) tea.Cmd {
	sess := tmux.PRSession{
		SessionName: tmux.SanitizeSessionName(r.PR.Title, r.PR.Number),
		PRNumber:    r.PR.Number,
		PRTitle:     r.PR.Title,
		WorkDir:     workDir,
		Branch:      r.PR.HeadRefName,
		PRURL:       r.PR.URL,
	}
	actionType := actionTypeForSession(r, false)
	recordID := session.NewSessionID()
	configDir := m.sessionStore.ConfigDir()
	statusFilePath := session.StatusFilePath(configDir, recordID)
	claudeCmd := buildAutonomousPrompt(r.PR, actionType, statusFilePath)
	windowName := "auto-" + actionType

	c := evaluateAutonomousSpawnsCandidate{
		sess:          sess,
		pr:            r.PR,
		actionType:    actionType,
		claudeCmd:     claudeCmd,
		windowName:    windowName,
		headCommitOID: r.PR.HeadCommitOID,
		recordID:      recordID,
	}
	return spawnAutonomousAgentCmd(m.sessionMgr, c)
}

func buildRows(prs []github.PR) []PRRow {
	rows := make([]PRRow, 0, len(prs))
	for _, pr := range prs {
		status := github.DetermineStatus(pr)
		rows = append(rows, PRRow{
			PR:      pr,
			Status:  status,
			Action:  github.DetermineAction(status),
			RowType: RowTypePR,
		})
	}
	return rows
}

func (m *Model) updateDeployStatus(msg deployStatusMsg) {
	if len(msg.deployments) == 0 {
		return
	}

	var allTargets []deploy.DeployTarget
	for _, d := range msg.deployments {
		allTargets = append(allTargets, d.Targets...)
	}

	overall := deploy.DetermineOverallStatus(allTargets)

	for i := range m.allRows {
		if m.allRows[i].PR.Number == msg.prNumber {
			m.allRows[i].DeployStatus = &overall
			m.allRows[i].Deployments = msg.deployments
			break
		}
	}
}

func (m *Model) rebuildLocalRows() {
	var rows []PRRow
	for _, entry := range m.sessionState.Sessions {
		if entry.Type != config.SessionTypeLocal {
			continue
		}
		rows = append(rows, PRRow{
			PR: github.PR{
				Number:            0,
				RepoNameWithOwner: entry.Repo,
				Title:             entry.Branch,
				HeadRefName:       entry.Branch,
			},
			RowType:      RowTypeLocal,
			WorktreePath: entry.WorktreePath,
			TmuxSession:  entry.TmuxSession,
		})
	}
	m.localRows = rows
}

func (m Model) findSelectedPRRow() *PRRow {
	idx := m.table.GetHighlightedRowIndex()
	if idx < 0 || idx >= len(m.rows) {
		return nil
	}
	return &m.rows[idx]
}

func (m Model) openSelectedPR() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil {
		return nil
	}
	url := r.PR.URL
	if r.RowType == RowTypeLocal {
		url = fmt.Sprintf("https://github.com/%s/compare/%s", r.PR.RepoNameWithOwner, r.PR.HeadRefName)
	}
	return func() tea.Msg {
		openBrowser(url)
		return nil
	}
}

func (m *Model) openImportWorkOverlay() tea.Cmd {
	m.showImportWork = true
	m.importWorkSessions = nil
	m.importWorkCursor = 0
	m.importWorkResolving = false
	return listTmuxSessionsCmd(m.sessionMgr)
}

func (m *Model) updateImportWorkOverlay(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.importWorkResolving {
		if msg.String() == "ctrl+c" {
			return m, tea.Quit
		}
		return m, nil
	}
	switch msg.String() {
	case "esc":
		m.showImportWork = false
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	case "j", "down":
		if m.importWorkCursor < len(m.importWorkSessions)-1 {
			m.importWorkCursor++
		}
		return m, nil
	case "k", "up":
		if m.importWorkCursor > 0 {
			m.importWorkCursor--
		}
		return m, nil
	case "enter":
		if len(m.importWorkSessions) == 0 || m.importWorkCursor >= len(m.importWorkSessions) {
			return m, nil
		}
		selected := m.importWorkSessions[m.importWorkCursor]
		m.importWorkResolving = true
		return m, resolveSessionInfoCmd(m.sessionMgr, selected)
	}
	return m, nil
}

func (m *Model) filteredNewWorkRepos() []string {
	filter := m.newWorkRepoFilterInput.Value()
	if filter == "" {
		return m.newWorkRepos
	}
	lowerFilter := strings.ToLower(filter)
	var filtered []string
	for _, repo := range m.newWorkRepos {
		if strings.Contains(strings.ToLower(repo), lowerFilter) {
			filtered = append(filtered, repo)
		}
	}
	return filtered
}

func (m *Model) openNewWorkOverlay() tea.Cmd {
	m.showNewWork = true
	m.newWorkStep = newWorkSelectRepo
	m.newWorkRepoCursor = 0
	m.newWorkRepos = nil
	m.newWorkRepoFilterMode = false
	m.newWorkUseExistingWorktree = false
	homeDir := m.sessionMgr.HomeDir
	return listReposCmd(m.sessionMgr, homeDir+"/dd/")
}

func (m *Model) updateNewWorkOverlay(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch m.newWorkStep {
	case newWorkSelectRepo:
		if m.newWorkRepoFilterMode {
			switch msg.Type {
			case tea.KeyEsc:
				m.newWorkRepoFilterMode = false
				m.newWorkRepoCursor = 0
				return m, nil
			case tea.KeyEnter:
				filtered := m.filteredNewWorkRepos()
				if m.newWorkRepoCursor >= len(filtered) {
					return m, nil
				}
				m.newWorkSelectedRepo = filtered[m.newWorkRepoCursor]
				m.newWorkRepoFilterMode = false
				m.newWorkStep = newWorkSelectWorktree
				m.newWorkWorktreeOptions = nil
				m.newWorkWorktreeCursor = 0
				repoDir := m.sessionMgr.RepoDir(m.newWorkSelectedRepo)
				return m, discoverWorktreesCmd(m.sessionMgr, repoDir, 0)
			}
			var cmd tea.Cmd
			m.newWorkRepoFilterInput, cmd = m.newWorkRepoFilterInput.Update(msg)
			// Reset cursor when filter text changes
			filtered := m.filteredNewWorkRepos()
			if m.newWorkRepoCursor >= len(filtered) {
				m.newWorkRepoCursor = max(0, len(filtered)-1)
			}
			return m, cmd
		}
		switch msg.String() {
		case "esc":
			m.showNewWork = false
			return m, nil
		case "q", "ctrl+c":
			return m, tea.Quit
		case "/":
			ti := textinput.New()
			ti.Placeholder = "filter repos..."
			ti.Focus()
			ti.CharLimit = 100
			ti.Width = 40
			m.newWorkRepoFilterInput = ti
			m.newWorkRepoFilterMode = true
			m.newWorkRepoCursor = 0
			return m, textinput.Blink
		case "j", "down":
			if m.newWorkRepoCursor < len(m.newWorkRepos)-1 {
				m.newWorkRepoCursor++
			}
			return m, nil
		case "k", "up":
			if m.newWorkRepoCursor > 0 {
				m.newWorkRepoCursor--
			}
			return m, nil
		case "enter":
			if m.newWorkRepoCursor >= len(m.newWorkRepos) {
				return m, nil
			}
			m.newWorkSelectedRepo = m.newWorkRepos[m.newWorkRepoCursor]
			m.newWorkStep = newWorkSelectWorktree
			m.newWorkWorktreeOptions = nil
			m.newWorkWorktreeCursor = 0
			repoDir := m.sessionMgr.RepoDir(m.newWorkSelectedRepo)
			return m, discoverWorktreesCmd(m.sessionMgr, repoDir, 0)
		}
		return m, nil

	case newWorkSelectWorktree:
		switch msg.String() {
		case "esc":
			m.newWorkStep = newWorkSelectRepo
			return m, nil
		case "q", "ctrl+c":
			return m, tea.Quit
		case "j", "down":
			if m.newWorkWorktreeCursor < len(m.newWorkWorktreeOptions)-1 {
				m.newWorkWorktreeCursor++
			}
			return m, nil
		case "k", "up":
			if m.newWorkWorktreeCursor > 0 {
				m.newWorkWorktreeCursor--
			}
			return m, nil
		case "enter":
			if m.newWorkWorktreeCursor >= len(m.newWorkWorktreeOptions) {
				return m, nil
			}
			opt := m.newWorkWorktreeOptions[m.newWorkWorktreeCursor]
			m.newWorkStep = newWorkNewBranch
			ti := textinput.New()
			ti.Placeholder = "branch name..."
			ti.Focus()
			ti.CharLimit = 100
			ti.Width = 40
			m.newWorkBranchInput = ti
			if opt.IsCreateNew {
				m.newWorkUseExistingWorktree = false
				return m, textinput.Blink
			}
			m.newWorkSelectedWorktree = opt.Path
			m.newWorkUseExistingWorktree = true
			return m, textinput.Blink
		}
		return m, nil

	case newWorkNewBranch:
		switch msg.Type {
		case tea.KeyEsc:
			m.newWorkStep = newWorkSelectWorktree
			return m, nil
		case tea.KeyEnter:
			branchName := m.newWorkBranchInput.Value()
			if branchName == "" {
				return m, nil
			}
			m.newWorkStep = newWorkSeedPrompt
			ti := textinput.New()
			ti.Placeholder = "describe what claude should work on..."
			ti.Focus()
			ti.CharLimit = 500
			ti.Width = 50
			m.newWorkSeedInput = ti
			return m, textinput.Blink
		}
		var cmd tea.Cmd
		m.newWorkBranchInput, cmd = m.newWorkBranchInput.Update(msg)
		return m, cmd

	case newWorkSeedPrompt:
		switch msg.Type {
		case tea.KeyEsc:
			m.newWorkStep = newWorkSelectWorktree
			return m, nil
		case tea.KeyEnter:
			seedPrompt := m.newWorkSeedInput.Value()
			if seedPrompt == "" {
				return m, nil
			}
			m.showNewWork = false
			return m, m.createNewWorkSession(seedPrompt)
		}
		var cmd tea.Cmd
		m.newWorkSeedInput, cmd = m.newWorkSeedInput.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m *Model) handleNewWorkWorktrees(msg worktreesDiscoveredMsg) tea.Cmd {
	options := make([]WorktreeOption, 0, len(msg.worktrees)+1)
	for _, wt := range msg.worktrees {
		if isTempWorktree(wt.Path) {
			continue
		}
		opt := WorktreeOption{
			Path:   wt.Path,
			Branch: wt.Branch,
		}
		if sessionName, ok := m.sessionInUse[wt.Path]; ok {
			opt.InUseBy = sessionName
		}
		options = append(options, opt)
	}
	options = append(options, WorktreeOption{IsCreateNew: true})

	m.newWorkWorktreeOptions = options
	m.newWorkWorktreeCursor = 0
	m.newWorkStep = newWorkSelectWorktree
	return nil
}

func (m *Model) createNewWorkSession(seedPrompt string) tea.Cmd {
	branchName := m.newWorkBranchInput.Value()
	repoDir := m.sessionMgr.RepoDir(m.newWorkSelectedRepo)
	m.newWorkPendingRepo = m.newWorkSelectedRepo

	sessionName := sanitizeBranchForSession(branchName)

	if m.newWorkUseExistingWorktree {
		// Existing worktree: fetch + checkout -b inside it, then claude
		sess := tmux.PRSession{
			SessionName: sessionName,
			PRNumber:    0,
			WorkDir:     m.newWorkSelectedWorktree,
			Branch:      branchName,
		}
		return newWorkSessionCmd(m.sessionMgr, sess, seedPrompt, m.newWorkSelectedRepo)
	}

	// New worktree: create worktree from origin/, then cd into it and run claude
	sanitizedBranch := strings.ReplaceAll(branchName, "/", "-")
	worktreePath := fmt.Sprintf("%s-%s", repoDir, sanitizedBranch)
	sess := tmux.PRSession{
		SessionName: sessionName,
		PRNumber:    0,
		WorkDir:     repoDir,
		Branch:      branchName,
	}
	return newWorkWorktreeSessionCmd(m.sessionMgr, sess, seedPrompt, m.newWorkSelectedRepo, worktreePath, branchName)
}

// sanitizeBranchForSession creates a tmux-safe session name from a branch name.
func sanitizeBranchForSession(branch string) string {
	s := strings.ToLower(branch)
	s = strings.NewReplacer(".", "-", ":", "-", "/", "-", "\\", "-").Replace(s)
	s = reNonAlphanumHyphen.ReplaceAllString(s, "-")
	s = reMultiHyphen.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	if len(s) > 40 {
		cut := s[:40]
		if idx := strings.LastIndex(cut, "-"); idx > 20 {
			cut = cut[:idx]
		}
		s = strings.TrimRight(cut, "-")
	}
	return s
}

// switchToSession handles the enter key: switches to the PR's tmux session.
// Creates a new session with claude if none exists yet.
func (m *Model) switchToSession() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil {
		return nil
	}

	// Local rows: keep existing interactive-claude window behavior
	if r.RowType == RowTypeLocal {
		sess := tmux.PRSession{
			SessionName: r.TmuxSession,
			WorkDir:     r.WorktreePath,
			Branch:      r.PR.HeadRefName,
		}
		return ensureWindowAndSwitchCmd(m.sessionMgr, sess, "claude", "", "followup", "", "")
	}

	// PR rows with an existing session: switch to it, recreating if deleted externally
	if sess, ok := m.prSessions[r.PR.Number]; ok {
		return createAndSwitchCmd(m.sessionMgr, sess)
	}

	// No session yet: discover worktree, checkout branch, and open claude
	windowName, claudeCmd := claudeWindowAndCmd(r, "")
	actionType := actionTypeForSession(r, false)
	repo := r.PR.RepoNameWithOwner
	headOID := r.PR.HeadCommitOID
	return m.initiateWorktreeDiscovery(r, func(workDir string) tea.Cmd {
		sess := tmux.PRSession{
			SessionName: tmux.SanitizeSessionName(r.PR.Title, r.PR.Number),
			PRNumber:    r.PR.Number,
			PRTitle:     r.PR.Title,
			WorkDir:     workDir,
			Branch:      r.PR.HeadRefName,
			PRURL:       r.PR.URL,
		}
		return ensureWindowAndSwitchCmd(m.sessionMgr, sess, windowName, claudeCmd, actionType, repo, headOID)
	})
}

// switchToPRSession handles the `c` key: switch to existing session or create one and run claude.
func (m *Model) switchToPRSession() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil {
		return nil
	}

	// Local rows already have a tmux session — just switch to it
	if r.RowType == RowTypeLocal {
		sess := tmux.PRSession{
			SessionName: r.TmuxSession,
			WorkDir:     r.WorktreePath,
			Branch:      r.PR.HeadRefName,
		}
		return ensureWindowAndSwitchCmd(m.sessionMgr, sess, "claude", "", "followup", "", "")
	}

	// If we have session details from a previous creation, reuse them.
	// ensureWindowAndSwitchCmd handles the case where the tmux session
	// was killed externally by recreating it.
	if sess, ok := m.prSessions[r.PR.Number]; ok {
		windowName, claudeCmd := claudeWindowAndCmd(r, "")
		actionType := actionTypeForSession(r, false)
		return ensureWindowAndSwitchCmd(m.sessionMgr, sess, windowName, claudeCmd, actionType, r.PR.RepoNameWithOwner, r.PR.HeadCommitOID)
	}

	// Need to discover worktrees and show picker (or auto-select)
	windowName, claudeCmd := claudeWindowAndCmd(r, "")
	actionType := actionTypeForSession(r, false)
	repo := r.PR.RepoNameWithOwner
	headOID := r.PR.HeadCommitOID
	return m.initiateWorktreeDiscovery(r, func(workDir string) tea.Cmd {
		sess := tmux.PRSession{
			SessionName: tmux.SanitizeSessionName(r.PR.Title, r.PR.Number),
			PRNumber:    r.PR.Number,
			PRTitle:     r.PR.Title,
			WorkDir:     workDir,
			Branch:      r.PR.HeadRefName,
			PRURL:       r.PR.URL,
		}
		return ensureWindowAndSwitchCmd(m.sessionMgr, sess, windowName, claudeCmd, actionType, repo, headOID)
	})
}

// destroyPRSession handles the `D` key: kill the session for the selected row.
func (m *Model) destroyPRSession() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil {
		return nil
	}
	if r.RowType == RowTypeLocal {
		return m.removeLocalEntry(r)
	}
	sess, ok := m.prSessions[r.PR.Number]
	if !ok {
		m.notification = fmt.Sprintf("No session for #%d", r.PR.Number)
		return clearNotificationCmd(3 * time.Second)
	}
	return destroySessionCmd(m.sessionMgr, sess.SessionName)
}

// removeLocalEntry removes a local session entry from state, killing the tmux session if active.
func (m *Model) removeLocalEntry(r *PRRow) tea.Cmd {
	var tmuxSession string
	for i, entry := range m.sessionState.Sessions {
		if entry.Type == config.SessionTypeLocal && entry.WorktreePath == r.WorktreePath {
			tmuxSession = entry.TmuxSession
			delete(m.sessionInUse, entry.WorktreePath)
			m.sessionState.Sessions = append(m.sessionState.Sessions[:i], m.sessionState.Sessions[i+1:]...)
			break
		}
	}
	m.notification = fmt.Sprintf("Removed local entry %s", r.PR.HeadRefName)
	m.rebuildLocalRows()
	m.applyFilters()
	m.table = m.rebuildTable()
	var cmds []tea.Cmd
	cmds = append(cmds, clearNotificationCmd(3*time.Second))
	if tmuxSession != "" {
		cmds = append(cmds, destroySessionCmd(m.sessionMgr, tmuxSession))
	}
	if m.config.SessionsPath != "" {
		cmds = append(cmds, saveSessionsCmd(m.sessionState, m.config.SessionsPath))
	}
	return tea.Batch(cmds...)
}

// spawnPRCreationAgent handles the `O` key: spawn a headless agent to create a PR.
func (m *Model) spawnPRCreationAgent() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil || r.RowType != RowTypeLocal {
		return nil
	}
	if m.prCreationInProgress[r.WorktreePath] {
		return nil
	}
	m.prCreationInProgress[r.WorktreePath] = true
	m.notification = fmt.Sprintf("Creating PR for %s...", r.PR.HeadRefName)
	return tea.Batch(spawnPRAgentCmd(r.WorktreePath), clearNotificationCmd(3*time.Second))
}

// transitionMatchedLocalEntries checks local session entries against fetched PRs
// and transitions any that have a matching branch+repo to PR type.
func (m *Model) transitionMatchedLocalEntries(prs []github.PR) []tea.Cmd {
	var cmds []tea.Cmd
	matchedPRs := make(map[int]bool)

	for i, entry := range m.sessionState.Sessions {
		if entry.Type != config.SessionTypeLocal {
			continue
		}
		for _, pr := range prs {
			if matchedPRs[pr.Number] {
				continue
			}
			repoName := extractRepoName(pr.RepoNameWithOwner)
			if entry.Branch == pr.HeadRefName && entry.Repo == repoName {
				matchedPRs[pr.Number] = true
				cmds = append(cmds, m.transitionEntryToPR(i, pr)...)
				break
			}
		}
	}
	if len(cmds) > 0 {
		m.rebuildLocalRows()
	}
	return cmds
}

// transitionLocalEntryByWorktree finds a local entry by worktree path and transitions it.
func (m *Model) transitionLocalEntryByWorktree(worktreePath string, prNumber int, prURL string) []tea.Cmd {
	for i, entry := range m.sessionState.Sessions {
		if entry.WorktreePath == worktreePath && entry.Type == config.SessionTypeLocal {
			pr := github.PR{
				Number:      prNumber,
				URL:         prURL,
				HeadRefName: entry.Branch,
			}
			return m.transitionEntryToPR(i, pr)
		}
	}
	return nil
}

// transitionEntryToPR converts a local session entry to a PR entry.
func (m *Model) transitionEntryToPR(entryIdx int, pr github.PR) []tea.Cmd {
	entry := &m.sessionState.Sessions[entryIdx]
	oldName := entry.TmuxSession
	newName := tmux.SanitizeSessionName(pr.Title, pr.Number)
	if newName == "" {
		newName = tmux.SanitizeSessionName(pr.HeadRefName, pr.Number)
	}

	entry.Type = config.SessionTypePR
	entry.PRNumber = pr.Number

	session := tmux.PRSession{
		SessionName: newName,
		PRNumber:    pr.Number,
		PRTitle:     pr.Title,
		WorkDir:     entry.WorktreePath,
		Branch:      entry.Branch,
		PRURL:       pr.URL,
	}
	m.prSessions[pr.Number] = session
	m.sessionInUse[entry.WorktreePath] = newName
	entry.TmuxSession = newName

	var cmds []tea.Cmd
	if oldName != newName {
		cmds = append(cmds, renameSessionCmd(m.sessionMgr, oldName, newName))
	}
	if m.config.SessionsPath != "" {
		cmds = append(cmds, saveSessionsCmd(m.sessionState, m.config.SessionsPath))
	}
	return cmds
}

// parsePRFromAgentOutput extracts a PR number and URL from agent output.
func parsePRFromAgentOutput(output string) (int, string) {
	lines := strings.Split(strings.TrimSpace(output), "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		if strings.Contains(line, "github.com") && strings.Contains(line, "/pull/") {
			idx := strings.Index(line, "/pull/")
			if idx == -1 {
				continue
			}
			numStr := line[idx+6:]
			// Trim any trailing non-digit characters
			end := 0
			for end < len(numStr) && numStr[end] >= '0' && numStr[end] <= '9' {
				end++
			}
			if end == 0 {
				continue
			}
			num := 0
			for _, c := range numStr[:end] {
				num = num*10 + int(c-'0')
			}
			// Extract the full URL (up to the number)
			urlStart := strings.LastIndex(line[:idx], "https://")
			if urlStart == -1 {
				urlStart = strings.LastIndex(line[:idx], "http://")
			}
			url := ""
			if urlStart >= 0 {
				url = line[urlStart : idx+6+end]
			}
			return num, url
		}
	}
	return 0, ""
}

// initiateWorktreeDiscovery starts the worktree discovery flow for a PR.
func (m *Model) initiateWorktreeDiscovery(r *PRRow, action func(workDir string) tea.Cmd) tea.Cmd {
	repoName := extractRepoName(r.PR.RepoNameWithOwner)
	repoDir := m.sessionMgr.RepoDir(repoName)

	// Check if repo dir exists
	if _, err := os.Stat(repoDir); os.IsNotExist(err) {
		m.notification = fmt.Sprintf("Repo directory not found: %s", repoDir)
		return clearNotificationCmd(5 * time.Second)
	}

	m.pendingSessionAction = action
	m.pendingSessionPR = r
	return discoverWorktreesCmd(m.sessionMgr, repoDir, r.PR.Number)
}

// showWorktreePickerForPR processes discovered worktrees: auto-selects matching branch or shows picker.
func (m *Model) showWorktreePickerForPR(msg worktreesDiscoveredMsg) tea.Cmd {
	if m.pendingSessionPR == nil || m.pendingSessionAction == nil {
		return nil
	}

	pr := m.pendingSessionPR
	branch := pr.PR.HeadRefName

	// Auto-select if a worktree is already on the PR's branch
	for _, wt := range msg.worktrees {
		if wt.Branch == branch && !isTempWorktree(wt.Path) {
			action := m.pendingSessionAction
			m.pendingSessionAction = nil
			m.pendingSessionPR = nil
			return action(wt.Path)
		}
	}

	// Build picker options, filtering out worktrees in temp directories
	options := make([]WorktreeOption, 0, len(msg.worktrees)+1)
	for _, wt := range msg.worktrees {
		if isTempWorktree(wt.Path) {
			continue
		}
		opt := WorktreeOption{
			Path:   wt.Path,
			Branch: wt.Branch,
		}
		if sessionName, ok := m.sessionInUse[wt.Path]; ok {
			opt.InUseBy = sessionName
		}
		options = append(options, opt)
	}
	options = append(options, WorktreeOption{IsCreateNew: true})

	m.worktreeOptions = options
	m.worktreePickerIdx = 0
	m.worktreePickerPR = pr.PR.Number
	m.worktreePickerBranch = pr.PR.HeadRefName
	m.showWorktreePicker = true
	return nil
}

func isTempWorktree(path string) bool {
	return strings.HasPrefix(path, "/private/var/folders/") ||
		strings.HasPrefix(path, "/tmp/") ||
		strings.HasPrefix(path, "/var/folders/")
}

// updateWorktreePickerOverlay handles key input for the worktree picker.
func (m *Model) updateWorktreePickerOverlay(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "esc":
		m.showWorktreePicker = false
		m.pendingSessionAction = nil
		m.pendingSessionPR = nil
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	case "j", "down":
		if m.worktreePickerIdx < len(m.worktreeOptions)-1 {
			m.worktreePickerIdx++
		}
		return m, nil
	case "k", "up":
		if m.worktreePickerIdx > 0 {
			m.worktreePickerIdx--
		}
		return m, nil
	case "enter":
		if m.worktreePickerIdx >= len(m.worktreeOptions) {
			return m, nil
		}
		opt := m.worktreeOptions[m.worktreePickerIdx]
		if opt.IsCreateNew {
			if m.pendingSessionPR == nil {
				return m, nil
			}
			pr := m.pendingSessionPR
			repoName := extractRepoName(pr.PR.RepoNameWithOwner)
			repoDir := m.sessionMgr.RepoDir(repoName)
			sanitizedBranch := strings.ReplaceAll(pr.PR.HeadRefName, "/", "-")
			worktreePath := fmt.Sprintf("%s-%s", repoDir, sanitizedBranch)
			return m, createWorktreeCmd(m.sessionMgr, repoDir, worktreePath, pr.PR.HeadRefName)
		}
		// Selected an existing worktree
		action := m.pendingSessionAction
		m.showWorktreePicker = false
		m.pendingSessionAction = nil
		m.pendingSessionPR = nil
		if action != nil {
			return m, action(opt.Path)
		}
		return m, nil
	}
	return m, nil
}

// claudeWindowAndCmd returns the tmux window name and claude command for a PR action.
func claudeWindowAndCmd(r *PRRow, customPrompt string) (windowName, claudeCmd string) {
	if customPrompt != "" {
		return "claude", fmt.Sprintf("I want to work on PR %s. %s", r.PR.URL, customPrompt)
	}
	switch r.Action {
	case github.ActionFixCI:
		return "ci-fix", fmt.Sprintf("/dd:ci:fix %s", r.PR.URL)
	case github.ActionAddressFeedback:
		return "feedback", fmt.Sprintf("/dd:pr:address-feedback %s", r.PR.URL)
	case github.ActionInvestigate:
		return "investigate", conductorInvestigatePromptFromRow(r)
	case github.ActionResolveConflicts:
		return "conflicts", fmt.Sprintf("I want to work on PR %s. This PR has merge conflicts with the base branch. Please rebase onto the base branch, resolve conflicts, and push.", r.PR.URL)
	default:
		return "claude", fmt.Sprintf("/dd:pr:followup %s", r.PR.URL)
	}
}

// actionTypeForSession derives the session record ActionType from context.
func actionTypeForSession(r *PRRow, isUserCustom bool) string {
	if isUserCustom {
		return "custom"
	}
	switch r.Action {
	case github.ActionFixCI:
		return "fix-ci"
	case github.ActionAddressFeedback:
		return "address-feedback"
	case github.ActionInvestigate:
		return "investigate"
	case github.ActionResolveConflicts:
		return "resolve-conflicts"
	default:
		return "followup"
	}
}

func (m *Model) launchClaudeForPR(r *PRRow, customPrompt string) tea.Cmd {
	windowName, claudeCmd := claudeWindowAndCmd(r, customPrompt)
	actionType := actionTypeForSession(r, customPrompt != "")
	repo := r.PR.RepoNameWithOwner
	headOID := r.PR.HeadCommitOID

	// If session already exists, ensure window and switch
	if sess, ok := m.prSessions[r.PR.Number]; ok {
		return ensureWindowAndSwitchCmd(m.sessionMgr, sess, windowName, claudeCmd, actionType, repo, headOID)
	}

	// Need worktree discovery first, then create session + window
	capturedWindow := windowName
	capturedClaudeCmd := claudeCmd
	return m.initiateWorktreeDiscovery(r, func(workDir string) tea.Cmd {
		sess := tmux.PRSession{
			SessionName: tmux.SanitizeSessionName(r.PR.Title, r.PR.Number),
			PRNumber:    r.PR.Number,
			PRTitle:     r.PR.Title,
			WorkDir:     workDir,
			Branch:      r.PR.HeadRefName,
			PRURL:       r.PR.URL,
		}
		return ensureWindowAndSwitchCmd(m.sessionMgr, sess, capturedWindow, capturedClaudeCmd, actionType, repo, headOID)
	})
}

func (m *Model) showPRDetailOverlay() tea.Cmd {
	idx := m.table.GetHighlightedRowIndex()
	if idx < 0 || idx >= len(m.rows) {
		return nil
	}
	r := m.rows[idx]

	m.showPRDetail = true
	m.prDetailIdx = idx
	m.prDetailCursor = 0
	m.prDetailExpandedSvc = -1
	m.prDetailExpandedComment = -1
	m.prDetailItems = buildPRDetailItems(r)
	m.prDetailReviewCommentsErr = nil
	m.prDetailReviewCommentsLoading = false

	// For open PRs with unresolved threads, fetch comment bodies
	if r.PR.State == github.PRStateOpen && r.PR.UnresolvedThreads > 0 {
		m.prDetailReviewCommentsLoading = true
		parts := strings.SplitN(r.PR.RepoNameWithOwner, "/", 2)
		if len(parts) == 2 {
			return fetchReviewThreadsCmd(m.ghClient, parts[0], parts[1], r.PR.Number)
		}
	}
	return nil
}

// extractRepoName returns the repo name from "Owner/Repo" format
func extractRepoName(nameWithOwner string) string {
	parts := strings.SplitN(nameWithOwner, "/", 2)
	if len(parts) == 2 {
		return parts[1]
	}
	return nameWithOwner
}

func (m *Model) openDeployRunOverlay() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil || r.PR.State != github.PRStateOpen {
		return nil
	}

	services := github.ExtractServiceNames(r.PR.Labels)
	if len(services) == 1 {
		return m.launchDeploy(r.PR.HeadRefName, services[0])
	}

	m.deployRunServices = services
	m.deployRunCursor = 0
	m.deployRunTextMode = len(services) == 0
	m.showDeployRun = true

	if m.deployRunTextMode {
		ti := textinput.New()
		ti.Placeholder = "service name..."
		ti.Focus()
		ti.CharLimit = 100
		ti.Width = 40
		m.deployRunInput = ti
		return textinput.Blink
	}

	return nil
}

func (m *Model) updateDeployRunOverlay(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.deployRunTextMode {
		switch msg.Type {
		case tea.KeyEsc:
			m.showDeployRun = false
			return m, nil
		case tea.KeyEnter:
			service := m.deployRunInput.Value()
			if service == "" {
				return m, nil
			}
			m.showDeployRun = false
			r := m.findSelectedPRRow()
			if r == nil {
				return m, nil
			}
			return m, m.launchDeploy(r.PR.HeadRefName, service)
		}
		var cmd tea.Cmd
		m.deployRunInput, cmd = m.deployRunInput.Update(msg)
		return m, cmd
	}

	switch msg.String() {
	case "esc":
		m.showDeployRun = false
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	case "j", "down":
		if m.deployRunCursor < len(m.deployRunServices)-1 {
			m.deployRunCursor++
		}
		return m, nil
	case "k", "up":
		if m.deployRunCursor > 0 {
			m.deployRunCursor--
		}
		return m, nil
	case "enter":
		if m.deployRunCursor < len(m.deployRunServices) {
			m.showDeployRun = false
			r := m.findSelectedPRRow()
			if r == nil {
				return m, nil
			}
			return m, m.launchDeploy(r.PR.HeadRefName, m.deployRunServices[m.deployRunCursor])
		}
		return m, nil
	}
	return m, nil
}

func (m Model) launchDeploy(branch, service string) tea.Cmd {
	shellCmd := fmt.Sprintf("ddr conductor run --branch %s --target staging %s", branch, service)
	windowName := fmt.Sprintf("deploy-%s", service)
	return func() tea.Msg {
		cmd := exec.Command("tmux", "new-window", "-n", windowName, "/bin/bash", "-c", shellCmd)
		_ = cmd.Start()
		return nil
	}
}

func (m *Model) triggerIntegrate() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil || r.PR.State != github.PRStateOpen {
		return nil
	}
	m.notification = fmt.Sprintf("Integrating #%d...", r.PR.Number)
	return integrateCmd(m.deployClient, r.PR.URL, r.PR.Number)
}

func (m *Model) openGithubActionsOverlay() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil || r.PR.State != github.PRStateOpen {
		return nil
	}
	m.githubActionsCursor = 0
	m.githubActionsCommentMode = false
	m.showGithubActions = true
	return nil
}

func (m *Model) updateGithubActionsOverlay(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.githubActionsCommentMode {
		switch msg.Type {
		case tea.KeyEsc:
			m.githubActionsCommentMode = false
			return m, nil
		case tea.KeyEnter:
			body := m.githubActionsCommentInput.Value()
			if body == "" {
				return m, nil
			}
			m.showGithubActions = false
			m.githubActionsCommentMode = false
			r := m.findSelectedPRRow()
			if r == nil {
				return m, nil
			}
			return m, commentCmd(m.ghClient.Runner, r.PR.URL, body, r.PR.Number)
		}
		var cmd tea.Cmd
		m.githubActionsCommentInput, cmd = m.githubActionsCommentInput.Update(msg)
		return m, cmd
	}

	switch msg.String() {
	case "esc":
		m.showGithubActions = false
		return m, nil
	case "q", "ctrl+c":
		return m, tea.Quit
	case "j", "down":
		if m.githubActionsCursor < len(githubActionItems)-1 {
			m.githubActionsCursor++
		}
		return m, nil
	case "k", "up":
		if m.githubActionsCursor > 0 {
			m.githubActionsCursor--
		}
		return m, nil
	case "enter":
		return m.executeGithubAction()
	}
	return m, nil
}

func (m *Model) executeGithubAction() (tea.Model, tea.Cmd) {
	r := m.findSelectedPRRow()
	if r == nil {
		return m, nil
	}
	switch githubActionItems[m.githubActionsCursor] {
	case "close":
		m.showGithubActions = false
		return m, closeCmd(m.ghClient.Runner, r.PR.URL, r.PR.Number)
	case "comment":
		ti := textinput.New()
		ti.Placeholder = "comment body..."
		ti.Focus()
		ti.CharLimit = 500
		ti.Width = 50
		m.githubActionsCommentInput = ti
		m.githubActionsCommentMode = true
		return m, textinput.Blink
	case "mark ready":
		m.showGithubActions = false
		return m, markReadyCmd(m.ghClient.Runner, r.PR.URL, r.PR.Number)
	case "request merge":
		m.showGithubActions = false
		return m, requestMergeCmd(m.ghClient.Runner, r.PR.URL, r.PR.Number)
	case "update branch":
		m.showGithubActions = false
		return m, updateBranchCmd(m.ghClient.Runner, r.PR.RepoNameWithOwner, r.PR.Number)
	}
	return m, nil
}

func (m *Model) showCustomPromptOverlay() tea.Cmd {
	r := m.findSelectedPRRow()
	if r == nil || r.PR.State != github.PRStateOpen {
		return nil
	}

	ti := textinput.New()
	ti.Placeholder = "describe what you want claude to do..."
	ti.Focus()
	ti.CharLimit = 500
	ti.Width = 50

	m.customPromptInput = ti
	m.showCustomPrompt = true
	return textinput.Blink
}

func (m *Model) applyFilters() {
	// Local rows are subject to repo filtering but not status filtering
	filteredLocal := filterByRepo(m.localRows, m.repoFilter)
	filteredLocal = filterBySearch(filteredLocal, m.searchFilter)

	filtered := m.allRows
	filtered = filterByRepo(filtered, m.repoFilter)
	filtered = filterByStatus(filtered, m.statusFilter)
	filtered = filterBySearch(filtered, m.searchFilter)

	// Local rows at top, then PR rows
	m.rows = append(filteredLocal, filtered...)
	m.updateAgentStatuses()
}

func (m *Model) openSearch() tea.Cmd {
	ti := textinput.New()
	ti.Focus()
	ti.CharLimit = 100
	ti.SetValue(m.searchFilter)
	m.searchInput = ti
	m.searchEditing = true
	return textinput.Blink
}

func (m *Model) openRepoFilterOverlay() tea.Cmd {
	m.repoFilterItems = uniqueRepos(m.allRows, m.localRows)
	m.repoFilterCursor = 0
	m.repoFilterTextMode = false
	m.showRepoFilter = true
	return nil
}

func (m *Model) selectRepoFilter(repo string) {
	m.repoFilter = repo
	m.showRepoFilter = false
	m.applyFilters()
	m.table = m.rebuildTable()
}

func (m *Model) openStatusFilterOverlay() tea.Cmd {
	m.statusFilterItems = availableStatusFilters(m.allRows)
	m.statusFilterCursor = 0
	m.showStatusFilter = true
	return nil
}

func (m *Model) selectStatusFilter(status string) {
	m.statusFilter = status
	m.showStatusFilter = false
	m.applyFilters()
	m.table = m.rebuildTable()
}

func (m *Model) openViewPicker() tea.Cmd {
	m.viewPickerCursor = m.activeViewIdx
	m.viewCreateMode = viewCreateNone
	m.showViewPicker = true
	return nil
}

func (m *Model) createNewView(name, query string) tea.Cmd {
	newView := View{Name: name, Query: query}
	configPath := m.configPath

	return func() tea.Msg {
		if configPath == "" {
			return viewSavedMsg{view: newView}
		}

		cfg, _ := config.LoadFromPath(configPath)
		cfg.Views = append(cfg.Views, config.View{
			Name:  name,
			Query: query,
		})

		err := config.Save(cfg, configPath)
		return viewSavedMsg{view: newView, err: err}
	}
}

func buildHelpText(row *PRRow, _ bool) string {
	parts := []string{"q: quit", "r: refresh", "/: search", "enter: session"}

	if row != nil && row.RowType != RowTypeLocal && (row.PR.State == github.PRStateOpen || row.Action == github.ActionInvestigate) {
		label := contextActionLabel(row.Action)
		parts = append(parts, "c: "+label)
	}

	parts = append(parts, "?: help")

	pipe := lipgloss.NewStyle().Foreground(gray).Render(" | ")
	styled := make([]string, len(parts))
	for i, p := range parts {
		styled[i] = helpStyle.Render(p)
	}
	return strings.Join(styled, pipe)
}

func (m Model) buildHelpLine() string {
	row := m.findSelectedPRRow()
	hasSession := false
	if row != nil {
		if row.RowType == RowTypeLocal {
			hasSession = true
		} else {
			_, hasSession = m.prSessions[row.PR.Number]
		}
	}
	return buildHelpText(row, hasSession)
}

func openBrowser(url string) {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", url)
	case "linux":
		cmd = exec.Command("xdg-open", url)
	default:
		return
	}
	_ = cmd.Start()
}
